{
  "timeline": [
    {
      "headline": "Birth of Telly Savalas",
      "text": "Aristotelis 'Telly' Savalas was born on January 21, 1922, in Garden City, New York, USA.",
      "date": "1922-01-21"
    },
    {
      "headline": "Military Service",
      "text": "During World War II, Telly Savalas served in the United States Army from 1941 to 1943.",
      "date": "1941"
    },
    {
      "headline": "Education",
      "text": "After his military service, Savalas attended Columbia University, where he earned a degree in psychology in 1946.",
      "date": "1946"
    },
    {
      "headline": "Television Debut",
      "text": "Telly Savalas made his television debut in 1959 on the series 'Armstrong Circle Theatre'.",
      "date": "1959"
    },
    {
      "headline": "Film Debut",
      "text": "Savalas made his film debut in 'Mad Dog Coll' in 1961.",
      "date": "1961"
    },
    {
      "headline": "Academy Award Nomination",
      "text": "In 1962, Savalas received an Academy Award nomination for Best Supporting Actor for his role in 'Birdman of Alcatraz'.",
      "date": "1962"
    },
    {
      "headline": "Role in 'The Dirty Dozen'",
      "text": "Savalas played the role of Archer Maggott in the film 'The Dirty Dozen', released in 1967.",
      "date": "1967"
    },
    {
      "headline": "Portrayal of Ernst Stavro Blofeld",
      "text": "In 1969, Savalas portrayed the James Bond villain Ernst Stavro Blofeld in 'On Her Majesty's Secret Service'.",
      "date": "1969"
    },
    {
      "headline": "Kojak Debut",
      "text": "Telly Savalas began his iconic role as Lt. Theo Kojak in the television series 'Kojak', which premiered in 1973.",
      "date": "1973"
    },
    {
      "headline": "End of Kojak Series",
      "text": "The original run of the television series 'Kojak' ended in 1978.",
      "date": "1978"
    },
    {
      "headline": "Death of Telly Savalas",
      "text": "Telly Savalas passed away on January 22, 1994, in Universal City, California, USA.",
      "date": "1994-01-22"
    }
  ]
}

