{
  "timeline": [
    {
      "headline": "Founding of Alexandria",
      "text": "Alexandria was founded by Alexander the Great in 331 BC. It was established on the site of the small Egyptian town of Rhacotis.",
      "date": "-0331"
    },
    {
      "headline": "Construction of the Lighthouse of Alexandria",
      "text": "The Lighthouse of Alexandria, also known as the Pharos of Alexandria, was constructed in the 3rd century BC. It was one of the Seven Wonders of the Ancient World.",
      "date": "-0280"
    },
    {
      "headline": "Ptolemaic Rule",
      "text": "Under the Ptolemaic dynasty, Alexandria became a major center of Hellenistic culture and trade. The city was the capital of Ptolemaic Egypt.",
      "date": "-0305"
    },
    {
      "headline": "Library of Alexandria",
      "text": "The Library of Alexandria was one of the largest and most significant libraries of the ancient world. It was established during the reign of Ptolemy II Philadelphus (283–246 BC).",
      "date": "-0283"
    },
    {
      "headline": "Roman Conquest",
      "text": "In 30 BC, Alexandria came under Roman control after the defeat of Mark Antony and Cleopatra by Octavian (later Augustus Caesar).",
      "date": "-0030"
    },
    {
      "headline": "Destruction of the Library of Alexandria",
      "text": "The Library of Alexandria suffered several destructive events, with significant damage occurring during the Roman civil war in 48 BC and later incidents.",
      "date": "-0048"
    },
    {
      "headline": "Arab Conquest",
      "text": "In 641 AD, Alexandria was conquered by the Arab forces led by Amr ibn al-As, marking the end of Byzantine rule.",
      "date": "0641"
    },
    {
      "headline": "Napoleon's Expedition",
      "text": "In 1798, Napoleon Bonaparte's expedition to Egypt included the capture of Alexandria, which was part of his campaign to weaken British influence in the region.",
      "date": "1798"
    },
    {
      "headline": "British Occupation",
      "text": "In 1882, Alexandria was bombarded by British naval forces, leading to British occupation of Egypt.",
      "date": "1882"
    },
    {
      "headline": "Modern Development",
      "text": "Throughout the 20th century, Alexandria underwent significant modernization and development, becoming a major industrial center and tourist destination.",
      "date": "1900"
    }
  ]
}

{
