{
  "timeline": [
    {
      "headline": "Publication of Special Relativity",
      "text": "Albert Einstein published his theory of special relativity in 1905. This theory revolutionized the understanding of space and time, introducing the concept that the laws of physics are the same for all non-accelerating observers and that the speed of light is constant regardless of the motion of the light source.",
      "date": "1905"
    },
    {
      "headline": "Publication of General Relativity",
      "text": "In 1915, Albert Einstein published his theory of general relativity. This theory provided a new description of gravitation, proposing that massive objects cause a distortion in space-time, which is felt as gravity.",
      "date": "1915"
    },
    {
      "headline": "Confirmation of General Relativity",
      "text": "In 1919, during a solar eclipse, observations made by Arthur Eddington and his team confirmed Einstein's predictions about the bending of light around the sun, providing strong evidence for general relativity.",
      "date": "1919"
    },
    {
      "headline": "Introduction of the Cosmological Constant",
      "text": "Einstein introduced the cosmological constant in 1917 as a modification to his original equations of general relativity to allow for a static universe, which was the prevailing thought at the time.",
      "date": "1917"
    },
    {
      "headline": "Einstein's Field Equations",
      "text": "The Einstein field equations, which form the core of general relativity, were first published in 1915. These equations describe how matter and energy in the universe influence the curvature of space-time.",
      "date": "1915"
    },
    {
      "headline": "Development of the Schwarzschild Solution",
      "text": "In 1916, Karl Schwarzschild provided the first exact solution to the Einstein field equations, describing the gravitational field outside a spherical mass, which later became known as the Schwarzschild solution.",
      "date": "1916"
    },
    {
      "headline": "Discovery of Gravitational Waves",
      "text": "Gravitational waves, which were predicted by Einstein's theory of general relativity, were directly detected for the first time by the LIGO observatory in 2015, confirming another aspect of Einstein's theory.",
      "date": "2015"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of the University",
      "text": "The University of California, Berkeley was founded on March 23, 1868, following the merger of the private College of California and the public Agricultural, Mining, and Mechanical Arts College in Oakland.",
      "date": "1868-03-23"
    },
    {
      "headline": "First Classes Held",
      "text": "The first classes at the University of California, Berkeley were held in 1869 in Oakland, before moving to its current location in Berkeley in 1873.",
      "date": "1869"
    },
    {
      "headline": "Move to Berkeley",
      "text": "In 1873, the University of California moved to its new campus in Berkeley, California.",
      "date": "1873"
    },
    {
      "headline": "Establishment of the College of Letters and Science",
      "text": "In 1915, the College of Letters and Science was established, becoming the largest of the university's colleges.",
      "date": "1915"
    },
    {
      "headline": "Development of the Cyclotron",
      "text": "In 1931, Ernest O. Lawrence invented the cyclotron at UC Berkeley, which later earned him the Nobel Prize in Physics in 1939.",
      "date": "1931"
    },
    {
      "headline": "Nobel Prize in Physics",
      "text": "Ernest O. Lawrence was awarded the Nobel Prize in Physics in 1939 for the invention of the cyclotron.",
      "date": "1939"
    },
    {
      "headline": "Free Speech Movement",
      "text": "The Free Speech Movement began in 1964 at UC Berkeley, led by students demanding the right to free speech and academic freedom.",
      "date": "1964"
    },
    {
      "headline": "Discovery of Plutonium",
      "text": "In 1941, Glenn T. Seaborg and his team at UC Berkeley discovered the element plutonium.",
      "date": "1941"
    },
    {
      "headline": "Nobel Prize in Chemistry",
      "text": "Glenn T. Seaborg was awarded the Nobel Prize in Chemistry in 1951 for discoveries in the chemistry of the transuranium elements, including plutonium.",
      "date": "1951"
    },
    {
      "headline": "Establishment of the Space Sciences Laboratory",
      "text": "In 1959, the Space Sciences Laboratory was established at UC Berkeley to conduct research in space science.",
      "date": "1959"
    },
    {
      "headline": "Nobel Prize in Economics",
      "text": "In 2000, Daniel L. McFadden, a professor at UC Berkeley, was awarded the Nobel Prize in Economics for his development of theory and methods for analyzing discrete choice.",
      "date": "2000"
    }
  ]
}

