{
  "timeline": [
    {
      "headline": "Introduction of the Hijri Calendar",
      "text": "The Hijri calendar was introduced by Caliph Umar ibn al-Khattab in 638 CE. It was established to standardize the Islamic year and is based on the lunar cycle.",
      "date": "0638"
    },
    {
      "headline": "First Year of the Hijri Calendar",
      "text": "The first year of the Hijri calendar is 622 CE, the year of the Hijra, when Prophet Muhammad and his followers migrated from Mecca to Medina.",
      "date": "0622"
    },
    {
      "headline": "Adoption by Islamic Empires",
      "text": "The Hijri calendar was adopted by various Islamic empires and became the standard for religious and civil purposes in the Islamic world.",
      "date": "0638"
    },
    {
      "headline": "Use in Determining Islamic Holidays",
      "text": "The Hijri calendar is used to determine the dates of Islamic holidays and rituals, such as Ramadan, Eid al-Fitr, and Eid al-Adha.",
      "date": "0638"
    },
    {
      "headline": "Modern Usage",
      "text": "In modern times, the Hijri calendar is primarily used for religious purposes, while the Gregorian calendar is used for civil purposes in most Islamic countries.",
      "date": "20th century"
    }
  ]
}

