{
  "timeline": [
    {
      "headline": "Cuban Revolution",
      "text": "The Cuban Revolution, led by Fidel Castro, culminated in the overthrow of Cuban dictator Fulgencio Batista on January 1, 1959.",
      "date": "1959-01-01"
    },
    {
      "headline": "Eisenhower Approves Plan",
      "text": "In March 1960, U.S. President Dwight D. Eisenhower approved a CIA plan to train Cuban exiles for a potential invasion of Cuba.",
      "date": "1960-03"
    },
    {
      "headline": "Training of Cuban Exiles",
      "text": "Throughout 1960, Cuban exiles were trained by the CIA in Guatemala for the planned invasion of Cuba.",
      "date": "1960"
    },
    {
      "headline": "Kennedy's Authorization",
      "text": "On April 4, 1961, President John F. Kennedy authorized the final plan for the Bay of Pigs Invasion.",
      "date": "1961-04-04"
    },
    {
      "headline": "Air Strikes Begin",
      "text": "On April 15, 1961, the invasion began with air strikes by eight B-26 bombers on Cuban airfields.",
      "date": "1961-04-15"
    },
    {
      "headline": "Invasion at Bay of Pigs",
      "text": "On April 17, 1961, approximately 1,400 Cuban exiles landed at the Bay of Pigs on the southern coast of Cuba.",
      "date": "1961-04-17"
    },
    {
      "headline": "Cuban Forces Counterattack",
      "text": "On April 19, 1961, Cuban forces, led by Fidel Castro, defeated the invading exiles, capturing or killing most of them.",
      "date": "1961-04-19"
    },
    {
      "headline": "Prisoners Released",
      "text": "In December 1962, the captured exiles were released in exchange for $53 million worth of food and medicine.",
      "date": "1962-12"
    },
    {
      "headline": "Impact on U.S.-Cuba Relations",
      "text": "The failed invasion significantly strained U.S.-Cuba relations and pushed Cuba closer to the Soviet Union, setting the stage for the Cuban Missile Crisis in 1962.",
      "date": "1961"
    }
  ]
}

{
  "timeline": [
