    {
      "headline": "Begins Career in Television",
      "text": "In 1975, David Letterman moved to Los Angeles, California, to pursue a career in comedy and television writing.",
      "date": "1975"
    },
    {
      "headline": "Debut of 'Late Night with David Letterman'",
      "text": "On February 1, 1982, 'Late Night with David Letterman' premiered on NBC, marking the beginning of his career as a late-night talk show host.",
      "date": "1982-02-01"
    },
    {
      "headline": "Launch of 'Late Show with David Letterman'",
      "text": "David Letterman began hosting the 'Late Show with David Letterman' on CBS on August 30, 1993, after leaving NBC.",
      "date": "1993-08-30"
    },
    {
      "headline": "Heart Surgery",
      "text": "In January 2000, David Letterman underwent quintuple bypass heart surgery.",
      "date": "2000-01"
    },
    {
      "headline": "Kennedy Center Honors",
      "text": "David Letterman was awarded the Kennedy Center Honors on December 2, 2012, recognizing his contributions to American culture.",
