    },
    {
      "headline": "Retirement from Late-Night Television",
      "text": "David Letterman retired from late-night television on May 20, 2015, after hosting the 'Late Show with David Letterman' for 22 years.",
      "date": "2015-05-20"
    },
    {
      "headline": "Launch of 'My Next Guest Needs No Introduction'",
