{
  "timeline": [
    {
      "headline": "Birth of Millard Fillmore",
      "text": "Millard Fillmore was born on January 7, 1800, in a log cabin in Moravia, Cayuga County, New York.",
      "date": "1800-01-07"
    },
    {
      "headline": "Marriage to Abigail Powers",
      "text": "On February 5, 1826, Millard Fillmore married Abigail Powers, a teacher who had been his former schoolteacher.",
      "date": "1826-02-05"
    },
    {
      "headline": "Elected to the U.S. House of Representatives",
      "text": "Fillmore was elected to the U.S. House of Representatives in 1832, serving from 1833 to 1835, and again from 1837 to 1843.",
      "date": "1832"
    },
    {
      "headline": "Vice President of the United States",
      "text": "Fillmore was elected as the 12th Vice President of the United States in 1848, serving under President Zachary Taylor.",
      "date": "1848"
    },
    {
      "headline": "Became 13th President of the United States",
      "text": "On July 9, 1850, Millard Fillmore became the 13th President of the United States following the death of President Zachary Taylor.",
      "date": "1850-07-09"
    },
    {
      "headline": "Signing of the Compromise of 1850",
      "text": "Fillmore signed the Compromise of 1850 into law, which was a series of measures intended to ease tensions between slave and free states.",
      "date": "1850"
    },
    {
      "headline": "End of Presidency",
      "text": "Fillmore's term as President ended on March 4, 1853, when Franklin Pierce succeeded him.",
      "date": "1853-03-04"
    },
    {
      "headline": "Death of Abigail Fillmore",
      "text": "Abigail Fillmore died on March 30, 1853, shortly after leaving the White House.",
      "date": "1853-03-30"
    },
    {
      "headline": "Marriage to Caroline Carmichael McIntosh",
      "text": "Fillmore married Caroline Carmichael McIntosh on February 10, 1858.",
      "date": "1858-02-10"
    },
    {
      "headline": "Death of Millard Fillmore",
      "text": "Millard Fillmore died on March 8, 1874, in Buffalo, New York, after suffering a stroke.",
      "date": "1874-03-08"
    }
  ]
}

