    },
    {
      "headline": "Kingdom of Abkhazia",
      "text": "In the early Middle Ages, Abkhazia became a kingdom, which later united with the Kingdom of Georgia in the 10th century.",
      "date": "0780"
    },
    {
      "headline": "Ottoman Empire Control",
      "text": "In the 16th century, Abkhazia came under the influence of the Ottoman Empire, which introduced Islam to the region.",
      "date": "1578"
    },
    {
      "headline": "Russian Empire Annexation",
      "text": "In 1810, Abkhazia became a protectorate of the Russian Empire and was fully annexed in 1864.",
      "date": "1810"
    },
    {
      "headline": "Soviet Era",
      "text": "After the Russian Revolution, Abkhazia was declared a Soviet Socialist Republic in 1921, and later became an autonomous republic within the Georgian SSR in 1931.",
      "date": "1921"
    },
    {
      "headline": "War in Abkhazia",
      "text": "The War in Abkhazia occurred from 1992 to 1993, resulting in the de facto independence of Abkhazia from Georgia.",
      "date": "1992"
    },
    {
      "headline": "Declaration of Independence",
      "text": "Abkhazia declared independence from Georgia on July 23, 1992, although it remains largely unrecognized internationally.",
      "date": "1992-07-23"
    },
    {
      "headline": "Recognition by Russia",
      "text": "On August 26, 2008, Russia officially recognized Abkhazia as an independent state following the Russo-Georgian War.",
      "date": "2008-08-26"
    }
  ]
}

