{
  "timeline": [
    {
      "headline": "Birth of Herod the Great",
      "text": "Herod the Great was born in 73 BCE. He was a Roman Jewish client king of the Herodian kingdom of Judea.",
      "date": "-0073"
    },
    {
      "headline": "Appointed Governor of Galilee",
      "text": "In 47 BCE, Herod was appointed governor of Galilee by his father Antipater, who was the procurator of Judea.",
      "date": "-0047"
    },
    {
      "headline": "Appointed King of Judea",
      "text": "In 40 BCE, Herod was appointed King of Judea by the Roman Senate, although he did not gain control of his kingdom until 37 BCE.",
      "date": "-0040"
    },
    {
      "headline": "Consolidation of Power",
      "text": "In 37 BCE, Herod captured Jerusalem and consolidated his power over Judea, marking the beginning of his reign.",
      "date": "-0037"
    },
    {
      "headline": "Rebuilding of the Second Temple",
      "text": "Around 20 BCE, Herod began the massive project of rebuilding the Second Temple in Jerusalem, which became one of his most famous architectural achievements.",
      "date": "-0020"
    },
    {
      "headline": "Completion of the Second Temple",
      "text": "The main construction of the Second Temple was completed in 10 BCE, although work continued on its surroundings for many years.",
      "date": "-0010"
    },
    {
      "headline": "Death of Herod the Great",
      "text": "Herod the Great died in 4 BCE in Jericho, Judea. His death marked the end of his reign and the division of his kingdom among his sons.",
      "date": "-0004"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Compilation of The Lesser Key of Solomon",
      "text": "The Lesser Key of Solomon, also known as Lemegeton Clavicula Salomonis, was compiled in the mid-17th century. It is an anonymously authored grimoire on sorcery, mysticism, and magic, drawing from materials several centuries older.",
      "date": "1650"
    },
    {
      "headline": "Ars Goetia",
      "text": "The first book of The Lesser Key of Solomon, Ars Goetia, details the seventy-two demons that King Solomon is said to have evoked and confined in a bronze vessel sealed by magic symbols. It provides instructions on how to summon and control these spirits.",
      "date": "1650"
    },
    {
      "headline": "Ars Theurgia-Goetia",
      "text": "The second book, Ars Theurgia-Goetia, describes the spirits of the cardinal directions and how to summon them. It focuses on the hierarchy and offices of these spirits.",
      "date": "1650"
    },
    {
      "headline": "Ars Paulina",
      "text": "The third book, Ars Paulina, is divided into two parts. The first part deals with the angels of the hours of the day and night, while the second part covers the angels of the zodiac.",
      "date": "1650"
    },
    {
      "headline": "Ars Almadel",
      "text": "The fourth book, Ars Almadel, describes how to make an almadel, a wax tablet used to communicate with angels. It provides instructions on summoning the angels of the four altitudes.",
      "date": "1650"
    },
    {
      "headline": "Ars Notoria",
      "text": "The fifth book, Ars Notoria, is a collection of prayers and orations intended to grant the practitioner perfect memory and wisdom. It is distinct from the other books in its focus on achieving knowledge rather than controlling spirits.",
      "date": "1650"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Settlement",
      "text": "The area around Bristol has been settled since the Iron Age and Roman periods, with evidence of Roman villas and forts in the region.",
      "date": "-0043"
    },
    {
      "headline": "Bristol's Founding",
      "text": "Bristol was founded as a town in the early 11th century. The name 'Bristol' is derived from the Old English 'Brycgstow', meaning 'the place at the bridge'.",
      "date": "1000"
    },
    {
      "headline": "Bristol's First Charter",
      "text": "In 1155, Bristol was granted its first charter by King Henry II, establishing it as a city and granting it certain rights and privileges.",
      "date": "1155"
    },
    {
      "headline": "Bristol as a County",
      "text": "In 1373, Bristol was made a county in its own right, separate from Gloucestershire and Somerset.",
      "date": "1373"
    },
    {
      "headline": "John Cabot's Voyage",
      "text": "In 1497, John Cabot set sail from Bristol on the ship Matthew and discovered Newfoundland, marking one of the earliest European explorations of North America.",
      "date": "1497"
    },
    {
      "headline": "Bristol Slave Trade",
      "text": "During the 17th and 18th centuries, Bristol became a major port in the transatlantic slave trade, with ships transporting enslaved Africans to the Americas.",
      "date": "1600"
    },
    {
      "headline": "Bristol Riots",
      "text": "In 1831, the Bristol Riots occurred in response to the rejection of the Second Reform Bill, which aimed to reform the electoral system.",
      "date": "1831"
    },
    {
      "headline": "Great Western Railway",
      "text": "In 1841, the Great Western Railway, engineered by Isambard Kingdom Brunel, opened, connecting Bristol to London and enhancing trade and travel.",
      "date": "1841"
    },
    {
      "headline": "Bristol Blitz",
      "text": "During World War II, Bristol was heavily bombed by the Luftwaffe in a series of raids known as the Bristol Blitz, causing significant damage to the city.",
      "date": "1940"
    },
    {
      "headline": "Bristol Bus Boycott",
      "text": "In 1963, the Bristol Bus Boycott took place, protesting against the Bristol Omnibus Company's refusal to employ Black or Asian bus crews, leading to changes in employment practices.",
      "date": "1963"
    },
    {
      "headline": "Bristol as a Unitary Authority",
      "text": "In 1996, Bristol became a unitary authority, gaining independence from the county of Avon.",
      "date": "1996"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Construction of R/P FLIP",
      "text": "R/P FLIP was constructed in 1962. It was designed as an open ocean research platform by the U.S. Office of Naval Research and operated by the Scripps Institution of Oceanography.",
      "date": "1962"
    },
    {
      "headline": "First Deployment",
      "text": "R/P FLIP was first deployed in 1962. The platform is 108 meters long and is designed to partially flood and pitch backward 90°, resulting in only the front 17 meters of the platform pointing up out of the water.",
      "date": "1962"
    },
    {
      "headline": "Innovative Design",
      "text": "R/P FLIP's innovative design allows it to be stable and mostly immune to wave action, similar to a spar buoy. This is achieved by having most of the buoyancy provided by water at depths below the influence of surface waves.",
      "date": "1962"
    },
    {
      "headline": "Operational Use",
      "text": "Throughout its operational life, R/P FLIP has been used for various oceanographic research missions. It has no propulsion and is towed to different locations for research purposes.",
      "date": "1962-2023"
    },
    {
      "headline": "Decommissioning",
      "text": "R/P FLIP was decommissioned in August 2023 after more than 50 years of service in oceanographic research.",
      "date": "2023-08"
    }
  ]
}

