      "text": "The first written evidence for Baku dates back to the 1st century AD, when it was mentioned by the Roman historian Pliny the Elder.",
      "date": "0001"
    },
    {
      "headline": "Baku Becomes Part of the Sassanian Empire",
      "text": "In the 3rd century, Baku became part of the Sassanian Empire, which ruled over the region until the Arab conquest.",
      "date": "0300"
    },
    {
      "headline": "Arab Conquest",
      "text": "In the 7th century, Baku was conquered by the Arabs and became part of the Islamic Caliphate.",
      "date": "0700"
    },
    {
      "headline": "Shirvanshahs' Rule",
      "text": "From the 9th to the 16th century, Baku was ruled by the Shirvanshahs, a local dynasty that contributed to the city's development.",
      "date": "0900"
    },
    {
      "headline": "Baku Captured by the Safavid Empire",
      "text": "In 1501, Baku was captured by the Safavid Empire, marking the beginning of Persian influence in the city.",
      "date": "1501"
    },
    {
      "headline": "Russian Conquest of Baku",
      "text": "In 1806, Baku was captured by the Russian Empire during the Russo-Persian War.",
      "date": "1806"
    },
    {
      "headline": "Oil Boom Begins",
      "text": "In the late 19th century, Baku experienced an oil boom, becoming one of the world's leading oil producers.",
      "date": "1870"
    },
    {
      "headline": "Baku Becomes Capital of Azerbaijan SSR",
      "text": "In 1920, Baku became the capital of the Azerbaijan Soviet Socialist Republic, part of the Soviet Union.",
      "date": "1920"
    },
    {
      "headline": "Independence of Azerbaijan",
      "text": "In 1991, following the dissolution of the Soviet Union, Baku became the capital of the independent Republic of Azerbaijan.",
      "date": "1991"
    },
    {
      "headline": "Baku Hosts Eurovision Song Contest",
      "text": "In 2012, Baku hosted the Eurovision Song Contest, showcasing the city on an international stage.",
      "date": "2012"
    }
  ]
}

