    {
      "headline": "Inception of the Ranji Trophy",
      "text": "The Ranji Trophy was founded in 1934 by the Board of Control for Cricket in India (BCCI) as a premier domestic first-class cricket championship in India.",
      "date": "1934"
    },
    {
      "headline": "First Ranji Trophy Tournament",
      "text": "The first Ranji Trophy tournament was held in the 1934-35 season. The championship was named after Ranjitsinhji, the famous Indian cricketer who played for England.",
      "date": "1934"
    },
    {
      "headline": "First Ranji Trophy Winner",
      "text": "Bombay (now Mumbai) won the inaugural Ranji Trophy in the 1934-35 season, defeating Northern India in the final.",
      "date": "1935"
    },
    {
      "headline": "Introduction of Zonal System",
      "text": "In 1952, the zonal system was introduced to the Ranji Trophy, dividing teams into five zones: North, South, East, West, and Central.",
      "date": "1952"
    },
    {
      "headline": "Bombay's Dominance",
      "text": "Bombay (Mumbai) dominated the Ranji Trophy from the 1950s to the 1970s, winning the championship 15 consecutive times from 1958-59 to 1972-73.",
      "date": "1958"
    },
    {
      "headline": "Introduction of Knockout Stage",
      "text": "In 1970-71, the Ranji Trophy format was changed to include a knockout stage after the zonal league phase.",
      "date": "1970"
    },
    {
      "headline": "Introduction of Elite and Plate Divisions",
      "text": "In the 2002-03 season, the Ranji Trophy was divided into Elite and Plate divisions to increase competitiveness.",
      "date": "2002"
    },
    {
      "headline": "Reversion to Group Format",
      "text": "In the 2012-13 season, the Ranji Trophy reverted to a group format with three groups, A, B, and C, replacing the Elite and Plate divisions.",
      "date": "2012"
    },
    {
      "headline": "Introduction of Neutral Venues",
      "text": "In the 2016-17 season, the BCCI introduced neutral venues for the Ranji Trophy matches to eliminate home advantage.",
      "date": "2016"
    },
    {
      "headline": "Impact of COVID-19 Pandemic",
      "text": "The 2020-21 Ranji Trophy season was canceled due to the COVID-19 pandemic, marking the first time the tournament was not held since its inception.",
      "date": "2020"
    }
  ]
}

