{
  "timeline": [
    {
      "headline": "Franklin D. Roosevelt Elected President",
      "text": "Franklin D. Roosevelt was elected as the 32nd President of the United States in a landslide victory over incumbent Herbert Hoover. This election set the stage for the implementation of the New Deal programs. Date: November 8, 1932.",
      "date": "1932-11-08"
    },
    {
      "headline": "Roosevelt Inaugurated as President",
      "text": "Franklin D. Roosevelt was inaugurated as President of the United States, marking the beginning of his first term and the start of the New Deal era. Date: March 4, 1933.",
      "date": "1933-03-04"
    },
    {
      "headline": "Emergency Banking Act Passed",
      "text": "The Emergency Banking Act was passed by Congress to stabilize the banking system. It was signed into law by Roosevelt on March 9, 1933, during the Great Depression.",
      "date": "1933-03-09"
    },
    {
      "headline": "Civilian Conservation Corps Established",
      "text": "The Civilian Conservation Corps (CCC) was established on March 31, 1933, as part of the New Deal to provide jobs in natural resource conservation.",
      "date": "1933-03-31"
    },
    {
      "headline": "Federal Emergency Relief Administration Created",
      "text": "The Federal Emergency Relief Administration (FERA) was created on May 12, 1933, to provide direct relief for the unemployed.",
      "date": "1933-05-12"
    },
    {
      "headline": "Tennessee Valley Authority Act Signed",
      "text": "The Tennessee Valley Authority (TVA) Act was signed into law on May 18, 1933, to provide navigation, flood control, electricity generation, and economic development in the Tennessee Valley.",
      "date": "1933-05-18"
    },
    {
      "headline": "National Industrial Recovery Act Enacted",
      "text": "The National Industrial Recovery Act (NIRA) was enacted on June 16, 1933, to promote industrial recovery and establish fair competition codes.",
      "date": "1933-06-16"
    },
    {
      "headline": "Public Works Administration Established",
      "text": "The Public Works Administration (PWA) was established in June 1933 as part of the NIRA to fund large-scale public works projects.",
      "date": "1933-06"
    },
    {
      "headline": "Agricultural Adjustment Act Passed",
      "text": "The Agricultural Adjustment Act (AAA) was passed on May 12, 1933, to boost agricultural prices by reducing surpluses.",
      "date": "1933-05-12"
    },
    {
      "headline": "Securities Act of 1933 Enacted",
      "text": "The Securities Act of 1933 was enacted on May 27, 1933, to regulate the securities industry and protect investors.",
      "date": "1933-05-27"
    },
    {
      "headline": "Social Security Act Signed",
      "text": "The Social Security Act was signed into law on August 14, 1935, establishing a system of old-age benefits and unemployment insurance.",
      "date": "1935-08-14"
    },
    {
      "headline": "Wagner Act Passed",
      "text": "The Wagner Act, also known as the National Labor Relations Act, was passed on July 5, 1935, to protect workers' rights to organize and bargain collectively.",
      "date": "1935-07-05"
    },
    {
      "headline": "Works Progress Administration Established",
      "text": "The Works Progress Administration (WPA) was established on May 6, 1935, to provide jobs for unemployed Americans during the Great Depression.",
      "date": "1935-05-06"
    },
    {
      "headline": "Fair Labor Standards Act Enacted",
      "text": "The Fair Labor Standards Act was enacted on June 25, 1938, establishing minimum wage, overtime pay eligibility, and child labor standards.",
      "date": "1938-06-25"
    }
  ]
}

