{
  "timeline": [
    {
      "headline": "Tauric Chersonese",
      "text": "Crimea was known as the Tauric Chersonese in ancient times, inhabited by the Tauri people.",
      "date": "-0500"
    },
    {
      "headline": "Greek Colonization",
      "text": "Greek settlers established colonies in Crimea, including Chersonesus and Panticapaeum, around the 7th century BCE.",
      "date": "-0700"
    },
    {
      "headline": "Roman Influence",
      "text": "Crimea came under Roman influence in the 1st century BCE, with the establishment of Roman client states.",
      "date": "-0063"
    },
    {
      "headline": "Gothic and Hunnic Invasions",
      "text": "Crimea was invaded by the Goths in the 3rd century CE and later by the Huns in the 4th century.",
      "date": "0300"
    },
    {
      "headline": "Byzantine Control",
      "text": "The Byzantine Empire exerted control over parts of Crimea from the 6th century onwards.",
      "date": "0500"
    },
    {
      "headline": "Khazar Rule",
      "text": "The Khazar Khaganate controlled Crimea from the 7th to the 10th century.",
      "date": "0650"
    },
    {
      "headline": "Kievan Rus' Influence",
      "text": "Crimea was influenced by the Kievan Rus' in the 10th century, with the establishment of trade routes.",
      "date": "0900"
    },
    {
      "headline": "Mongol Invasion",
      "text": "The Mongols invaded Crimea in the 13th century, establishing the Crimean Khanate.",
      "date": "1239"
    },
    {
      "headline": "Ottoman Empire Control",
      "text": "Crimea became a vassal state of the Ottoman Empire in 1475.",
      "date": "1475"
    },
    {
      "headline": "Annexation by the Russian Empire",
      "text": "Crimea was annexed by the Russian Empire in 1783 following the Russo-Turkish War.",
      "date": "1783"
    },
    {
      "headline": "Crimean War",
      "text": "The Crimean War took place from 1853 to 1856, involving Russia against an alliance of the Ottoman Empire, France, Britain, and Sardinia.",
      "date": "1853"
    },
    {
      "headline": "Transfer to the Ukrainian SSR",
      "text": "In 1954, Crimea was transferred from the Russian SFSR to the Ukrainian SSR by the Soviet Union.",
      "date": "1954"
    },
    {
      "headline": "Ukrainian Independence",
      "text": "Following the dissolution of the Soviet Union, Crimea became part of independent Ukraine in 1991.",
      "date": "1991"
    },
    {
      "headline": "Annexation by Russia",
      "text": "In 2014, Russia annexed Crimea following a disputed referendum, leading to international condemnation.",
      "date": "2014"
    }
  ]
}

{
