      "date": "2022-03"
    },
    {
      "headline": "AAP Granted National Party Status",
      "text": "On 10 April 2023, the Aam Aadmi Party was officially granted the status of a national party by the Election Commission of India.",
      "date": "2023-04-10"
    },
    {
      "headline": "Awadh Ojha Joins AAP",
