      "headline": "Settlement of Micronesia",
      "text": "The first settlers arrived in Micronesia around 2000 BCE, likely from Southeast Asia, marking the beginning of human habitation in the region.",
      "date": "-2000"
    },
    {
      "headline": "Development of the Saudeleur Dynasty",
      "text": "Around 1100 CE, the Saudeleur Dynasty was established on the island of Pohnpei, known for constructing the megalithic city of Nan Madol.",
      "date": "1100"
    },
    {
      "headline": "European Contact",
      "text": "In 1521, Portuguese explorer Ferdinand Magellan became the first European to reach the islands of Micronesia during his circumnavigation of the globe.",
      "date": "1521"
    },
    {
      "headline": "Spanish Colonization",
      "text": "In 1565, Spain claimed the islands of Micronesia as part of the Spanish East Indies, initiating a period of colonial rule.",
      "date": "1565"
    },
    {
      "headline": "German Purchase of Micronesia",
      "text": "In 1899, following the Spanish-American War, Spain sold its Micronesian territories to Germany under the German-Spanish Treaty.",
      "date": "1899"
    },
    {
      "headline": "Japanese Control",
      "text": "In 1914, during World War I, Japan seized control of Micronesia from Germany and later received a League of Nations mandate to govern the islands.",
      "date": "1914"
    },
    {
      "headline": "United States Administration",
      "text": "After World War II, in 1947, the United Nations established the Trust Territory of the Pacific Islands, placing Micronesia under U.S. administration.",
      "date": "1947"
    },
    {
      "headline": "Federated States of Micronesia Independence",
      "text": "On November 3, 1986, the Federated States of Micronesia became independent, entering into a Compact of Free Association with the United States.",
      "date": "1986-11-03"
    }
  ]
}

