    {
      "headline": "Creation of the Voynich Manuscript",
      "text": "The vellum of the Voynich manuscript has been carbon-dated to the early 15th century, specifically between 1404 and 1438. Stylistic analysis suggests it may have been composed in Italy during the Italian Renaissance.",
      "date": "1404"
    },
    {
      "headline": "Wilfrid Voynich Acquires the Manuscript",
      "text": "In 1912, Wilfrid Voynich, a Polish book dealer, acquired the manuscript from the Jesuit College at Frascati, near Rome.",
      "date": "1912"
    },
    {
      "headline": "Voynich Manuscript Gains Public Attention",
      "text": "After acquiring the manuscript, Wilfrid Voynich began to publicize it, sparking interest and speculation about its origins and meaning.",
      "date": "1912"
    },
    {
      "headline": "Voynich Manuscript Becomes Widely Known",
      "text": "In the 1920s, the manuscript became widely known among scholars and cryptographers, leading to numerous attempts to decipher its contents.",
      "date": "1920"
    },
    {
      "headline": "Voynich Manuscript at Yale University",
      "text": "The Voynich manuscript was donated to Yale University's Beinecke Rare Book & Manuscript Library in 1969, where it remains today.",
      "date": "1969"
    }
  ]
}

