{
  "timeline": [
    {
      "headline": "First Paralympic Games",
      "text": "The first official Paralympic Games were held in Rome, Italy, in 1960. These Games featured 400 athletes from 23 countries.",
      "date": "1960"
    },
    {
      "headline": "First Winter Paralympic Games",
      "text": "The first Winter Paralympic Games took place in Örnsköldsvik, Sweden, in 1976. This event included athletes with physical disabilities and visual impairments.",
      "date": "1976"
    },
    {
      "headline": "Integration with the Olympic Games",
      "text": "Starting with the 1988 Summer Olympics in Seoul, South Korea, the Paralympic Games have been held shortly after the corresponding Olympic Games.",
      "date": "1988"
    },
    {
      "headline": "Establishment of the International Paralympic Committee",
      "text": "The International Paralympic Committee (IPC) was founded in Düsseldorf, Germany, on September 22, 1989, to act as the global governing body of the Paralympic Movement.",
      "date": "1989-09-22"
    },
    {
      "headline": "First Unified Paralympic Games",
      "text": "The 1992 Summer Paralympics in Barcelona, Spain, were the first to be held in the same city as the Olympics, marking a significant step towards integration.",
      "date": "1992"
    },
    {
      "headline": "Introduction of the IPC Classification Code",
      "text": "In 2003, the IPC introduced the Classification Code to ensure fair competition by classifying athletes based on their disabilities.",
      "date": "2003"
    },
    {
      "headline": "First Paralympic Games in South America",
      "text": "The 2016 Summer Paralympics were held in Rio de Janeiro, Brazil, marking the first time the Games were hosted in South America.",
      "date": "2016"
    },
    {
      "headline": "Postponement of the Tokyo 2020 Paralympics",
      "text": "Due to the COVID-19 pandemic, the Tokyo 2020 Paralympic Games were postponed to 2021, marking the first postponement in Paralympic history.",
      "date": "2020"
    }
  ]
}

