{
  "timeline": [
    {
      "headline": "Establishment of Ladakh Kingdom",
      "text": "The Kingdom of Ladakh was established in the 10th century by the descendants of the Tibetan royal family.",
      "date": "0900"
    },
    {
      "headline": "Ladakh under Namgyal Dynasty",
      "text": "In the early 17th century, the Namgyal dynasty came to power in Ladakh, marking a period of expansion and consolidation.",
      "date": "1600"
    },
    {
      "headline": "Invasion by the Mughal Empire",
      "text": "In 1684, Ladakh was invaded by the Mughal Empire, leading to the Treaty of Tingmosgang which established Ladakh as a tributary of the Mughals.",
      "date": "1684"
    },
    {
      "headline": "Dogra Conquest of Ladakh",
      "text": "In 1834, the Dogra general Zorawar Singh invaded and annexed Ladakh to the Sikh Empire.",
      "date": "1834"
    },
    {
      "headline": "Ladakh under British Raj",
      "text": "Following the First Anglo-Sikh War, Ladakh became part of the princely state of Jammu and Kashmir under British suzerainty in 1846.",
      "date": "1846"
    },
    {
      "headline": "Partition of India",
      "text": "In 1947, the partition of India led to the division of the princely state of Jammu and Kashmir, with Ladakh becoming part of India.",
      "date": "1947"
    },
    {
      "headline": "Sino-Indian War",
      "text": "In 1962, the Sino-Indian War resulted in China gaining control over the Aksai Chin region, which India claims as part of Ladakh.",
      "date": "1962"
    },
    {
      "headline": "Formation of Union Territory",
      "text": "On October 31, 2019, Ladakh was officially declared a union territory of India, separate from Jammu and Kashmir.",
      "date": "2019-10-31"
    }
  ]
}

