{
  "timeline": [
    {
      "headline": "Birth of Walt Whitman",
      "text": "Walter Whitman Jr. was born on May 31, 1819, in West Hills, Town of Huntington, Long Island, New York.",
      "date": "1819-05-31"
    },
    {
      "headline": "First Job as a Printer",
      "text": "In 1831, at the age of 12, Whitman began working as a printer's apprentice in Brooklyn.",
      "date": "1831"
    },
    {
      "headline": "Teaching Career",
      "text": "Whitman began his career as a teacher in 1836, working in various schools on Long Island until 1841.",
      "date": "1836"
    },
    {
      "headline": "Journalism Career",
      "text": "In 1841, Whitman moved to New York City and began working as a journalist, editor, and freelance writer.",
      "date": "1841"
    },
    {
      "headline": "Publication of Leaves of Grass",
      "text": "Whitman self-published the first edition of Leaves of Grass on July 4, 1855. The collection was noted for its innovative free verse style.",
      "date": "1855-07-04"
    },
    {
      "headline": "Second Edition of Leaves of Grass",
      "text": "In 1856, Whitman published the second edition of Leaves of Grass, which included 20 new poems.",
      "date": "1856"
    },
    {
      "headline": "Civil War Service",
      "text": "During the American Civil War, Whitman volunteered as a nurse in army hospitals in Washington, D.C., from 1862 to 1865.",
      "date": "1862"
    },
    {
      "headline": "Publication of Drum-Taps",
      "text": "In 1865, Whitman published Drum-Taps, a collection of poems inspired by his experiences during the Civil War.",
      "date": "1865"
    },
    {
      "headline": "Federal Government Employment",
      "text": "Whitman worked for the federal government in Washington, D.C., from 1865 to 1873, holding various clerical positions.",
      "date": "1865"
    },
    {
      "headline": "Stroke and Move to Camden",
      "text": "In 1873, Whitman suffered a stroke that left him partially paralyzed. He moved to Camden, New Jersey, to live with his brother.",
      "date": "1873"
    },
    {
      "headline": "Publication of Specimen Days",
      "text": "In 1882, Whitman published Specimen Days, a collection of prose works that included autobiographical sketches.",
      "date": "1882"
    },
    {
      "headline": "Final Edition of Leaves of Grass",
      "text": "The final edition of Leaves of Grass, known as the 'Deathbed Edition,' was published in 1892.",
      "date": "1892"
    },
    {
      "headline": "Death of Walt Whitman",
      "text": "Walt Whitman died on March 26, 1892, in Camden, New Jersey, at the age of 72.",
      "date": "1892-03-26"
    }
  ]
}

