    }
  ]
}

{
  "timeline": [
    {
      "headline": "Discovery of Sirius as a Binary Star",
      "text": "In 1844, Friedrich Bessel deduced that Sirius was a binary star system due to the wobbling motion of Sirius A, suggesting the presence of an unseen companion.",
      "date": "1844"
    },
    {
      "headline": "Observation of Sirius B",
      "text": "In 1862, Alvan Graham Clark observed Sirius B, the faint white dwarf companion to Sirius A, confirming Bessel's earlier hypothesis.",
      "date": "1862"
    },
    {
      "headline": "Spectral Classification of Sirius A",
      "text": "In the early 20th century, Sirius A was classified as a main-sequence star of spectral type A0 or A1, based on its spectral characteristics.",
      "date": "1900"
    },
    {
      "headline": "Orbital Period of Sirius Binary System",
      "text": "The orbital period of the Sirius binary system was determined to be approximately 50 years, with the distance between Sirius A and Sirius B varying between 8.2 and 31.5 astronomical units.",
      "date": "1900"
    },
    {
      "headline": "Sirius B as a White Dwarf",
      "text": "Sirius B was identified as a white dwarf of spectral type DA2, making it one of the first white dwarfs to be discovered.",
      "date": "1915"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Early Christian Observance",
      "text": "Epiphany is one of the oldest Christian feasts, celebrated since the end of the second century, even before the Christmas holiday was established.",
      "date": "0200"
    },
    {
      "headline": "Council of Tours",
      "text": "In 567, the Council of Tours proclaimed the twelve days from Christmas to Epiphany as a sacred and festive season, establishing the period known as Christmastide.",
      "date": "0567"
    },
    {
      "headline": "Western Church Tradition",
      "text": "In the Western Christian tradition, Epiphany commemorates the visit of the Magi to the Christ child, representing Jesus' physical manifestation to the Gentiles. This tradition became more established in the early Middle Ages.",
      "date": "0700"
    },
    {
      "headline": "Eastern Church Tradition",
      "text": "In the Eastern Orthodox Church, Epiphany, also known as Theophany, primarily commemorates the baptism of Jesus in the Jordan River, revealing the Holy Trinity to humanity. This tradition has been observed since ancient times.",
      "date": "0700"
    },
    {
      "headline": "Adoption of January 6th",
      "text": "By the 4th century, January 6th was widely recognized as the date for celebrating Epiphany in both Eastern and Western Christian traditions.",
      "date": "0400"
    },
    {
      "headline": "Introduction of the Blessing of Waters",
      "text": "The Blessing of Waters, a significant ritual in the Eastern Orthodox celebration of Epiphany, was introduced to symbolize the sanctification of the world through Christ's baptism.",
      "date": "0800"
    },
    {
      "headline": "Twelfth Night Celebrations",
      "text": "In medieval and early modern Europe, the eve of Epiphany, known as Twelfth Night, became a time of feasting and merrymaking, marking the end of the Christmas season.",
      "date": "1500"
    },
    {
      "headline": "Modern Observance",
      "text": "Today, Epiphany is celebrated by Christians around the world with various customs and traditions, including processions, the blessing of homes, and the sharing of special pastries like the King Cake.",
      "date": "2023"
    }
  ]
}

