    {
      "headline": "Napoleon Invades Russia",
      "text": "On June 24, 1812, Napoleon Bonaparte led his Grande Armée across the Neman River, marking the beginning of the French invasion of Russia. This campaign was initiated to compel Russia to comply with the continental blockade against the United Kingdom.",
      "date": "1812-06-24"
    },
    {
      "headline": "Battle of Smolensk",
      "text": "The Battle of Smolensk took place from August 16 to August 18, 1812. It was one of the first major battles of the invasion, resulting in a French victory but with significant casualties on both sides.",
      "date": "1812-08-16"
    },
    {
      "headline": "Battle of Borodino",
      "text": "On September 7, 1812, the Battle of Borodino occurred. It was the largest and bloodiest single-day action of the Napoleonic Wars, resulting in a tactical French victory but with heavy losses.",
      "date": "1812-09-07"
    },
    {
      "headline": "Capture of Moscow",
      "text": "Napoleon's forces entered Moscow on September 14, 1812. However, the city was largely abandoned and set on fire by the retreating Russian army, denying Napoleon the victory he sought.",
      "date": "1812-09-14"
    },
    {
      "headline": "French Retreat from Moscow",
      "text": "On October 19, 1812, Napoleon began the retreat from Moscow due to the onset of winter and lack of supplies. This retreat marked the beginning of the end for the French invasion.",
      "date": "1812-10-19"
    },
    {
      "headline": "Battle of Berezina",
      "text": "The Battle of Berezina took place from November 26 to November 29, 1812. It was a critical engagement during the retreat, where the French managed to escape across the Berezina River but suffered heavy losses.",
      "date": "1812-11-26"
    },
    {
      "headline": "End of the Campaign",
      "text": "By December 14, 1812, the remnants of Napoleon's Grande Armée had exited Russian territory. The campaign ended in a disastrous defeat for the French, with massive casualties and loss of resources.",
      "date": "1812-12-14"
    }
  ]
}

