{
  "timeline": [
    {
      "headline": "Formation of the Plot",
      "text": "In early 1604, Robert Catesby began to recruit a group of English Catholics to assassinate King James I and restore a Catholic monarch to the throne.",
      "date": "1604"
    },
    {
      "headline": "Initial Meeting",
      "text": "On May 20, 1604, the initial conspirators, including Robert Catesby, Thomas Wintour, John Wright, Thomas Percy, and Guy Fawkes, met at the Duck and Drake Inn in London to plan the assassination.",
      "date": "1604-05-20"
    },
    {
      "headline": "Lease of the Undercroft",
      "text": "In March 1605, the conspirators leased a cellar beneath the House of Lords, where they planned to store gunpowder.",
      "date": "1605-03"
    },
    {
      "headline": "Discovery of the Plot",
      "text": "On November 5, 1605, the Gunpowder Plot was discovered when Guy Fawkes was found guarding 36 barrels of gunpowder in the cellar beneath the House of Lords.",
      "date": "1605-11-05"
    },
    {
      "headline": "Arrest of Guy Fawkes",
      "text": "Guy Fawkes was arrested on November 5, 1605, after being discovered in the cellar with the gunpowder.",
      "date": "1605-11-05"
    },
    {
      "headline": "Capture and Death of Robert Catesby",
      "text": "Robert Catesby was killed on November 8, 1605, during a shootout with the authorities at Holbeche House in Staffordshire.",
      "date": "1605-11-08"
    },
    {
      "headline": "Trial of the Conspirators",
      "text": "The surviving conspirators were tried on January 27, 1606, and found guilty of high treason.",
      "date": "1606-01-27"
    },
    {
      "headline": "Execution of the Conspirators",
      "text": "On January 30 and 31, 1606, the conspirators, including Guy Fawkes, were executed by hanging, drawing, and quartering.",
      "date": "1606-01-30"
    }
  ]
}

