{
  "timeline": [
    {
      "headline": "Emergence of Hominini",
      "text": "The tribe Hominini, which includes humans and their ancestors, diverged from the common ancestor with chimpanzees and bonobos. This divergence is estimated to have occurred around 6 to 7 million years ago.",
      "date": "-7000000"
    },
    {
      "headline": "Appearance of Australopithecus",
      "text": "Australopithecus, an early hominin genus, appeared around 4 million years ago. These species were bipedal and are considered a significant step in human evolution.",
      "date": "-4000000"
    },
    {
      "headline": "Emergence of Homo habilis",
      "text": "Homo habilis, one of the earliest members of the genus Homo, appeared around 2.4 million years ago. They are known for using stone tools.",
      "date": "-2400000"
    },
    {
      "headline": "Appearance of Homo erectus",
      "text": "Homo erectus emerged around 1.9 million years ago. They were the first hominins to have body proportions similar to modern humans and were capable of long-distance walking.",
      "date": "-1900000"
    },
    {
      "headline": "Control of Fire",
      "text": "Evidence suggests that Homo erectus began using fire around 1 million years ago, which was a significant development in human evolution.",
      "date": "-1000000"
    },
    {
      "headline": "Emergence of Neanderthals",
      "text": "Neanderthals, a distinct species of the genus Homo, appeared around 400,000 years ago in Europe and parts of Asia.",
      "date": "-400000"
    },
    {
      "headline": "Appearance of Homo sapiens",
      "text": "Homo sapiens, the species to which all modern human beings belong, first appeared in Africa around 300,000 years ago.",
      "date": "-300000"
    },
    {
      "headline": "Out of Africa Migration",
      "text": "Homo sapiens began migrating out of Africa around 70,000 years ago, spreading across the globe.",
      "date": "-70000"
    },
