    {
      "headline": "Establishment of the Fédération Internationale d'Escrime (FIE)",
      "text": "The Fédération Internationale d'Escrime (FIE), the international governing body of fencing, was established in 1913 to oversee the sport worldwide.",
      "date": "1913"
    },
    {
      "headline": "Introduction of Electric Scoring",
      "text": "Electric scoring was introduced to fencing competitions in the 1930s, initially for épée, to improve the accuracy of scoring.",
      "date": "1930"
    },
    {
      "headline": "Electric Scoring for Foil and Sabre",
      "text": "Electric scoring was later adopted for foil in 1956 and for sabre in 1988, further enhancing the precision of scoring in fencing competitions.",
      "date": "1956"
    }
  ]
}

