    },
    {
      "headline": "Death of Maharaja Gangadhar Rao",
      "text": "Maharaja Gangadhar Rao died in 1853, leaving Rani Lakshmibai as the regent for their adopted son, Damodar Rao.",
      "date": "1853"
    },
    {
      "headline": "Annexation of Jhansi by the British",
      "text": "In 1854, under the Doctrine of Lapse, the British East India Company annexed Jhansi, rejecting Damodar Rao's claim to the throne.",
      "date": "1854"
    },
    {
      "headline": "Indian Rebellion of 1857",
      "text": "Rani Lakshmibai became one of the leading figures in the Indian Rebellion of 1857, resisting British rule and becoming a symbol of resistance.",
      "date": "1857"
    },
    {
      "headline": "Battle of Jhansi",
      "text": "In March 1858, Rani Lakshmibai defended Jhansi against British forces led by Hugh Rose. Despite a fierce battle, Jhansi fell to the British.",
      "date": "1858-03"
    },
    {
      "headline": "Death of Rani Lakshmibai",
      "text": "Rani Lakshmibai died on June 18, 1858, in Gwalior, India, during a battle against British forces.",
      "date": "1858-06-18"
    }
  ]
}

