{
  "timeline": [
    {
      "headline": "Formation of the Central Powers",
      "text": "The Central Powers were formed as a coalition of the German Empire, Austria-Hungary, the Ottoman Empire, and Bulgaria during World War I.",
      "date": "1914"
    },
    {
      "headline": "World War I Begins",
      "text": "World War I began on July 28, 1914, with the Central Powers fighting against the Allied Powers.",
      "date": "1914-07-28"
    },
    {
      "headline": "Ottoman Empire Joins the Central Powers",
      "text": "The Ottoman Empire joined the Central Powers on October 29, 1914, following the signing of a secret alliance with Germany.",
      "date": "1914-10-29"
    },
    {
      "headline": "Bulgaria Joins the Central Powers",
      "text": "Bulgaria joined the Central Powers on October 14, 1915, after signing a treaty with Germany and Austria-Hungary.",
      "date": "1915-10-14"
    },
    {
      "headline": "Battle of Verdun",
      "text": "The Battle of Verdun, one of the longest and most grueling battles of World War I, took place from February 21 to December 18, 1916, involving the Central Powers.",
      "date": "1916-02-21"
    },
    {
      "headline": "Battle of the Somme",
      "text": "The Battle of the Somme, another major battle involving the Central Powers, occurred from July 1 to November 18, 1916.",
      "date": "1916-07-01"
    },
