{
  "timeline": [
    {
      "headline": "Earliest Use of Opium",
      "text": "The earliest reference to opium poppy cultivation and opium use is from the Sumerians in Mesopotamia, who referred to it as the 'joy plant'. This dates back to around 3400 BCE.",
      "date": "-3400"
    },
    {
      "headline": "Opium in Ancient Egypt",
      "text": "Opium was used in ancient Egypt as early as 1500 BCE. It was mentioned in the Ebers Papyrus, an ancient Egyptian medical text.",
      "date": "-1500"
    },
    {
      "headline": "Opium in Ancient Greece",
      "text": "Homer's 'The Odyssey', written around 800 BCE, mentions the use of opium. The Greeks used opium for medicinal purposes.",
      "date": "-0800"
    },
    {
      "headline": "Opium in the Roman Empire",
      "text": "Opium was widely used in the Roman Empire for its medicinal properties. Galen, a prominent Greek physician in the Roman Empire, wrote extensively about opium's uses around 150 CE.",
      "date": "0150"
    },
    {
      "headline": "Spread of Opium to the Islamic World",
      "text": "During the Islamic Golden Age (8th to 13th centuries), opium was used in medicine and was spread throughout the Islamic world by Arab traders.",
      "date": "0800"
    },
    {
      "headline": "Opium in Medieval Europe",
      "text": "Opium was reintroduced to Europe through the Crusades in the 11th and 12th centuries. It was used in various medicinal concoctions.",
      "date": "1100"
    },
    {
      "headline": "Introduction of Opium to China",
      "text": "Opium was introduced to China by Arab traders in the 7th century, but its use became widespread during the Ming Dynasty (1368–1644).",
      "date": "1368"
    },
    {
      "headline": "Opium Wars",
      "text": "The First Opium War (1839-1842) and the Second Opium War (1856-1860) were conflicts between China and Western countries, primarily Britain, over trade imbalances and opium trade.",
      "date": "1839"
    },
    {
      "headline": "Morphine Isolated from Opium",
      "text": "In 1804, Friedrich Sertürner, a German pharmacist, isolated morphine from opium, marking a significant advancement in the use of opium derivatives for pain relief.",
      "date": "1804"
    },
    {
      "headline": "Heroin Synthesized from Morphine",
      "text": "In 1874, C.R. Alder Wright, an English chemist, synthesized heroin from morphine, which was later marketed by Bayer as a cough suppressant and pain reliever.",
      "date": "1874"
    },
    {
      "headline": "International Opium Convention",
      "text": "The first International Opium Convention was held in 1912 in The Hague, marking the beginning of international drug control efforts.",
      "date": "1912"
    }
  ]
}

