{
  "timeline": [
    {
      "headline": "First Mention of Frankfurt",
      "text": "The city of Frankfurt is first mentioned in historical records in the year 794 during the reign of Charlemagne.",
      "date": "0794"
    },
    {
      "headline": "Frankfurt Becomes a Free Imperial City",
      "text": "In 1372, Frankfurt was granted the status of a Free Imperial City, which allowed it to operate with a degree of autonomy within the Holy Roman Empire.",
      "date": "1372"
    },
    {
      "headline": "Coronation City of Holy Roman Emperors",
      "text": "From 1562, Frankfurt became the city where the Holy Roman Emperors were crowned, a tradition that continued until 1792.",
      "date": "1562"
    },
    {
      "headline": "Frankfurt Joins the German Confederation",
      "text": "In 1815, after the Napoleonic Wars, Frankfurt became a member of the German Confederation.",
      "date": "1815"
    },
    {
      "headline": "Frankfurt Parliament",
      "text": "In 1848, the Frankfurt Parliament, the first freely elected parliament for all of Germany, convened in the city.",
      "date": "1848"
    },
    {
      "headline": "Annexation by Prussia",
      "text": "In 1866, following the Austro-Prussian War, Frankfurt was annexed by the Kingdom of Prussia.",
      "date": "1866"
    },
    {
      "headline": "Frankfurt Becomes Part of the German Empire",
      "text": "In 1871, Frankfurt became part of the newly established German Empire.",
      "date": "1871"
    },
    {
      "headline": "Destruction in World War II",
      "text": "During World War II, Frankfurt suffered extensive damage from Allied bombing raids, particularly in 1944.",
      "date": "1944"
    },
    {
      "headline": "Reconstruction and Economic Growth",
      "text": "Post-World War II, Frankfurt underwent significant reconstruction and became a major financial center in Germany and Europe.",
      "date": "1945"
    },
    {
      "headline": "European Central Bank Headquarters",
      "text": "In 1998, the European Central Bank was established in Frankfurt, solidifying its status as a financial hub.",
