{
  "timeline": [
    {
      "headline": "Christopher Columbus's First Voyage",
      "text": "In 1492, Christopher Columbus, under the sponsorship of the Catholic Monarchs of Spain, embarked on his first voyage across the Atlantic Ocean, leading to the European discovery of the Americas.",
      "date": "1492"
    },
    {
      "headline": "Treaty of Tordesillas",
      "text": "On June 7, 1494, the Treaty of Tordesillas was signed between Spain and Portugal, dividing newly discovered lands outside Europe between them along a meridian 370 leagues west of the Cape Verde islands.",
      "date": "1494-06-07"
    },
    {
      "headline": "Conquest of the Aztec Empire",
      "text": "In 1521, Hernán Cortés led the Spanish conquest of the Aztec Empire, marking a significant expansion of Spanish territories in the Americas.",
      "date": "1521"
    },
    {
      "headline": "Conquest of the Inca Empire",
      "text": "In 1533, Francisco Pizarro and his brothers conquered the Inca Empire, further expanding Spanish control in South America.",
      "date": "1533"
    },
    {
      "headline": "Establishment of the Viceroyalty of New Spain",
      "text": "In 1535, the Viceroyalty of New Spain was established, encompassing territories in North America, Central America, Asia, and Oceania.",
      "date": "1535"
    },
    {
      "headline": "Battle of Lepanto",
      "text": "On October 7, 1571, the Spanish Empire, as part of the Holy League, defeated the Ottoman Empire in the Battle of Lepanto, marking a significant naval victory.",
      "date": "1571-10-07"
    },
    {
      "headline": "Spanish Armada",
      "text": "In 1588, the Spanish Armada was launched against England but was ultimately defeated, marking a turning point in the decline of Spanish naval dominance.",
      "date": "1588"
    },
    {
      "headline": "Union of the Crowns",
      "text": "In 1580, the Iberian Union was formed when Philip II of Spain became King of Portugal, uniting the two crowns under Spanish rule until 1640.",
      "date": "1580"
    },
    {
      "headline": "Peace of Westphalia",
      "text": "In 1648, the Peace of Westphalia ended the Thirty Years' War, resulting in territorial losses for the Spanish Empire and marking the decline of Spanish influence in Europe.",
      "date": "1648"
    },
    {
      "headline": "War of Spanish Succession",
      "text": "From 1701 to 1714, the War of Spanish Succession was fought over who should succeed to the Spanish throne, leading to the Treaty of Utrecht and the loss of several European territories.",
      "date": "1701"
    },
    {
      "headline": "Treaty of Utrecht",
      "text": "In 1713, the Treaty of Utrecht was signed, ending the War of Spanish Succession and resulting in the cession of Spanish territories in Europe to other powers.",
      "date": "1713"
    },
    {
      "headline": "Independence of Spanish American Colonies",
      "text": "Throughout the early 19th century, Spanish American colonies gained independence, significantly reducing the size of the Spanish Empire.",
      "date": "1808"
    },
    {
      "headline": "Spanish-American War",
      "text": "In 1898, the Spanish-American War resulted in Spain losing its last major overseas territories, including Cuba, Puerto Rico, Guam, and the Philippines.",
      "date": "1898"
    },
    {
      "headline": "End of the Spanish Empire",
      "text": "In 1976, the Spanish Empire effectively ended with the decolonization of the last Spanish territories in Africa.",
      "date": "1976"
    }
  ]
}

