{
  "timeline": [
    {
      "headline": "Roman Conquest of Andalusia",
      "text": "The Romans began their conquest of the Iberian Peninsula, including the region now known as Andalusia, around 206 BCE.",
      "date": "-0206"
    },
    {
      "headline": "Visigothic Rule",
      "text": "After the fall of the Roman Empire, the Visigoths took control of the region in the early 5th century.",
      "date": "0400"
    },
    {
      "headline": "Muslim Conquest",
      "text": "In 711, Muslim forces led by Tariq ibn Ziyad crossed the Strait of Gibraltar and began the conquest of the Iberian Peninsula, including Andalusia.",
      "date": "0711"
    },
    {
      "headline": "Umayyad Emirate Established",
      "text": "In 756, Abd al-Rahman I established the independent Emirate of Córdoba, marking the beginning of Muslim rule in Andalusia.",
      "date": "0756"
    },
    {
      "headline": "Caliphate of Córdoba",
      "text": "In 929, Abd al-Rahman III declared himself Caliph, establishing the Caliphate of Córdoba, which became a major cultural and economic center.",
      "date": "0929"
    },
    {
      "headline": "Fall of the Caliphate",
      "text": "The Caliphate of Córdoba collapsed in 1031, leading to the fragmentation into smaller kingdoms known as taifas.",
      "date": "1031"
    },
    {
      "headline": "Reconquista of Seville",
      "text": "In 1248, Ferdinand III of Castile captured Seville, marking a significant event in the Christian Reconquista of Andalusia.",
      "date": "1248"
    },
    {
      "headline": "Completion of the Reconquista",
      "text": "The Reconquista was completed in 1492 with the fall of Granada, the last Muslim stronghold in Andalusia, to the Catholic Monarchs Ferdinand and Isabella.",
      "date": "1492"
    },
    {
      "headline": "Andalusia in the Spanish Empire",
      "text": "During the 16th and 17th centuries, Andalusia became a major center of Spanish colonial trade and culture.",
      "date": "1500"
    },
    {
      "headline": "Napoleonic Invasion",
      "text": "In 1808, Andalusia was invaded by Napoleonic forces during the Peninsular War.",
      "date": "1808"
    },
    {
      "headline": "Establishment of Andalusian Autonomy",
      "text": "On December 30, 1981, Andalusia was officially recognized as an autonomous community within Spain.",
      "date": "1981-12-30"
    }
  ]
}

