{
  "timeline": [
    {
      "headline": "Origin of Vulgar Latin",
      "text": "Vulgar Latin, the non-standard form of Latin spoken by the common people in the Roman Empire, began to diverge into distinct languages after the fall of the Roman Empire. This process started around the 3rd century CE.",
      "date": "0300"
    },
    {
      "headline": "Fall of the Western Roman Empire",
      "text": "The fall of the Western Roman Empire in 476 CE accelerated the divergence of Vulgar Latin into distinct Romance languages as political fragmentation led to regional linguistic evolution.",
      "date": "0476"
    },
    {
      "headline": "Earliest Romance Language Texts",
      "text": "The earliest texts in Romance languages began to appear around the 9th century. These include the Oaths of Strasbourg (842 CE) and the Sequence of Saint Eulalia (circa 880 CE), which are among the earliest examples of Old French.",
      "date": "0842"
    },
    {
      "headline": "First Grammar of a Romance Language",
      "text": "In 1492, Antonio de Nebrija published 'Gramática de la lengua castellana', the first grammar of a Romance language, which was Spanish.",
      "date": "1492"
    },
    {
      "headline": "Standardization of Romance Languages",
      "text": "During the Renaissance and early modern period, many Romance languages underwent standardization. This included the creation of dictionaries and grammars, which helped to formalize languages like French, Italian, and Spanish.",
      "date": "1500"
    },
    {
      "headline": "Spread of Romance Languages",
      "text": "The Age of Exploration from the 15th to the 17th centuries saw the spread of Romance languages to the Americas, Africa, and Asia due to European colonialism, particularly by Spain, Portugal, and France.",
      "date": "1500"
    },
    {
      "headline": "Recognition of Romance Languages as Separate Languages",
      "text": "By the 19th century, Romance languages were widely recognized as distinct languages, each with its own literature, grammar, and vocabulary.",
      "date": "1800"
    }
  ]
}

