    },
    {
      "headline": "London Stock Exchange Founded",
      "text": "The London Stock Exchange was officially founded in 1801, becoming a major financial institution in the City.",
      "date": "1801"
    },
    {
      "headline": "The Blitz",
      "text": "During World War II, the City of London was heavily bombed during the Blitz, causing extensive damage.",
