    {
      "headline": "Albuquerque Becomes a Trade Center",
      "text": "Throughout the 18th century, Albuquerque developed as a trade center due to its strategic location on El Camino Real, the trade route linking Mexico City to the northernmost territories of New Spain.",
      "date": "1700s"
    },
    {
      "headline": "Mexican-American War",
      "text": "During the Mexican-American War, the United States Army occupied Albuquerque in 1846 without resistance, as part of the larger campaign to secure New Mexico for the United States.",
      "date": "1846"
