    {
      "headline": "Territorial Period",
      "text": "After the Treaty of Guadalupe Hidalgo in 1848, Albuquerque became part of the United States, marking the beginning of the Territorial Period.",
      "date": "1848"
    },
    {
      "headline": "Arrival of the Railroad",
      "text": "The Atchison, Topeka and Santa Fe Railway arrived in Albuquerque in 1880, which significantly boosted the city's growth and economic development.",
      "date": "1880"
    },
    {
      "headline": "Incorporation as a City",
      "text": "Albuquerque was officially incorporated as a city in 1891, marking its transition from a small settlement to a recognized urban area.",
      "date": "1891"
    },
    {
      "headline": "Establishment of Kirtland Air Force Base",
      "text": "Kirtland Air Force Base was established in 1941, becoming a major military installation and contributing to Albuquerque's growth during and after World War II.",
      "date": "1941"
    },
    {
      "headline": "University of New Mexico",
      "text": "The University of New Mexico, founded in 1889, became a significant educational and cultural institution in Albuquerque, contributing to the city's development.",
      "date": "1889"
    },
    {
      "headline": "Balloon Fiesta Inception",
      "text": "The first Albuquerque International Balloon Fiesta was held in 1972, growing to become the largest hot air balloon festival in the world and a major tourist attraction.",
      "date": "1972"
    }
  ]
}

