      "headline": "Foundation of Königsberg",
      "text": "Königsberg was founded in 1255 by the Teutonic Knights during the Northern Crusades. It was named in honor of King Ottokar II of Bohemia.",
      "date": "1255"
    },
    {
      "headline": "Königsberg becomes part of the Duchy of Prussia",
      "text": "In 1525, Königsberg became the capital of the Duchy of Prussia, following the secularization of the Teutonic Order's Prussian territories.",
      "date": "1525"
    },
    {
      "headline": "Königsberg becomes part of the Kingdom of Prussia",
      "text": "In 1701, Königsberg became part of the Kingdom of Prussia when Frederick I crowned himself King in Prussia.",
      "date": "1701"
    },
    {
      "headline": "Königsberg University founded",
      "text": "The University of Königsberg, known as Albertina, was founded in 1544 and became a major center of education and culture in the region.",
      "date": "1544"
    },
    {
      "headline": "Königsberg becomes part of the German Empire",
      "text": "In 1871, Königsberg became part of the German Empire following the unification of Germany.",
      "date": "1871"
    },
    {
      "headline": "World War II and the Battle of Königsberg",
      "text": "Königsberg was heavily damaged during World War II, particularly during the Battle of Königsberg in 1945 when Soviet forces captured the city.",
      "date": "1945"
    },
    {
      "headline": "Königsberg renamed Kaliningrad",
      "text": "In 1946, following the Potsdam Agreement, Königsberg was annexed by the Soviet Union and renamed Kaliningrad in honor of Mikhail Kalinin.",
      "date": "1946"
    },
    {
      "headline": "Kaliningrad becomes part of the Russian Federation",
      "text": "After the dissolution of the Soviet Union in 1991, Kaliningrad became part of the Russian Federation.",
      "date": "1991"
    }
  ]
}

