{
  "timeline": [
    {
      "headline": "Start of the Franco-Prussian War",
      "text": "The Franco-Prussian War began on 19 July 1870, when France declared war on the Kingdom of Prussia.",
      "date": "1870-07-19"
    },
    {
      "headline": "Battle of Wissembourg",
      "text": "The Battle of Wissembourg took place on 4 August 1870, marking the first major engagement of the war. Prussian forces defeated the French army.",
      "date": "1870-08-04"
    },
    {
      "headline": "Battle of Wörth",
      "text": "On 6 August 1870, the Battle of Wörth occurred, resulting in a decisive Prussian victory and forcing the French to retreat.",
      "date": "1870-08-06"
    },
    {
      "headline": "Battle of Sedan",
      "text": "The Battle of Sedan was fought on 1 September 1870. The French army, led by Emperor Napoleon III, was decisively defeated, leading to his capture.",
      "date": "1870-09-01"
    },
    {
      "headline": "Proclamation of the Third Republic",
      "text": "Following the defeat at Sedan, the French Third Republic was proclaimed on 4 September 1870, ending the Second French Empire.",
      "date": "1870-09-04"
    },
    {
      "headline": "Siege of Paris",
      "text": "The Siege of Paris began on 19 September 1870, with Prussian forces encircling the city. The siege lasted until the end of the war.",
      "date": "1870-09-19"
    },
    {
      "headline": "Battle of Le Mans",
      "text": "The Battle of Le Mans took place from 10 to 12 January 1871, resulting in a German victory over the French forces.",
      "date": "1871-01-10"
    },
    {
      "headline": "Proclamation of the German Empire",
      "text": "On 18 January 1871, the German Empire was proclaimed at the Palace of Versailles, with King Wilhelm I of Prussia being crowned as the German Emperor.",
      "date": "1871-01-18"
    },
    {
      "headline": "Armistice and End of the War",
      "text": "An armistice was signed on 28 January 1871, effectively ending the Franco-Prussian War.",
      "date": "1871-01-28"
    },
    {
      "headline": "Treaty of Frankfurt",
      "text": "The Treaty of Frankfurt was signed on 10 May 1871, formally ending the war and resulting in territorial losses for France, including Alsace and Lorraine.",
      "date": "1871-05-10"
    }
  ]
}

