{
  "timeline": [
    {
      "headline": "Origin of Black Lives Matter",
      "text": "The Black Lives Matter movement began in 2013 as a hashtag #BlackLivesMatter on social media, following the acquittal of George Zimmerman in the shooting death of African-American teen Trayvon Martin on July 13, 2013.",
      "date": "2013-07-13"
    },
    {
      "headline": "Ferguson Protests",
      "text": "In August 2014, the Black Lives Matter movement gained national attention for its role in the Ferguson protests, which were sparked by the shooting death of Michael Brown, an unarmed black teenager, by a white police officer in Ferguson, Missouri.",
      "date": "2014-08"
    },
    {
      "headline": "Formation of Black Lives Matter Global Network",
      "text": "In 2014, the Black Lives Matter Global Network was formed as an organization to provide a platform and support for the movement's activities and advocacy.",
      "date": "2014"
    },
    {
      "headline": "Protests Following the Death of Eric Garner",
      "text": "In December 2014, Black Lives Matter organized protests in response to the death of Eric Garner, who died in New York City after a police officer put him in a chokehold.",
      "date": "2014-12"
    },
    {
      "headline": "Protests Following the Death of Freddie Gray",
      "text": "In April 2015, Black Lives Matter was involved in protests in Baltimore, Maryland, following the death of Freddie Gray, who died from spinal injuries sustained while in police custody.",
      "date": "2015-04"
    },
    {
      "headline": "Protests Following the Death of Sandra Bland",
      "text": "In July 2015, Black Lives Matter organized protests after the death of Sandra Bland, who was found hanged in a jail cell in Texas after being arrested during a traffic stop.",
      "date": "2015-07"
    },
    {
      "headline": "Protests Following the Death of Alton Sterling and Philando Castile",
      "text": "In July 2016, Black Lives Matter led protests across the United States after the police shootings of Alton Sterling in Baton Rouge, Louisiana, and Philando Castile in Falcon Heights, Minnesota.",
      "date": "2016-07"
    },
    {
      "headline": "Protests Following the Death of George Floyd",
      "text": "In May 2020, Black Lives Matter organized nationwide protests following the death of George Floyd, an African-American man who died after a police officer knelt on his neck for over nine minutes in Minneapolis, Minnesota.",
      "date": "2020-05"
    },
    {
      "headline": "Global Protests and Expansion",
      "text": "In 2020, the Black Lives Matter movement expanded globally, with protests and demonstrations occurring in countries around the world in solidarity with the movement's goals and in response to local issues of racial injustice.",
      "date": "2020"
    },
    {
      "headline": "Nobel Peace Prize Nomination",
      "text": "In January 2021, the Black Lives Matter movement was nominated for the Nobel Peace Prize for its role in raising global awareness about racial injustice and inequality.",
      "date": "2021-01"
    }
  ]
}

