{
  "timeline": [
    {
      "headline": "Selection of Canberra as the Capital",
      "text": "In 1908, Canberra was selected as the site for the nation's capital. The decision was made after a long dispute between Sydney and Melbourne, the two largest cities in Australia.",
      "date": "1908"
    },
    {
      "headline": "Foundation of Canberra",
      "text": "On March 12, 1913, the city of Canberra was officially founded. The foundation stone was laid by the Governor-General, Lord Denman, and the city was named by Lady Denman.",
      "date": "1913-03-12"
    },
    {
      "headline": "Opening of the Provisional Parliament House",
      "text": "The Provisional Parliament House was opened on May 9, 1927, by the Duke of York (later King George VI). This event marked the official transfer of the Parliament of Australia from Melbourne to Canberra.",
      "date": "1927-05-09"
    },
    {
      "headline": "Establishment of the Australian National University",
      "text": "The Australian National University was established in Canberra in 1946, further cementing the city's status as a center for education and research.",
      "date": "1946"
    },
    {
      "headline": "Opening of the National Library of Australia",
      "text": "The National Library of Australia was officially opened in Canberra on August 15, 1968, providing a national repository for Australia's literary and historical materials.",
      "date": "1968-08-15"
    },
    {
      "headline": "Opening of the New Parliament House",
      "text": "The New Parliament House was opened on May 9, 1988, by Queen Elizabeth II. This modern building replaced the Provisional Parliament House as the meeting place of the Parliament of Australia.",
      "date": "1988-05-09"
    },
    {
      "headline": "Centenary of Canberra",
      "text": "In 2013, Canberra celebrated its centenary with a year-long program of events and activities to mark 100 years since its founding.",
      "date": "2013"
    }
  ]
}

