{
  "timeline": [
    {
      "headline": "Origins of Pizza",
      "text": "The origins of pizza can be traced back to ancient civilizations such as the Greeks, Egyptians, and Romans, who made flatbreads with toppings. However, the modern pizza as we know it began to take shape in Naples, Italy, in the late 18th century.",
      "date": "1700"
    },
    {
      "headline": "First Use of the Word 'Pizza'",
      "text": "The word 'pizza' was first documented in a Latin text from the southern Italian town of Gaeta in 997 AD.",
      "date": "0997"
    },
    {
      "headline": "Introduction of Tomatoes to Italy",
      "text": "Tomatoes were introduced to Europe from the Americas in the 16th century, but it wasn't until the late 18th century that they became a common topping for pizza in Naples.",
      "date": "1700"
    },
    {
      "headline": "Creation of Pizza Margherita",
      "text": "In 1889, Raffaele Esposito, a Neapolitan pizzaiolo, created the Pizza Margherita in honor of Queen Margherita of Savoy. The pizza featured tomatoes, mozzarella, and basil, representing the colors of the Italian flag.",
      "date": "1889"
    },
    {
      "headline": "Pizza's Popularity in the United States",
      "text": "Pizza was introduced to the United States by Italian immigrants in the late 19th and early 20th centuries. It gained popularity after World War II, when returning soldiers sought out the food they had enjoyed while stationed in Italy.",
      "date": "1945"
    },
    {
      "headline": "First Pizzeria in the United States",
      "text": "Gennaro Lombardi opened the first pizzeria in the United States, Lombardi's, in New York City in 1905.",
      "date": "1905"
    },
    {
      "headline": "Frozen Pizza Invented",
      "text": "In the 1950s, frozen pizza was invented, making it easier for people to enjoy pizza at home.",
      "date": "1950"
    },
    {
      "headline": "Pizza Hut Founded",
      "text": "Pizza Hut, one of the largest pizza chains in the world, was founded in 1958 in Wichita, Kansas, by brothers Dan and Frank Carney.",
      "date": "1958"
    },
    {
      "headline": "Domino's Pizza Founded",
      "text": "Domino's Pizza was founded in 1960 by Tom Monaghan and his brother James in Ypsilanti, Michigan.",
      "date": "1960"
    }
  ]
}

