{
  "timeline": [
    {
      "headline": "First European Sightings",
      "text": "In 1770, Lieutenant James Cook became the first European to sight the east coast of Australia, including what is now New South Wales, during his voyage on the HMS Endeavour.",
      "date": "1770"
    },
    {
      "headline": "First Fleet Arrives",
      "text": "On January 26, 1788, the First Fleet, led by Captain Arthur Phillip, arrived at Port Jackson, establishing the first European colony in New South Wales, which later became Sydney.",
      "date": "1788-01-26"
    },
    {
      "headline": "Proclamation of New South Wales",
      "text": "In 1788, New South Wales was officially proclaimed as a British colony, covering a vast area including much of the Australian continent.",
      "date": "1788"
    },
    {
      "headline": "Rum Rebellion",
      "text": "The Rum Rebellion occurred in 1808, when the New South Wales Corps, led by Major George Johnston, overthrew Governor William Bligh.",
      "date": "1808"
    },
    {
      "headline": "Establishment of Legislative Council",
      "text": "In 1825, the New South Wales Legislative Council was established, marking the beginning of representative government in the colony.",
      "date": "1825"
    },
    {
      "headline": "Separation of Victoria",
      "text": "In 1851, the colony of Victoria was separated from New South Wales, reducing its territory.",
      "date": "1851"
    },
    {
      "headline": "Gold Rush",
      "text": "The discovery of gold in New South Wales in 1851 led to a gold rush, significantly boosting the colony's economy and population.",
      "date": "1851"
    },
    {
      "headline": "Federation of Australia",
      "text": "On January 1, 1901, New South Wales became a state of the newly formed Commonwealth of Australia, following the federation of the Australian colonies.",
      "date": "1901-01-01"
    },
    {
      "headline": "Sydney Opera House Opening",
      "text": "The Sydney Opera House, an iconic symbol of New South Wales and Australia, was officially opened on October 20, 1973.",
      "date": "1973-10-20"
    },
    {
      "headline": "2000 Summer Olympics",
      "text": "Sydney, the capital of New South Wales, hosted the 2000 Summer Olympics, showcasing the state on an international stage.",
      "date": "2000"
    },
    {
      "headline": "Population Milestone",
      "text": "In December 2023, the population of New South Wales was recorded to be over 8.3 million, making it Australia's most populous state.",
      "date": "2023-12"
    }
  ]
}

