  "timeline": [
    {
      "headline": "Birth of Adi Shankara",
      "text": "Adi Shankara was born in Kaladi, a village in present-day Kerala, India. His birth is traditionally dated to 788 CE.",
      "date": "0788"
    },
    {
      "headline": "Completion of Vedic Studies",
      "text": "By the age of eight, Adi Shankara had completed his Vedic studies, showcasing his prodigious intellect and deep understanding of the scriptures.",
      "date": "0796"
    },
    {
      "headline": "Initiation into Sannyasa",
      "text": "At the age of eight, Adi Shankara was initiated into Sannyasa (monastic life) by his guru, Govinda Bhagavatpada.",
      "date": "0796"
    },
    {
      "headline": "Writing of Commentaries",
      "text": "Adi Shankara began writing his commentaries on the Brahma Sutras, Upanishads, and the Bhagavad Gita, which are foundational texts of Advaita Vedanta.",
      "date": "0800"
    },
    {
      "headline": "Establishment of Mathas",
      "text": "Adi Shankara established four mathas (monastic centers) in Sringeri, Dwaraka, Puri, and Jyotirmath between 800 and 820 CE to promote and preserve Advaita Vedanta.",
      "date": "0800"
    },
    {
      "headline": "Debates with Buddhist Scholars",
      "text": "Adi Shankara engaged in numerous debates with Buddhist scholars, which were instrumental in the decline of Buddhism in India and the revival of Hinduism.",
      "date": "0810"
    },
    {
      "headline": "Introduction of Pañcāyatana Puja",
      "text": "Adi Shankara introduced the Pañcāyatana form of worship, which involves the simultaneous worship of five deities, promoting the idea that all deities are forms of the one Brahman.",
      "date": "0810"
    },
    {
      "headline": "Death of Adi Shankara",
      "text": "Adi Shankara passed away at the age of 32 in Kedarnath, present-day Uttarakhand, India. His death is traditionally dated to 820 CE.",
      "date": "0820"
    }
  ]
}

