    {
      "headline": "Ancient Kingdom of Kalinga",
      "text": "The region of present-day Odisha was known as Kalinga in ancient times. It was a powerful kingdom and played a significant role in the history of India. The earliest references to Kalinga are found in ancient Indian texts and inscriptions.",
      "date": "-0300"
    },
    {
      "headline": "Kalinga War",
      "text": "The Kalinga War was fought between the Maurya Empire under Ashoka and the state of Kalinga. The war, which took place around 262-261 BCE, was one of the bloodiest battles in Indian history and led to Ashoka's conversion to Buddhism.",
      "date": "-0261"
    },
    {
      "headline": "Rule of the Eastern Ganga Dynasty",
      "text": "The Eastern Ganga dynasty ruled over Kalinga from the 11th century to the 15th century. They were known for their patronage of art and architecture, including the construction of the famous Jagannath Temple in Puri.",
      "date": "1078"
    },
    {
      "headline": "Construction of the Konark Sun Temple",
      "text": "The Konark Sun Temple, a UNESCO World Heritage Site, was built in the 13th century by King Narasimhadeva I of the Eastern Ganga dynasty. It is one of the most renowned temples in India, known for its unique architecture.",
      "date": "1250"
    },
    {
      "headline": "British Colonial Rule",
      "text": "Odisha came under British colonial rule in the early 19th century. It was initially part of the Bengal Presidency and later became a separate province.",
      "date": "1803"
    },
    {
      "headline": "Formation of Odisha Province",
      "text": "Odisha became a separate province on April 1, 1936, carved out of the Bengal and Bihar provinces. This day is celebrated as Utkala Dibasa (Odisha Day).",
      "date": "1936-04-01"
    },
    {
      "headline": "Bhubaneswar Becomes Capital",
      "text": "Bhubaneswar was declared the capital of Odisha on August 13, 1949, replacing Cuttack. The city is known for its ancient temples and modern urban planning.",
      "date": "1949-08-13"
    },
    {
      "headline": "Odisha Statehood",
      "text": "After India's independence, Odisha became a state of the Indian Union on January 26, 1950, when the Constitution of India came into effect.",
      "date": "1950-01-26"
    }
  ]
}

