  "timeline": [
    {
      "headline": "Development of Agent Orange",
      "text": "Agent Orange was developed as a mixture of two herbicides, 2,4,5-T and 2,4-D. It was initially developed for use in agricultural settings.",
      "date": "1940s"
    },
    {
      "headline": "Use in the Malayan Emergency",
      "text": "The British military used herbicides similar to Agent Orange during the Malayan Emergency to destroy crops used by insurgents.",
      "date": "1950s"
    },
    {
      "headline": "Operation Ranch Hand Begins",
      "text": "The U.S. military began using Agent Orange as part of Operation Ranch Hand during the Vietnam War to defoliate forested and rural land, depriving guerrillas of cover and food.",
      "date": "1961"
    },
    {
      "headline": "Peak Usage of Agent Orange",
      "text": "Agent Orange was used extensively during the Vietnam War, with its peak usage occurring between 1967 and 1969.",
      "date": "1967"
    },
    {
      "headline": "End of Operation Ranch Hand",
      "text": "The use of Agent Orange was discontinued with the end of Operation Ranch Hand, as the U.S. military ceased its herbicidal warfare program in Vietnam.",
      "date": "1971"
    },
    {
      "headline": "Health and Environmental Impact Discovered",
      "text": "In the years following the Vietnam War, the health and environmental impacts of Agent Orange, including birth defects and other serious health issues, became increasingly apparent.",
      "date": "1970s"
    },
    {
      "headline": "Agent Orange Act of 1991",
      "text": "The U.S. Congress passed the Agent Orange Act, which mandated that certain diseases associated with Agent Orange exposure be treated as service-related for veterans' benefits.",
      "date": "1991"
    },
    {
      "headline": "Ongoing Legal and Health Issues",
      "text": "Legal battles and health issues related to Agent Orange exposure continue to affect veterans and Vietnamese populations, with ongoing research and compensation efforts.",
      "date": "2000s"
    }
  ]
}

