{
  "timeline": [
    {
      "headline": "Signing of the Warsaw Pact",
      "text": "The Warsaw Pact was signed on May 14, 1955, in Warsaw, Poland. It was a collective defense treaty between the Soviet Union and seven other Eastern Bloc socialist republics of Central and Eastern Europe.",
      "date": "1955-05-14"
    },
    {
      "headline": "Hungarian Revolution",
      "text": "In 1956, the Warsaw Pact was invoked to justify the Soviet invasion of Hungary to suppress the Hungarian Revolution, demonstrating the military alliance's role in maintaining Soviet influence in Eastern Europe.",
      "date": "1956"
    },
    {
      "headline": "Prague Spring and Invasion of Czechoslovakia",
      "text": "In August 1968, Warsaw Pact troops invaded Czechoslovakia to halt the Prague Spring, a period of political liberalization. This action highlighted the Pact's role in enforcing Soviet control over its satellite states.",
      "date": "1968-08"
    },
    {
      "headline": "Albania Withdraws from the Warsaw Pact",
      "text": "Albania formally withdrew from the Warsaw Pact in 1968, following its ideological split with the Soviet Union and alignment with China.",
      "date": "1968"
    },
    {
      "headline": "Soviet-Afghan War",
      "text": "During the Soviet-Afghan War (1979-1989), the Warsaw Pact countries were involved in supporting the Soviet Union's military efforts, although the war was not directly a Pact operation.",
      "date": "1979"
    },
    {
      "headline": "End of the Cold War",
      "text": "The end of the Cold War in the late 1980s and early 1990s led to political changes in Eastern Europe, weakening the Warsaw Pact's influence and relevance.",
      "date": "1989"
    },
    {
      "headline": "Dissolution of the Warsaw Pact",
      "text": "The Warsaw Pact was officially dissolved on July 1, 1991, following the collapse of communist governments in Eastern Europe and the disintegration of the Soviet Union.",
      "date": "1991-07-01"
    }
  ]
}

