{
  "timeline": [
    {
      "headline": "My Lai Massacre",
      "text": "On March 16, 1968, the My Lai massacre occurred in Sơn Mỹ village, Quảng Ngãi province, South Vietnam. U.S. Army soldiers from C Company, 1st Battalion, 20th Infantry Regiment, 11th Brigade and B Company, 4th Battalion, 3rd Infantry Regiment, 11th Brigade of the 23rd (Americal) Division murdered at least 347 and up to 504 unarmed civilians, including women, children, and elderly men. Some women were gang-raped and their bodies mutilated, and some soldiers mutilated and raped children as young as 12. This incident became the largest massacre of civilians by U.S. forces in the 20th century.",
      "date": "1968-03-16"
    },
    {
      "headline": "Investigation and Cover-up",
      "text": "In the months following the massacre, the U.S. Army attempted to cover up the incident. Initial reports falsely claimed a successful engagement with enemy forces. However, rumors and reports of the massacre began to circulate, leading to an investigation.",
      "date": "1968"
    },
    {
      "headline": "Seymour Hersh's Report",
      "text": "In November 1969, investigative journalist Seymour Hersh broke the story of the My Lai massacre to the public, bringing widespread attention to the incident and prompting further investigations.",
      "date": "1969-11"
    },
    {
      "headline": "Court-Martial of Lieutenant William Calley",
      "text": "Lieutenant William Calley, a platoon leader during the massacre, was court-martialed and found guilty of murdering 22 villagers. On March 29, 1971, he was sentenced to life in prison, but his sentence was later reduced.",
      "date": "1971-03-29"
    },
    {
      "headline": "Calley's Sentence Commuted",
      "text": "In 1974, President Richard Nixon commuted Calley's sentence to house arrest, and he was released after serving three and a half years.",
      "date": "1974"
    }
  ]
}

