    {
      "headline": "British Occupation",
      "text": "In 1882, British forces occupied Cairo, establishing a protectorate over Egypt that lasted until 1952.",
      "date": "1882"
    },
    {
      "headline": "Egyptian Revolution",
      "text": "In 1952, the Egyptian Revolution led by the Free Officers Movement resulted in the end of the British occupation and the establishment of a republic.",
      "date": "1952"
    },
    {
      "headline": "Cairo Metro Opening",
      "text": "In 1987, the Cairo Metro was inaugurated, becoming the first metro system in Africa and the Arab world.",
      "date": "1987"
