{
  "timeline": [
    {
      "headline": "Construction of Deepwater Horizon",
      "text": "The Deepwater Horizon was constructed by Hyundai Heavy Industries in Ulsan, South Korea. It was delivered to R&B Falcon (a later subsidiary of Transocean) in 2001.",
      "date": "2001"
    },
    {
      "headline": "Deepwater Horizon Begins Operations",
      "text": "The Deepwater Horizon began its operations in the Gulf of Mexico, drilling wells for various oil companies, including BP.",
      "date": "2001"
    },
    {
      "headline": "Deepwater Horizon Drills Deepest Oil Well",
      "text": "In September 2009, the Deepwater Horizon drilled the deepest oil well in history at a vertical depth of 35,050 feet (10,683 meters) and measured depth of 35,055 feet (10,685 meters).",
      "date": "2009-09"
    },
    {
      "headline": "Explosion on Deepwater Horizon",
      "text": "On April 20, 2010, a blowout caused an explosion on the Deepwater Horizon rig while drilling at the Macondo Prospect in the Gulf of Mexico. The explosion killed 11 crew members and ignited a fireball visible from 40 miles away.",
      "date": "2010-04-20"
    },
    {
      "headline": "Deepwater Horizon Sinks",
      "text": "On April 22, 2010, two days after the explosion, the Deepwater Horizon rig sank, leaving the well gushing oil at the seabed.",
      "date": "2010-04-22"
    },
    {
      "headline": "Largest Marine Oil Spill in History",
      "text": "Following the sinking of the Deepwater Horizon, the well continued to leak oil into the Gulf of Mexico, resulting in the largest marine oil spill in history.",
      "date": "2010"
    },
    {
      "headline": "Well Capped",
      "text": "On July 15, 2010, the leaking well was successfully capped, stopping the flow of oil into the Gulf of Mexico.",
      "date": "2010-07-15"
    },
    {
      "headline": "Well Permanently Sealed",
      "text": "On September 19, 2010, the Macondo well was declared 'effectively dead' after being permanently sealed.",
      "date": "2010-09-19"
    }
  ]
}

