    {
      "headline": "British Annexation",
      "text": "In 1839, Karachi was annexed by the British East India Company, marking the beginning of its development as a major port city.",
      "date": "1839"
    },
    {
      "headline": "Karachi Becomes Capital of Sindh",
      "text": "In 1843, Karachi became the capital of Sindh after the British conquest of Sindh.",
      "date": "1843"
    },
    {
      "headline": "Development as a Major Port",
      "text": "By 1854, Karachi had developed into a major port city, facilitating trade and commerce in the region.",
      "date": "1854"
    },
    {
      "headline": "Railway Connection",
      "text": "In 1861, Karachi was connected by railway to the rest of British India, further enhancing its status as a trade hub.",
      "date": "1861"
    },
    {
      "headline": "Becomes Part of Pakistan",
      "text": "On August 14, 1947, Karachi became part of the newly independent state of Pakistan and served as its capital.",
      "date": "1947-08-14"
    },
    {
      "headline": "Capital Moved to Islamabad",
      "text": "In 1963, the capital of Pakistan was moved from Karachi to Islamabad.",
      "date": "1963"
    },
    {
      "headline": "Economic Growth",
      "text": "Throughout the 1960s and 1970s, Karachi experienced rapid economic growth, becoming Pakistan's premier industrial and financial center.",
      "date": "1960"
    },
    {
      "headline": "Ethnic and Political Tensions",
      "text": "During the 1980s and 1990s, Karachi faced significant ethnic and political tensions, impacting its social and economic landscape.",
      "date": "1980"
    },
    {
      "headline": "Modern Development",
      "text": "In the 21st century, Karachi continues to grow as a major metropolitan city, with a diverse population and significant economic contributions to Pakistan.",
      "date": "2000"
    }
  ]
}

