    {
      "headline": "Signing of the Good Friday Agreement",
      "text": "The Good Friday Agreement, also known as the Belfast Agreement, was signed on 10 April 1998. It marked a major development in the Northern Ireland peace process, aiming to end the violence of the Troubles.",
      "date": "1998-04-10"
    },
    {
      "headline": "Referendums on the Agreement",
      "text": "On 22 May 1998, referendums were held in both Northern Ireland and the Republic of Ireland. In Northern Ireland, 71.1% voted in favor, while in the Republic of Ireland, 94.4% voted in favor of the Agreement.",
      "date": "1998-05-22"
    },
    {
      "headline": "Establishment of the Northern Ireland Assembly",
      "text": "Following the Agreement, the Northern Ireland Assembly was established on 2 December 1999, providing a devolved government for Northern Ireland.",
      "date": "1999-12-02"
    },
    {
      "headline": "Decommissioning of Weapons",
      "text": "On 23 October 2001, the IRA began decommissioning its weapons, a significant step in the peace process as outlined in the Good Friday Agreement.",
      "date": "2001-10-23"
    },
    {
      "headline": "St Andrews Agreement",
      "text": "On 13 October 2006, the St Andrews Agreement was reached, which aimed to restore the Northern Ireland Assembly and address outstanding issues from the Good Friday Agreement.",
      "date": "2006-10-13"
    },
    {
      "headline": "Restoration of the Northern Ireland Executive",
      "text": "On 8 May 2007, the Northern Ireland Executive was restored following the St Andrews Agreement, with power-sharing between the Democratic Unionist Party and Sinn Féin.",
      "date": "2007-05-08"
    }
  ]
}

