{
  "timeline": [
    {
      "headline": "First Mention of Brussels",
      "text": "The first recorded mention of Brussels dates back to around 979 when Charles, Duke of Lower Lorraine, transferred the relics of Saint Gudula from Moorsel to the Saint Gaugericus chapel in Brussels.",
      "date": "0979"
    },
    {
      "headline": "Brussels as a City",
      "text": "In 1229, Brussels received its city charter, which granted it certain rights and privileges.",
      "date": "1229"
    },
    {
      "headline": "Brussels Becomes Capital of the Burgundian Netherlands",
      "text": "In 1430, Brussels became the capital of the Burgundian Netherlands under Philip the Good.",
      "date": "1430"
    },
    {
      "headline": "The Bombardment of Brussels",
      "text": "In 1695, Brussels was bombarded by the French army under the command of Marshal François de Neufville, Duke of Villeroy, causing extensive damage.",
      "date": "1695"
    },
    {
      "headline": "Brussels Under French Rule",
      "text": "In 1795, Brussels was annexed by France and became the capital of the French department of the Dyle.",
      "date": "1795"
    },
    {
      "headline": "Brussels as Capital of the United Kingdom of the Netherlands",
      "text": "In 1815, following the defeat of Napoleon, Brussels became one of the capitals of the United Kingdom of the Netherlands.",
      "date": "1815"
    },
    {
      "headline": "Belgian Revolution",
      "text": "In 1830, the Belgian Revolution began in Brussels, leading to the independence of Belgium from the Netherlands.",
      "date": "1830"
    },
    {
      "headline": "Brussels as Capital of Belgium",
      "text": "In 1831, Brussels was officially designated as the capital of the newly independent Belgium.",
      "date": "1831"
    },
    {
      "headline": "World War I German Occupation",
      "text": "During World War I, Brussels was occupied by German forces from 1914 to 1918.",
      "date": "1914"
    },
    {
      "headline": "World War II German Occupation",
      "text": "Brussels was again occupied by German forces during World War II from 1940 to 1944.",
      "date": "1940"
    },
    {
      "headline": "Establishment of the Brussels-Capital Region",
      "text": "In 1989, the Brussels-Capital Region was officially established as a separate region of Belgium.",
      "date": "1989"
    },
    {
      "headline": "Brussels as EU Capital",
      "text": "Brussels became the de facto capital of the European Union, hosting major EU institutions such as the European Commission and the European Council.",
      "date": "1990s"
    }
  ]
}

