{
  "timeline": [
    {
      "headline": "Initial Settlement",
      "text": "The Acropolis of Athens was inhabited as early as the Neolithic period, around 4000-3500 BCE.",
      "date": "-4000"
    },
    {
      "headline": "Mycenaean Period",
      "text": "During the Mycenaean period (1600-1100 BCE), the Acropolis served as a royal residence and was fortified with Cyclopean walls.",
      "date": "-1600"
    },
    {
      "headline": "Construction of the Old Temple of Athena",
      "text": "In the 6th century BCE, the Old Temple of Athena was constructed on the Acropolis.",
      "date": "-0600"
    },
    {
      "headline": "Destruction by the Persians",
      "text": "In 480 BCE, during the Persian Wars, the Acropolis was destroyed by the Persians.",
      "date": "-0480"
    },
    {
      "headline": "Rebuilding under Pericles",
      "text": "In the mid-5th century BCE, Pericles initiated a massive building project on the Acropolis, including the construction of the Parthenon, the Propylaea, the Erechtheion, and the Temple of Athena Nike.",
      "date": "-0450"
    },
    {
      "headline": "Completion of the Parthenon",
      "text": "The Parthenon, the most famous structure on the Acropolis, was completed in 432 BCE.",
      "date": "-0432"
    },
    {
      "headline": "Conversion to a Christian Church",
      "text": "In the 6th century CE, the Parthenon was converted into a Christian church dedicated to the Virgin Mary.",
      "date": "0500"
    },
    {
      "headline": "Ottoman Period",
      "text": "During the Ottoman occupation, the Parthenon was converted into a mosque in the 1460s.",
      "date": "1460"
    },
    {
      "headline": "Explosion in the Parthenon",
      "text": "In 1687, during the siege of Athens by the Venetians, a gunpowder explosion severely damaged the Parthenon.",
      "date": "1687"
    },
    {
      "headline": "Greek War of Independence",
      "text": "In 1822, during the Greek War of Independence, the Acropolis was captured by Greek forces.",
      "date": "1822"
    },
    {
      "headline": "Restoration Efforts",
      "text": "In the 19th and 20th centuries, extensive restoration efforts were undertaken to preserve the Acropolis structures.",
      "date": "1900"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of the Medellín Cartel",
      "text": "The Medellín Cartel was formed in the late 1970s in Medellín, Colombia. It was founded and led by Pablo Escobar, with key members including Jorge Luis Ochoa Vásquez, Fabio Ochoa Vásquez, Juan David Ochoa Vásquez, José Gonzalo Rodríguez Gacha, and Carlos Lehder.",
      "date": "1970s"
    },
    {
      "headline": "Peak of Cocaine Trafficking",
      "text": "During the 1980s, the Medellín Cartel supplied at least 80% of the world's cocaine. The cartel's operations were highly organized, with Pablo Escobar and his cousin Gustavo Gaviria managing logistics and shipping.",
      "date": "1980s"
    },
    {
      "headline": "Assassination of Justice Minister Rodrigo Lara",
      "text": "On April 30, 1984, Colombian Justice Minister Rodrigo Lara Bonilla was assassinated by hitmen hired by the Medellín Cartel. This event marked a significant escalation in the Colombian government's war against the cartel.",
      "date": "1984-04-30"
    },
    {
      "headline": "Death of José Gonzalo Rodríguez Gacha",
      "text": "On December 15, 1989, José Gonzalo Rodríguez Gacha, a key member of the Medellín Cartel, was killed by Colombian police.",
      "date": "1989-12-15"
    },
    {
      "headline": "Surrender of Jorge Luis Ochoa Vásquez",
      "text": "In January 1991, Jorge Luis Ochoa Vásquez surrendered to Colombian authorities. He was one of the top leaders of the Medellín Cartel.",
      "date": "1991-01"
    },
    {
      "headline": "Death of Pablo Escobar",
      "text": "On December 2, 1993, Pablo Escobar, the leader of the Medellín Cartel, was killed by Colombian National Police in Medellín.",
      "date": "1993-12-02"
    },
    {
      "headline": "Dismantling of the Medellín Cartel",
      "text": "Following the death of Pablo Escobar in 1993, the Medellín Cartel was effectively dismantled. The Colombian government and law enforcement agencies continued to pursue remaining members and dismantle the cartel's operations.",
      "date": "1993"
    }
  ]
}

