    {
      "headline": "First Transcontinental Supersonic Flight",
      "text": "On July 16, 1957, Glenn made the first supersonic transcontinental flight across the United States in a Vought F8U Crusader.",
      "date": "1957-07-16"
    },
    {
      "headline": "Selection as a NASA Astronaut",
      "text": "In 1959, John Glenn was selected as one of the original seven astronauts for NASA's Project Mercury.",
      "date": "1959"
    },
    {
      "headline": "First American to Orbit Earth",
      "text": "On February 20, 1962, Glenn became the first American to orbit the Earth, completing three orbits aboard the Friendship 7 spacecraft.",
      "date": "1962-02-20"
    },
    {
      "headline": "Retirement from NASA",
      "text": "John Glenn retired from NASA in 1964 to pursue a career in politics.",
      "date": "1964"
    },
    {
      "headline": "Election to U.S. Senate",
      "text": "In 1974, John Glenn was elected as a U.S. Senator from Ohio, a position he held until 1999.",
      "date": "1974"
    },
    {
      "headline": "Return to Space on Space Shuttle Discovery",
      "text": "On October 29, 1998, at the age of 77, John Glenn returned to space aboard the Space Shuttle Discovery, becoming the oldest person to fly in space.",
      "date": "1998-10-29"
    },
    {
      "headline": "Retirement from U.S. Senate",
      "text": "John Glenn retired from the U.S. Senate in 1999 after serving for 25 years.",
      "date": "1999"
