{
  "timeline": [
    {
      "headline": "Birth of Hercules",
      "text": "Hercules was born as the son of Jupiter (Zeus in Greek mythology) and the mortal woman Alcmena. His birth is a significant event in Roman mythology, marking the beginning of the life of one of the most famous mythological heroes.",
      "date": "-1280"
    },
    {
      "headline": "Hercules' Childhood Feats",
      "text": "Even as a child, Hercules displayed extraordinary strength. One famous story recounts how he strangled two serpents sent by Juno (Hera in Greek mythology) to kill him in his cradle.",
      "date": "-1275"
    },
    {
      "headline": "Hercules' Madness and the Twelve Labors",
      "text": "Driven mad by Juno, Hercules killed his own children. As penance, he was required to perform twelve labors, which became some of his most famous adventures.",
      "date": "-1260"
    },
    {
      "headline": "First Labor: Slay the Nemean Lion",
      "text": "Hercules' first labor was to slay the Nemean Lion, a beast that could not be killed with mortal weapons. He strangled it with his bare hands.",
      "date": "-1259"
    },
    {
      "headline": "Second Labor: Slay the nine-headed Lernaean Hydra",
      "text": "Hercules' second labor was to slay the Lernaean Hydra, a serpent-like creature with multiple heads. Each time a head was cut off, two more would grow back.",
      "date": "-1258"
    },
    {
      "headline": "Third Labor: Capture the Golden Hind of Artemis",
      "text": "Hercules was tasked with capturing the Ceryneian Hind, a sacred deer of Artemis, without harming it.",
      "date": "-1257"
    },
    {
      "headline": "Fourth Labor: Capture the Erymanthian Boar",
      "text": "Hercules captured the Erymanthian Boar, a giant beast that terrorized the region of Erymanthos.",
      "date": "-1256"
    },
    {
      "headline": "Fifth Labor: Clean the Augean Stables",
      "text": "Hercules was tasked with cleaning the Augean Stables in a single day, which he accomplished by rerouting two rivers.",
      "date": "-1255"
    },
    {
      "headline": "Sixth Labor: Slay the Stymphalian Birds",
      "text": "Hercules drove away the Stymphalian Birds, man-eating creatures with beaks of bronze, by using a rattle given to him by Athena.",
      "date": "-1254"
    },
    {
      "headline": "Seventh Labor: Capture the Cretan Bull",
      "text": "Hercules captured the Cretan Bull, which was terrorizing the island of Crete.",
      "date": "-1253"
    },
    {
      "headline": "Eighth Labor: Steal the Mares of Diomedes",
      "text": "Hercules was tasked with stealing the Mares of Diomedes, which were trained to eat human flesh.",
      "date": "-1252"
    },
    {
      "headline": "Ninth Labor: Obtain the Girdle of Hippolyta",
      "text": "Hercules was sent to retrieve the girdle of Hippolyta, the queen of the Amazons.",
      "date": "-1251"
    },
    {
      "headline": "Tenth Labor: Capture the Cattle of Geryon",
      "text": "Hercules was tasked with capturing the cattle of the monster Geryon, who had three bodies.",
      "date": "-1250"
    },
    {
      "headline": "Eleventh Labor: Steal the Apples of the Hesperides",
      "text": "Hercules was tasked with stealing the golden apples from the garden of the Hesperides, which were guarded by a dragon.",
      "date": "-1249"
    },
    {
      "headline": "Twelfth Labor: Capture Cerberus",
      "text": "Hercules' final labor was to capture Cerberus, the three-headed dog guarding the entrance to the Underworld, without using weapons.",
      "date": "-1248"
    },
    {
      "headline": "Death of Hercules",
      "text": "Hercules died after being poisoned by a tunic sent by Deianira, his wife, who was tricked into believing it was a love charm. He was granted immortality and ascended to Olympus.",
      "date": "-1220"
    }
  ]
}

