{
  "timeline": [
    {
      "headline": "First Recorded Use",
      "text": "The first recorded use of being hanged, drawn, and quartered as a punishment for treason was in 1241, during the reign of King Henry III of England.",
      "date": "1241"
    },
    {
      "headline": "Statute of Treasons",
      "text": "In 1351, the Statute of Treasons was enacted under King Edward III, which formally defined treason and established the punishment of being hanged, drawn, and quartered for those convicted of high treason.",
      "date": "1351"
    },
    {
      "headline": "Execution of William Wallace",
      "text": "On August 23, 1305, Scottish knight William Wallace was executed by being hanged, drawn, and quartered for high treason against King Edward I of England.",
      "date": "1305-08-23"
    },
    {
      "headline": "Execution of Guy Fawkes",
      "text": "On January 31, 1606, Guy Fawkes, one of the conspirators of the Gunpowder Plot, was executed by being hanged, drawn, and quartered.",
      "date": "1606-01-31"
    },
    {
      "headline": "Last Recorded Execution",
      "text": "The last recorded execution by hanging, drawing, and quartering was that of David Tyrie in 1782, who was convicted of espionage for France during the American Revolutionary War.",
      "date": "1782"
    },
    {
      "headline": "Abolition of the Punishment",
      "text": "The punishment of being hanged, drawn, and quartered was abolished in 1870 with the passage of the Forfeiture Act, which ended the practice of disemboweling and quartering.",
      "date": "1870"
    }
  ]
}

{
