{
  "timeline": [
    {
      "headline": "Publication of The Satanic Verses",
      "text": "The Satanic Verses, the fourth novel by Salman Rushdie, was first published in September 1988. The book was inspired by the life of the Islamic prophet Muhammad and used magical realism to explore contemporary events and characters.",
      "date": "1988-09"
    },
    {
      "headline": "Fatwa Issued Against Salman Rushdie",
      "text": "On February 14, 1989, Iran's Supreme Leader Ayatollah Ruhollah Khomeini issued a fatwa calling for the death of Salman Rushdie, the author of The Satanic Verses, due to the book's controversial content.",
      "date": "1989-02-14"
    },
    {
      "headline": "Protests and Bans",
      "text": "Following the publication of The Satanic Verses, the book was banned in several countries, including India, Bangladesh, Sudan, and South Africa. Protests erupted in various parts of the world, with some turning violent.",
      "date": "1989"
    },
    {
      "headline": "Attack on Translators and Publishers",
      "text": "In the years following the fatwa, several individuals associated with the publication of The Satanic Verses were attacked. In July 1991, Hitoshi Igarashi, the Japanese translator, was killed. Ettore Capriolo, the Italian translator, was seriously injured in an attack in the same year.",
      "date": "1991"
    },
    {
      "headline": "Iran's Government Distances from Fatwa",
      "text": "In 1998, the Iranian government publicly distanced itself from the fatwa, stating that it would not support any attempt to assassinate Salman Rushdie. However, the fatwa was never officially rescinded.",
      "date": "1998"
    },
    {
      "headline": "Salman Rushdie's Knighthood",
      "text": "In June 2007, Salman Rushdie was knighted by Queen Elizabeth II for his services to literature, which reignited controversy and protests in some Muslim-majority countries.",
      "date": "2007-06"
    }
  ]
}

