{
  "timeline": [
    {
      "headline": "Coining of the Term 'Neurodiversity'",
      "text": "The term 'neurodiversity' was coined by Australian sociologist Judy Singer in her 1998 honors thesis. Singer's work laid the foundation for the neurodiversity movement by framing neurological differences as a natural and valuable form of human diversity.",
      "date": "1998"
    },
    {
      "headline": "Publication of 'Neurodiversity: The Birth of an Idea'",
      "text": "In 1999, journalist Harvey Blume published an article in The Atlantic titled 'Neurodiversity: On the Neurological Underpinnings of Geekdom,' which helped popularize the concept of neurodiversity. Blume's work emphasized the idea that neurological differences should be recognized and respected as a social category.",
      "date": "1999"
    },
    {
      "headline": "Founding of the Autism Network International",
      "text": "Autism Network International (ANI) was founded in 1992 by Jim Sinclair, Kathy Lissner Grant, and Donna Williams. ANI played a crucial role in the early neurodiversity movement by advocating for the rights and acceptance of autistic individuals.",
      "date": "1992"
    },
    {
      "headline": "Publication of 'The Autism Rights Movement'",
      "text": "In 2005, the book 'The Autism Rights Movement: A History' by Steve Silberman was published. This book provided a comprehensive history of the autism rights movement, which is closely linked to the neurodiversity movement.",
      "date": "2005"
    },
    {
      "headline": "Neurodiversity in the DSM-5",
      "text": "In 2013, the fifth edition of the Diagnostic and Statistical Manual of Mental Disorders (DSM-5) was published. It included significant changes in the classification of autism spectrum disorders, reflecting a growing recognition of neurodiversity.",
      "date": "2013"
    },
    {
      "headline": "Neurodiversity in the Workplace",
      "text": "In the 2010s, several major companies, including Microsoft and SAP, began implementing neurodiversity hiring programs. These initiatives aimed to leverage the unique skills of neurodivergent individuals and promote inclusive work environments.",
      "date": "2010s"
    },
    {
      "headline": "Publication of 'NeuroTribes: The Legacy of Autism and the Future of Neurodiversity'",
      "text": "In 2015, Steve Silberman published 'NeuroTribes: The Legacy of Autism and the Future of Neurodiversity,' which won the Samuel Johnson Prize for non-fiction. The book explores the history of autism and advocates for the acceptance and understanding of neurodiversity.",
      "date": "2015"
    }
  ]
}

