{
  "timeline": [
    {
      "headline": "First Recorded Observation",
      "text": "The Persian astronomer Abd al-Rahman al-Sufi made the earliest recorded observation of the Andromeda Galaxy, describing it as a 'small cloud' in his Book of Fixed Stars.",
      "date": "0964"
    },
    {
      "headline": "First Telescopic Observation",
      "text": "Simon Marius, a German astronomer, made the first telescopic observation of the Andromeda Galaxy in 1612, describing it as a nebulous object.",
      "date": "1612"
    },
    {
      "headline": "Cataloged by Charles Messier",
      "text": "In 1764, the Andromeda Galaxy was cataloged by Charles Messier as M31 in his catalog of comet-like objects.",
      "date": "1764"
    },
    {
      "headline": "Discovery of Spiral Structure",
      "text": "In 1850, William Parsons, 3rd Earl of Rosse, discovered the spiral structure of the Andromeda Galaxy using his telescope, the Leviathan of Parsonstown.",
      "date": "1850"
    },
    {
      "headline": "First Photograph",
      "text": "The first photograph of the Andromeda Galaxy was taken by Isaac Roberts in 1887, revealing its spiral structure.",
      "date": "1887"
    },
    {
      "headline": "Recognition as a Galaxy",
      "text": "In 1923, Edwin Hubble identified individual Cepheid variable stars in the Andromeda Galaxy, proving it was a separate galaxy outside of the Milky Way.",
      "date": "1923"
    },
    {
      "headline": "Discovery of Andromeda's Rotation",
      "text": "In 1943, Walter Baade and Rudolph Minkowski discovered that the Andromeda Galaxy rotates, using spectroscopic observations.",
      "date": "1943"
    },
    {
      "headline": "Discovery of Andromeda's Halo",
      "text": "In 1970, astronomers discovered a halo of globular clusters surrounding the Andromeda Galaxy, indicating its large size and mass.",
      "date": "1970"
    },
    {
      "headline": "Measurement of Distance",
      "text": "In 1989, the distance to the Andromeda Galaxy was measured more accurately using the Hubble Space Telescope, confirming it is approximately 2.5 million light-years away.",
      "date": "1989"
    }
  ]
}

