{
  "timeline": [
    {
      "headline": "Birth of the Titans",
      "text": "The Titans were born as the twelve children of the primordial deities Uranus (Sky) and Gaia (Earth). They consisted of six male Titans—Oceanus, Coeus, Crius, Hyperion, Iapetus, and Cronus—and six female Titanesses—Theia, Rhea, Themis, Mnemosyne, Phoebe, and Tethys.",
      "date": "-3000"
    },
    {
      "headline": "Overthrow of Uranus",
      "text": "Cronus, the youngest of the Titans, overthrew his father Uranus with the help of his mother Gaia. This event marked the beginning of the rule of the Titans.",
      "date": "-2500"
    },
    {
      "headline": "Reign of Cronus",
      "text": "After overthrowing Uranus, Cronus became the ruler of the cosmos. His reign is often referred to as the Golden Age, a time of prosperity and peace.",
      "date": "-2500"
    },
    {
      "headline": "Birth of the Olympian Gods",
      "text": "During the reign of Cronus, several of the Olympian gods were born, including Zeus, Hera, Poseidon, Hades, Demeter, and Hestia. Cronus swallowed each of his children at birth to prevent them from overthrowing him, as he had done to his father.",
      "date": "-2000"
    },
    {
      "headline": "The Titanomachy",
      "text": "The Titanomachy was a ten-year series of battles fought between the Titans, led by Cronus, and the Olympian gods, led by Zeus. This war ultimately resulted in the defeat of the Titans.",
      "date": "-1500"
    },
    {
      "headline": "Defeat and Imprisonment of the Titans",
      "text": "After their defeat in the Titanomachy, the Titans were imprisoned in Tartarus, a deep abyss used as a dungeon of torment and suffering.",
      "date": "-1500"
    },
    {
      "headline": "Rule of the Olympian Gods",
      "text": "Following the defeat of the Titans, Zeus and the Olympian gods established their rule over the cosmos, marking the end of the Titan's dominion.",
      "date": "-1500"
    }
  ]
}

