{
  "timeline": [
    {
      "headline": "Birth of Pyotr Ilyich Tchaikovsky",
      "text": "Pyotr Ilyich Tchaikovsky was born on May 7, 1840, in Votkinsk, Russia.",
      "date": "1840-05-07"
    },
    {
      "headline": "Enrolled at the Imperial School of Jurisprudence",
      "text": "In 1850, Tchaikovsky was enrolled at the Imperial School of Jurisprudence in Saint Petersburg, where he studied for a career in civil service.",
      "date": "1850"
    },
    {
      "headline": "Graduation and Civil Service",
      "text": "Tchaikovsky graduated from the Imperial School of Jurisprudence in 1859 and began working as a clerk in the Ministry of Justice.",
      "date": "1859"
    },
    {
      "headline": "Enrollment at the Saint Petersburg Conservatory",
      "text": "In 1862, Tchaikovsky enrolled at the Saint Petersburg Conservatory, where he studied music under Anton Rubinstein.",
      "date": "1862"
    },
    {
      "headline": "Graduation from the Conservatory",
      "text": "Tchaikovsky graduated from the Saint Petersburg Conservatory in 1865, having completed his studies in music.",
      "date": "1865"
    },
    {
      "headline": "Appointed Professor at Moscow Conservatory",
      "text": "In 1866, Tchaikovsky was appointed as a professor of harmony at the Moscow Conservatory, a position he held for several years.",
      "date": "1866"
    },
    {
      "headline": "Premiere of Swan Lake",
      "text": "Tchaikovsky's ballet Swan Lake premiered on March 4, 1877, at the Bolshoi Theatre in Moscow.",
      "date": "1877-03-04"
    },
    {
      "headline": "Marriage to Antonina Miliukova",
      "text": "Tchaikovsky married Antonina Miliukova on July 18, 1877, but the marriage was short-lived and troubled.",
      "date": "1877-07-18"
    },
    {
      "headline": "Premiere of Eugene Onegin",
      "text": "The opera Eugene Onegin premiered on March 29, 1879, in Moscow, marking one of Tchaikovsky's major operatic successes.",
      "date": "1879-03-29"
    },
    {
      "headline": "Premiere of the 1812 Overture",
      "text": "The 1812 Overture, one of Tchaikovsky's most famous compositions, premiered on August 20, 1882, in Moscow.",
      "date": "1882-08-20"
    },
    {
      "headline": "Premiere of The Nutcracker",
      "text": "The Nutcracker ballet premiered on December 18, 1892, at the Mariinsky Theatre in Saint Petersburg.",
      "date": "1892-12-18"
    },
    {
      "headline": "Death of Pyotr Ilyich Tchaikovsky",
      "text": "Pyotr Ilyich Tchaikovsky died on November 6, 1893, in Saint Petersburg, Russia, under circumstances that remain a subject of speculation.",
      "date": "1893-11-06"
    }
  ]
}

