{
  "timeline": [
    {
      "headline": "Assassination of Ernst vom Rath",
      "text": "On 7 November 1938, Herschel Grynszpan, a 17-year-old German-born Polish Jew, shot and fatally wounded Ernst vom Rath, a German diplomat, in Paris. Vom Rath died two days later, on 9 November 1938.",
      "date": "1938-11-07"
    },
    {
      "headline": "Kristallnacht Begins",
      "text": "On the night of 9 November 1938, the pogrom known as Kristallnacht, or the Night of Broken Glass, began. Nazi Party's Sturmabteilung (SA) and Schutzstaffel (SS) paramilitary forces, along with some participation from the Hitler Youth and German civilians, attacked Jewish-owned stores, buildings, and synagogues throughout Nazi Germany.",
      "date": "1938-11-09"
    },
    {
      "headline": "Destruction and Violence",
      "text": "Throughout the night of 9-10 November 1938, Jewish homes, hospitals, and schools were ransacked as attackers demolished buildings with sledgehammers. Over 1,400 synagogues and 7,000 Jewish businesses were damaged or destroyed.",
      "date": "1938-11-10"
    },
    {
      "headline": "Aftermath of Kristallnacht",
      "text": "Following the events of Kristallnacht, approximately 30,000 Jewish men were arrested and sent to concentration camps. The pogrom marked a significant escalation in the Nazi regime's antisemitic policies, leading to further persecution of Jews.",
      "date": "1938-11-10"
    }
  ]
}

