      "headline": "Death of Alexander the Great",
      "text": "Alexander the Great died in Babylon on June 10, 323 BC, marking the beginning of the Hellenistic period.",
      "date": "-0323-06-10"
    },
    {
      "headline": "Partition of Babylon",
      "text": "In 323 BC, the Partition of Babylon divided Alexander's empire among his generals, known as the Diadochi.",
      "date": "-0323"
    },
    {
      "headline": "Wars of the Diadochi",
      "text": "From 322 BC to 275 BC, the Wars of the Diadochi were fought among Alexander's successors to control his empire.",
      "date": "-0322"
    },
    {
      "headline": "Battle of Ipsus",
      "text": "In 301 BC, the Battle of Ipsus was fought, resulting in the division of Alexander's empire among the Diadochi.",
      "date": "-0301"
    },
    {
      "headline": "Foundation of the Library of Alexandria",
      "text": "The Library of Alexandria was founded in the early 3rd century BC, becoming a major center of scholarship and learning.",
      "date": "-0300"
    },
    {
      "headline": "Rise of the Seleucid Empire",
      "text": "The Seleucid Empire, one of the major Hellenistic states, was established by Seleucus I Nicator after the division of Alexander's empire.",
      "date": "-0305"
    },
    {
      "headline": "Ptolemaic Kingdom in Egypt",
      "text": "The Ptolemaic Kingdom was established in Egypt by Ptolemy I Soter, one of Alexander's generals, around 305 BC.",
      "date": "-0305"
    },
    {
      "headline": "Antigonid Dynasty in Macedonia",
      "text": "The Antigonid dynasty was established in Macedonia by Antigonus I Monophthalmus and his descendants.",
      "date": "-0276"
    },
    {
      "headline": "Battle of Raphia",
      "text": "In 217 BC, the Battle of Raphia was fought between the Ptolemaic Kingdom and the Seleucid Empire, resulting in a Ptolemaic victory.",
      "date": "-0217"
    },
    {
      "headline": "Roman Conquest of Greece",
      "text": "In 146 BC, Rome conquered Greece, marking the end of Greek political independence.",
      "date": "-0146"
    },
    {
      "headline": "Battle of Actium",
      "text": "On September 2, 31 BC, the Battle of Actium was fought between Octavian and the forces of Mark Antony and Cleopatra, leading to the fall of the Ptolemaic Kingdom.",
      "date": "-0031-09-02"
    },
    {
      "headline": "Death of Cleopatra VII",
      "text": "Cleopatra VII, the last active ruler of the Ptolemaic Kingdom of Egypt, died on August 10, 30 BC, marking the end of the Hellenistic period.",
      "date": "-0030-08-10"
    }
  ]
}

