    },
    {
      "headline": "Evacuation of Stalag Luft III",
      "text": "In January 1945, as Soviet forces advanced, the prisoners were evacuated from Stalag Luft III and forced to march westward in what became known as 'The Long March'.",
      "date": "1945-01"
    },
    {
      "headline": "Liberation of Remaining Prisoners",
      "text": "The remaining prisoners of Stalag Luft III were liberated by Allied forces in April 1945.",
      "date": "1945-04"
    }
  ]
}

