      "headline": "Discovery of 99942 Apophis",
      "text": "99942 Apophis was discovered on June 19, 2004, by astronomers Roy A. Tucker, David J. Tholen, and Fabrizio Bernardi at the Kitt Peak National Observatory.",
      "date": "2004-06-19"
    },
    {
      "headline": "Initial Impact Concern",
      "text": "In December 2004, initial observations indicated a 2.7% probability that Apophis would impact Earth on April 13, 2029, causing significant concern.",
      "date": "2004-12"
    },
    {
      "headline": "Highest Torino Scale Rating",
      "text": "On December 27, 2004, Apophis reached a level 4 on the Torino impact hazard scale, the highest rating ever recorded at that time.",
      "date": "2004-12-27"
    },
    {
      "headline": "Probability of 2029 Impact Eliminated",
      "text": "Further observations improved predictions, eliminating the possibility of an impact on Earth in 2029.",
      "date": "2005"
    },
    {
      "headline": "Torino Scale Rating Lowered",
      "text": "In August 2006, the probability that Apophis would pass through a gravitational keyhole and impact Earth in 2036 was determined to be very small, lowering its Torino scale rating to zero.",
      "date": "2006-08"
    },
    {
      "headline": "Keyhole Size Determined",
      "text": "By 2008, the gravitational keyhole that could have led to a 2036 impact was determined to be less than 1 km wide.",
      "date": "2008"
    }
  ]
}

