{
  "timeline": [
    {
      "headline": "Origin of Aramaic",
      "text": "Aramaic originated in the ancient region of Syria and quickly spread to Mesopotamia, the southern Levant, southeastern Anatolia, Eastern Arabia, and the Sinai Peninsula. It has been continually written and spoken in different varieties for over three thousand years.",
      "date": "-1200"
    },
    {
      "headline": "Adoption as Lingua Franca",
      "text": "By the 8th century BCE, Aramaic had become the lingua franca of the Neo-Assyrian Empire, facilitating communication across the vast empire.",
      "date": "-0800"
    },
    {
      "headline": "Official Language of the Achaemenid Empire",
      "text": "During the Achaemenid Empire (c. 550–330 BCE), Aramaic was adopted as the official language of administration, known as Imperial Aramaic.",
      "date": "-0550"
    },
    {
      "headline": "Use in Jewish Texts",
      "text": "Aramaic became the language of significant Jewish texts, including parts of the Hebrew Bible, the Talmud, and other rabbinic literature.",
      "date": "-0500"
    },
    {
      "headline": "Decline in Use",
      "text": "Following the conquests of Alexander the Great and the spread of Hellenistic culture, Greek began to replace Aramaic as the dominant language in many regions.",
      "date": "-0330"
    },
    {
      "headline": "Syriac Aramaic Flourishes",
      "text": "From the 1st century CE, Syriac, a dialect of Aramaic, became a major literary and liturgical language of Eastern Christianity.",
      "date": "0100"
    },
    {
      "headline": "Aramaic in the Islamic Period",
      "text": "During the Islamic conquests of the 7th century, Aramaic continued to be spoken by Christian and Jewish communities, although Arabic became the dominant language.",
      "date": "0650"
    },
    {
      "headline": "Modern Aramaic Dialects",
      "text": "In the modern era, Aramaic survives in various dialects spoken by small communities, primarily in the Middle East, including Assyrian Neo-Aramaic and Chaldean Neo-Aramaic.",
      "date": "1900"
    }
  ]
}

