      "headline": "Birth of Stonewall Jackson",
      "text": "Thomas Jonathan Jackson was born on January 21, 1824, in Clarksburg, Virginia (now West Virginia).",
      "date": "1824-01-21"
    },
    {
      "headline": "Graduation from West Point",
      "text": "Jackson graduated from the United States Military Academy at West Point in 1846, ranking 17th in his class.",
      "date": "1846"
    },
    {
      "headline": "Service in the Mexican-American War",
      "text": "Jackson served with distinction in the Mexican-American War from 1846 to 1848, earning two brevet promotions for his actions.",
      "date": "1846"
    },
    {
      "headline": "Professor at Virginia Military Institute",
      "text": "In 1851, Jackson accepted a position as a professor of natural and experimental philosophy and artillery tactics at the Virginia Military Institute in Lexington, Virginia.",
      "date": "1851"
    },
    {
      "headline": "First Battle of Bull Run",
      "text": "On July 21, 1861, Jackson earned his famous nickname 'Stonewall' at the First Battle of Bull Run, where his brigade stood firm against Union attacks.",
      "date": "1861-07-21"
    },
    {
      "headline": "Shenandoah Valley Campaign",
      "text": "In the spring of 1862, Jackson led the successful Shenandoah Valley Campaign, demonstrating his tactical prowess by defeating multiple Union armies.",
      "date": "1862"
    },
    {
      "headline": "Battle of Chancellorsville",
      "text": "Jackson played a crucial role in the Confederate victory at the Battle of Chancellorsville from April 30 to May 6, 1863, executing a successful flanking maneuver.",
      "date": "1863-05"
    },
    {
      "headline": "Wounding and Death",
      "text": "Jackson was accidentally shot by his own men on May 2, 1863, during the Battle of Chancellorsville. He died of pneumonia on May 10, 1863, in Guinea Station, Virginia.",
      "date": "1863-05-10"
    }
  ]
}

