      "headline": "First Modern Olympics - Rings Event",
      "text": "The rings event was first held for men at the first modern Olympics in 1896.",
      "date": "1896"
    },
    {
      "headline": "Rings Event Held Again",
      "text": "The rings event was held again at the Olympics in 1904.",
      "date": "1904"
    },
    {
      "headline": "Rings as Part of All-Around",
      "text": "In 1900, 1908, and 1912, the rings was one of the components of the men's artistic individual all-around, but no separate medals were awarded for the apparatus.",
      "date": "1912"
    },
    {
      "headline": "Return of Rings as Medal Event",
      "text": "The men's rings returned as a medal event in the 1924 Olympics and has been held at every Games since.",
      "date": "1924"
    },
    {
      "headline": "Rings Scores in All-Around",
      "text": "Rings scores were included in the individual all-around for the 1924 and 1928 Olympics, with no separate apparatus final.",
      "date": "1928"
    },
    {
      "headline": "Rings Event Separate from All-Around",
      "text": "In 1932, the rings event was entirely separate from the all-around competition.",
      "date": "1932"
