    },
    {
      "headline": "First Sub-2:10 Marathon",
      "text": "Derek Clayton of Australia set a new world record with a time of 2:09:36 on December 3, 1967, at the Fukuoka Marathon in Japan, becoming the first to break the 2:10 barrier.",
      "date": "1967-12-03"
    },
    {
      "headline": "First Sub-2:05 Marathon",
      "text": "Paul Tergat of Kenya set a new world record with a time of 2:04:55 on September 28, 2003, at the Berlin Marathon, becoming the first to run under 2:05.",
      "date": "2003-09-28"
    },
    {
      "headline": "First Sub-2:04 Marathon",
      "text": "Haile Gebrselassie of Ethiopia set a new world record with a time of 2:03:59 on September 28, 2008, at the Berlin Marathon, breaking the 2:04 barrier.",
      "date": "2008-09-28"
    },
    {
      "headline": "First Sub-2:03 Marathon",
      "text": "Patrick Makau of Kenya set a new world record with a time of 2:03:38 on September 25, 2011, at the Berlin Marathon.",
      "date": "2011-09-25"
    },
    {
      "headline": "First Sub-2:02 Marathon",
      "text": "Dennis Kimetto of Kenya set a new world record with a time of 2:02:57 on September 28, 2014, at the Berlin Marathon, becoming the first to run under 2:03.",
      "date": "2014-09-28"
    },
    {
      "headline": "First Sub-2:01 Marathon",
      "text": "Eliud Kipchoge of Kenya set a new world record with a time of 2:01:39 on September 16, 2018, at the Berlin Marathon, breaking the 2:02 barrier.",
