{
  "timeline": [
    {
      "headline": "Molotov–Ribbentrop Pact Signed",
      "text": "On 23 August 1939, Nazi Germany and the Soviet Union signed the Molotov–Ribbentrop Pact, a non-aggression treaty that included a secret protocol to divide Eastern Europe into spheres of influence.",
      "date": "1939-08-23"
    },
    {
      "headline": "German Invasion of Poland Begins",
      "text": "On 1 September 1939, Germany launched an invasion of Poland, marking the beginning of World War II. The attack was characterized by the use of blitzkrieg tactics.",
      "date": "1939-09-01"
    },
    {
      "headline": "Soviet Union Approves Molotov–Ribbentrop Pact",
      "text": "On 31 August 1939, the Supreme Soviet of the Soviet Union approved the Molotov–Ribbentrop Pact, paving the way for the Soviet invasion of Poland.",
      "date": "1939-08-31"
    },
    {
      "headline": "Soviet Invasion of Poland",
      "text": "On 17 September 1939, the Soviet Union invaded Poland from the east, in accordance with the Molotov–Ribbentrop Pact.",
      "date": "1939-09-17"
    },
    {
      "headline": "Warsaw Surrenders",
      "text": "On 28 September 1939, after a prolonged siege, the Polish capital of Warsaw surrendered to German forces.",
      "date": "1939-09-28"
    },
    {
      "headline": "Battle of Kock Ends",
      "text": "The Battle of Kock, the last significant battle of the Polish campaign, ended on 6 October 1939 with the surrender of Polish forces.",
      "date": "1939-10-06"
    },
    {
      "headline": "German–Soviet Frontier Treaty",
      "text": "On 28 September 1939, Germany and the Soviet Union signed the German–Soviet Frontier Treaty, which divided and annexed the whole of Poland between the two powers.",
      "date": "1939-09-28"
    }
  ]
}

