{
  "timeline": [
    {
      "headline": "Annexation of Korea by Japan",
      "text": "On August 22, 1910, the Japan–Korea Annexation Treaty was signed, officially annexing Korea into the Japanese Empire. This marked the beginning of Japanese rule over Korea.",
      "date": "1910-08-22"
    },
    {
      "headline": "Establishment of the Government-General of Korea",
      "text": "In 1910, following the annexation, the Government-General of Korea was established to administer the colony. The Governor-General had significant power over Korean affairs.",
      "date": "1910"
    },
    {
      "headline": "March 1st Movement",
      "text": "On March 1, 1919, a nationwide protest against Japanese rule began, known as the March 1st Movement. It was a pivotal moment in Korean resistance, leading to increased Japanese repression.",
      "date": "1919-03-01"
    },
    {
      "headline": "Cultural Rule Period",
      "text": "Following the March 1st Movement, Japan implemented a more lenient policy known as 'Cultural Rule' in the 1920s, allowing some cultural and educational freedoms.",
      "date": "1920"
    },
    {
      "headline": "Establishment of Korean Provisional Government",
      "text": "In April 1919, the Korean Provisional Government was established in Shanghai, China, as a government-in-exile to resist Japanese rule.",
      "date": "1919-04"
    },
    {
      "headline": "Industrialization and Economic Exploitation",
      "text": "Throughout the 1930s, Japan intensified industrialization in Korea, focusing on infrastructure and resource extraction, often exploiting Korean labor.",
      "date": "1930"
    },
    {
      "headline": "Sino-Japanese War and Increased Militarization",
      "text": "With the outbreak of the Second Sino-Japanese War in 1937, Japan increased its militarization of Korea, conscripting Koreans into the military and labor forces.",
      "date": "1937"
    },
    {
      "headline": "Name Change Policy",
      "text": "In 1939, Japan implemented the Sōshi-kaimei policy, forcing Koreans to adopt Japanese-style names as part of assimilation efforts.",
      "date": "1939"
    },
    {
      "headline": "End of Japanese Rule",
      "text": "On August 15, 1945, Japan surrendered to the Allies, marking the end of World War II and Japanese rule in Korea. Korea was subsequently divided into North and South.",
      "date": "1945-08-15"
    }
  ]
}

{
  "timeline": [
