{
  "timeline": [
    {
      "headline": "Portuguese Arrival",
      "text": "The Portuguese first arrived in the region that is now Guinea-Bissau in the 15th century. They established trading posts and began to exert influence over the area.",
      "date": "1400"
    },
    {
      "headline": "Colonization by Portugal",
      "text": "Guinea-Bissau became a Portuguese colony in the 19th century as part of Portuguese Guinea.",
      "date": "1800"
    },
    {
      "headline": "PAIGC Formation",
      "text": "The African Party for the Independence of Guinea and Cape Verde (PAIGC) was founded in 1956 by Amílcar Cabral and others to fight for independence from Portuguese rule.",
      "date": "1956"
    },
    {
      "headline": "Guinea-Bissau War of Independence",
      "text": "The war for independence from Portugal began in 1963, led by the PAIGC, and lasted until 1974.",
      "date": "1963"
    },
    {
      "headline": "Independence Declared",
      "text": "Guinea-Bissau unilaterally declared its independence from Portugal on September 24, 1973.",
      "date": "1973-09-24"
    },
    {
      "headline": "Official Independence",
      "text": "Portugal officially recognized Guinea-Bissau's independence on September 10, 1974, following the Carnation Revolution in Portugal.",
      "date": "1974-09-10"
    },
    {
      "headline": "Civil War",
      "text": "A civil war erupted in Guinea-Bissau in 1998, leading to significant political instability and displacement of people.",
      "date": "1998"
    },
    {
      "headline": "End of Civil War",
      "text": "The civil war ended in 1999 with the ousting of President João Bernardo Vieira.",
      "date": "1999"
    },
    {
      "headline": "Assassination of President Vieira",
      "text": "President João Bernardo Vieira was assassinated on March 2, 2009, amid political turmoil.",
      "date": "2009-03-02"
    },
    {
      "headline": "Coup d'état",
      "text": "A military coup took place on April 12, 2012, disrupting the presidential election process.",
      "date": "2012-04-12"
    },
    {
      "headline": "Return to Civilian Rule",
      "text": "Guinea-Bissau returned to civilian rule with the election of José Mário Vaz as president in 2014.",
      "date": "2014"
    }
  ]
}

{
  "timeline": [
    {
