    },
    {
      "headline": "Wins Gold Medals at the 1912 Olympics",
      "text": "Jim Thorpe won two gold medals in the pentathlon and decathlon at the 1912 Summer Olympics held in Stockholm, Sweden.",
      "date": "1912"
    },
    {
      "headline": "Stripped of Olympic Titles",
      "text": "In 1913, Jim Thorpe was stripped of his Olympic titles after it was discovered that he had played semi-professional baseball, violating the amateurism rules of the time.",
      "date": "1913"
    },
    {
      "headline": "Professional Baseball Career",
      "text": "Jim Thorpe played professional baseball from 1913 to 1919, including stints with the New York Giants, Cincinnati Reds, and Boston Braves.",
