{
  "timeline": [
    {
      "headline": "Founding of Siemens & Halske",
      "text": "Siemens & Halske was founded by Werner von Siemens and Johann Georg Halske on October 12, 1847. The company was established to build telegraph systems.",
      "date": "1847-10-12"
    },
    {
      "headline": "First Long-Distance Telegraph Line",
      "text": "In 1848, Siemens & Halske completed the construction of the first long-distance telegraph line in Europe, which ran from Berlin to Frankfurt am Main.",
      "date": "1848"
    },
    {
      "headline": "Introduction of the Pointer Telegraph",
      "text": "In 1855, Siemens & Halske introduced the pointer telegraph, which became widely used in Europe.",
      "date": "1855"
    },
    {
      "headline": "Expansion to London",
      "text": "In 1858, Siemens & Halske expanded its operations by opening a branch in London, marking the beginning of its international expansion.",
      "date": "1858"
    },
    {
      "headline": "Completion of Indo-European Telegraph Line",
      "text": "In 1867, Siemens completed the Indo-European telegraph line, which connected London to Calcutta, India.",
      "date": "1867"
    },
    {
      "headline": "Invention of the Dynamo",
      "text": "In 1866, Werner von Siemens invented the dynamo, a significant advancement in electrical engineering.",
      "date": "1866"
    },
    {
      "headline": "Formation of Siemens-Schuckertwerke",
      "text": "In 1903, Siemens & Halske merged with Schuckert & Co. to form Siemens-Schuckertwerke, focusing on electrical engineering.",
      "date": "1903"
    },
    {
      "headline": "Siemens During World War II",
      "text": "During World War II, Siemens was involved in the war effort, producing electrical components and equipment for the German military.",
      "date": "1939-1945"
    },
    {
      "headline": "Post-War Reconstruction",
      "text": "After World War II, Siemens played a significant role in the reconstruction of Germany, focusing on rebuilding its industrial base.",
      "date": "1945"
    },
    {
      "headline": "Introduction of the Siemens S1",
      "text": "In 1983, Siemens introduced the Siemens S1, one of the first digital telephone exchanges.",
      "date": "1983"
    },
    {
      "headline": "Acquisition of Westinghouse Power Generation",
      "text": "In 1998, Siemens acquired the power generation division of Westinghouse Electric Corporation, expanding its energy sector.",
      "date": "1998"
    },
    {
      "headline": "Formation of Siemens Healthineers",
      "text": "In 2015, Siemens rebranded its healthcare division as Siemens Healthineers, focusing on medical technology and services.",
      "date": "2015"
    },
    {
      "headline": "Spin-off of Siemens Energy",
      "text": "In 2020, Siemens spun off its energy business into a separate company, Siemens Energy, to focus on renewable energy and power generation.",
      "date": "2020"
    }
  ]
}

