  "timeline": [
    {
      "headline": "Establishment of the Rashidun Caliphate",
      "text": "The Rashidun Caliphate was established following the death of the Prophet Muhammad in 632. It was the first of the four major caliphates established after Muhammad's death.",
      "date": "0632"
    },
    {
      "headline": "Abu Bakr becomes the first Caliph",
      "text": "In 632, Abu Bakr was appointed as the first caliph, succeeding the Prophet Muhammad. His caliphate lasted until his death in 634.",
      "date": "0632"
    },
    {
      "headline": "Umar ibn al-Khattab's Caliphate",
      "text": "Umar ibn al-Khattab became the second caliph in 634. His reign saw the expansion of the caliphate and significant administrative developments until his assassination in 644.",
      "date": "0634"
    },
    {
      "headline": "Uthman ibn Affan's Caliphate",
      "text": "Uthman ibn Affan became the third caliph in 644. His rule was marked by internal strife and ended with his assassination in 656.",
      "date": "0644"
    },
    {
      "headline": "Ali ibn Abi Talib's Caliphate",
      "text": "Ali ibn Abi Talib became the fourth caliph in 656. His caliphate was marked by civil war and ended with his assassination in 661.",
      "date": "0656"
    },
    {
      "headline": "Establishment of the Umayyad Caliphate",
      "text": "The Umayyad Caliphate was established in 661 following the death of Ali. It was the second of the four major caliphates and lasted until 750.",
      "date": "0661"
    },
    {
      "headline": "Battle of Karbala",
      "text": "The Battle of Karbala occurred on October 10, 680, resulting in the death of Husayn ibn Ali, a significant event in Islamic history.",
      "date": "0680-10-10"
    },
    {
      "headline": "Establishment of the Abbasid Caliphate",
      "text": "The Abbasid Caliphate was established in 750, overthrowing the Umayyad Caliphate. It became a major center of learning and culture.",
      "date": "0750"
    },
    {
      "headline": "Sack of Baghdad",
      "text": "In 1258, the Mongols sacked Baghdad, marking the end of the Abbasid Caliphate's political power.",
      "date": "1258"
    },
    {
      "headline": "Establishment of the Ottoman Caliphate",
      "text": "The Ottoman Caliphate was established in 1517 after the Ottoman conquest of Egypt, marking the beginning of the last major Islamic caliphate.",
      "date": "1517"
    },
    {
      "headline": "Abolition of the Ottoman Caliphate",
      "text": "The Ottoman Caliphate was officially abolished on March 3, 1924, by Mustafa Kemal Atatürk as part of his reforms in the newly established Republic of Turkey.",
      "date": "1924-03-03"
    }
  ]
}

