    {
      "headline": "Introduction of the Film Rating System",
      "text": "On November 1, 1968, the Motion Picture Association of America (MPAA) introduced its film rating system. This system was designed to provide parents with advance information about the content of films to help them determine what movies are appropriate for their children.",
      "date": "1968-11-01"
    },
    {
      "headline": "Initial Ratings Categories",
      "text": "The original ratings included G (General Audiences), M (Mature Audiences), R (Restricted), and X (Adults Only).",
      "date": "1968-11-01"
    },
    {
      "headline": "Modification of the M Rating",
      "text": "In 1969, the M rating was changed to GP (General audiences, Parental guidance suggested) to avoid confusion. It was later changed to PG (Parental Guidance) in 1972.",
      "date": "1969"
    },
    {
      "headline": "Introduction of PG-13 Rating",
      "text": "On July 1, 1984, the PG-13 rating was introduced. This new category was created to indicate that some material may be inappropriate for children under 13.",
      "date": "1984-07-01"
    },
    {
      "headline": "Replacement of X Rating with NC-17",
      "text": "In 1990, the X rating was replaced with NC-17 (No Children 17 and Under Admitted) to distinguish films with adult content from pornography.",
      "date": "1990"
    },
    {
      "headline": "Renaming of the MPAA to MPA",
      "text": "In 2019, the Motion Picture Association of America (MPAA) was renamed to the Motion Picture Association (MPA).",
      "date": "2019"
    }
  ]
}

