{
  "timeline": [
    {
      "headline": "Costa Concordia Sets Sail",
      "text": "On 13 January 2012, the Costa Concordia, a seven-year-old vessel operated by Costa Cruises, set sail on the first leg of a cruise around the Mediterranean Sea.",
      "date": "2012-01-13"
    },
    {
      "headline": "Deviation from Planned Route",
      "text": "On 13 January 2012, the Costa Concordia deviated from its planned route at Isola del Giglio, Tuscany, to perform a sail-by salute.",
      "date": "2012-01-13"
    },
    {
      "headline": "Collision with Rock Formation",
      "text": "On 13 January 2012, the Costa Concordia sailed closer to Isola del Giglio than intended and struck a rock formation on the sea floor.",
      "date": "2012-01-13"
    },
    {
      "headline": "Ship Lists and Partially Sinks",
      "text": "On 13 January 2012, after striking the rock formation, the Costa Concordia began to list and partially sank, landing unevenly on an underwater ledge.",
      "date": "2012-01-13"
    },
    {
      "headline": "Rescue Effort",
      "text": "A six-hour rescue effort on 13 January 2012 brought most of the passengers ashore.",
      "date": "2012-01-13"
    },
    {
      "headline": "Casualties",
      "text": "The disaster resulted in the deaths of 32 people: 27 passengers and 5 crew members.",
      "date": "2012-01-13"
    },
    {
      "headline": "Salvage Team Member Death",
      "text": "A member of the salvage team died following injuries received during the recovery operation.",
      "date": "2012"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of William Blake",
      "text": "William Blake was born on November 28, 1757, in Soho, London, England.",
      "date": "1757-11-28"
    },
    {
      "headline": "Apprenticeship with James Basire",
      "text": "In 1772, at the age of 14, Blake was apprenticed to the engraver James Basire.",
      "date": "1772"
    },
    {
      "headline": "Admission to the Royal Academy",
      "text": "In 1779, Blake was admitted to the Royal Academy of Arts' Schools of Design, where he studied for six years.",
      "date": "1779"
    },
    {
      "headline": "Marriage to Catherine Boucher",
      "text": "On August 18, 1782, Blake married Catherine Boucher, who would become his lifelong companion and collaborator.",
      "date": "1782-08-18"
    },
    {
      "headline": "Publication of 'Poetical Sketches'",
      "text": "In 1783, Blake's first collection of poems, 'Poetical Sketches', was published.",
      "date": "1783"
    },
    {
      "headline": "Creation of 'Songs of Innocence'",
      "text": "In 1789, Blake published 'Songs of Innocence', a collection of illustrated poems.",
      "date": "1789"
    },
    {
      "headline": "Move to Felpham",
      "text": "In 1800, Blake moved to Felpham, Sussex, where he worked on his epic poem 'Milton'.",
      "date": "1800"
    },
    {
      "headline": "Return to London",
      "text": "Blake returned to London in 1803 after spending three years in Felpham.",
      "date": "1803"
    },
    {
      "headline": "Trial for Sedition",
      "text": "In 1803, Blake was tried for sedition after an altercation with a soldier, but he was acquitted.",
      "date": "1803"
    },
    {
      "headline": "Publication of 'Songs of Experience'",
      "text": "In 1794, Blake published 'Songs of Experience', complementing his earlier 'Songs of Innocence'.",
      "date": "1794"
    },
    {
      "headline": "Creation of 'Jerusalem'",
      "text": "Between 1804 and 1820, Blake worked on 'Jerusalem', one of his most ambitious works.",
      "date": "1804"
    },
    {
      "headline": "Death of William Blake",
      "text": "William Blake died on August 12, 1827, in London, England.",
      "date": "1827-08-12"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Rodney King Beating",
      "text": "On March 3, 1991, Rodney King was beaten by LAPD officers after a high-speed chase. The incident was videotaped by a bystander, George Holliday, and widely broadcasted.",
      "date": "1991-03-03"
    },
    {
      "headline": "Trial of LAPD Officers",
      "text": "The trial of the four LAPD officers charged with using excessive force in the beating of Rodney King began on March 4, 1992.",
      "date": "1992-03-04"
    },
    {
      "headline": "Acquittal of LAPD Officers",
      "text": "On April 29, 1992, a jury acquitted the four LAPD officers of all charges related to the beating of Rodney King, sparking outrage and leading to the Los Angeles riots.",
      "date": "1992-04-29"
    },
    {
      "headline": "Start of the Los Angeles Riots",
      "text": "The Los Angeles riots began on April 29, 1992, in South Central Los Angeles, following the acquittal of the LAPD officers.",
      "date": "1992-04-29"
    },
    {
      "headline": "Reginald Denny Beating",
      "text": "On April 29, 1992, during the riots, truck driver Reginald Denny was pulled from his vehicle and severely beaten by rioters at the intersection of Florence and Normandie.",
      "date": "1992-04-29"
    },
    {
      "headline": "Deployment of National Guard",
      "text": "On April 30, 1992, California Governor Pete Wilson ordered the deployment of the California Army National Guard to assist in restoring order in Los Angeles.",
      "date": "1992-04-30"
    },
    {
      "headline": "Federal Troops and Marines Deployed",
      "text": "On May 1, 1992, President George H. W. Bush authorized the deployment of federal troops and Marines to Los Angeles to help quell the riots.",
      "date": "1992-05-01"
    },
    {
      "headline": "End of the Los Angeles Riots",
      "text": "The Los Angeles riots officially ended on May 4, 1992, after six days of violence, resulting in 63 deaths, over 2,000 injuries, and more than $1 billion in property damage.",
      "date": "1992-05-04"
    }
  ]
}

