      "headline": "Birth of Sun Yat-sen",
      "text": "Sun Yat-sen was born on November 12, 1866, in the village of Cuiheng, Xiangshan County, Guangdong Province, Qing Empire.",
      "date": "1866-11-12"
    },
    {
      "headline": "Education in Hawaii",
      "text": "In 1879, Sun Yat-sen was sent to live with his elder brother in Honolulu, Hawaii, where he attended Iolani School and later Oahu College.",
      "date": "1879"
    },
    {
      "headline": "Return to China and Conversion to Christianity",
      "text": "Sun Yat-sen returned to China in 1883 and was baptized as a Christian in Hong Kong in 1884.",
      "date": "1884"
    },
    {
      "headline": "Founding of the Revive China Society",
      "text": "In 1894, Sun Yat-sen founded the Revive China Society in Honolulu, aiming to overthrow the Qing dynasty and establish a republic.",
      "date": "1894"
    },
    {
      "headline": "First Guangzhou Uprising",
      "text": "Sun Yat-sen led the First Guangzhou Uprising on October 26, 1895, which failed, forcing him into exile.",
      "date": "1895-10-26"
    },
    {
      "headline": "Formation of the Tongmenghui",
      "text": "In 1905, Sun Yat-sen helped form the Tongmenghui, a revolutionary alliance, in Tokyo, Japan.",
      "date": "1905"
    },
    {
      "headline": "Wuchang Uprising",
      "text": "The Wuchang Uprising on October 10, 1911, marked the beginning of the Xinhai Revolution, leading to the fall of the Qing dynasty.",
      "date": "1911-10-10"
    },
    {
      "headline": "Provisional President of the Republic of China",
      "text": "On January 1, 1912, Sun Yat-sen was inaugurated as the provisional President of the Republic of China.",
      "date": "1912-01-01"
    },
    {
      "headline": "Resignation as Provisional President",
      "text": "Sun Yat-sen resigned as provisional president on March 10, 1912, in favor of Yuan Shikai, who promised to unify China.",
      "date": "1912-03-10"
    },
    {
      "headline": "Formation of the Kuomintang (KMT)",
      "text": "In 1919, Sun Yat-sen reorganized the Kuomintang (KMT) as a political party in Guangzhou.",
      "date": "1919"
    },
    {
      "headline": "Death of Sun Yat-sen",
      "text": "Sun Yat-sen died of liver cancer on March 12, 1925, in Beijing, Republic of China.",
      "date": "1925-03-12"
    }
  ]
}

