{
  "timeline": [
    {
      "headline": "Founding of Carthage",
      "text": "Carthage was founded by the Phoenicians in the ninth century BC. It began as a settlement in present-day Tunisia.",
      "date": "-0900"
    },
    {
      "headline": "Carthage Becomes a City-State",
      "text": "Over time, Carthage developed from a settlement into a powerful city-state, becoming a major hub for trade and commerce in the Mediterranean.",
      "date": "-0800"
    },
    {
      "headline": "Carthage as a Major Power",
      "text": "By the fourth century BC, Carthage had grown into one of the largest metropoleis in the world and was the center of the Carthaginian Empire.",
      "date": "-0400"
    },
    {
      "headline": "First Punic War",
      "text": "The First Punic War between Carthage and Rome began in 264 BC and lasted until 241 BC. It was primarily fought over control of Sicily.",
      "date": "-0264"
    },
    {
      "headline": "End of the First Punic War",
      "text": "The First Punic War ended in 241 BC with a Roman victory, leading to Carthage losing control of Sicily.",
      "date": "-0241"
    },
    {
      "headline": "Second Punic War",
      "text": "The Second Punic War began in 218 BC, marked by Hannibal's famous crossing of the Alps to attack Rome.",
      "date": "-0218"
    },
    {
      "headline": "Battle of Cannae",
      "text": "In 216 BC, Hannibal achieved a major victory against Rome at the Battle of Cannae, one of the greatest tactical feats in military history.",
      "date": "-0216"
    },
    {
      "headline": "End of the Second Punic War",
      "text": "The Second Punic War ended in 201 BC with the defeat of Carthage, leading to significant territorial losses and a heavy indemnity to Rome.",
      "date": "-0201"
    },
    {
      "headline": "Third Punic War",
      "text": "The Third Punic War began in 149 BC, as Rome sought to completely destroy Carthage.",
      "date": "-0149"
    },
    {
      "headline": "Destruction of Carthage",
      "text": "In 146 BC, Carthage was destroyed by the Romans at the end of the Third Punic War. The city was razed, and its territory became a Roman province.",
      "date": "-0146"
    },
    {
      "headline": "Rebuilding of Carthage",
      "text": "After its destruction, Carthage was later rebuilt by the Romans and became a major city in the Roman Empire.",
      "date": "-0146"
    }
  ]
}

