{
  "timeline": [
    {
      "headline": "Construction of the Pyramid of Djoser",
      "text": "The Pyramid of Djoser, also known as the Step Pyramid, was constructed during the reign of Pharaoh Djoser in the 27th century BCE. It is considered the earliest colossal stone building in Egypt and was designed by the architect Imhotep.",
      "date": "-02670"
    },
    {
      "headline": "Construction of the Bent Pyramid",
      "text": "The Bent Pyramid was built during the reign of Pharaoh Sneferu around 2600 BCE. It is located at Dahshur and is notable for its unique bent shape, which represents an early attempt at constructing a smooth-sided pyramid.",
      "date": "-02600"
    },
    {
      "headline": "Construction of the Red Pyramid",
      "text": "The Red Pyramid, also built by Pharaoh Sneferu, was completed around 2590 BCE. It is the first successful attempt at constructing a true smooth-sided pyramid and is located at Dahshur.",
      "date": "-02590"
    },
    {
      "headline": "Construction of the Great Pyramid of Giza",
      "text": "The Great Pyramid of Giza, built for Pharaoh Khufu, was completed around 2560 BCE. It is the largest of the three pyramids on the Giza plateau and one of the Seven Wonders of the Ancient World.",
      "date": "-02560"
    },
    {
      "headline": "Construction of the Pyramid of Khafre",
      "text": "The Pyramid of Khafre was built for Pharaoh Khafre around 2570 BCE. It is the second-largest pyramid at Giza and is known for its preserved casing stones at the top.",
      "date": "-02570"
    },
    {
      "headline": "Construction of the Pyramid of Menkaure",
      "text": "The Pyramid of Menkaure was constructed for Pharaoh Menkaure around 2510 BCE. It is the smallest of the three main pyramids at Giza.",
      "date": "-02510"
    },
    {
      "headline": "Construction of the Pyramid of Amenemhat I",
      "text": "The Pyramid of Amenemhat I was built during the 12th Dynasty around 1985 BCE. It marked a revival of pyramid construction during the Middle Kingdom.",
      "date": "-01985"
    },
    {
      "headline": "Construction of the Pyramid of Senusret I",
      "text": "The Pyramid of Senusret I was constructed around 1950 BCE. It is located at Lisht and is part of the Middle Kingdom pyramid-building tradition.",
      "date": "-01950"
    },
    {
      "headline": "Construction of the Pyramid of Senusret II",
      "text": "The Pyramid of Senusret II was built around 1895 BCE at El-Lahun. It is known for its mudbrick core and limestone casing.",
      "date": "-01895"
    },
    {
      "headline": "Construction of the Pyramid of Senusret III",
      "text": "The Pyramid of Senusret III was constructed around 1870 BCE at Dahshur. It reflects the continued evolution of pyramid construction techniques during the Middle Kingdom.",
      "date": "-01870"
    },
    {
      "headline": "Construction of the Pyramid of Amenemhat III",
      "text": "The Pyramid of Amenemhat III, also known as the Black Pyramid, was built around 1850 BCE at Dahshur. It is one of the last major pyramids constructed during the Middle Kingdom.",
      "date": "-01850"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Alexander III",
      "text": "Alexander III was born on March 10, 1845, in Saint Petersburg, Russia.",
      "date": "1845-03-10"
    },
    {
      "headline": "Marriage to Princess Dagmar of Denmark",
      "text": "On November 9, 1866, Alexander married Princess Dagmar of Denmark, who became known as Maria Feodorovna.",
      "date": "1866-11-09"
    },
    {
      "headline": "Becomes Tsarevich",
      "text": "Alexander became Tsarevich, the heir apparent to the Russian throne, after the death of his elder brother, Nicholas, in 1865.",
      "date": "1865"
    },
    {
      "headline": "Ascension to the Throne",
      "text": "Alexander III became Emperor of Russia on March 13, 1881, following the assassination of his father, Alexander II.",
      "date": "1881-03-13"
    },
    {
      "headline": "Coronation as Emperor",
      "text": "Alexander III was officially crowned as Emperor of Russia on May 27, 1883, in the Dormition Cathedral in the Moscow Kremlin.",
      "date": "1883-05-27"
    },
    {
      "headline": "Implementation of Counter-Reforms",
      "text": "Throughout his reign, Alexander III implemented a series of counter-reforms, reversing many of the liberal policies of his father. These included tightening censorship, increasing the power of the secret police, and promoting Russian nationalism.",
      "date": "1881"
    },
