{
  "timeline": [
    {
      "headline": "Formation of the African National Congress",
      "text": "The African National Congress (ANC) was founded on January 8, 1912, in Bloemfontein, South Africa, as a national liberation movement to unite African people and spearhead the struggle for fundamental political, social, and economic change.",
      "date": "1912-01-08"
    },
    {
      "headline": "Adoption of the Freedom Charter",
      "text": "On June 26, 1955, the ANC, along with its allies, adopted the Freedom Charter at the Congress of the People in Kliptown. The Charter outlined the vision of a non-racial South Africa and became a cornerstone of the ANC's policy.",
      "date": "1955-06-26"
    },
    {
      "headline": "Sharpeville Massacre and ANC Ban",
      "text": "On March 21, 1960, the Sharpeville Massacre occurred, where police opened fire on a peaceful protest against pass laws, killing 69 people. Following this, the South African government banned the ANC on April 8, 1960.",
      "date": "1960-04-08"
    },
    {
      "headline": "Formation of Umkhonto we Sizwe",
      "text": "In response to the banning of the ANC, the armed wing Umkhonto we Sizwe (Spear of the Nation) was formed on December 16, 1961, to carry out acts of sabotage against the apartheid regime.",
      "date": "1961-12-16"
    },
    {
      "headline": "Rivonia Trial",
      "text": "The Rivonia Trial took place between 1963 and 1964, where key ANC leaders, including Nelson Mandela, were tried and sentenced to life imprisonment for their roles in the anti-apartheid struggle.",
      "date": "1964"
    },
    {
      "headline": "Release of Nelson Mandela",
      "text": "Nelson Mandela was released from prison on February 11, 1990, after 27 years of incarceration, marking a significant step towards the end of apartheid.",
      "date": "1990-02-11"
    },
    {
      "headline": "ANC Legalization",
      "text": "On February 2, 1990, President F.W. de Klerk announced the lifting of the ban on the ANC, allowing it to operate legally in South Africa for the first time since 1960.",
      "date": "1990-02-02"
    },
    {
      "headline": "First Democratic Elections",
      "text": "The first democratic elections in South Africa were held from April 26 to April 29, 1994. The ANC won a majority, and Nelson Mandela was elected as the first black President of South Africa.",
      "date": "1994-04-29"
    },
    {
      "headline": "Cyril Ramaphosa Elected ANC President",
      "text": "Cyril Ramaphosa was elected as the President of the African National Congress on December 18, 2017, succeeding Jacob Zuma.",
      "date": "2017-12-18"
    }
  ]
}

