    {
      "headline": "Establishment of the Golden Horde",
      "text": "The Golden Horde was established in the 13th century as the northwestern sector of the Mongol Empire, originally founded by Batu Khan, a grandson of Genghis Khan.",
      "date": "1240"
    },
    {
      "headline": "Battle of Mohi",
      "text": "In 1241, the Mongols, under the command of Batu Khan and Subutai, defeated the Kingdom of Hungary at the Battle of Mohi, expanding their influence in Eastern Europe.",
      "date": "1241"
    },
    {
      "headline": "Death of Batu Khan",
      "text": "Batu Khan, the founder of the Golden Horde, died in 1255. His death marked a significant transition in the leadership of the khanate.",
      "date": "1255"
    },
    {
      "headline": "Division of the Mongol Empire",
      "text": "After the death of Möngke Khan in 1259, the Mongol Empire was divided, and the Golden Horde became a functionally separate khanate.",
      "date": "1259"
    },
    {
      "headline": "Reign of Berke Khan",
      "text": "Berke Khan, a Muslim convert, ruled the Golden Horde from 1257 to 1266. He was notable for his conflicts with the Ilkhanate and his alliance with the Mamluks.",
      "date": "1257"
    },
    {
      "headline": "Battle of Elbistan",
      "text": "In 1277, the Golden Horde, under the leadership of Berke Khan, allied with the Mamluks to defeat the Ilkhanate at the Battle of Elbistan.",
      "date": "1277"
    },
    {
      "headline": "Reign of Öz Beg Khan",
      "text": "Öz Beg Khan ruled the Golden Horde from 1313 to 1341, during which time he converted the state to Islam and expanded its influence.",
      "date": "1313"
    },
    {
      "headline": "Decline of the Golden Horde",
      "text": "The decline of the Golden Horde began in the late 14th century, exacerbated by internal strife and external pressures from emerging powers like the Grand Duchy of Moscow.",
      "date": "1360"
    },
    {
      "headline": "Battle of Kulikovo",
      "text": "In 1380, the forces of the Golden Horde were defeated by the Russian principalities at the Battle of Kulikovo, marking a significant turning point in the decline of Mongol influence in Russia.",
      "date": "1380"
    },
    {
      "headline": "Timur's Invasion",
      "text": "In 1395, Timur (Tamerlane) invaded the territories of the Golden Horde, further weakening its power.",
      "date": "1395"
    },
    {
      "headline": "Disintegration of the Golden Horde",
      "text": "By the early 15th century, the Golden Horde had fragmented into several smaller khanates, including the Crimean Khanate, Kazan Khanate, and Astrakhan Khanate.",
      "date": "1400"
    }
  ]
}

