      "headline": "Foundation of the Tower of London",
      "text": "The Tower of London was founded towards the end of 1066 as part of the Norman Conquest of England.",
      "date": "1066"
    },
    {
      "headline": "Construction of the White Tower",
      "text": "In 1078, William the Conqueror began the construction of the White Tower, which gave the entire castle its name. It was initially a resented symbol of oppression by the new Norman ruling class.",
      "date": "1078"
    },
    {
      "headline": "Use as a Prison",
      "text": "The Tower of London began to be used as a prison in 1100, although it was not its primary purpose.",
      "date": "1100"
    },
    {
      "headline": "Expansion under Richard I",
      "text": "During the reign of Richard I (1189–1199), the Tower of London underwent expansion.",
      "date": "1189"
    },
    {
      "headline": "Expansion under Henry III",
      "text": "King Henry III (1216–1272) expanded the Tower of London, adding more buildings and fortifications.",
      "date": "1216"
    },
    {
      "headline": "Expansion under Edward I",
      "text": "King Edward I (1272–1307) continued the expansion of the Tower of London, further developing its defenses and structures.",
      "date": "1272"
    },
    {
      "headline": "Completion of General Layout",
      "text": "By the late 13th century, the general layout of the Tower of London was established, which remains largely unchanged despite later modifications.",
      "date": "1300"
    },
    {
      "headline": "End of Use as a Prison",
      "text": "The Tower of London ceased to be used as a prison in 1952, marking the end of its long history as a place of incarceration.",
      "date": "1952"
    }
  ]
}

