{
  "timeline": [
    {
      "headline": "Beginning of European Colonial Settlements",
      "text": "The American frontier began with European colonial settlements in the early 17th century, marking the start of westward expansion in mainland North America.",
      "date": "1600"
    },
    {
      "headline": "Louisiana Purchase",
      "text": "In 1803, President Thomas Jefferson completed the Louisiana Purchase, which doubled the size of the United States and significantly encouraged westward expansion.",
      "date": "1803"
    },
    {
      "headline": "Lewis and Clark Expedition",
      "text": "From 1804 to 1806, the Lewis and Clark Expedition explored the newly acquired western portion of the United States after the Louisiana Purchase, mapping the territory and establishing American presence.",
      "date": "1804"
    },
    {
      "headline": "Manifest Destiny",
      "text": "The term 'Manifest Destiny' was coined in 1845, reflecting the belief that the expansion of the United States throughout the American continents was both justified and inevitable.",
      "date": "1845"
    },
    {
      "headline": "California Gold Rush",
      "text": "The California Gold Rush began in 1848, leading to a massive influx of settlers to the western territories in search of gold and opportunities.",
      "date": "1848"
    },
    {
      "headline": "Homestead Act",
      "text": "In 1862, the Homestead Act was signed into law, providing 160 acres of public land to settlers for a small fee, further encouraging westward migration.",
      "date": "1862"
    },
    {
      "headline": "Completion of the First Transcontinental Railroad",
      "text": "The First Transcontinental Railroad was completed in 1869, connecting the eastern U.S. rail network with the Pacific coast, facilitating travel and commerce.",
      "date": "1869"
    },
    {
      "headline": "End of the American Frontier",
      "text": "The American frontier era is considered to have ended in 1912 with the admission of the last few contiguous western territories as states.",
      "date": "1912"
    }
  ]
}

