{
    "timeline": [
        {
            "headline": "First Mention of Turkic Peoples",
            "text": "The first mention of the Turkic peoples is found in Chinese sources from the 6th century CE, referring to the Göktürks.",
            "date": "0552"
        },
        {
            "headline": "Establishment of the Göktürk Khaganate",
            "text": "In 552 CE, the Göktürk Khaganate was established under the leadership of Bumin Qaghan, marking the first known political entity of the Turkic peoples.",
            "date": "0552"
        },
        {
            "headline": "Division of the Göktürk Khaganate",
            "text": "In 583 CE, the Göktürk Khaganate split into the Eastern and Western Göktürk Khaganates due to internal conflicts.",
            "date": "0583"
        },
        {
            "headline": "Rise of the Uyghur Khaganate",
            "text": "In 744 CE, the Uyghur Khaganate was established after the fall of the Eastern Göktürk Khaganate.",
            "date": "0744"
        },
        {
            "headline": "Fall of the Uyghur Khaganate",
            "text": "In 840 CE, the Uyghur Khaganate fell due to invasions by the Kyrgyz.",
            "date": "0840"
        },
        {
            "headline": "Seljuk Empire Formation",
            "text": "In the 11th century, the Seljuk Empire was formed by the Seljuk Turks, marking a significant expansion of Turkic influence into the Middle East.",
            "date": "1037"
        },
        {
            "headline": "Battle of Manzikert",
            "text": "In 1071 CE, the Seljuk Turks defeated the Byzantine Empire at the Battle of Manzikert, leading to the Turkification of Anatolia.",
            "date": "1071"
        },
        {
            "headline": "Establishment of the Ottoman Empire",
            "text": "In 1299 CE, the Ottoman Empire was established by Osman I, becoming one of the most powerful empires in history.",
            "date": "1299"
        },
        {
            "headline": "Fall of Constantinople",
            "text": "In 1453 CE, the Ottoman Empire captured Constantinople, marking the end of the Byzantine Empire and a significant expansion of Turkic influence.",
            "date": "1453"
        },
        {
            "headline": "Dissolution of the Ottoman Empire",
            "text": "In 1922 CE, the Ottoman Empire was officially dissolved following World War I, leading to the establishment of the Republic of Turkey.",
            "date": "1922"
        }
    ]
}

{
