{
  "timeline": [
    {
      "headline": "First Mardi Gras Celebration in America",
      "text": "The first American Mardi Gras took place on March 3, 1699, when French explorers Pierre Le Moyne d'Iberville and Sieur de Bienville landed near present-day New Orleans, Louisiana. They held a small celebration and named the spot Point du Mardi Gras.",
      "date": "1699-03-03"
    },
    {
      "headline": "Establishment of New Orleans",
      "text": "In 1718, the city of New Orleans was established by Jean-Baptiste Le Moyne de Bienville. Mardi Gras celebrations began to grow in popularity in the city.",
      "date": "1718"
    },
    {
      "headline": "First Recorded Mardi Gras Parade",
      "text": "The first recorded Mardi Gras parade in New Orleans took place in 1837. This marked the beginning of the tradition of parades that continues to this day.",
      "date": "1837"
    },
    {
      "headline": "Formation of the Mystick Krewe of Comus",
      "text": "In 1856, the Mystick Krewe of Comus was formed, establishing the tradition of secret societies or 'krewes' organizing Mardi Gras parades and balls.",
      "date": "1856"
    },
    {
      "headline": "Rex, King of Carnival, Established",
      "text": "In 1872, the Krewe of Rex was established, introducing the tradition of having a 'King of Carnival' to preside over the festivities. The krewe also introduced the official Mardi Gras colors: purple, green, and gold.",
      "date": "1872"
    },
    {
      "headline": "Mardi Gras Becomes a Legal Holiday in Louisiana",
      "text": "In 1875, the Louisiana state legislature declared Mardi Gras a legal holiday, ensuring its celebration would continue to be a significant cultural event.",
      "date": "1875"
    },
    {
      "headline": "First Zulu Parade",
      "text": "The Zulu Social Aid & Pleasure Club, an African American krewe, held its first parade in 1909, adding to the diversity and richness of Mardi Gras celebrations.",
      "date": "1909"
    },
    {
      "headline": "Mardi Gras Cancelled During World Wars",
      "text": "Mardi Gras celebrations were cancelled during World War I (1918-1919) and World War II (1942-1945) due to the global conflicts.",
      "date": "1918"
    },
    {
      "headline": "Mardi Gras Resumes Post-World War II",
      "text": "Mardi Gras celebrations resumed in 1946 after the end of World War II, marking a return to the traditional festivities.",
      "date": "1946"
    },
    {
      "headline": "Hurricane Katrina Cancels Mardi Gras",
      "text": "In 2006, Mardi Gras was significantly scaled back due to the devastation caused by Hurricane Katrina in 2005. However, the tradition continued as a symbol of resilience.",
      "date": "2006"
    }
  ]
}

