    },
    {
      "headline": "Democrats Expand Senate Majority",
      "text": "Despite predictions favoring the Republican Party to gain control of the Senate, the Democrats outperformed expectations and expanded the majority they had held since 2021, gaining a seat for a functioning 51–49 majority.",
      "date": "2022-11-08"
    },
    {
      "headline": "Special Elections Held",
      "text": "In addition to the regularly scheduled elections, 2 special elections were held to complete unexpired terms in the United States Senate.",
      "date": "2022-11-08"
    }
  ]
}

