      "headline": "Birth of Diogenes",
      "text": "Diogenes was born in Sinope, an Ionian colony on the Black Sea coast of Anatolia, in either 412 or 404 BC.",
      "date": "-0412"
    },
    {
      "headline": "Exile from Sinope",
      "text": "Diogenes was exiled from Sinope, possibly due to his involvement in defacing the currency, which led him to Athens.",
      "date": "-0400"
    },
    {
      "headline": "Meeting Antisthenes",
      "text": "After arriving in Athens, Diogenes became a follower of Antisthenes, who was a pupil of Socrates and a major influence on Diogenes' philosophy.",
      "date": "-0390"
    },
    {
      "headline": "Life in Athens",
      "text": "Diogenes lived in Athens, where he became known for his ascetic lifestyle and his practice of living in a large ceramic jar.",
      "date": "-0380"
    },
    {
      "headline": "Encounter with Alexander the Great",
      "text": "Diogenes famously encountered Alexander the Great in Corinth, where he reportedly told Alexander to 'stand out of my sunlight.'",
      "date": "-0336"
    },
    {
      "headline": "Death of Diogenes",
      "text": "Diogenes died at Corinth in 323 BC. The exact circumstances of his death are unclear, with various accounts suggesting different causes.",
      "date": "-0323"
    }
  ]
}

