{
  "timeline": [
    {
      "headline": "Foundation of Thessaloniki",
      "text": "Thessaloniki was founded in 315 BC by Cassander of Macedon. He named it after his wife Thessalonike, a half-sister of Alexander the Great.",
      "date": "-0315"
    },
    {
      "headline": "Roman Conquest",
      "text": "In 168 BC, Thessaloniki came under Roman control after the Battle of Pydna, becoming an important city in the Roman Empire.",
      "date": "-0168"
    },
    {
      "headline": "Via Egnatia Construction",
      "text": "Around 146 BC, the Romans constructed the Via Egnatia, a road that connected Byzantium (later Constantinople) to the Adriatic Sea, passing through Thessaloniki.",
      "date": "-0146"
    },
    {
      "headline": "Thessaloniki as a Roman Capital",
      "text": "In 42 BC, Thessaloniki became the capital of one of the four Roman districts of Macedonia.",
      "date": "-0042"
    },
    {
      "headline": "Paul the Apostle's Visit",
      "text": "Around 50 AD, Paul the Apostle visited Thessaloniki and wrote two epistles to the Thessalonians, which are part of the New Testament.",
      "date": "0050"
    },
    {
      "headline": "Gothic Invasion",
      "text": "In 254 AD, Thessaloniki was attacked by the Goths during their invasions of the Roman Empire.",
      "date": "0254"
    },
    {
      "headline": "Byzantine Era Begins",
      "text": "In 330 AD, Thessaloniki became part of the Byzantine Empire after the division of the Roman Empire.",
      "date": "0330"
    },
    {
      "headline": "St. Demetrius Martyred",
      "text": "In 306 AD, St. Demetrius, the patron saint of Thessaloniki, was martyred during the persecutions of Christians by Emperor Galerius.",
      "date": "0306"
    },
    {
      "headline": "Sack by Saracens",
      "text": "In 904 AD, Thessaloniki was sacked by Saracen pirates, causing significant destruction and loss of life.",
      "date": "0904"
    },
    {
      "headline": "Norman Conquest",
      "text": "In 1185, the Normans captured Thessaloniki, leading to a brief period of Norman control.",
      "date": "1185"
    },
    {
      "headline": "Ottoman Conquest",
      "text": "In 1430, Thessaloniki was conquered by the Ottoman Empire, marking the beginning of nearly five centuries of Ottoman rule.",
      "date": "1430"
    },
    {
      "headline": "Greek Liberation",
      "text": "In 1912, during the First Balkan War, Thessaloniki was liberated by the Greek army and became part of modern Greece.",
      "date": "1912"
    },
    {
      "headline": "Great Fire of Thessaloniki",
      "text": "In 1917, a devastating fire destroyed two-thirds of Thessaloniki, leaving over 70,000 people homeless.",
      "date": "1917"
    },
    {
      "headline": "World War II Occupation",
      "text": "In 1941, Thessaloniki was occupied by Nazi Germany during World War II, leading to the deportation of its Jewish population.",
      "date": "1941"
    },
    {
      "headline": "Post-War Reconstruction",
      "text": "After World War II, Thessaloniki underwent significant reconstruction and development, becoming a major economic and cultural center in Greece.",
      "date": "1945"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "SSL 1.0 Development",
      "text": "In the early 1990s, Netscape Communications began developing the Secure Sockets Layer (SSL) protocol to secure communications over the Internet. SSL 1.0 was never released to the public due to serious security flaws.",
      "date": "1990"
    },
    {
      "headline": "SSL 2.0 Released",
      "text": "SSL 2.0 was released in February 1995 by Netscape. It was the first publicly released version of the protocol, but it contained a number of security vulnerabilities.",
      "date": "1995-02"
    },
    {
      "headline": "SSL 3.0 Released",
      "text": "SSL 3.0 was released in 1996, addressing many of the security issues found in SSL 2.0 and laying the groundwork for future versions of the protocol.",
      "date": "1996"
    },
    {
      "headline": "TLS 1.0 Standardized",
      "text": "In January 1999, the Internet Engineering Task Force (IETF) published RFC 2246, which standardized the Transport Layer Security (TLS) 1.0 protocol as an upgrade to SSL 3.0.",
      "date": "1999-01"
    },
    {
      "headline": "TLS 1.1 Released",
      "text": "TLS 1.1 was released in April 2006 as RFC 4346, introducing improvements such as protection against cipher block chaining (CBC) attacks.",
      "date": "2006-04"
    },
    {
      "headline": "TLS 1.2 Released",
      "text": "In August 2008, TLS 1.2 was released as RFC 5246, bringing enhancements like the ability to specify hash and signature algorithms and improved flexibility.",
      "date": "2008-08"
    },
    {
      "headline": "TLS 1.3 Released",
      "text": "TLS 1.3 was officially published in August 2018 as RFC 8446, offering significant security and performance improvements over previous versions.",
      "date": "2018-08"
    },
    {
      "headline": "Deprecation of TLS 1.0 and 1.1",
      "text": "In March 2020, major web browsers and platforms began deprecating support for TLS 1.0 and 1.1 due to security vulnerabilities and the availability of more secure versions.",
      "date": "2020-03"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Early Grain Gathering",
      "text": "Humans began gathering grains at least 105,000 years ago, marking the early stages of agricultural development.",
      "date": "-103000"
    },
    {
      "headline": "Beginning of Planting Grains",
      "text": "Around 11,500 years ago, nascent farmers began planting grains, transitioning from gathering to cultivation.",
      "date": "-09500"
    },
    {
      "headline": "Domestication of Animals",
      "text": "Sheep, goats, pigs, and cattle were domesticated around 10,000 years ago, providing a stable source of food and labor.",
      "date": "-08000"
    },
    {
      "headline": "Independent Cultivation of Plants",
      "text": "Plants were independently cultivated in at least 11 regions of the world, showcasing the global spread and diversification of agriculture.",
      "date": "-08000"
    },
    {
      "headline": "Rise of Sedentary Human Civilization",
      "text": "Agriculture was a key factor in the rise of sedentary human civilization, enabling the development of cities through food surpluses.",
      "date": "-08000"
    },
    {
      "headline": "Industrial Agriculture",
      "text": "In the 20th century, industrial agriculture based on large-scale monocultures came to dominate agricultural output, significantly increasing productivity.",
      "date": "1900"
    }
  ]
}

