    {
      "headline": "Earliest Known Use of Basque Language",
      "text": "The Basque language is believed to have been spoken in the region since before the Roman Empire, making it one of the oldest languages in Europe. Its origins are not precisely dated, but it predates the Indo-European languages that dominate Europe today.",
      "date": "-0001"
    },
    {
      "headline": "Roman Era References",
      "text": "During the Roman era, the Basque language was spoken in the region, as evidenced by Roman historical references. However, the exact date of these references is not clearly documented.",
      "date": "0000"
    },
    {
      "headline": "First Written Records",
      "text": "The first written records of the Basque language appear in the Middle Ages, with glosses and inscriptions dating back to the 10th century.",
      "date": "1000"
    },
    {
      "headline": "Publication of Linguae Vasconum Primitiae",
      "text": "In 1545, the first book in Basque, 'Linguae Vasconum Primitiae', was published by Bernard Etxepare. This marked a significant milestone in the documentation and preservation of the Basque language.",
      "date": "1545"
    },
    {
      "headline": "Suppression Under Francoist Spain",
      "text": "During the Francoist regime in Spain (1939-1975), the Basque language was heavily suppressed. Public use of Basque was banned, and the language was not allowed in education or media.",
      "date": "1939"
    },
    {
      "headline": "Revival and Official Status",
      "text": "Following the end of Francoist Spain, the Basque language experienced a revival. In 1978, it was granted co-official status in the Basque Autonomous Community and Navarre, leading to increased use in education and media.",
      "date": "1978"
    },
    {
      "headline": "Establishment of Euskaltzaindia",
      "text": "Euskaltzaindia, the Royal Academy of the Basque Language, was established in 1919 to promote and standardize the Basque language.",
      "date": "1919"
    },
    {
      "headline": "Current Status",
      "text": "As of the 21st century, the Basque language is spoken by approximately 806,000 people, with the majority residing in the Spanish Basque Country. Efforts continue to promote and preserve the language.",
      "date": "2023"
    }
  ]
}

