  "timeline": [
    {
      "headline": "Start of the French and Indian War",
      "text": "The French and Indian War began in 1754 as a conflict between the British and French colonies in North America, each supported by various Native American tribes.",
      "date": "1754"
    },
    {
      "headline": "Battle of Fort Necessity",
      "text": "On July 3, 1754, the Battle of Fort Necessity took place, marking one of the first engagements of the French and Indian War. British forces led by George Washington were defeated by the French.",
      "date": "1754-07-03"
    },
    {
      "headline": "Braddock Expedition",
      "text": "In 1755, British General Edward Braddock led an expedition to capture Fort Duquesne. The campaign ended in disaster at the Battle of the Monongahela on July 9, 1755, where Braddock was mortally wounded.",
      "date": "1755-07-09"
    },
    {
      "headline": "Battle of Lake George",
      "text": "The Battle of Lake George occurred on September 8, 1755, resulting in a British victory under Sir William Johnson against the French forces.",
      "date": "1755-09-08"
    },
    {
      "headline": "Siege of Fort William Henry",
      "text": "From August 3 to August 9, 1757, the French, led by General Montcalm, laid siege to Fort William Henry, resulting in a French victory and the massacre of British troops by Native American allies of the French.",
      "date": "1757-08-09"
    },
    {
      "headline": "Battle of Carillon",
      "text": "On July 8, 1758, the Battle of Carillon took place, where French forces successfully defended Fort Carillon against a larger British force.",
      "date": "1758-07-08"
    },
    {
      "headline": "Capture of Louisbourg",
      "text": "In 1758, British forces captured the French fortress of Louisbourg on July 26, opening the route to Quebec.",
      "date": "1758-07-26"
    },
    {
      "headline": "Battle of Quebec",
      "text": "The Battle of Quebec, also known as the Battle of the Plains of Abraham, occurred on September 13, 1759. British forces under General James Wolfe defeated the French, leading to the fall of Quebec.",
      "date": "1759-09-13"
    },
    {
      "headline": "Fall of Montreal",
      "text": "Montreal fell to British forces on September 8, 1760, effectively ending French rule in Canada.",
      "date": "1760-09-08"
    },
    {
      "headline": "Treaty of Paris",
      "text": "The Treaty of Paris was signed on February 10, 1763, officially ending the French and Indian War. France ceded its territories in mainland North America to Britain.",
      "date": "1763-02-10"
    }
  ]
}

