{
  "timeline": [
    {
      "headline": "Establishment of the First French Empire",
      "text": "Napoleon Bonaparte was proclaimed Emperor of the French, marking the establishment of the First French Empire on May 18, 1804.",
      "date": "1804-05-18"
    },
    {
      "headline": "Napoleon's Coronation",
      "text": "Napoleon Bonaparte was crowned Emperor of the French at Notre-Dame Cathedral in Paris on December 2, 1804.",
      "date": "1804-12-02"
    },
    {
      "headline": "Battle of Austerlitz",
      "text": "On December 2, 1805, Napoleon achieved a decisive victory against the Russian and Austrian armies at the Battle of Austerlitz, also known as the Battle of the Three Emperors.",
      "date": "1805-12-02"
    },
    {
      "headline": "Treaty of Tilsit",
      "text": "The Treaty of Tilsit was signed on July 7, 1807, between Napoleon and Tsar Alexander I of Russia, marking the end of the War of the Fourth Coalition.",
      "date": "1807-07-07"
    },
    {
      "headline": "Peninsular War",
      "text": "The Peninsular War began in 1808 when Napoleon invaded Spain and Portugal, leading to a prolonged conflict that lasted until 1814.",
      "date": "1808"
    },
    {
      "headline": "Invasion of Russia",
      "text": "Napoleon launched his disastrous invasion of Russia on June 24, 1812, which ended in a retreat and significant losses for the French army.",
      "date": "1812-06-24"
    },
    {
      "headline": "Battle of Leipzig",
      "text": "The Battle of Leipzig, also known as the Battle of Nations, took place from October 16 to October 19, 1813, resulting in a decisive defeat for Napoleon by the Sixth Coalition.",
      "date": "1813-10-16"
    },
    {
      "headline": "Napoleon's First Abdication",
      "text": "Napoleon abdicated the throne for the first time on April 4, 1814, and was exiled to the island of Elba.",
      "date": "1814-04-04"
    },
    {
      "headline": "Napoleon's Return and the Hundred Days",
      "text": "Napoleon returned from exile on March 20, 1815, marking the beginning of the Hundred Days, his brief return to power.",
      "date": "1815-03-20"
    },
    {
      "headline": "Battle of Waterloo",
      "text": "On June 18, 1815, Napoleon was defeated at the Battle of Waterloo by the Seventh Coalition, leading to his final abdication.",
      "date": "1815-06-18"
    },
    {
      "headline": "Napoleon's Second Abdication",
      "text": "Napoleon abdicated for the second time on June 22, 1815, following his defeat at Waterloo.",
      "date": "1815-06-22"
    },
    {
      "headline": "End of the First French Empire",
      "text": "The First French Empire officially ended on July 7, 1815, when Napoleon was exiled to St. Helena.",
      "date": "1815-07-07"
    }
  ]
}

