{
  "timeline": [
    {
      "headline": "Emergence of Feudalism",
      "text": "Feudalism began to emerge in Europe during the early Middle Ages, around the 9th century, as a response to the need for security and stability following the collapse of the Roman Empire.",
      "date": "0800"
    },
    {
      "headline": "Charlemagne's Reign",
      "text": "During the reign of Charlemagne (768-814), the Carolingian Empire saw the development of a system resembling feudalism, where land was granted to nobles in exchange for military service.",
      "date": "0768"
    },
    {
      "headline": "Feudal System Codified",
      "text": "By the 10th century, the feudal system was more formally established across Europe, with lords granting land to vassals in exchange for military service and loyalty.",
      "date": "0900"
    },
    {
      "headline": "Norman Conquest of England",
      "text": "The Norman Conquest of England in 1066 by William the Conqueror led to the establishment of a feudal system in England, with land distributed to Norman nobles.",
      "date": "1066"
    },
    {
      "headline": "Magna Carta Signed",
      "text": "In 1215, the Magna Carta was signed by King John of England, which began to limit the powers of the king and laid the groundwork for the decline of feudalism.",
      "date": "1215"
    },
    {
      "headline": "Black Death Impact",
      "text": "The Black Death (1347-1351) significantly impacted the feudal system by reducing the population, leading to labor shortages and increased bargaining power for peasants.",
      "date": "1347"
    },
    {
      "headline": "Peasants' Revolt",
      "text": "The Peasants' Revolt in 1381 in England was a major uprising against feudal oppression, signaling growing discontent with the feudal system.",
      "date": "1381"
    },
    {
      "headline": "Decline of Feudalism",
      "text": "By the 15th century, feudalism began to decline due to economic changes, the rise of centralized monarchies, and the growth of towns and trade.",
      "date": "1400"
    },
    {
      "headline": "End of Feudalism in France",
      "text": "The French Revolution in 1789 marked the definitive end of feudalism in France, as revolutionary leaders abolished feudal privileges and dues.",
      "date": "1789"
    }
  ]
}

