{
  "timeline": [
    {
      "headline": "German Colonization",
      "text": "In 1884, Gustav Nachtigal signed a treaty with local chiefs, and Togo became a German protectorate known as Togoland.",
      "date": "1884"
    },
    {
      "headline": "British and French Occupation",
      "text": "During World War I, in 1914, British and French forces invaded Togoland, and by 1916, the territory was divided between the two countries.",
      "date": "1914"
    },
    {
      "headline": "League of Nations Mandate",
      "text": "In 1922, the League of Nations formalized the division, with Britain administering the western part and France the eastern part.",
      "date": "1922"
    },
    {
      "headline": "United Nations Trusteeship",
      "text": "After World War II, in 1946, the League of Nations mandates were converted into United Nations Trust Territories, continuing the division between British and French administration.",
      "date": "1946"
    },
    {
      "headline": "Independence from France",
      "text": "On April 27, 1960, Togo gained independence from France, with Sylvanus Olympio becoming the first President.",
      "date": "1960-04-27"
    },
    {
      "headline": "Military Coup and Assassination of Olympio",
      "text": "On January 13, 1963, President Sylvanus Olympio was assassinated during a military coup led by Étienne Eyadéma (later known as Gnassingbé Eyadéma).",
      "date": "1963-01-13"
    },
    {
      "headline": "Gnassingbé Eyadéma's Presidency",
      "text": "Gnassingbé Eyadéma became President in 1967 after another coup and ruled Togo for 38 years until his death in 2005.",
      "date": "1967"
    },
    {
      "headline": "Death of Gnassingbé Eyadéma",
      "text": "On February 5, 2005, President Gnassingbé Eyadéma died, leading to a brief period of political instability.",
      "date": "2005-02-05"
    },
    {
      "headline": "Faure Gnassingbé's Presidency",
      "text": "Faure Gnassingbé, son of Gnassingbé Eyadéma, became President in 2005 after his father's death, initially through a disputed election.",
      "date": "2005"
    }
  ]
}

