{
  "timeline": [
    {
      "headline": "Birth of Hernán Cortés",
      "text": "Hernán Cortés was born in 1485 in Medellín, Spain.",
      "date": "1485"
    },
    {
      "headline": "Cortés sails to the New World",
      "text": "In 1504, Hernán Cortés sailed to the New World, arriving in Hispaniola, where he lived for several years.",
      "date": "1504"
    },
    {
      "headline": "Cortés joins the expedition to Cuba",
      "text": "In 1511, Cortés joined Diego Velázquez de Cuéllar's expedition to conquer Cuba.",
      "date": "1511"
    },
    {
      "headline": "Appointed Mayor of Santiago",
      "text": "Cortés was appointed as the mayor of Santiago, the capital of Cuba, in 1518.",
      "date": "1518"
    },
    {
      "headline": "Cortés begins expedition to Mexico",
      "text": "In 1519, Hernán Cortés led an expedition to Mexico, defying the orders of the Cuban governor.",
      "date": "1519"
    },
    {
      "headline": "Cortés lands in Mexico",
      "text": "Cortés landed on the coast of Mexico in February 1519, marking the beginning of his campaign against the Aztec Empire.",
      "date": "1519-02"
    },
    {
      "headline": "Founding of Veracruz",
      "text": "In April 1519, Cortés founded the city of Veracruz, establishing the first Spanish settlement on the mainland of the Americas.",
      "date": "1519-04"
    },
    {
      "headline": "Alliance with Tlaxcala",
      "text": "In 1519, Cortés formed an alliance with the Tlaxcalans, who became crucial allies in his campaign against the Aztecs.",
      "date": "1519"
    },
    {
      "headline": "Cortés enters Tenochtitlán",
      "text": "On November 8, 1519, Cortés and his forces entered the Aztec capital of Tenochtitlán.",
      "date": "1519-11-08"
    },
    {
      "headline": "La Noche Triste",
      "text": "On June 30, 1520, Cortés and his men were forced to flee Tenochtitlán during a night known as La Noche Triste.",
      "date": "1520-06-30"
    },
    {
      "headline": "Siege of Tenochtitlán",
      "text": "Cortés began the siege of Tenochtitlán in May 1521, which lasted until the city's fall in August.",
      "date": "1521-05"
    },
    {
      "headline": "Fall of Tenochtitlán",
      "text": "On August 13, 1521, Tenochtitlán fell to Cortés and his forces, marking the end of the Aztec Empire.",
      "date": "1521-08-13"
    },
    {
      "headline": "Cortés appointed Governor of New Spain",
      "text": "In 1522, Cortés was appointed as the Governor and Captain General of New Spain by King Charles I of Spain.",
      "date": "1522"
    },
    {
      "headline": "Cortés returns to Spain",
      "text": "In 1528, Cortés returned to Spain to defend his actions in Mexico and to seek support from the Spanish crown.",
      "date": "1528"
    },
    {
      "headline": "Cortés returns to Mexico",
      "text": "In 1530, Cortés returned to Mexico, but his power was significantly reduced.",
      "date": "1530"
    },
    {
      "headline": "Cortés participates in the expedition to Baja California",
      "text": "In 1536, Cortés led an expedition to explore the Pacific coast of Mexico, including Baja California.",
      "date": "1536"
    },
    {
      "headline": "Cortés returns to Spain permanently",
      "text": "In 1541, Cortés returned to Spain, where he spent the remainder of his life.",
      "date": "1541"
    },
    {
      "headline": "Death of Hernán Cortés",
      "text": "Hernán Cortés died on December 2, 1547, in Castilleja de la Cuesta, Spain.",
      "date": "1547-12-02"
    }
  ]
}

