{
  "timeline": [
    {
      "headline": "Kursk Submarine Disaster",
      "text": "On 12 August 2000, the Russian nuclear submarine K-141 Kursk sank in an accident in the Barents Sea, resulting in the loss of all 118 personnel on board. The submarine was participating in the first major Russian naval exercise in over a decade.",
      "date": "2000-08-12"
    },
    {
      "headline": "Initial Explosions Detected",
      "text": "Crews of nearby ships felt an initial explosion followed by a second, much larger explosion on 12 August 2000. Despite these explosions, the Russian Navy did not realize an accident had occurred.",
      "date": "2000-08-12"
    },
    {
      "headline": "Delayed Search Initiation",
      "text": "The Russian Navy did not initiate a search for the Kursk submarine for over six hours after the explosions were detected on 12 August 2000.",
      "date": "2000-08-12"
    },
    {
      "headline": "Emergency Rescue Buoy Disabled",
      "text": "The Kursk's emergency rescue buoy had been intentionally disabled during an earlier mission, complicating rescue efforts after the submarine sank on 12 August 2000.",
      "date": "2000-08-12"
    },
    {
      "headline": "Submarine Located",
      "text": "It took more than 16 hours to locate the Kursk submarine, which was found resting on the ocean floor at a depth of 108 metres (354 ft) on 13 August 2000.",
      "date": "2000-08-13"
    }
  ]
}

