      "headline": "Birth of John Lewis",
      "text": "John Robert Lewis was born on February 21, 1940, in Troy, Alabama.",
      "date": "1940-02-21"
    },
    {
      "headline": "Nashville Sit-ins",
      "text": "In 1960, John Lewis participated in the Nashville sit-ins, a series of nonviolent protests against segregated lunch counters in Nashville, Tennessee.",
      "date": "1960"
    },
    {
      "headline": "Freedom Rides",
      "text": "In 1961, Lewis became one of the original 13 Freedom Riders, challenging segregation at interstate bus terminals across the South.",
      "date": "1961"
    },
    {
      "headline": "Chairman of SNCC",
      "text": "John Lewis served as the chairman of the Student Nonviolent Coordinating Committee (SNCC) from 1963 to 1966.",
      "date": "1963"
    },
    {
      "headline": "March on Washington",
      "text": "On August 28, 1963, Lewis was one of the 'Big Six' leaders who organized the March on Washington for Jobs and Freedom, where he delivered a speech.",
      "date": "1963-08-28"
    },
    {
      "headline": "Bloody Sunday",
      "text": "On March 7, 1965, Lewis led over 600 marchers across the Edmund Pettus Bridge in Selma, Alabama, where they were attacked by state troopers in an event known as Bloody Sunday.",
      "date": "1965-03-07"
    },
    {
      "headline": "Elected to U.S. House of Representatives",
      "text": "In 1986, John Lewis was elected to the United States House of Representatives for Georgia's 5th congressional district, taking office on January 3, 1987.",
      "date": "1987-01-03"
    },
    {
      "headline": "Awarded Presidential Medal of Freedom",
      "text": "On February 15, 2011, President Barack Obama awarded John Lewis the Presidential Medal of Freedom.",
      "date": "2011-02-15"
    },
    {
      "headline": "Death of John Lewis",
      "text": "John Lewis passed away on July 17, 2020, in Atlanta, Georgia, after a battle with pancreatic cancer.",
      "date": "2020-07-17"
    }
  ]
}

