{
  "timeline": [
    {
      "headline": "First Description of Sickle Cell Disease",
      "text": "In 1910, sickle cell disease was first described by Dr. James B. Herrick, who noted the peculiar shape of the red blood cells in a dental student from Grenada.",
      "date": "1910"
    },
    {
      "headline": "Identification of Sickle Cell Trait",
      "text": "In 1927, the sickle cell trait was identified by Dr. Vernon Mason, who discovered that the trait was inherited in a Mendelian fashion.",
      "date": "1927"
    },
    {
      "headline": "Discovery of Hemoglobin S",
      "text": "In 1949, Dr. Linus Pauling and his colleagues discovered that sickle cell disease was caused by an abnormal form of hemoglobin, which they named Hemoglobin S.",
      "date": "1949"
    },
    {
      "headline": "Molecular Basis of Sickle Cell Disease",
      "text": "In 1956, Dr. Vernon Ingram identified the specific mutation in the hemoglobin gene that causes sickle cell disease, marking the first time a genetic disease was traced to a specific molecular defect.",
      "date": "1956"
    },
    {
      "headline": "Introduction of Newborn Screening",
      "text": "In the 1970s, newborn screening for sickle cell disease began in the United States, allowing for early diagnosis and management of the disease.",
      "date": "1970"
    },
    {
      "headline": "Approval of Hydroxyurea",
      "text": "In 1998, the FDA approved hydroxyurea as the first drug to reduce the frequency of painful crises and the need for blood transfusions in adults with sickle cell anemia.",
      "date": "1998"
    },
    {
      "headline": "Gene Therapy Advancements",
      "text": "In the 2010s, significant advancements were made in gene therapy for sickle cell disease, offering potential curative treatments by correcting the genetic defect.",
      "date": "2010"
    }
  ]
}

