  "timeline": [
    {
      "headline": "Foundation of Baghdad",
      "text": "Baghdad was founded on July 30, 762, by the Abbasid caliph Al-Mansur. The city was designed to be the capital of the Abbasid Caliphate.",
      "date": "0762-07-30"
    },
    {
      "headline": "Baghdad as a Center of Learning",
      "text": "During the 8th and 9th centuries, Baghdad became a significant cultural, commercial, and intellectual center of the Muslim world. The city was home to the House of Wisdom, where scholars of various cultures and religions sought to translate and gather all the world's knowledge.",
      "date": "0800"
    },
    {
      "headline": "Sack of Baghdad by the Mongols",
      "text": "In 1258, Baghdad was sacked by the Mongols under Hulagu Khan. This event marked the end of the Islamic Golden Age and resulted in the destruction of the House of Wisdom and the massacre of a large portion of the city's population.",
      "date": "1258"
    },
    {
      "headline": "Ottoman Control",
      "text": "Baghdad came under Ottoman control in 1534 when it was captured by Sultan Suleiman the Magnificent. The city remained under Ottoman rule, with brief interruptions, until the early 20th century.",
      "date": "1534"
    },
    {
      "headline": "British Occupation",
      "text": "During World War I, British forces captured Baghdad on March 11, 1917, from the Ottoman Empire. This marked the beginning of British influence in the region.",
      "date": "1917-03-11"
    },
    {
      "headline": "Establishment of the Kingdom of Iraq",
      "text": "In 1921, the Kingdom of Iraq was established under British administration, with Baghdad as its capital. Faisal I was installed as the king.",
      "date": "1921"
    },
    {
      "headline": "Republic of Iraq Declared",
      "text": "On July 14, 1958, a coup d'état overthrew the monarchy, and the Republic of Iraq was declared. Baghdad remained the capital of the new republic.",
      "date": "1958-07-14"
    },
    {
      "headline": "Iran-Iraq War",
      "text": "From 1980 to 1988, Baghdad was significantly affected by the Iran-Iraq War, with the city experiencing air raids and missile attacks.",
      "date": "1980"
    },
    {
      "headline": "Gulf War Impact",
      "text": "In 1991, during the Gulf War, Baghdad was heavily bombed by coalition forces. The war caused significant damage to the city's infrastructure.",
      "date": "1991"
    },
    {
      "headline": "Invasion of Iraq",
      "text": "In 2003, Baghdad was captured by U.S.-led coalition forces during the invasion of Iraq, leading to the fall of Saddam Hussein's regime.",
      "date": "2003"
    },
    {
      "headline": "Baghdad Security Plan",
      "text": "In 2007, the Baghdad Security Plan was implemented to reduce violence in the city, which had been experiencing sectarian violence and insurgency.",
      "date": "2007"
    }
  ]
}

