    },
    {
      "headline": "Expansion of Rugby Sevens",
      "text": "Throughout the late 19th and early 20th centuries, rugby sevens gained popularity, spreading to other parts of Scotland and eventually to England and beyond.",
      "date": "1900"
    },
    {
      "headline": "Hong Kong Sevens Established",
      "text": "In 1976, the Hong Kong Sevens was established, becoming one of the most prestigious and well-known rugby sevens tournaments in the world.",
      "date": "1976"
    },
    {
      "headline": "Rugby World Cup Sevens Inauguration",
      "text": "The first Rugby World Cup Sevens was held in 1993 in Scotland, further solidifying the sport's international appeal.",
      "date": "1993"
    },
    {
      "headline": "Inclusion in Commonwealth Games",
      "text": "Rugby sevens was included in the Commonwealth Games for the first time in 1998, held in Kuala Lumpur, Malaysia.",
      "date": "1998"
    },
    {
      "headline": "World Rugby Sevens Series Launch",
      "text": "The World Rugby Sevens Series was launched in 1999, providing an annual series of international tournaments for national teams.",
      "date": "1999"
    },
    {
      "headline": "Olympic Inclusion",
      "text": "Rugby sevens was included in the Olympic Games for the first time at the 2016 Summer Olympics in Rio de Janeiro, Brazil.",
      "date": "2016"
