{
  "timeline": [
    {
      "headline": "Birth of Icarus",
      "text": "Icarus was born to Daedalus, a master craftsman, in ancient Greece. The exact date of his birth is not specified in mythology.",
      "date": "-1300"  },
    {
      "headline": "Imprisonment in Crete",
      "text": "Icarus and his father Daedalus were imprisoned by King Minos of Crete, either in a large tower overlooking the ocean or in the labyrinth itself, after Theseus escaped from the labyrinth. This event is part of the mythological narrative and does not have a specific date.",
      "date": "-1250"
    },
    {
      "headline": "Construction of Wings",
      "text": "Daedalus constructed wings for himself and Icarus using birds’ molted feathers, threads from blankets, leather straps from their sandals, and beeswax, in preparation for their escape from Crete.",
      "date": "-1250"
    },
    {
      "headline": "Escape from Crete",
      "text": "Icarus and Daedalus attempted to escape from Crete using the wings Daedalus had constructed. Daedalus warned Icarus not to fly too low or too high.",
      "date": "-1250"
    },
    {
      "headline": "Fall of Icarus",
      "text": "Ignoring his father's warnings, Icarus flew too close to the sun, causing the beeswax in his wings to melt. He fell into the sea and drowned. This tragic event is a central part of the myth and serves as a cautionary tale.",
      "date": "-1250"
    }
  ]
}

