    {
      "headline": "Discovery of Salicin",
      "text": "In 1763, Reverend Edward Stone discovered that willow bark, which contains salicin, could be used to reduce fever.",
      "date": "1763"
    },
    {
      "headline": "Isolation of Salicin",
      "text": "In 1828, Johann Buchner, a German chemist, isolated salicin, the active ingredient in willow bark.",
      "date": "1828"
    },
    {
      "headline": "Synthesis of Salicylic Acid",
      "text": "In 1838, Italian chemist Raffaele Piria successfully converted salicin into salicylic acid.",
      "date": "1838"
    },
    {
      "headline": "First Commercial Production of Salicylic Acid",
      "text": "In 1874, salicylic acid was first produced commercially by the German company Heyden Chemical Company.",
      "date": "1874"
    },
    {
      "headline": "Synthesis of Acetylsalicylic Acid",
      "text": "On August 10, 1897, Felix Hoffmann, a chemist at Bayer, synthesized acetylsalicylic acid in a stable form.",
      "date": "1897-08-10"
    },
    {
      "headline": "Introduction of Aspirin",
      "text": "In 1899, Bayer registered 'Aspirin' as a trademark and began marketing the drug as a powder.",
      "date": "1899"
    },
    {
      "headline": "Aspirin Tablets Introduced",
      "text": "In 1915, Bayer introduced aspirin in tablet form, making it easier for consumers to use.",
      "date": "1915"
    },
    {
      "headline": "Aspirin's Role in Heart Attack Prevention",
      "text": "In the 1970s, studies began to show that aspirin could help prevent heart attacks due to its antithrombotic properties.",
      "date": "1970"
    },
    {
      "headline": "FDA Approval for Heart Attack Prevention",
      "text": "In 1985, the U.S. Food and Drug Administration approved the use of aspirin to reduce the risk of recurrent heart attacks.",
      "date": "1985"
    }
  ]
}

