{
  "timeline": [
    {
      "headline": "First Mention of Transylvania",
      "text": "The first known written mention of Transylvania dates back to 1075 in a document of King Géza I of Hungary.",
      "date": "1075"
    },
    {
      "headline": "Transylvania as a Voivodeship",
      "text": "In the 12th century, Transylvania became a voivodeship, a semi-independent region under the Kingdom of Hungary.",
      "date": "1100"
    },
    {
      "headline": "Saxon Settlement",
      "text": "In the 12th and 13th centuries, German-speaking Saxons were invited to settle in Transylvania, contributing to its cultural diversity.",
      "date": "1200"
    },
    {
      "headline": "Mongol Invasion",
      "text": "In 1241, Transylvania was invaded by the Mongols, causing significant destruction and loss of life.",
      "date": "1241"
    },
    {
      "headline": "Union of Transylvania with Hungary",
      "text": "In 1437, the Union of Kápolna was formed, uniting the Hungarian nobility, Saxon patricians, and Szekler military class in Transylvania.",
      "date": "1437"
    },
    {
      "headline": "Battle of Mohács",
      "text": "In 1526, the Battle of Mohács led to the fall of the Kingdom of Hungary, and Transylvania became an autonomous principality under Ottoman suzerainty.",
      "date": "1526"
    },
    {
      "headline": "Principality of Transylvania",
      "text": "In 1570, the Treaty of Speyer recognized Transylvania as a principality under Ottoman influence but with significant autonomy.",
      "date": "1570"
    },
    {
      "headline": "Habsburg Control",
      "text": "In 1699, the Treaty of Karlowitz transferred Transylvania from Ottoman to Habsburg control, integrating it into the Habsburg Monarchy.",
      "date": "1699"
    },
    {
      "headline": "Revolution of 1848",
      "text": "During the European revolutions of 1848, Transylvania saw significant nationalist movements and demands for autonomy.",
      "date": "1848"
    },
    {
      "headline": "Union with Romania",
      "text": "On December 1, 1918, the Great National Assembly of Alba Iulia declared the union of Transylvania with Romania.",
      "date": "1918-12-01"
    },
    {
      "headline": "Second Vienna Award",
      "text": "In 1940, the Second Vienna Award resulted in Northern Transylvania being ceded to Hungary, but it was returned to Romania after World War II.",
      "date": "1940"
    },
    {
      "headline": "Post-World War II",
      "text": "After World War II, Transylvania was fully integrated into Romania, as confirmed by the Paris Peace Treaties of 1947.",
      "date": "1947"
    }
  ]
}

