{
  "timeline": [
    {
      "headline": "Initial Reports of Havana Syndrome",
      "text": "In late 2016, U.S. and Canadian government officials and their families in Havana, Cuba, began reporting symptoms of what would later be known as Havana syndrome. These symptoms included acute onset associated with a perceived localized loud sound, followed by chronic symptoms such as balance issues, dizziness, cognitive problems, insomnia, and headaches.",
      "date": "2016"
    },
    {
      "headline": "Expansion of Reported Cases",
      "text": "By 2017, reports of similar symptoms began to emerge from other locations, including China. U.S. diplomats and their families in Guangzhou reported experiencing similar health issues.",
      "date": "2017"
    },
    {
      "headline": "U.S. Government Response",
      "text": "In 2018, the U.S. government began investigating the incidents, with the State Department setting up a task force to address the health concerns of affected personnel.",
      "date": "2018"
    },
    {
      "headline": "Reports in Additional Locations",
      "text": "In subsequent years, reports of Havana syndrome symptoms were made by U.S. officials in various locations, including India, Vienna, Hanoi, Berlin, London, and Taiwan.",
      "date": "2019"
    },
    {
      "headline": "Reports in the United States",
      "text": "In 2020, symptoms were also reported within the United States, including in Washington, D.C.",
      "date": "2020"
    },
    {
      "headline": "National Academy of Sciences Report",
      "text": "In December 2020, the National Academy of Sciences released a report suggesting that directed microwave radiation was a plausible cause of the symptoms experienced by U.S. diplomats.",
      "date": "2020-12"
    },
    {
      "headline": "Continued Investigation and Debate",
      "text": "Throughout 2021 and 2022, investigations continued into the cause of Havana syndrome, with various theories proposed, including sonic attacks, microwave radiation, and psychological factors. The condition remains a topic of debate and research.",
      "date": "2021"
    }
  ]
}

