{
  "timeline": [
    {
      "headline": "Conceptualization of IoT",
      "text": "The concept of a network of smart devices was discussed as early as 1982, with a modified Coke machine at Carnegie Mellon University becoming the first internet-connected appliance, able to report its inventory and whether newly loaded drinks were cold.",
      "date": "1982"
    },
    {
      "headline": "Coining of the Term 'Internet of Things'",
      "text": "The term 'Internet of Things' was coined by Kevin Ashton in 1999 during his work at Procter & Gamble, which later became more widely known through his work at MIT's Auto-ID Center.",
      "date": "1999"
    },
    {
      "headline": "First International Conference on IoT",
      "text": "The first International Conference on the Internet of Things (IoT) was held in 2008 in Zurich, Switzerland, marking a significant step in the formalization and global recognition of IoT as a field.",
      "date": "2008"
    },
    {
      "headline": "Launch of IPv6",
      "text": "The launch of IPv6 in 2012 was a critical development for IoT, as it provided a vastly larger address space, enabling the connection of a massive number of devices.",
      "date": "2012"
    },
    {
      "headline": "IoT Security Concerns Highlighted",
      "text": "In 2016, the Mirai botnet attack, which hijacked IoT devices to launch a massive distributed denial-of-service (DDoS) attack, highlighted significant security vulnerabilities in IoT devices.",
      "date": "2016"
    },
    {
      "headline": "IoT Becomes Mainstream",
      "text": "By 2020, IoT had become mainstream, with billions of devices connected worldwide, impacting various sectors including healthcare, manufacturing, and smart homes.",
      "date": "2020"
    }
  ]
}

