{
  "timeline": [
    {
      "headline": "First Oktoberfest",
      "text": "The first Oktoberfest was held on October 12, 1810, to celebrate the marriage of Crown Prince Ludwig of Bavaria to Princess Therese of Saxe-Hildburghausen. The citizens of Munich were invited to join in the festivities, which were held over five days on the fields in front of the city gates.",
      "date": "1810-10-12"
    },
    {
      "headline": "Introduction of Agricultural Show",
      "text": "In 1811, an agricultural show was added to the Oktoberfest to promote Bavarian agriculture. This tradition continues to this day, although it is now held only every four years.",
      "date": "1811"
    },
    {
      "headline": "First Horse Race",
      "text": "The first horse race, which was the highlight of the original Oktoberfest, was held in 1810 and continued annually until 1960.",
      "date": "1810"
    },
    {
      "headline": "First Beer Stalls",
      "text": "In 1818, the first beer stalls were introduced at Oktoberfest, marking the beginning of the festival's association with beer.",
      "date": "1818"
    },
    {
      "headline": "Introduction of Beer Tents",
      "text": "In 1896, the first large beer tents and halls replaced the smaller beer stands, allowing for a more organized and larger-scale beer service.",
      "date": "1896"
    },
    {
      "headline": "Oktoberfest Canceled Due to War",
      "text": "Oktoberfest was canceled during the years of World War I (1914-1918) and World War II (1939-1945).",
      "date": "1914"
    },
    {
      "headline": "Oktoberfest Resumes After WWII",
      "text": "The festival resumed in 1946, but it was initially called the 'Autumn Festival' due to post-war restrictions. It returned to its original name in 1949.",
      "date": "1946"
    },
    {
      "headline": "First Oktoberfest Bombing",
      "text": "On September 26, 1980, a bomb exploded at the main entrance of Oktoberfest, killing 13 people and injuring over 200. It was the deadliest terrorist attack in Germany since World War II.",
      "date": "1980-09-26"
    },
    {
      "headline": "200th Anniversary of Oktoberfest",
      "text": "In 2010, Oktoberfest celebrated its 200th anniversary with special events and historical exhibitions to commemorate its long history.",
      "date": "2010"
    },
    {
      "headline": "Oktoberfest Canceled Due to COVID-19",
      "text": "Oktoberfest was canceled in 2020 and 2021 due to the COVID-19 pandemic, marking the first time since World War II that the event did not take place.",
      "date": "2020"
    }
  ]
}

