{
  "timeline": [
    {
      "headline": "Establishment of the Han Dynasty",
      "text": "In 202 BC, Liu Bang, later known as Emperor Gaozu, established the Han dynasty after defeating Xiang Yu in the Chu–Han Contention.",
      "date": "-0202"
    },
    {
      "headline": "Reign of Emperor Gaozu",
      "text": "Emperor Gaozu ruled from 202 BC until his death in 195 BC, consolidating power and laying the foundation for the Han dynasty.",
      "date": "-0202"
    },
    {
      "headline": "Reign of Emperor Wen",
      "text": "Emperor Wen ruled from 180 BC to 157 BC, known for his frugality and efforts to reduce the tax burden on the people.",
      "date": "-0180"
    },
    {
      "headline": "Reign of Emperor Wu",
      "text": "Emperor Wu, who reigned from 141 BC to 87 BC, expanded the Han empire through military campaigns and established Confucianism as the state philosophy.",
      "date": "-0141"
    },
    {
      "headline": "Reign of Emperor Zhao",
      "text": "Emperor Zhao ruled from 87 BC to 74 BC, continuing the policies of his predecessor, Emperor Wu.",
      "date": "-0087"
    },
    {
      "headline": "Reign of Emperor Xuan",
      "text": "Emperor Xuan reigned from 74 BC to 49 BC, known for his efforts to stabilize the empire and promote economic prosperity.",
      "date": "-0074"
    },
    {
      "headline": "Reign of Emperor Yuan",
      "text": "Emperor Yuan ruled from 49 BC to 33 BC, focusing on Confucian scholarship and reducing military expenditures.",
      "date": "-0049"
    },
    {
      "headline": "Reign of Emperor Cheng",
      "text": "Emperor Cheng reigned from 33 BC to 7 BC, a period marked by increasing influence of eunuchs and palace intrigues.",
      "date": "-0033"
    },
    {
      "headline": "Reign of Emperor Ai",
      "text": "Emperor Ai ruled from 7 BC to 1 BC, known for his controversial policies and favoritism towards certain officials.",
      "date": "-0007"
    },
    {
      "headline": "Reign of Emperor Ping",
      "text": "Emperor Ping reigned from 1 BC to 6 AD, during which Wang Mang began consolidating power as regent.",
      "date": "-0001"
    },
    {
      "headline": "Xin Dynasty Interruption",
      "text": "In 9 AD, Wang Mang usurped the throne and established the Xin dynasty, interrupting the Han dynasty until 23 AD.",
      "date": "0009"
    },
    {
      "headline": "Restoration of the Han Dynasty",
      "text": "In 25 AD, Liu Xiu, known as Emperor Guangwu, restored the Han dynasty, marking the beginning of the Eastern Han period.",
      "date": "0025"
    },
    {
      "headline": "Reign of Emperor Ming",
      "text": "Emperor Ming ruled from 57 AD to 75 AD, known for promoting Buddhism in China.",
      "date": "0057"
    },
    {
      "headline": "Reign of Emperor Zhang",
      "text": "Emperor Zhang reigned from 75 AD to 88 AD, a period of peace and prosperity.",
      "date": "0075"
    },
    {
      "headline": "Reign of Emperor He",
      "text": "Emperor He ruled from 88 AD to 105 AD, during which the empire faced internal strife and external threats.",
      "date": "0088"
    },
    {
      "headline": "Reign of Emperor An",
      "text": "Emperor An reigned from 106 AD to 125 AD, marked by corruption and decline in central authority.",
      "date": "0106"
    },
