      "headline": "Arrival of Islam in India",
      "text": "Islam first arrived in the Indian subcontinent in the 7th century with Arab traders along the Malabar Coast in present-day Kerala.",
      "date": "0600"
    },
    {
      "headline": "Muhammad bin Qasim's Conquest",
      "text": "In 711, Muhammad bin Qasim led the Umayyad Caliphate's conquest of Sindh, marking the first major Muslim incursion into the Indian subcontinent.",
      "date": "0711"
    },
    {
      "headline": "Establishment of the Delhi Sultanate",
      "text": "In 1206, the Delhi Sultanate was established by Qutb-ud-din Aibak, marking the beginning of Muslim rule in northern India.",
      "date": "1206"
    },
    {
      "headline": "Tughlaq Dynasty",
      "text": "The Tughlaq dynasty ruled the Delhi Sultanate from 1320 to 1413, expanding the empire and consolidating Muslim rule in India.",
      "date": "1320"
    },
    {
      "headline": "Timur's Invasion",
      "text": "In 1398, Timur invaded India, sacking Delhi and weakening the Delhi Sultanate.",
      "date": "1398"
    },
    {
      "headline": "Founding of the Mughal Empire",
      "text": "In 1526, Babur defeated Ibrahim Lodi at the First Battle of Panipat, establishing the Mughal Empire in India.",
      "date": "1526"
    },
    {
      "headline": "Reign of Akbar the Great",
      "text": "Akbar the Great ruled from 1556 to 1605, known for his policy of religious tolerance and administrative reforms.",
      "date": "1556"
    },
    {
      "headline": "Aurangzeb's Reign",
      "text": "Aurangzeb ruled from 1658 to 1707, expanding the Mughal Empire to its greatest extent but also facing significant resistance due to his policies.",
      "date": "1658"
    },
    {
      "headline": "Decline of the Mughal Empire",
      "text": "The Mughal Empire began to decline after Aurangzeb's death in 1707, leading to the rise of regional powers and eventually British colonial rule.",
      "date": "1707"
    },
    {
      "headline": "Partition of India",
      "text": "In 1947, British India was partitioned into India and Pakistan, leading to significant migration and communal violence between Hindus and Muslims.",
      "date": "1947"
    },
    {
      "headline": "2011 Census",
      "text": "According to the 2011 census, Muslims made up 14.2% of India's population, amounting to approximately 172.2 million people.",
      "date": "2011"
    }
  ]
}

