{
  "timeline": [
    {
      "headline": "Origin of Cannabis",
      "text": "Cannabis is widely accepted as being indigenous to and originating from Asia. The exact timeline of its origin is not precisely known, but it is believed to have been used by humans for thousands of years.",
      "date": "-08000"
    },
    {
      "headline": "Earliest Evidence of Cannabis Use",
      "text": "The earliest evidence of cannabis use dates back to around 5000 BCE in ancient China, where it was used for its fibers and seeds.",
      "date": "-05000"
    },
    {
      "headline": "Cannabis in Ancient China",
      "text": "By 2727 BCE, cannabis was documented in the pharmacopoeia of Emperor Shen Nung, one of the fathers of Chinese medicine.",
      "date": "-02727"
    },
    {
      "headline": "Cannabis in Ancient India",
      "text": "Cannabis was used in ancient India for religious and medicinal purposes, with references found in the Atharva Veda, which dates back to around 2000 BCE.",
      "date": "-02000"
    },
    {
      "headline": "Cannabis in Ancient Egypt",
      "text": "Cannabis pollen was found on the mummy of Ramesses II, who died in 1213 BCE, indicating its use in ancient Egypt.",
      "date": "-01213"
    },
    {
      "headline": "Cannabis in Ancient Greece",
      "text": "In the 5th century BCE, Herodotus mentioned the use of cannabis by the Scythians, a nomadic people in the region of modern-day Ukraine.",
      "date": "-0500"
    },
    {
      "headline": "Cannabis in the Islamic Golden Age",
      "text": "During the Islamic Golden Age (8th to 13th centuries), cannabis was used in the Middle East for medicinal purposes and was documented by several scholars.",
      "date": "0800"
    },
    {
      "headline": "Introduction of Cannabis to the Americas",
      "text": "Cannabis was introduced to the Americas by the Spanish in the mid-16th century, primarily for hemp production.",
      "date": "1550"
    },
    {
      "headline": "Cannabis in the United States",
      "text": "In the early 20th century, cannabis became more widely used recreationally in the United States, leading to increased regulation and eventual prohibition.",
      "date": "1900"
    },
    {
      "headline": "Prohibition of Cannabis in the United States",
      "text": "The Marihuana Tax Act of 1937 effectively prohibited cannabis in the United States, marking the beginning of widespread legal restrictions.",
      "date": "1937"
    },
    {
      "headline": "Cannabis Legalization Movement",
      "text": "In the late 20th and early 21st centuries, a movement to legalize cannabis for medical and recreational use gained momentum, leading to changes in laws in several countries and U.S. states.",
      "date": "1990"
    },
    {
      "headline": "Canada Legalizes Cannabis",
      "text": "On October 17, 2018, Canada became the second country in the world to legalize cannabis for recreational use.",
      "date": "2018-10-17"
    }
  ]
}

