    {
      "headline": "Reign of Ptolemy III Euergetes",
      "text": "Ptolemy III Euergetes ruled from 246 BC to 222 BC, expanding the kingdom's territory and securing Egypt's prosperity.",
      "date": "-0246"
    },
    {
      "headline": "Reign of Ptolemy IV Philopator",
      "text": "Ptolemy IV Philopator reigned from 222 BC to 204 BC, during which the kingdom began to decline due to internal strife and external pressures.",
      "date": "-0222"
    },
    {
      "headline": "Reign of Ptolemy V Epiphanes",
      "text": "Ptolemy V Epiphanes ruled from 204 BC to 180 BC, known for the Rosetta Stone, which was created during his reign to establish his royal cult.",
      "date": "-0204"
    },
    {
      "headline": "Reign of Ptolemy VI Philometor",
      "text": "Ptolemy VI Philometor reigned from 180 BC to 145 BC, facing challenges from the Seleucid Empire and internal family disputes.",
      "date": "-0180"
    },
    {
      "headline": "Reign of Ptolemy VIII Physcon",
      "text": "Ptolemy VIII Physcon ruled intermittently from 145 BC to 116 BC, known for his tyrannical rule and conflicts with his siblings.",
      "date": "-0145"
    },
    {
      "headline": "Reign of Cleopatra VII",
      "text": "Cleopatra VII reigned from 51 BC to 30 BC, the last active ruler of the Ptolemaic Kingdom, known for her alliances with Julius Caesar and Mark Antony.",
