    {
      "headline": "First World Series",
      "text": "The first World Series was held in 1903. The Boston Americans (now the Boston Red Sox) of the American League defeated the Pittsburgh Pirates of the National League in a best-of-nine series, winning five games to three.",
      "date": "1903"
    },
    {
      "headline": "World Series Cancelled",
      "text": "The World Series was cancelled in 1904. The New York Giants, champions of the National League, refused to play the American League champions, the Boston Americans.",
      "date": "1904"
    },
    {
      "headline": "Resumption of World Series",
      "text": "The World Series resumed in 1905 and has been played annually since, except for 1994.",
      "date": "1905"
    },
    {
      "headline": "Black Sox Scandal",
      "text": "In 1919, the World Series was marred by the Black Sox Scandal, where eight players from the Chicago White Sox were accused of intentionally losing games in exchange for money from gamblers.",
      "date": "1919"
    },
    {
      "headline": "First Night Game",
      "text": "The first night game in World Series history was played on October 13, 1971, in Game 4 between the Pittsburgh Pirates and the Baltimore Orioles.",
      "date": "1971-10-13"
    },
    {
      "headline": "World Series Cancelled Due to Strike",
      "text": "The World Series was cancelled in 1994 due to a players' strike, marking the first time since 1904 that the series was not played.",
      "date": "1994"
    },
    {
      "headline": "First World Series Game in November",
      "text": "The first World Series game played in November occurred on November 1, 2001, due to the delay caused by the September 11 attacks.",
      "date": "2001-11-01"
    },
    {
      "headline": "Boston Red Sox Break the Curse",
      "text": "In 2004, the Boston Red Sox won the World Series, breaking the 'Curse of the Bambino' after 86 years without a championship.",
      "date": "2004"
    }
  ]
}

