{
  "timeline": [
    {
      "headline": "Initial Concept of Lithium-ion Battery",
      "text": "The concept of the lithium-ion battery was first proposed by M. Stanley Whittingham in the 1970s. He used titanium(IV) sulfide and lithium metal as the electrodes.",
      "date": "1970"
    },
    {
      "headline": "Development of Lithium Cobalt Oxide Cathode",
      "text": "In 1980, John B. Goodenough developed a lithium cobalt oxide (LiCoO2) cathode, which offered much higher energy density than previous designs.",
      "date": "1980"
    },
    {
      "headline": "Development of Graphite Anode",
      "text": "In 1985, Akira Yoshino developed a prototype lithium-ion battery using a carbonaceous material (graphite) as the anode, which was safer and more practical than lithium metal.",
      "date": "1985"
    },
    {
      "headline": "Commercial Introduction by Sony",
      "text": "Sony and Asahi Kasei released the first commercial lithium-ion battery in 1991, revolutionizing the portable electronics market.",
      "date": "1991"
    },
    {
      "headline": "Nobel Prize in Chemistry",
      "text": "In 2019, John B. Goodenough, M. Stanley Whittingham, and Akira Yoshino were awarded the Nobel Prize in Chemistry for their development of lithium-ion batteries.",
      "date": "2019"
    }
  ]
}

