{
  "timeline": [
    {
      "headline": "Start of the Gallipoli Campaign",
      "text": "The Gallipoli campaign began on 19 February 1915 with a naval attack by the Entente powers, including Britain and France, on the Dardanelles strait in an attempt to weaken the Ottoman Empire.",
      "date": "1915-02-19"
    },
    {
      "headline": "First Naval Attack",
      "text": "On 18 March 1915, the Entente powers launched a major naval attack on the Dardanelles, which ended in failure due to strong Ottoman defenses and minefields.",
      "date": "1915-03-18"
    },
    {
      "headline": "Land Invasion at Gallipoli",
      "text": "The land invasion of the Gallipoli peninsula began on 25 April 1915, with British, French, Australian, and New Zealand troops landing at various points, including Anzac Cove.",
      "date": "1915-04-25"
    },
    {
      "headline": "Battle of Krithia",
      "text": "The first Battle of Krithia took place on 28 April 1915, as part of the Gallipoli campaign, but resulted in a stalemate with heavy casualties on both sides.",
      "date": "1915-04-28"
    },
    {
      "headline": "Battle of Sari Bair",
      "text": "The Battle of Sari Bair, a major offensive by the Entente forces to capture the high ground of the Gallipoli peninsula, began on 6 August 1915 and ended unsuccessfully on 21 August 1915.",
      "date": "1915-08-06"
    },
    {
      "headline": "Evacuation of Suvla Bay and Anzac Cove",
      "text": "The evacuation of Suvla Bay and Anzac Cove was completed by 20 December 1915, marking a strategic withdrawal of Entente forces from these positions.",
      "date": "1915-12-20"
    },
    {
      "headline": "End of the Gallipoli Campaign",
      "text": "The Gallipoli campaign officially ended on 9 January 1916 with the evacuation of the last Entente troops from the peninsula, marking a victory for the Ottoman Empire.",
      "date": "1916-01-09"
    }
  ]
}

