      "text": "Construction of the Forbidden City began in 1406 under the orders of the Yongle Emperor of the Ming dynasty.",
      "date": "1406"
    },
    {
      "headline": "Completion of Construction",
      "text": "The construction of the Forbidden City was completed in 1420, marking the beginning of its use as the imperial palace.",
      "date": "1420"
    },
    {
      "headline": "Ming Dynasty Occupation",
      "text": "The Forbidden City served as the imperial palace for the Ming dynasty from 1420 until the dynasty's fall in 1644.",
      "date": "1420"
    },
    {
      "headline": "Qing Dynasty Occupation",
      "text": "After the fall of the Ming dynasty, the Forbidden City became the imperial palace for the Qing dynasty, starting in 1644.",
      "date": "1644"
    },
    {
      "headline": "End of Imperial Use",
      "text": "The Forbidden City ceased to be the political center of China in 1912 when the last emperor, Puyi, abdicated following the Xinhai Revolution.",
      "date": "1912"
    },
    {
      "headline": "Puyi's Expulsion",
      "text": "Puyi, the last emperor of China, was expelled from the Forbidden City in 1924, marking the end of its use as an imperial residence.",
      "date": "1924"
    },
    {
      "headline": "Establishment of the Palace Museum",
      "text": "The Palace Museum was established in the Forbidden City in 1925, opening the site to the public as a museum.",
      "date": "1925"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "The Forbidden City was declared a UNESCO World Heritage Site in 1987, recognized for its historical and cultural significance.",
      "date": "1987"
    }
  ]
}

