{
  "timeline": [
    {
      "headline": "Divergence from Genus Pan",
      "text": "The ancestors of the genus Homo diverged from the genus Pan, the closest living relatives, approximately 5.7 to 11 million years ago during the Late Miocene.",
      "date": "-11000000"
    },
    {
      "headline": "Emergence of Homo Genus",
      "text": "The genus Homo emerged from the genus Australopithecus, with the earliest known species being Homo habilis, which appeared just over 2 million years ago.",
      "date": "-2000000"
    },
    {
      "headline": "Homo habilis",
      "text": "Homo habilis is considered one of the earliest members of the genus Homo, living approximately 2.1 to 1.5 million years ago. It is known for its use of stone tools.",
      "date": "-2100000"
    },
    {
      "headline": "Homo erectus",
      "text": "Homo erectus appeared around 1.9 million years ago and is known for its significant increase in brain size and use of more advanced tools. It was one of the first hominins to leave Africa.",
      "date": "-1900000"
    },
    {
      "headline": "Homo heidelbergensis",
      "text": "Homo heidelbergensis lived approximately 600,000 to 200,000 years ago and is believed to be a common ancestor of both Neanderthals and modern humans.",
      "date": "-0600000"
    },
    {
      "headline": "Homo neanderthalensis",
      "text": "Homo neanderthalensis, commonly known as Neanderthals, lived from about 400,000 to 40,000 years ago. They were adapted to cold climates and had a robust build.",
      "date": "-0400000"
    },
    {
      "headline": "Emergence of Homo sapiens",
      "text": "Homo sapiens, the only extant species of the genus Homo, emerged approximately 300,000 years ago in Africa. They are characterized by a high forehead, rounded skull, and smaller teeth.",
      "date": "-0300000"
    },
    {
      "headline": "Out of Africa Migration",
      "text": "Homo sapiens began migrating out of Africa around 70,000 years ago, spreading across the globe and eventually replacing other hominin species.",
      "date": "-0070000"
    },
    {
      "headline": "Extinction of Neanderthals",
      "text": "Neanderthals became extinct approximately 40,000 years ago, possibly due to competition with Homo sapiens or climate change.",
      "date": "-0040000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Susan B. Anthony",
      "text": "Susan B. Anthony was born on February 15, 1820, in Adams, Massachusetts.",
      "date": "1820-02-15"
    },
    {
      "headline": "Early Activism in Anti-Slavery",
      "text": "At the age of 17, Susan B. Anthony collected anti-slavery petitions, marking her early involvement in social reform.",
      "date": "1837"
    },
    {
      "headline": "Becomes New York State Agent for the American Anti-Slavery Society",
      "text": "In 1856, Susan B. Anthony became the New York state agent for the American Anti-Slavery Society, furthering her commitment to the abolitionist movement.",
      "date": "1856"
    },
    {
      "headline": "Co-founds the American Equal Rights Association",
      "text": "In 1866, Susan B. Anthony co-founded the American Equal Rights Association with Elizabeth Cady Stanton, advocating for equal rights for both women and African Americans.",
      "date": "1866"
    },
    {
      "headline": "Publishes The Revolution",
      "text": "In 1868, Susan B. Anthony and Elizabeth Cady Stanton began publishing 'The Revolution', a weekly publication that advocated for women's rights.",
      "date": "1868"
    },
    {
      "headline": "Forms the National Woman Suffrage Association",
      "text": "In 1869, Susan B. Anthony and Elizabeth Cady Stanton founded the National Woman Suffrage Association, focusing on securing women's right to vote.",
      "date": "1869"
    },
    {
      "headline": "Votes in the 1872 Presidential Election",
      "text": "On November 5, 1872, Susan B. Anthony illegally voted in the presidential election in Rochester, New York, leading to her arrest and trial.",
      "date": "1872-11-05"
    },
    {
      "headline": "Trial for Voting",
      "text": "In 1873, Susan B. Anthony was tried and fined $100 for voting illegally in the 1872 election, a pivotal moment in the women's suffrage movement.",
      "date": "1873"
    },
    {
      "headline": "Death of Susan B. Anthony",
      "text": "Susan B. Anthony died on March 13, 1906, in Rochester, New York, leaving a lasting legacy in the fight for women's suffrage.",
      "date": "1906-03-13"
    }
  ]
}

