{
  "timeline": [
    {
      "headline": "Construction of the Dome of the Rock",
      "text": "The Dome of the Rock was constructed by the Umayyad Caliph Abd al-Malik between 688 and 692 CE. It is the world's oldest surviving work of Islamic architecture.",
      "date": "0692"
    },
    {
      "headline": "Completion of the Dome of the Rock",
      "text": "The construction of the Dome of the Rock was completed in 692 CE. It is located at the center of the Al-Aqsa mosque compound on the Temple Mount in the Old City of Jerusalem.",
      "date": "0692"
    },
    {
      "headline": "First Major Renovation",
      "text": "The Dome of the Rock underwent its first major renovation under the Abbasid Caliph Al-Ma'mun in 820 CE. This renovation included replacing the original wooden dome with a lead one.",
      "date": "0820"
    },
    {
      "headline": "Reconstruction of the Dome",
      "text": "In 1022-1023 CE, the Dome of the Rock was reconstructed by the Fatimid Caliph Ali az-Zahir after being damaged by an earthquake.",
      "date": "1023"
    },
    {
      "headline": "Crusader Period Alterations",
      "text": "During the Crusader period, the Dome of the Rock was converted into a church and named Templum Domini (Temple of the Lord) in 1099 CE.",
      "date": "1099"
    },
    {
      "headline": "Restoration by Saladin",
      "text": "After the recapture of Jerusalem by Saladin in 1187 CE, the Dome of the Rock was restored to its original Islamic function.",
      "date": "1187"
    },
    {
      "headline": "Ottoman Renovations",
      "text": "In the 16th century, the Ottoman Sultan Suleiman the Magnificent ordered extensive renovations of the Dome of the Rock, including the addition of the current exterior tile work.",
      "date": "1500"
    },
    {
      "headline": "Modern Restoration",
