      "headline": "Foundation of Kyiv",
      "text": "Kyiv is believed to have been founded in the late 5th or early 6th century as a Slavic settlement.",
      "date": "-0500"
    },
    {
      "headline": "Kyiv becomes the capital of Kievan Rus'",
      "text": "In the late 9th century, Kyiv became the capital of Kievan Rus', a federation of Slavic tribes.",
      "date": "0882"
    },
    {
      "headline": "Christianization of Kievan Rus'",
      "text": "In 988, Grand Prince Vladimir the Great of Kyiv converted to Christianity and Christianized Kievan Rus'.",
      "date": "0988"
    },
    {
      "headline": "Mongol Invasion",
      "text": "In 1240, Kyiv was sacked by the Mongol Empire, leading to a significant decline in its importance.",
      "date": "1240"
    },
    {
      "headline": "Union with Lithuania",
      "text": "In 1362, Kyiv became part of the Grand Duchy of Lithuania after the Battle of Blue Waters.",
      "date": "1362"
    },
    {
      "headline": "Union with Poland",
      "text": "In 1569, Kyiv became part of the Polish-Lithuanian Commonwealth following the Union of Lublin.",
      "date": "1569"
    },
    {
      "headline": "Khmelnytsky Uprising",
      "text": "In 1648, the Khmelnytsky Uprising began, leading to Kyiv becoming part of the Cossack Hetmanate under Russian protection.",
      "date": "1648"
    },
    {
      "headline": "Russian Empire Control",
      "text": "In 1793, Kyiv was fully integrated into the Russian Empire following the Second Partition of Poland.",
      "date": "1793"
    },
    {
      "headline": "Kyiv becomes part of the Ukrainian SSR",
      "text": "In 1921, Kyiv became part of the Ukrainian Soviet Socialist Republic within the Soviet Union.",
      "date": "1921"
    },
    {
      "headline": "World War II Occupation",
      "text": "Kyiv was occupied by Nazi Germany from September 19, 1941, until November 6, 1943.",
      "date": "1941-09-19"
    },
    {
      "headline": "Kyiv becomes the capital of independent Ukraine",
      "text": "On August 24, 1991, Ukraine declared independence from the Soviet Union, with Kyiv as its capital.",
      "date": "1991-08-24"
    },
    {
      "headline": "Orange Revolution",
      "text": "In 2004, Kyiv was the center of the Orange Revolution, a series of protests and political events following a disputed presidential election.",
      "date": "2004"
    },
    {
      "headline": "Euromaidan Protests",
      "text": "Starting in November 2013, Kyiv was the focal point of the Euromaidan protests, which led to significant political changes in Ukraine.",
      "date": "2013-11"
