{
  "timeline": [
    {
      "headline": "Origins of Ayurveda",
      "text": "Ayurveda is believed to have originated in India over 3,000 years ago. The earliest references to Ayurveda are found in the Vedas, particularly the Atharva Veda, which dates back to around 1500 BCE.",
      "date": "-1500"
    },
    {
      "headline": "Compilation of Ayurvedic Texts",
      "text": "The foundational texts of Ayurveda, the Charaka Samhita and Sushruta Samhita, were compiled around 600 BCE. These texts provide detailed information on various aspects of medicine, surgery, and health practices.",
      "date": "-0600"
    },
    {
      "headline": "Development of the Ashtanga Hridaya",
      "text": "Around 400 CE, the Ashtanga Hridaya, a central Ayurvedic text, was composed by Vagbhata. It synthesized earlier Ayurvedic knowledge and became one of the most influential texts in the tradition.",
      "date": "0400"
    },
    {
      "headline": "Influence of Ayurveda in the Gupta Period",
      "text": "During the Gupta Empire (approximately 320-550 CE), Ayurveda flourished as a major system of medicine in India. This period saw the establishment of many Ayurvedic schools and hospitals.",
      "date": "0320"
    },
    {
      "headline": "Spread of Ayurveda to the Arab World",
      "text": "In the 8th century, Ayurvedic knowledge was translated into Arabic and Persian, influencing medical practices in the Arab world and later in Europe.",
      "date": "0800"
    },
    {
      "headline": "Colonial Impact on Ayurveda",
      "text": "During British colonial rule in India (1757-1947), Ayurveda faced suppression as Western medicine was promoted. However, it continued to be practiced by traditional healers and in rural areas.",
      "date": "1757"
    },
    {
      "headline": "Revival of Ayurveda in Modern India",
      "text": "Post-independence in 1947, India saw a revival of Ayurveda. The government established institutions for Ayurvedic education and research, integrating it into the national healthcare system.",
      "date": "1947"
    },
    {
      "headline": "Globalization of Ayurveda",
      "text": "In the late 20th and early 21st centuries, Ayurveda gained popularity worldwide as part of the holistic health and wellness movement. It is now practiced in many countries outside India.",
      "date": "2000"
    }
  ]
}

