{
  "timeline": [
    {
      "headline": "Institution of the Eucharist",
      "text": "According to Christian tradition, Jesus instituted the Eucharist during the Last Supper, which took place on the night before his crucifixion. This event is described in the synoptic Gospels as occurring during a Passover meal. Jesus gave his disciples bread and wine, referring to the bread as 'my body' and the wine as 'the blood of my covenant, which is poured out for many'. He commanded them to 'do this in memory of me'.",
      "date": "-0033"
    },
    {
      "headline": "Paul's First Letter to the Corinthians",
      "text": "Around 53-54 AD, Paul the Apostle wrote the First Letter to the Corinthians, which includes one of the earliest written accounts of the Eucharist. In 1 Corinthians 11:23-26, Paul recounts the words of Jesus at the Last Supper and emphasizes the importance of the rite.",
      "date": "0053"
    },
    {
      "headline": "Development of Eucharistic Theology",
      "text": "Throughout the early centuries of Christianity, the theology and understanding of the Eucharist developed significantly. Church Fathers like Ignatius of Antioch, Justin Martyr, and Irenaeus wrote about the Eucharist, emphasizing its significance as a sacrament and its role in Christian worship.",
      "date": "0100"
    },
    {
      "headline": "Council of Nicaea",
      "text": "In 325 AD, the First Council of Nicaea, the first ecumenical council of the Christian Church, affirmed the practice of the Eucharist and helped to standardize its celebration across the Christian world.",
      "date": "0325"
    },
    {
      "headline": "Fourth Lateran Council",
      "text": "In 1215, the Fourth Lateran Council defined the doctrine of transubstantiation, which describes the change of the substance of bread and wine into the body and blood of Christ during the Eucharist, while the appearances of bread and wine remain.",
      "date": "1215"
    },
    {
      "headline": "Council of Trent",
      "text": "Between 1545 and 1563, the Council of Trent was held in response to the Protestant Reformation. It reaffirmed the Catholic Church's teachings on the Eucharist, including the doctrine of transubstantiation and the sacrificial nature of the Mass.",
      "date": "1545"
    },
    {
      "headline": "Second Vatican Council",
      "text": "The Second Vatican Council, held from 1962 to 1965, brought significant changes to the Catholic Church's liturgy, including the celebration of the Eucharist. It allowed for the use of vernacular languages in the Mass and encouraged active participation by the laity.",
      "date": "1962"
    }
  ]
}

