    },
    {
      "headline": "Doha Development Round Launch",
      "text": "The Doha Development Round, a trade negotiation round of the WTO which commenced in November 2001, aimed to achieve major reform of the international trading system through the introduction of lower trade barriers and revised trade rules.",
      "date": "2001-11"
    },
    {
      "headline": "Accession of China",
      "text": "China officially joined the WTO on December 11, 2001, marking a significant expansion of the organization and integrating China into the global trading system.",
      "date": "2001-12-11"
    },
    {
      "headline": "Bali Package Agreement",
      "text": "In December 2013, the WTO reached a significant agreement known as the Bali Package, which aimed to streamline trade, allow developing countries more options for providing food security, boost least-developed countries' trade, and help development more generally.",
      "date": "2013-12"
    },
    {
      "headline": "Trade Facilitation Agreement",
      "text": "The Trade Facilitation Agreement (TFA), the first multilateral deal concluded in the 21-year history of the WTO, entered into force on February 22, 2017. It aims to expedite the movement, release, and clearance of goods across borders.",
      "date": "2017-02-22"
    }
  ]
}

