{
  "timeline": [
    {
      "headline": "German Invasion Begins",
      "text": "On May 10, 1940, Germany launched its invasion of the Low Countries and France, marking the beginning of the Battle of France. This operation was known as Case Yellow.",
      "date": "1940-05-10"
    },
    {
      "headline": "Evacuation at Dunkirk",
      "text": "From May 26 to June 4, 1940, Allied forces conducted a massive evacuation of troops from Dunkirk, France, in an operation known as Operation Dynamo.",
      "date": "1940-05-26"
    },
    {
      "headline": "Fall Rot Begins",
      "text": "On June 5, 1940, Germany launched Fall Rot, the second phase of the invasion, aimed at defeating the remaining French forces after the evacuation at Dunkirk.",
      "date": "1940-06-05"
    },
    {
      "headline": "Paris Falls to Germany",
      "text": "On June 14, 1940, German forces entered Paris, leading to the city's fall and further demoralizing the French resistance.",
      "date": "1940-06-14"
    },
    {
      "headline": "Armistice Signed",
      "text": "On June 22, 1940, France signed an armistice with Germany, leading to the occupation of northern and western France by German forces.",
      "date": "1940-06-22"
    },
    {
      "headline": "Vichy France Established",
      "text": "Following the armistice, the Vichy regime was established on July 10, 1940, governing the unoccupied southern part of France.",
      "date": "1940-07-10"
    },
    {
      "headline": "Wehrmacht Occupies Vichy France",
      "text": "In November 1942, German troops occupied Vichy France, ending the nominal independence of the Vichy regime and consolidating German control over all of France.",
      "date": "1942-11"
    },
    {
      "headline": "Normandy Landings",
      "text": "On June 6, 1944, the Normandy landings began, marking the start of the liberation of Western Europe from Nazi occupation.",
      "date": "1944-06-06"
    }
  ]
}

