{
  "timeline": [
    {
      "headline": "Origins of Lacrosse",
      "text": "Lacrosse originated with the indigenous people of North America as early as the 12th century. It was played by various Native American tribes, particularly in the eastern half of North America.",
      "date": "-1100"
    },
    {
      "headline": "First European Observation",
      "text": "In 1637, French Jesuit missionary Jean de Brébeuf was the first European to document the game, observing it being played by the Huron people.",
      "date": "1637"
    },
    {
      "headline": "Naming of Lacrosse",
      "text": "The name 'lacrosse' was coined by French settlers in the 17th century, derived from the French term 'la crosse', meaning 'the stick'.",
      "date": "1600"
    },
    {
      "headline": "First Recorded Game",
      "text": "The first recorded game of lacrosse between Europeans and Native Americans took place in 1844 in Montreal, Canada.",
      "date": "1844"
    },
    {
      "headline": "Codification of Rules",
      "text": "In 1856, the Montreal Lacrosse Club was founded, and in 1867, Canadian dentist Dr. William George Beers codified the first set of rules for the game.",
      "date": "1867"
    },
    {
      "headline": "Lacrosse Becomes Canada's National Game",
      "text": "In 1867, lacrosse was declared the national game of Canada by the Canadian Parliament.",
      "date": "1867"
    },
    {
      "headline": "Introduction to the United States",
      "text": "Lacrosse was introduced to the United States in the late 19th century, with the first college teams forming in the 1870s.",
      "date": "1870"
    },
    {
      "headline": "Formation of the United States Intercollegiate Lacrosse Association",
      "text": "In 1882, the United States Intercollegiate Lacrosse Association (USILA) was formed to govern the sport at the college level.",
      "date": "1882"
    },
    {
      "headline": "Lacrosse in the Olympics",
      "text": "Lacrosse was played as a demonstration sport in the 1904 and 1908 Summer Olympics.",
      "date": "1904"
    },
    {
      "headline": "Formation of the International Lacrosse Federation",
      "text": "In 1974, the International Lacrosse Federation (ILF) was formed to promote and develop the sport worldwide.",
      "date": "1974"
    },
    {
      "headline": "Merger to Form World Lacrosse",
      "text": "In 2008, the International Lacrosse Federation (ILF) and the International Federation of Women's Lacrosse Associations (IFWLA) merged to form World Lacrosse, the international governing body for the sport.",
      "date": "2008"
    }
  ]
}

{
