{
  "timeline": [
    {
      "headline": "Earliest Use of Hieroglyphs",
      "text": "The earliest known use of Egyptian hieroglyphs dates back to around 3300 BCE. These early hieroglyphs were used primarily for administrative and ceremonial purposes.",
      "date": "-3300"
    },
    {
      "headline": "Development of Cursive Hieroglyphs",
      "text": "Cursive hieroglyphs were developed for religious literature on papyrus and wood. This form of writing was more fluid and less formal than monumental hieroglyphs.",
      "date": "-2600"
    },
    {
      "headline": "Creation of Hieratic Script",
      "text": "Around 2000 BCE, the hieratic script was developed as a cursive form of hieroglyphs, used primarily for religious texts and administrative documents.",
      "date": "-2000"
    },
    {
      "headline": "Development of Demotic Script",
      "text": "The demotic script evolved from the hieratic script around 650 BCE. It was used for daily purposes and became the dominant script for administrative and legal documents.",
      "date": "-0650"
    },
    {
      "headline": "Proto-Sinaitic Script",
      "text": "Around 1800 BCE, the Proto-Sinaitic script, which later evolved into the Phoenician alphabet, was derived from Egyptian hieroglyphs. This script is considered the ancestor of most modern alphabets.",
      "date": "-1800"
    },
    {
      "headline": "Decline of Hieroglyphic Writing",
      "text": "The use of hieroglyphic writing began to decline after the Roman conquest of Egypt in 30 BCE, as Greek and Latin became more dominant.",
      "date": "-0030"
    },
    {
      "headline": "Last Known Hieroglyphic Inscription",
      "text": "The last known inscription in Egyptian hieroglyphs is dated to 394 CE, found on the island of Philae.",
      "date": "0394"
    }
  ]
}

{
