      "headline": "Creation of Saturn Devouring His Son",
      "text": "Francisco Goya painted Saturn Devouring His Son directly onto the walls of his house, Quinta del Sordo, as part of the series known as the Black Paintings. This work was created sometime between 1820 and 1823.",
      "date": "1820"
    },
    {
      "headline": "Transfer to Canvas",
      "text": "After Francisco Goya's death, the painting Saturn Devouring His Son was transferred from the wall to canvas. This process preserved the artwork for future generations.",
      "date": "1828"
    },
    {
      "headline": "Display at Museo del Prado",
      "text": "Saturn Devouring His Son is now housed in the Museo del Prado in Madrid, where it is displayed as one of Goya's most famous works.",
      "date": "1874"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "UNSCOP Drafts Partition Plan",
      "text": "The United Nations Special Committee on Palestine (UNSCOP) drafted the Partition Plan for Palestine on 3 September 1947. The plan proposed the end of the British Mandate and the partition of Palestine into independent Arab and Jewish states.",
      "date": "1947-09-03"
    },
    {
      "headline": "UN General Assembly Adopts Resolution 181",
      "text": "On 29 November 1947, the United Nations General Assembly adopted Resolution 181 (II), which recommended the implementation of the Partition Plan. The resolution called for the creation of independent Arab and Jewish states and a Special International Regime for Jerusalem.",
      "date": "1947-11-29"
    },
    {
      "headline": "British Mandate Scheduled to End",
      "text": "The British Mandate for Palestine was scheduled to end on 15 May 1948, as per the terms of the Partition Plan. This date marked the planned transition to the new political arrangement proposed by the UN.",
      "date": "1948-05-15"
    }
  ]
}

