    {
      "headline": "Islamization",
      "text": "From the 16th to the 19th centuries, the Circassians gradually converted to Islam due to Ottoman influence.",
      "date": "1500"
    },
    {
      "headline": "Russo-Circassian War",
      "text": "The Russo-Circassian War, a series of military conflicts between the Russian Empire and the Circassians, lasted from 1763 to 1864.",
      "date": "1763"
    },
    {
      "headline": "Circassian Genocide",
      "text": "In 1864, following the end of the Russo-Circassian War, the Russian Empire expelled and killed a large number of Circassians, an event recognized by many as the Circassian Genocide.",
      "date": "1864"
    },
    {
      "headline": "Diaspora Formation",
      "text": "After the Circassian Genocide, many Circassians were forced into exile, forming a large diaspora in Turkey, the Middle East, and other regions.",
      "date": "1864"
    },
    {
      "headline": "Soviet Era",
      "text": "During the Soviet era, Circassian culture and language were suppressed, and many Circassians were assimilated into the broader Soviet identity.",
      "date": "1922"
    },
    {
      "headline": "Post-Soviet Revival",
      "text": "Following the dissolution of the Soviet Union in 1991, there has been a revival of Circassian culture and identity, with efforts to preserve the language and traditions.",
      "date": "1991"
    }
  ]
}

{
