{
  "timeline": [
    {
      "headline": "Establishment of the Tang Dynasty",
      "text": "The Tang dynasty was established in 618 when Li Yuan, known as Emperor Gaozu, seized the throne from the Sui dynasty.",
      "date": "0618"
    },
    {
      "headline": "Reign of Emperor Taizong",
      "text": "Emperor Taizong, the second emperor of the Tang dynasty, reigned from 626 to 649. His reign is considered a golden age of prosperity and stability.",
      "date": "0626"
    },
    {
      "headline": "Battle of Hulao",
      "text": "In 621, the Tang forces, led by Li Shimin (later Emperor Taizong), defeated the rival warlord Wang Shichong at the Battle of Hulao, consolidating Tang control over China.",
      "date": "0621"
    },
    {
      "headline": "Empress Wu Zetian's Rule",
      "text": "Wu Zetian, the only female emperor in Chinese history, ruled from 690 to 705, establishing the Zhou dynasty during her reign.",
      "date": "0690"
    },
    {
      "headline": "Reinstatement of the Tang Dynasty",
      "text": "In 705, the Tang dynasty was restored after the fall of Wu Zetian's Zhou dynasty.",
      "date": "0705"
    },
    {
      "headline": "An Lushan Rebellion",
      "text": "The An Lushan Rebellion began in 755, leading to a devastating civil war that lasted until 763, significantly weakening the Tang dynasty.",
      "date": "0755"
    },
    {
      "headline": "End of the An Lushan Rebellion",
      "text": "The An Lushan Rebellion ended in 763, but it left the Tang dynasty weakened and contributed to its eventual decline.",
      "date": "0763"
    },
    {
      "headline": "Huang Chao Rebellion",
      "text": "The Huang Chao Rebellion, which lasted from 874 to 884, further destabilized the Tang dynasty and hastened its decline.",
      "date": "0874"
    },
    {
      "headline": "Fall of the Tang Dynasty",
      "text": "The Tang dynasty officially ended in 907 when Zhu Wen, a military governor, usurped the throne and established the Later Liang dynasty.",
      "date": "0907"
    }
  ]
}

