{
  "timeline": [
    {
      "headline": "Introduction of the Domain Name System (DNS)",
      "text": "The Domain Name System (DNS) was introduced in 1983 as a solution to the growing problem of maintaining a single, centralized host table on the ARPANET. DNS was designed to be a distributed and hierarchical system that could scale with the growth of the Internet.",
      "date": "1983"
    },
    {
      "headline": "Publication of RFC 882 and RFC 883",
      "text": "In November 1983, the specifications for the Domain Name System were published in RFC 882 and RFC 883 by Paul Mockapetris. These documents outlined the concepts and initial implementation of DNS.",
      "date": "1983-11"
    },
    {
      "headline": "Replacement of Host Table with DNS",
      "text": "In 1984, the Domain Name System began to replace the centralized host table system, which had become impractical due to the rapid growth of the Internet.",
      "date": "1984"
    },
    {
      "headline": "Publication of RFC 1034 and RFC 1035",
      "text": "In November 1987, RFC 1034 and RFC 1035 were published, updating and refining the DNS specifications. These documents, authored by Paul Mockapetris, became the foundational standards for DNS.",
      "date": "1987-11"
    },
    {
      "headline": "Introduction of DNS Security Extensions (DNSSEC)",
      "text": "In 1999, the DNS Security Extensions (DNSSEC) were introduced to add security to the DNS protocol by enabling DNS responses to be verified for authenticity.",
      "date": "1999"
    },
    {
      "headline": "Deployment of DNSSEC Root Zone",
      "text": "In July 2010, the root zone of the DNS was signed with DNSSEC, marking a significant milestone in enhancing the security of the DNS infrastructure.",
      "date": "2010-07"
    }
  ]
}

