  "timeline": [
    {
      "headline": "Invention of the Camera Obscura",
      "text": "The camera obscura, a precursor to the modern camera, was developed as early as the 11th century. It was a dark room or box with a small hole that projected an inverted image of the outside scene onto the opposite wall.",
      "date": "-1000"
    },
    {
      "headline": "First Photograph",
      "text": "In 1826 or 1827, Joseph Nicéphore Niépce took the first permanent photograph using a camera obscura and a process called heliography. The image was captured on a pewter plate coated with bitumen.",
      "date": "1826"
    },
    {
      "headline": "Daguerreotype Process Announced",
      "text": "In 1839, Louis Daguerre announced the daguerreotype process, the first publicly available photographic process, which created highly detailed images on silvered copper plates.",
      "date": "1839"
    },
    {
      "headline": "Introduction of Calotype Process",
      "text": "In 1841, William Henry Fox Talbot introduced the calotype process, which used paper coated with silver iodide to create a negative image that could be used to produce multiple positive prints.",
      "date": "1841"
    },
    {
      "headline": "Invention of the Collodion Process",
      "text": "In 1851, Frederick Scott Archer invented the collodion process, which allowed for quicker exposure times and sharper images than previous methods, using glass plates coated with collodion.",
      "date": "1851"
    },
    {
      "headline": "Introduction of Dry Plate Photography",
      "text": "In 1871, Richard Leach Maddox introduced the dry plate process, which used gelatin-coated glass plates, making photography more convenient and accessible.",
      "date": "1871"
    },
    {
      "headline": "Kodak Box Camera Released",
      "text": "In 1888, George Eastman released the Kodak box camera, which was pre-loaded with film and allowed users to take multiple photographs before sending the camera back to the factory for processing.",
      "date": "1888"
    },
    {
      "headline": "Introduction of 35mm Film",
      "text": "In 1925, the Leica I, the first commercially successful 35mm camera, was introduced, popularizing the use of 35mm film in photography.",
      "date": "1925"
    },
    {
      "headline": "Polaroid Instant Camera Launched",
      "text": "In 1948, Edwin Land introduced the Polaroid Model 95, the first instant camera that could produce a developed photograph within minutes of taking the picture.",
      "date": "1948"
    },
    {
      "headline": "First Digital Camera Invented",
      "text": "In 1975, Steven Sasson, an engineer at Eastman Kodak, invented the first digital camera, which used a CCD image sensor to capture images.",
      "date": "1975"
    },
    {
      "headline": "Introduction of DSLR Cameras",
      "text": "In 1988, Nikon released the QV-1000C, one of the first digital single-lens reflex (DSLR) cameras, which combined the optics and mechanisms of a single-lens reflex camera with a digital imaging sensor.",
      "date": "1988"
    },
    {
      "headline": "Launch of the First Camera Phone",
      "text": "In 2000, Sharp introduced the J-SH04, the first commercially available camera phone, in Japan, marking the beginning of widespread mobile photography.",
      "date": "2000"
    }
  ]
}

