{
  "timeline": [
    {
      "headline": "Concept of Continental Drift",
      "text": "The idea of continental drift, which laid the groundwork for plate tectonics, was developed during the first decades of the 20th century. Alfred Wegener was a key figure in proposing that continents were once joined and have since drifted apart.",
      "date": "1912"
    },
    {
      "headline": "Alfred Wegener's Theory",
      "text": "In 1912, Alfred Wegener presented his theory of continental drift, suggesting that continents were once part of a single landmass and have drifted to their current positions.",
      "date": "1912"
    },
    {
      "headline": "Seafloor Spreading Hypothesis",
      "text": "In the 1960s, the hypothesis of seafloor spreading was proposed, providing a mechanism for continental drift. This hypothesis suggested that new oceanic crust is formed at mid-ocean ridges and spreads outward.",
      "date": "1960"
    },
    {
      "headline": "Acceptance of Plate Tectonics",
      "text": "By the mid-to-late 1960s, the theory of plate tectonics was widely accepted by geoscientists. This acceptance was largely due to the validation of seafloor spreading and the discovery of symmetrical magnetic stripes on the ocean floor.",
      "date": "1967"
    },
    {
      "headline": "Development of Plate Tectonics Theory",
      "text": "The theory of plate tectonics was developed further in the late 1960s and early 1970s, integrating concepts of continental drift and seafloor spreading into a comprehensive model explaining the movement of Earth's lithosphere.",
      "date": "1970"
    }
  ]
}

