      "headline": "Birth of Adam Smith",
      "text": "Adam Smith was born on June 16, 1723, in Kirkcaldy, Scotland.",
      "date": "1723-06-16"
    },
    {
      "headline": "Education at University of Glasgow",
      "text": "In 1737, at the age of 14, Adam Smith entered the University of Glasgow, where he studied moral philosophy under Francis Hutcheson.",
      "date": "1737"
    },
    {
      "headline": "Studies at Balliol College, Oxford",
      "text": "In 1740, Smith won a scholarship to attend Balliol College, Oxford, where he studied for six years.",
      "date": "1740"
