{
  "timeline": [
    {
      "headline": "Birth of Atlas",
      "text": "Atlas was born as a Titan in Greek mythology, the son of the Titan Iapetus and the Oceanid Clymene (or Asia). His birth is part of the mythological era of the Titans, which predates the Olympian gods.",
      "date": "-3000"
    },
    {
      "headline": "Titanomachy",
      "text": "Atlas participated in the Titanomachy, the war between the Titans and the Olympian gods. After the defeat of the Titans, Atlas was condemned by Zeus to hold up the heavens for eternity.",
      "date": "-1500"
    },
    {
      "headline": "Role in Heracles' Labors",
      "text": "Atlas plays a role in the myth of Heracles (Hercules), specifically in his Twelve Labors. Heracles was tasked with retrieving the Golden Apples of the Hesperides, and he sought the help of Atlas to accomplish this task.",
      "date": "-1200"
    },
    {
      "headline": "Encounter with Perseus",
      "text": "In another myth, Perseus encounters Atlas during his journey. Perseus uses the head of Medusa to turn Atlas into stone, which is said to have formed the Atlas Mountains.",
      "date": "-1100"
    },
    {
      "headline": "King of Mauretania",
      "text": "Atlas was later identified as the first King of Mauretania, a region in northwest Africa. He was said to have been skilled in philosophy, mathematics, and astronomy.",
      "date": "-1000"
    },
    {
      "headline": "Invention of the Celestial Sphere",
      "text": "Atlas is credited with inventing the first celestial sphere, a model of the heavens. In some texts, he is even credited with the invention of astronomy itself.",
      "date": "-900"
    }
  ]
}

