{
  "timeline": [
    {
      "headline": "Beginning of the Atlantic Slave Trade",
      "text": "The Atlantic slave trade began in the 15th century when Portuguese traders started capturing and buying enslaved Africans to work in Europe and on Atlantic islands.",
      "date": "1400"
    },
    {
      "headline": "Expansion to the Americas",
      "text": "In the 16th century, the Atlantic slave trade expanded to the Americas, with European traders transporting enslaved Africans across the Atlantic Ocean to work on plantations in the New World.",
      "date": "1500"
    },
    {
      "headline": "Triangular Trade Route",
      "text": "The triangular trade route was established, involving the transportation of goods from Europe to Africa, enslaved Africans to the Americas, and raw materials back to Europe.",
      "date": "1600"
    },
    {
      "headline": "Peak of the Slave Trade",
      "text": "The 18th century marked the peak of the Atlantic slave trade, with millions of Africans being transported to the Americas under brutal conditions.",
      "date": "1700"
    },
    {
      "headline": "Abolition Movements Begin",
      "text": "In the late 18th century, abolition movements began to gain momentum in Europe and the Americas, calling for the end of the slave trade and slavery.",
      "date": "1780"
    },
    {
      "headline": "British Abolition of the Slave Trade",
      "text": "The British Parliament passed the Slave Trade Act in 1807, which made it illegal to engage in the slave trade within the British Empire.",
      "date": "1807"
    },
    {
      "headline": "End of the Atlantic Slave Trade",
      "text": "The Atlantic slave trade effectively ended in the 19th century, although illegal trading continued for some time. The last known slave ship arrived in the Americas in 1860.",
      "date": "1860"
    }
  ]
}

