{
  "timeline": [
    {
      "headline": "Dmitri Ivanovsky's Discovery",
      "text": "In 1892, Dmitri Ivanovsky published an article describing a non-bacterial pathogen infecting tobacco plants, marking one of the earliest studies of viruses.",
      "date": "1892"
    },
    {
      "headline": "Discovery of Tobacco Mosaic Virus",
      "text": "In 1898, Martinus Beijerinck discovered the tobacco mosaic virus, which he described as a new type of infectious agent, coining the term 'virus'.",
      "date": "1898"
    },
    {
      "headline": "Bacteriophage Discovery",
      "text": "In 1915, Frederick Twort discovered bacteriophages, viruses that infect bacteria, further expanding the understanding of viral entities.",
      "date": "1915"
    },
    {
      "headline": "First Animal Virus Identified",
      "text": "In 1898, Friedrich Loeffler and Paul Frosch identified the first animal virus, the foot-and-mouth disease virus, demonstrating that viruses could infect animals.",
      "date": "1898"
    },
    {
      "headline": "Discovery of Influenza Virus",
      "text": "In 1933, the influenza virus was isolated by Wilson Smith, Christopher Andrewes, and Patrick Laidlaw, marking a significant advancement in medical virology.",
      "date": "1933"
    },
    {
      "headline": "Electron Microscopy of Viruses",
      "text": "In 1939, the first electron micrographs of viruses were taken, allowing scientists to see viruses for the first time and study their structure in detail.",
      "date": "1939"
    },
    {
      "headline": "Polio Vaccine Development",
      "text": "In 1955, Jonas Salk developed the first effective polio vaccine, a major milestone in virology and public health.",
      "date": "1955"
    },
    {
      "headline": "Discovery of HIV",
      "text": "In 1983, the human immunodeficiency virus (HIV) was discovered by Luc Montagnier and his team, identifying the cause of AIDS.",
      "date": "1983"
    },
    {
      "headline": "SARS Outbreak",
      "text": "In 2003, the severe acute respiratory syndrome (SARS) outbreak occurred, caused by a novel coronavirus, highlighting the global impact of viral diseases.",
      "date": "2003"
    },
    {
      "headline": "COVID-19 Pandemic",
      "text": "In 2019, the COVID-19 pandemic began, caused by the SARS-CoV-2 virus, leading to unprecedented global health and economic challenges.",
      "date": "2019"
    }
  ]
}

