{
  "timeline": [
    {
      "headline": "Formation of the Iroquois Confederacy",
      "text": "The Iroquois Confederacy, originally known as the Five Nations, was formed by the Mohawk, Oneida, Onondaga, Cayuga, and Seneca tribes. The exact date of formation is debated, but it is believed to have been established between 1450 and 1600.",
      "date": "1450"
    },
    {
      "headline": "Addition of the Tuscarora",
      "text": "In 1722, the Tuscarora people, originally from the southeast, were accepted into the Iroquois Confederacy, which then became known as the Six Nations.",
      "date": "1722"
    },
    {
      "headline": "Iroquois in the American Revolutionary War",
      "text": "During the American Revolutionary War (1775-1783), the Iroquois Confederacy was divided, with some nations siding with the British and others with the American colonists.",
      "date": "1775"
    },
    {
      "headline": "Treaty of Canandaigua",
      "text": "On November 11, 1794, the Treaty of Canandaigua was signed between the United States and the Six Nations, recognizing their land rights in New York.",
      "date": "1794-11-11"
    },
    {
      "headline": "Establishment of the Grand River Reserve",
      "text": "In 1784, following the American Revolutionary War, the British granted the Iroquois land along the Grand River in what is now Ontario, Canada, as a reward for their loyalty.",
      "date": "1784"
    }
  ]
}

