    {
      "headline": "Hussite Wars",
      "text": "The Hussite Wars, a series of conflicts in Bohemia, took place from 1419 to 1434, following the execution of reformer Jan Hus.",
      "date": "1419"
    },
    {
      "headline": "Battle of White Mountain",
      "text": "On November 8, 1620, the Battle of White Mountain took place, marking a decisive Catholic victory in the Thirty Years' War and leading to the re-Catholicization of Bohemia.",
      "date": "1620-11-08"
    },
    {
      "headline": "Austrian Rule",
      "text": "After the Battle of White Mountain, Bohemia became part of the Habsburg Monarchy, which lasted until the end of World War I in 1918.",
      "date": "1620"
    },
    {
      "headline": "Formation of Czechoslovakia",
      "text": "In 1918, after World War I, Bohemia became part of the newly formed state of Czechoslovakia.",
      "date": "1918"
    },
    {
      "headline": "Dissolution of Czechoslovakia",
      "text": "On January 1, 1993, Czechoslovakia peacefully split into the Czech Republic and Slovakia, with Bohemia becoming part of the Czech Republic.",
