{
  "timeline": [
    {
      "headline": "Muslim Conquest of Iberia",
      "text": "In 711, the Umayyad Caliphate began the conquest of the Iberian Peninsula, marking the beginning of Muslim rule in the region known as Al-Andalus.",
      "date": "0711"
    },
    {
      "headline": "Battle of Guadalete",
      "text": "In 711, the Battle of Guadalete took place, where the Umayyad forces defeated the Visigothic King Roderic, leading to the rapid expansion of Muslim control in the Iberian Peninsula.",
      "date": "0711"
    },
    {
      "headline": "Establishment of the Emirate of Córdoba",
      "text": "In 756, Abd al-Rahman I established the Emirate of Córdoba, declaring independence from the Umayyad Caliphate in Damascus.",
      "date": "0756"
    },
    {
      "headline": "Proclamation of the Caliphate of Córdoba",
      "text": "In 929, Abd al-Rahman III proclaimed the Caliphate of Córdoba, marking a period of political and cultural flourishing in Al-Andalus.",
      "date": "0929"
    },
    {
      "headline": "Collapse of the Caliphate of Córdoba",
      "text": "In 1031, the Caliphate of Córdoba collapsed, leading to the fragmentation of Al-Andalus into smaller independent kingdoms known as Taifas.",
      "date": "1031"
    },
    {
      "headline": "Almoravid Conquest",
      "text": "In 1086, the Almoravids, a Berber Muslim dynasty, began their conquest of the Taifas, unifying much of Al-Andalus under their rule.",
      "date": "1086"
    },
    {
      "headline": "Almohad Rule",
      "text": "In 1147, the Almohads, another Berber Muslim dynasty, took control of Al-Andalus from the Almoravids, ruling until the mid-13th century.",
      "date": "1147"
    },
    {
      "headline": "Battle of Las Navas de Tolosa",
      "text": "In 1212, the Christian forces defeated the Almohads at the Battle of Las Navas de Tolosa, marking a significant turning point in the Reconquista.",
      "date": "1212"
    },
    {
      "headline": "Establishment of the Emirate of Granada",
      "text": "In 1238, the Nasrid dynasty established the Emirate of Granada, the last Muslim state in Iberia, which lasted until 1492.",
      "date": "1238"
    },
    {
      "headline": "Fall of Granada",
      "text": "On January 2, 1492, the Emirate of Granada surrendered to the Catholic Monarchs, Ferdinand II of Aragon and Isabella I of Castile, marking the end of Muslim rule in Iberia.",
      "date": "1492-01-02"
    }
  ]
}

