    {
      "headline": "Establishment of the Royal Observatory",
      "text": "The Royal Observatory in Greenwich, London, was established in 1675 by King Charles II. It was intended to improve navigation and mapmaking by providing accurate astronomical data.",
      "date": "1675"
    },
    {
      "headline": "Greenwich Mean Time Introduced",
      "text": "Greenwich Mean Time (GMT) was first established in 1675 when the Royal Observatory was founded. It was initially calculated from noon.",
      "date": "1675"
    },
    {
      "headline": "Adoption of GMT by British Railways",
      "text": "In 1847, the Railway Clearing House in Britain adopted Greenwich Mean Time for the railway timetables, leading to its widespread use across the country.",
      "date": "1847"
    },
    {
      "headline": "GMT Adopted as Legal Time in the UK",
      "text": "In 1880, Greenwich Mean Time was legally adopted as the standard time across the United Kingdom.",
      "date": "1880"
    },
    {
      "headline": "International Meridian Conference",
      "text": "In 1884, the International Meridian Conference was held in Washington, D.C., where GMT was adopted as the world's time standard, establishing the Prime Meridian at Greenwich.",
      "date": "1884"
    },
    {
      "headline": "GMT Replaced by UTC",
      "text": "In 1972, Coordinated Universal Time (UTC) replaced GMT as the basis for the world's time standard, although GMT is still used in some contexts.",
      "date": "1972"
    }
  ]
}

