{
  "timeline": [
    {
      "headline": "Birth of Jean-Jacques Rousseau",
      "text": "Jean-Jacques Rousseau was born on June 28, 1712, in Geneva, which was at the time a city-state and a Protestant associate of the Swiss Confederacy.",
      "date": "1712-06-28"
    },
    {
      "headline": "Rousseau's Mother Dies",
      "text": "Rousseau's mother, Suzanne Bernard Rousseau, died on July 7, 1712, just nine days after his birth.",
      "date": "1712-07-07"
    },
    {
      "headline": "Rousseau Leaves Geneva",
      "text": "In 1728, at the age of 16, Rousseau left Geneva and began traveling, eventually settling in Annecy, France.",
      "date": "1728"
    },
    {
      "headline": "Rousseau Moves to Paris",
      "text": "In 1742, Rousseau moved to Paris, where he became involved with the intellectual circles of the city.",
      "date": "1742"
    },
    {
      "headline": "Publication of 'Discourse on the Arts and Sciences'",
      "text": "In 1750, Rousseau published his first major philosophical work, 'Discourse on the Arts and Sciences', which argued that the arts and sciences corrupt human morality.",
      "date": "1750"
    },
    {
      "headline": "Publication of 'Discourse on the Origin and Basis of Inequality Among Men'",
      "text": "In 1755, Rousseau published 'Discourse on the Origin and Basis of Inequality Among Men', where he explored the concept of natural human equality and the social constructs that lead to inequality.",
      "date": "1755"
    },
    {
      "headline": "Publication of 'The Social Contract'",
      "text": "In 1762, Rousseau published 'The Social Contract', a seminal work in political philosophy that introduced the concept of the general will and the idea that legitimate political authority comes from a social contract agreed upon by all citizens.",
      "date": "1762"
    },
    {
      "headline": "Publication of 'Émile, or On Education'",
      "text": "Also in 1762, Rousseau published 'Émile, or On Education', which presented his philosophy of education and the idea of educating the whole person for citizenship.",
      "date": "1762"
    },
    {
      "headline": "Rousseau Flees France",
      "text": "Following the condemnation of his works by the authorities, Rousseau fled France in 1762 and sought refuge in Switzerland.",
      "date": "1762"
    },
    {
      "headline": "Rousseau's Return to France",
      "text": "In 1767, Rousseau returned to France under the protection of the Prince de Conti.",
      "date": "1767"
    },
    {
      "headline": "Rousseau's Final Years",
      "text": "Rousseau spent his final years in relative seclusion, working on his autobiographical works, including 'Confessions'.",
      "date": "1770"
    },
    {
      "headline": "Death of Jean-Jacques Rousseau",
      "text": "Jean-Jacques Rousseau died on July 2, 1778, in Ermenonville, France, at the estate of the Marquis de Girardin.",
      "date": "1778-07-02"
    }
  ]
}

