{
  "timeline": [
    {
      "headline": "Invention of Rayon",
      "text": "Rayon was first developed in the late 19th century as a substitute for silk. The first successful process for making rayon was developed by French chemist Hilaire de Chardonnet in 1884.",
      "date": "1884"
    },
    {
      "headline": "First Commercial Production",
      "text": "The first commercial production of rayon began in 1891, when Hilaire de Chardonnet opened a factory in Besançon, France.",
      "date": "1891"
    },
    {
      "headline": "Viscose Process Patented",
      "text": "The viscose process, which became the most common method for producing rayon, was patented by English chemists Charles Frederick Cross, Edward John Bevan, and Clayton Beadle in 1892.",
      "date": "1892"
    },
    {
      "headline": "Commercialization of Viscose Rayon",
      "text": "The first commercial viscose rayon was produced in 1905 by the British company Courtaulds.",
      "date": "1905"
    },
    {
      "headline": "Introduction of High-Tenacity Rayon",
      "text": "High-tenacity rayon, which is stronger and more durable, was introduced in the 1930s, expanding the applications of rayon in textiles.",
      "date": "1930"
    },
    {
      "headline": "Development of Cuprammonium Rayon",
      "text": "Cuprammonium rayon, a type of rayon made using a different process, was developed in the early 20th century and became commercially available in the 1930s.",
      "date": "1930"
    },
    {
      "headline": "Introduction of High-Wet-Modulus Rayon",
      "text": "High-wet-modulus (HWM) rayon, which has improved wet strength, was developed in the 1950s, further enhancing the versatility of rayon fabrics.",
      "date": "1950"
    }
  ]
}

