{
  "timeline": [
    {
      "headline": "Bernhard Riemann Proposes the Hypothesis",
      "text": "In 1859, Bernhard Riemann proposed the Riemann hypothesis in his paper 'On the Number of Primes Less Than a Given Magnitude'. He conjectured that all non-trivial zeros of the Riemann zeta function have a real part of 1/2.",
      "date": "1859"
    },
    {
      "headline": "David Hilbert's Recognition",
      "text": "In 1900, David Hilbert included the Riemann hypothesis as the eighth problem in his famous list of 23 unsolved problems presented at the International Congress of Mathematicians in Paris.",
      "date": "1900"
    },
    {
      "headline": "Hardy Proves Infinitely Many Zeros on the Critical Line",
      "text": "In 1914, G.H. Hardy proved that there are infinitely many zeros of the Riemann zeta function on the critical line where the real part is 1/2.",
      "date": "1914"
    },
    {
      "headline": "Turing's Contribution",
      "text": "In 1953, Alan Turing developed a method to verify the Riemann hypothesis for the first 1,104 zeros using early computers.",
      "date": "1953"
    },
    {
      "headline": "The Riemann Hypothesis as a Millennium Prize Problem",
      "text": "In 2000, the Clay Mathematics Institute included the Riemann hypothesis as one of its seven Millennium Prize Problems, offering a $1 million prize for a correct proof.",
      "date": "2000"
    }
  ]
}

