{
  "timeline": [
    {
      "headline": "Formation of Anonymous",
      "text": "Anonymous was formed in 2003 on the imageboard 4chan, representing the concept of many online and offline community users simultaneously existing as an anarchic, digitized global brain.",
      "date": "2003"
    },
    {
      "headline": "Project Chanology",
      "text": "In January 2008, Anonymous launched Project Chanology, a protest movement against the Church of Scientology, following the Church's attempts to remove a video of Tom Cruise from the internet.",
      "date": "2008-01"
    },
    {
      "headline": "Operation Payback",
      "text": "In September 2010, Anonymous initiated Operation Payback, a series of cyberattacks targeting anti-piracy organizations and law firms that supported copyright enforcement.",
      "date": "2010-09"
    },
    {
      "headline": "Operation Tunisia",
      "text": "In January 2011, Anonymous launched Operation Tunisia, supporting the Tunisian revolution by attacking government websites and aiding in the dissemination of information.",
      "date": "2011-01"
    },
    {
      "headline": "Operation Egypt",
      "text": "In January 2011, Anonymous launched Operation Egypt, supporting the Egyptian revolution by attacking government websites and providing communication tools to protesters.",
      "date": "2011-01"
    },
    {
      "headline": "Operation Sony",
      "text": "In April 2011, Anonymous targeted Sony in response to the company's legal actions against PlayStation 3 hackers, leading to a series of attacks on Sony's online services.",
      "date": "2011-04"
    },
    {
      "headline": "Operation Darknet",
      "text": "In October 2011, Anonymous launched Operation Darknet, targeting child pornography sites on the Tor network and releasing information about users of these sites.",
      "date": "2011-10"
    },
    {
      "headline": "Operation Megaupload",
      "text": "In January 2012, Anonymous launched Operation Megaupload, attacking websites of the U.S. Department of Justice and others in retaliation for the shutdown of the file-sharing site Megaupload.",
      "date": "2012-01"
    },
    {
      "headline": "Operation Russia",
      "text": "In March 2012, Anonymous launched Operation Russia, targeting Russian government websites in protest of the country's censorship and human rights violations.",
      "date": "2012-03"
    },
    {
      "headline": "Operation Israel",
      "text": "In November 2012, Anonymous launched Operation Israel, targeting Israeli websites in protest of the country's military actions in Gaza.",
      "date": "2012-11"
    },
    {
      "headline": "Operation Ferguson",
      "text": "In August 2014, Anonymous launched Operation Ferguson, targeting websites of the Ferguson, Missouri government and police department in response to the shooting of Michael Brown.",
      "date": "2014-08"
    },
    {
      "headline": "Operation Charlie Hebdo",
      "text": "In January 2015, Anonymous launched Operation Charlie Hebdo, targeting jihadist websites in response to the terrorist attack on the French satirical magazine Charlie Hebdo.",
      "date": "2015-01"
    },
    {
      "headline": "Operation KKK",
      "text": "In November 2015, Anonymous launched Operation KKK, releasing the identities of alleged members of the Ku Klux Klan.",
      "date": "2015-11"
    },
    {
      "headline": "Operation Icarus",
      "text": "In May 2016, Anonymous launched Operation Icarus, targeting global financial institutions with a series of cyberattacks.",
      "date": "2016-05"
    },
    {
      "headline": "Operation Death Eaters",
      "text": "In 2016, Anonymous launched Operation Death Eaters, aiming to expose and bring to justice those involved in international child abuse rings.",
      "date": "2016"
    },
    {
      "headline": "Operation Hong Kong",
      "text": "In August 2019, Anonymous launched Operation Hong Kong, targeting Chinese government websites in support of the Hong Kong protests.",
      "date": "2019-08"
    },
    {
      "headline": "Operation Minneapolis",
      "text": "In May 2020, Anonymous launched Operation Minneapolis, targeting the Minneapolis Police Department's website in response to the murder of George Floyd.",
      "date": "2020-05"
    }
  ]
}

