{
  "timeline": [
    {
      "headline": "Commission of the Pietà",
      "text": "In 1498, Michelangelo Buonarroti was commissioned to create the Pietà by French Cardinal Jean de Bilhères, who was a representative in Rome. The sculpture was intended for the cardinal's funeral monument.",
      "date": "1498"
    },
    {
      "headline": "Completion of the Pietà",
      "text": "Michelangelo completed the Pietà in 1499. The sculpture was carved from a single slab of Carrara marble and depicts the Virgin Mary holding the dead body of Jesus Christ after his crucifixion.",
      "date": "1499"
    },
    {
      "headline": "Installation in St. Peter's Basilica",
      "text": "The Pietà was installed in St. Peter's Basilica, Vatican City, where it remains to this day. It was placed in the Chapel of the Pietà, to the right of the entrance of the basilica.",
      "date": "1499"
    },
    {
      "headline": "Vandalism Incident",
      "text": "On May 21, 1972, the Pietà was attacked by a mentally disturbed geologist named Laszlo Toth. He damaged the sculpture with a hammer, breaking off Mary's arm at the elbow, part of her nose, and a chunk of her eyelid.",
      "date": "1972-05-21"
    },
    {
      "headline": "Restoration of the Pietà",
      "text": "Following the vandalism in 1972, the Pietà underwent a meticulous restoration process. The restoration was completed, and the sculpture was returned to public display behind bulletproof glass to prevent future attacks.",
      "date": "1972"
    }
  ]
}

