{
  "timeline": [
    {
      "headline": "Emergence of Capitalism",
      "text": "The roots of capitalism can be traced back to the late Middle Ages in Europe, around the 13th to 16th centuries, with the rise of merchant capitalism and the expansion of trade networks.",
      "date": "1300"
    },
    {
      "headline": "Development of Joint-Stock Companies",
      "text": "In the 16th and 17th centuries, joint-stock companies emerged, allowing for the pooling of capital for large-scale ventures, such as the British East India Company founded in 1600.",
      "date": "1600"
    },
    {
      "headline": "The Industrial Revolution",
      "text": "The Industrial Revolution, beginning in the late 18th century, marked a significant turning point in capitalism with the rise of industrial production and factory systems.",
      "date": "1760"
    },
    {
      "headline": "Adam Smith's 'The Wealth of Nations'",
      "text": "In 1776, Adam Smith published 'The Wealth of Nations', which laid the foundations for classical economics and articulated the principles of a free market economy.",
      "date": "1776"
    },
    {
      "headline": "Rise of Laissez-Faire Capitalism",
      "text": "During the 19th century, laissez-faire capitalism gained prominence, advocating minimal government intervention in economic affairs.",
      "date": "1800"
    },
    {
      "headline": "The Great Depression",
      "text": "The Great Depression of the 1930s challenged the principles of capitalism, leading to increased government intervention and the development of welfare states.",
      "date": "1930"
    },
    {
      "headline": "Post-World War II Economic Expansion",
      "text": "After World War II, capitalism experienced a period of significant growth and expansion, particularly in Western countries, characterized by increased consumerism and technological innovation.",
      "date": "1945"
    },
    {
      "headline": "Neoliberalism and Globalization",
      "text": "From the late 20th century onwards, neoliberal policies promoting free markets and globalization became dominant, leading to increased global trade and investment.",
      "date": "1980"
    },
    {
      "headline": "2008 Financial Crisis",
      "text": "The 2008 financial crisis exposed vulnerabilities in the global capitalist system, leading to widespread economic downturns and debates over regulation and reform.",
      "date": "2008"
    }
  ]
}

