    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Simón Bolívar",
      "text": "Simón Bolívar was born on July 24, 1783, in Caracas, which was then part of the Captaincy General of Venezuela within the Spanish Empire.",
      "date": "1783-07-24"
    },
    {
      "headline": "Bolívar's Education in Europe",
      "text": "In 1799, Bolívar traveled to Spain to continue his education. During his time in Europe, he was influenced by Enlightenment ideas and witnessed the coronation of Napoleon Bonaparte.",
      "date": "1799"
    },
    {
      "headline": "Marriage to María Teresa Rodríguez del Toro y Alaysa",
      "text": "In 1802, Bolívar married María Teresa Rodríguez del Toro y Alaysa in Madrid. Tragically, she died of yellow fever less than a year later.",
      "date": "1802"
    },
    {
      "headline": "Return to Venezuela",
      "text": "Bolívar returned to Venezuela in 1807 after his wife's death and began to engage in the independence movement.",
      "date": "1807"
    },
    {
      "headline": "The Admirable Campaign",
      "text": "In 1813, Bolívar led the Admirable Campaign, a military campaign that resulted in the liberation of western Venezuela from Spanish control.",
      "date": "1813"
    },
    {
      "headline": "Proclamation of the Second Republic of Venezuela",
      "text": "On August 6, 1813, Bolívar proclaimed the Second Republic of Venezuela in Caracas.",
      "date": "1813-08-06"
    },
    {
      "headline": "Exile in Jamaica",
      "text": "In 1815, Bolívar went into exile in Jamaica after the fall of the Second Republic. During this time, he wrote the famous 'Letter from Jamaica,' outlining his vision for Latin America.",
      "date": "1815"
    },
    {
      "headline": "Return to South America and Victory at Boyacá",
      "text": "Bolívar returned to South America and achieved a decisive victory at the Battle of Boyacá on August 7, 1819, which was crucial for the liberation of New Granada (modern-day Colombia).",
      "date": "1819-08-07"
    },
    {
      "headline": "Creation of Gran Colombia",
      "text": "In 1819, Bolívar established the Republic of Gran Colombia, which included modern-day Colombia, Venezuela, Ecuador, and Panama.",
      "date": "1819"
    },
    {
      "headline": "Liberation of Peru",
      "text": "Bolívar led the campaign to liberate Peru from Spanish rule, culminating in the victory at the Battle of Ayacucho on December 9, 1824.",
      "date": "1824-12-09"
    },
    {
      "headline": "Founding of Bolivia",
      "text": "In 1825, the Republic of Bolivia was founded and named in Bolívar's honor after he played a key role in its liberation.",
      "date": "1825"
    },
    {
      "headline": "Resignation from Presidency of Gran Colombia",
      "text": "On April 27, 1830, Bolívar resigned from the presidency of Gran Colombia due to political turmoil and declining health.",
      "date": "1830-04-27"
    },
    {
      "headline": "Death of Simón Bolívar",
      "text": "Simón Bolívar died on December 17, 1830, in Santa Marta, Colombia, after battling tuberculosis.",
      "date": "1830-12-17"
    }
  ]
}

