{
  "timeline": [
    {
      "headline": "The Exodus from Egypt",
      "text": "According to the Hebrew Bible, the Exodus from Egypt, which Passover commemorates, took place. This event marks the liberation of the Israelites from slavery under the leadership of Moses.",
      "date": "-01300"
    },
    {
      "headline": "Institution of Passover",
      "text": "The Passover festival was instituted to commemorate the Exodus. The Israelites were instructed to observe this festival annually, as described in the Book of Exodus.",
      "date": "-01300"
    },
    {
      "headline": "Passover in the Second Temple Period",
      "text": "During the Second Temple period, Passover was one of the major pilgrimage festivals, with Jews traveling to Jerusalem to offer sacrifices at the Temple.",
      "date": "-00516"
    },
    {
      "headline": "Destruction of the Second Temple",
      "text": "In 70 CE, the Second Temple was destroyed by the Romans, which significantly impacted the observance of Passover, shifting it from a Temple-centered festival to one observed in homes and synagogues.",
      "date": "0070"
    },
    {
      "headline": "Development of the Passover Haggadah",
      "text": "The Passover Haggadah, the text recited during the Passover Seder, began to take shape in the early centuries of the Common Era, incorporating biblical and rabbinic texts.",
      "date": "0300"
    },
    {
      "headline": "Codification of the Passover Seder",
      "text": "By the Middle Ages, the Passover Seder had been codified, with specific rituals and the recitation of the Haggadah becoming standardized.",
      "date": "1000"
    },
    {
      "headline": "Modern Passover Observance",
      "text": "In contemporary times, Passover is celebrated by Jewish communities worldwide, with the Seder being a central ritual, involving the retelling of the Exodus story, symbolic foods, and prayers.",
      "date": "2023"
    }
  ]
}

