{
  "timeline": [
    {
      "headline": "Founding of Tbilisi",
      "text": "Tbilisi was founded in the 5th century AD by Vakhtang I of Iberia. According to legend, King Vakhtang discovered the hot springs in the area and decided to build a city there.",
      "date": "0450"
    },
    {
      "headline": "Tbilisi Becomes Capital of Iberia",
      "text": "In the late 5th century, Tbilisi became the capital of the Kingdom of Iberia, marking its importance as a political and cultural center.",
      "date": "0490"
    },
    {
      "headline": "Arab Conquest",
      "text": "In 736, Tbilisi was captured by Arab forces and became the center of an emirate, remaining under Arab control for several centuries.",
      "date": "0736"
    },
    {
      "headline": "King David IV's Liberation",
      "text": "In 1122, King David IV of Georgia liberated Tbilisi from Arab rule and made it the capital of a unified Georgian state.",
      "date": "1122"
    },
    {
      "headline": "Mongol Invasion",
      "text": "In 1236, Tbilisi was invaded by the Mongols, leading to a period of instability and decline for the city.",
      "date": "1236"
    },
    {
      "headline": "Timur's Invasion",
      "text": "In the late 14th century, Tbilisi was sacked by the armies of Timur, causing significant destruction.",
      "date": "1386"
    },
    {
      "headline": "Persian Control",
      "text": "In 1795, Tbilisi was invaded and destroyed by the Persian ruler Agha Mohammad Khan Qajar.",
      "date": "1795"
    },
    {
      "headline": "Annexation by the Russian Empire",
      "text": "In 1801, Tbilisi became part of the Russian Empire following the annexation of the Kingdom of Kartli-Kakheti.",
      "date": "1801"
    },
    {
      "headline": "Tbilisi as the Seat of the Caucasus Viceroyalty",
      "text": "Between 1801 and 1917, Tbilisi served as the seat of the Caucasus Viceroyalty, governing both the northern and southern parts of the Caucasus.",
      "date": "1801"
    },
    {
      "headline": "Establishment of the Democratic Republic of Georgia",
      "text": "In 1918, Tbilisi became the capital of the newly established Democratic Republic of Georgia.",
      "date": "1918"
    },
    {
      "headline": "Soviet Occupation",
      "text": "In 1921, Tbilisi was occupied by the Red Army, leading to the incorporation of Georgia into the Soviet Union.",
      "date": "1921"
    },
    {
      "headline": "Tbilisi Riots",
      "text": "In 1956, Tbilisi was the site of anti-Soviet riots, which were violently suppressed by Soviet troops.",
      "date": "1956"
    },
    {
      "headline": "April 9 Tragedy",
      "text": "On April 9, 1989, a peaceful demonstration in Tbilisi was violently dispersed by Soviet troops, resulting in numerous deaths and injuries.",
      "date": "1989-04-09"
    },
    {
      "headline": "Independence of Georgia",
      "text": "In 1991, following the dissolution of the Soviet Union, Tbilisi became the capital of an independent Georgia.",
      "date": "1991"
    },
    {
      "headline": "Rose Revolution",
      "text": "In 2003, Tbilisi was the center of the Rose Revolution, which led to the resignation of President Eduard Shevardnadze and significant political changes in Georgia.",
      "date": "2003"
    }
  ]
}

