{
  "timeline": [
    {
      "headline": "Worship of Horus Begins",
      "text": "Horus was worshipped from at least the late prehistoric Egypt, which dates back to around 3100 BCE. He was one of the most significant deities in ancient Egyptian religion.",
      "date": "-3100"
    },
    {
      "headline": "Horus as the God of Kingship",
      "text": "Horus was associated with the living pharaoh, who was considered the earthly embodiment of Horus. This association was particularly emphasized during the Early Dynastic Period of Egypt, starting around 3100 BCE.",
      "date": "-3100"
    },
    {
      "headline": "Horus and the Osiris Myth",
      "text": "Horus is a central figure in the Osiris myth, where he is the son of Osiris and Isis. He avenges his father's death by defeating his uncle Set, who had murdered Osiris. This myth became prominent during the Old Kingdom period, around 2686-2181 BCE.",
      "date": "-2686"
    },
    {
      "headline": "Horus as a Sky God",
      "text": "Horus was also associated with the sky and was often depicted as a falcon. His right eye represented the sun and his left eye the moon. This aspect of Horus was emphasized throughout ancient Egyptian history.",
      "date": "-2686"
    },
    {
      "headline": "Horus in the Ptolemaic Kingdom",
      "text": "During the Ptolemaic Kingdom (305-30 BCE), Horus continued to be worshipped, and his cult was integrated with that of other deities, such as Ra and Amun, reflecting the syncretic nature of Egyptian religion.",
      "date": "-0305"
    },
    {
      "headline": "Horus in Roman Egypt",
      "text": "Horus remained an important deity during Roman Egypt (30 BCE - 641 CE), where he was often depicted in Roman-style art and continued to be worshipped alongside other Egyptian gods.",
      "date": "-0030"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Rise to Prominence",
      "text": "By the Fifth Dynasty, in the 25th and 24th centuries BC, Ra had become one of the most important gods in ancient Egyptian religion, identified primarily with the noon-day sun.",
      "date": "-2400"
    },
    {
      "headline": "Role as a Creator God",
      "text": "Ra was believed to have created all forms of life by calling them into existence by speaking their secret names.",
      "date": "-2400"
    },
    {
      "headline": "Association with the Pharaoh",
      "text": "Ra was believed to have ruled as the first pharaoh of Ancient Egypt, establishing the divine right of kings.",
      "date": "-2400"
    },
    {
      "headline": "Integration with Other Deities",
      "text": "Ra was often merged with other deities, such as Amun, to form Amun-Ra, reflecting his supreme status in the Egyptian pantheon.",
      "date": "-2400"
    },
    {
      "headline": "Cultural Impact",
      "text": "Ra's influence extended beyond religion into Egyptian culture, art, and architecture, with many temples and monuments dedicated to him.",
      "date": "-2400"
    }
  ]
}

