{
  "timeline": [
    {
      "headline": "First Use of the Term 'Pogrom'",
      "text": "The term 'pogrom' entered the English language from Russian to describe 19th and 20th-century attacks on Jews in the Russian Empire.",
      "date": "1800"
    },
    {
      "headline": "Odessa Pogrom",
      "text": "The Odessa pogroms were a series of anti-Jewish riots in Odessa, a city in the Russian Empire, occurring in 1821, 1859, 1871, 1881, and 1905. These pogroms resulted in numerous deaths and injuries among the Jewish population.",
      "date": "1821"
    },
    {
      "headline": "Kishinev Pogrom",
      "text": "The Kishinev pogrom was an anti-Jewish riot that took place in Kishinev, the capital of the Bessarabia Governorate of the Russian Empire, on April 6–7, 1903. It resulted in the deaths of 49 Jews, the injury of hundreds, and the destruction of over 1,500 homes.",
      "date": "1903-04-06"
    },
    {
      "headline": "Lviv Pogroms",
      "text": "The Lviv pogroms were two separate massacres of Jews in Lviv, at the time part of Poland, in 1941. The first pogrom took place from June 30 to July 2, and the second from July 25 to 29, resulting in thousands of Jewish deaths.",
      "date": "1941-06-30"
    },
    {
      "headline": "Jedwabne Pogrom",
      "text": "The Jedwabne pogrom was a massacre of at least 340 Polish Jews, including women and children, by their non-Jewish neighbors in the town of Jedwabne, Poland, on July 10, 1941.",
      "date": "1941-07-10"
    },
    {
      "headline": "Kielce Pogrom",
      "text": "The Kielce pogrom was an outbreak of violence against the Jewish community in the city of Kielce, Poland, on July 4, 1946, resulting in the deaths of 42 Jews and the injury of over 40 others.",
      "date": "1946-07-04"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Apparition",
      "text": "On December 9, 1531, the Virgin Mary is believed to have appeared to Juan Diego, a Mexican peasant, on the hill of Tepeyac near Mexico City.",
      "date": "1531-12-09"
    },
    {
      "headline": "Second Apparition",
      "text": "On December 10, 1531, the Virgin Mary appeared again to Juan Diego, instructing him to build a shrine in her honor at the site of the apparition.",
      "date": "1531-12-10"
    },
    {
      "headline": "Third Apparition",
      "text": "On December 11, 1531, the Virgin Mary appeared to Juan Diego for the third time, urging him to persist in his request to the bishop for a shrine.",
      "date": "1531-12-11"
    },
    {
      "headline": "Fourth Apparition",
      "text": "On December 12, 1531, the Virgin Mary appeared to Juan Diego for the fourth time, providing him with roses as a sign for the bishop. When Juan Diego presented the roses to the bishop, an image of the Virgin was miraculously imprinted on his tilma (cloak).",
      "date": "1531-12-12"
    },
    {
      "headline": "Apparition to Juan Bernardino",
      "text": "On December 12, 1531, the Virgin Mary is also believed to have appeared to Juan Diego's uncle, Juan Bernardino, curing him of a serious illness and revealing her name as 'the ever-virgin Holy Mary of Guadalupe.'",
      "date": "1531-12-12"
    },
    {
      "headline": "Construction of the Shrine",
      "text": "Following the apparitions, a shrine was constructed on the hill of Tepeyac, becoming a major pilgrimage site.",
      "date": "1531"
    },
    {
      "headline": "Papal Recognition",
      "text": "In 1754, Pope Benedict XIV granted a canonical coronation to the image of Our Lady of Guadalupe.",
      "date": "1754"
    },
    {
      "headline": "Basilica of Our Lady of Guadalupe",
      "text": "In 1976, the new Basilica of Our Lady of Guadalupe was completed in Mexico City, becoming one of the most visited Catholic pilgrimage sites in the world.",
      "date": "1976"
