      "headline": "Birth of Frederick the Great",
      "text": "Frederick II, later known as Frederick the Great, was born on January 24, 1712, in Berlin, Kingdom of Prussia.",
      "date": "1712-01-24"
    },
    {
      "headline": "Accession to the Throne",
      "text": "Frederick II became King in Prussia on May 31, 1740, following the death of his father, Frederick William I.",
      "date": "1740-05-31"
    },
    {
      "headline": "First Silesian War",
      "text": "Frederick the Great initiated the First Silesian War in 1740, which was part of the larger War of the Austrian Succession. The war ended in 1742 with the Treaty of Breslau, granting Silesia to Prussia.",
      "date": "1740"
    },
    {
      "headline": "Second Silesian War",
      "text": "The Second Silesian War began in 1744 and ended in 1745 with the Treaty of Dresden, reaffirming Prussian control over Silesia.",
      "date": "1744"
    },
    {
      "headline": "Seven Years' War",
      "text": "Frederick the Great led Prussia during the Seven Years' War from 1756 to 1763, a major conflict involving most of the great powers of the time. The war ended with the Treaty of Hubertusburg, which confirmed Prussia's status as a major European power.",
      "date": "1756"
    },
    {
      "headline": "First Partition of Poland",
      "text": "In 1772, Frederick the Great participated in the First Partition of Poland, annexing Royal Prussia and other territories, which significantly expanded Prussian territory.",
      "date": "1772"
    },
    {
      "headline": "Declaration as King of Prussia",
      "text": "After the annexation of Royal Prussia in 1772, Frederick declared himself King of Prussia, changing the title from King in Prussia.",
      "date": "1772"
    },
    {
      "headline": "Death of Frederick the Great",
      "text": "Frederick the Great died on August 17, 1786, at Sanssouci Palace in Potsdam, Kingdom of Prussia.",
      "date": "1786-08-17"
    }
  ]
}

