{
  "timeline": [
    {
      "headline": "Construction of the Sistine Chapel",
      "text": "The construction of the Sistine Chapel was commissioned by Pope Sixtus IV and took place between 1473 and 1481. It was originally known as the Cappella Magna.",
      "date": "1473"
    },
    {
      "headline": "Completion of the Sistine Chapel",
      "text": "The construction of the Sistine Chapel was completed in 1481. It was built as a place for both religious and functionary papal activities.",
      "date": "1481"
    },
    {
      "headline": "Decoration of the Sistine Chapel Walls",
      "text": "Between 1481 and 1482, a team of Renaissance painters including Botticelli, Ghirlandaio, and Perugino decorated the walls of the Sistine Chapel with frescoes.",
      "date": "1481"
    },
    {
      "headline": "Commissioning of the Sistine Chapel Ceiling",
      "text": "In 1508, Pope Julius II commissioned Michelangelo to paint the ceiling of the Sistine Chapel.",
      "date": "1508"
    },
    {
      "headline": "Completion of the Sistine Chapel Ceiling",
      "text": "Michelangelo completed the painting of the Sistine Chapel ceiling in 1512. The ceiling includes the iconic 'Creation of Adam'.",
      "date": "1512"
    },
    {
      "headline": "Commissioning of The Last Judgment",
      "text": "In 1535, Pope Clement VII commissioned Michelangelo to paint The Last Judgment on the altar wall of the Sistine Chapel.",
      "date": "1535"
    },
    {
      "headline": "Completion of The Last Judgment",
      "text": "Michelangelo completed The Last Judgment in 1541. It is a large fresco covering the whole altar wall of the Sistine Chapel.",
      "date": "1541"
    },
    {
      "headline": "Restoration of the Sistine Chapel Ceiling",
      "text": "A major restoration of the Sistine Chapel ceiling took place from 1980 to 1994, revealing the original vibrant colors used by Michelangelo.",
      "date": "1980"
    },
    {
      "headline": "Completion of the Sistine Chapel Ceiling Restoration",
      "text": "The restoration of the Sistine Chapel ceiling was completed in 1994, allowing the public to view Michelangelo's work in its restored state.",
      "date": "1994"
    }
  ]
}

