{
  "timeline": [
    {
      "headline": "Formation of the County of Holland",
      "text": "The County of Holland was established as a political region within the Holy Roman Empire. It emerged from the Frisian lands in the 10th century.",
      "date": "0900"
    },
    {
      "headline": "Rule of Dirk I",
      "text": "Dirk I became the first count of Holland, ruling from around 896 to 931. He is considered the founder of the county.",
      "date": "0896"
    },
    {
      "headline": "Expansion under Dirk III",
      "text": "Dirk III expanded the territory of Holland by defeating the Bishop of Utrecht in the Battle of Vlaardingen in 1018.",
      "date": "1018"
    },
    {
      "headline": "Holland becomes a significant power",
      "text": "Under the rule of Floris V, who reigned from 1256 to 1296, Holland became a significant power in the region, expanding its influence and territory.",
      "date": "1256"
    },
    {
      "headline": "The Hook and Cod Wars",
      "text": "A series of civil wars known as the Hook and Cod Wars took place in Holland from 1350 to 1490, involving rival factions vying for control of the county.",
      "date": "1350"
    },
    {
      "headline": "Holland joins the Burgundian Netherlands",
      "text": "In 1432, Holland became part of the Burgundian Netherlands under Philip the Good, Duke of Burgundy.",
      "date": "1432"
    },
    {
      "headline": "Holland under Habsburg rule",
      "text": "After the death of Mary of Burgundy in 1482, Holland came under the control of the Habsburgs, marking the beginning of Habsburg rule.",
      "date": "1482"
    },
    {
      "headline": "Dutch Revolt begins",
      "text": "The Dutch Revolt against Spanish Habsburg rule began in 1568, leading to the Eighty Years' War and the eventual independence of the Dutch Republic.",
      "date": "1568"
    },
    {
      "headline": "Formation of the Dutch Republic",
      "text": "In 1581, the northern provinces, including Holland, declared independence from Spain, forming the Dutch Republic.",
      "date": "1581"
    },
    {
      "headline": "The Golden Age of Holland",
      "text": "During the 17th century, Holland became a leading maritime and economic power, dominating trade and culture in the Dutch Republic.",
      "date": "1600"
    },
    {
      "headline": "End of the Dutch Republic",
      "text": "The Batavian Revolution in 1795 led to the end of the Dutch Republic, and Holland became part of the Batavian Republic.",
      "date": "1795"
    }
  ]
}

