{
  "timeline": [
    {
      "headline": "Invention of the Enigma Machine",
      "text": "The Enigma machine was invented by German engineer Arthur Scherbius at the end of World War I. The first patent for the machine was filed in 1918.",
      "date": "1918"
    },
    {
      "headline": "Commercial Production Begins",
      "text": "The Enigma machine was first produced commercially in the early 1920s. It was initially marketed to businesses for secure communications.",
      "date": "1923"
    },
    {
      "headline": "Adoption by the German Military",
      "text": "The German military began using the Enigma machine in the late 1920s, recognizing its potential for secure military communications.",
      "date": "1926"
    },
    {
      "headline": "Polish Cipher Bureau Breakthrough",
      "text": "In December 1932, Polish mathematician Marian Rejewski, working for the Polish Cipher Bureau, succeeded in reconstructing the German military Enigma machine, marking the first successful decryption of Enigma-encrypted messages.",
      "date": "1932-12"
    },
    {
      "headline": "Transfer of Knowledge to Allies",
      "text": "In July 1939, just before the outbreak of World War II, Polish cryptanalysts shared their knowledge of the Enigma machine with French and British intelligence, significantly aiding Allied efforts to break Enigma codes during the war.",
      "date": "1939-07"
    },
    {
      "headline": "Bletchley Park Codebreaking Efforts",
      "text": "During World War II, British cryptanalysts at Bletchley Park, including Alan Turing, developed techniques and machines such as the Bombe to break Enigma-encrypted messages, greatly contributing to the Allied war effort.",
      "date": "1939"
    },
    {
      "headline": "End of World War II",
      "text": "The Enigma machine continued to be used by Nazi Germany until the end of World War II in 1945. The successful decryption of Enigma messages by the Allies is credited with shortening the war.",
      "date": "1945"
    }
  ]
}

