{
  "timeline": [
    {
      "headline": "Formation of the Gestapo",
      "text": "The Gestapo was formed on April 26, 1933, by Hermann Göring, who was then the Minister President of Prussia. It was established as a secret police force to serve the Nazi regime.",
      "date": "1933-04-26"
    },
    {
      "headline": "Heinrich Himmler Takes Control",
      "text": "On April 20, 1934, Heinrich Himmler was appointed as the head of the Gestapo. This marked the beginning of the Gestapo's integration into the SS and its expansion throughout Nazi Germany.",
      "date": "1934-04-20"
    },
    {
      "headline": "Gestapo Becomes Part of the Reich Main Security Office",
      "text": "In September 1939, the Gestapo was incorporated into the Reich Main Security Office (RSHA), which was headed by Reinhard Heydrich. This integration further centralized the Nazi security apparatus.",
      "date": "1939-09"
    },
    {
      "headline": "Role in the Holocaust",
      "text": "Throughout World War II, the Gestapo played a crucial role in the Holocaust, participating in the deportation of Jews and other groups to concentration camps. They were instrumental in enforcing Nazi racial policies.",
      "date": "1939"
    },
    {
      "headline": "End of the Gestapo",
      "text": "The Gestapo was officially dissolved in May 1945, following the defeat of Nazi Germany in World War II. Its leaders were tried for war crimes during the Nuremberg Trials.",
      "date": "1945-05"
    }
  ]
}

