{
  "timeline": [
    {
      "headline": "Establishment of Pinkerton Detective Agency",
      "text": "The Pinkerton National Detective Agency was established in 1850 by Allan Pinkerton and Edward Rucker in the United States. Originally named the North-Western Police Agency, it later became Pinkerton & Co.",
      "date": "1850"
    },
    {
      "headline": "Foiling of Baltimore Plot",
      "text": "In February 1861, Pinkerton agents uncovered and foiled a plot to assassinate President-elect Abraham Lincoln in Baltimore, Maryland, while he was on his way to his inauguration.",
      "date": "1861-02"
    },
    {
      "headline": "Pinkerton's Role in the American Civil War",
      "text": "During the American Civil War (1861-1865), the Pinkerton Agency provided intelligence services to the Union Army, including espionage and counter-espionage operations.",
      "date": "1861"
    },
    {
      "headline": "Largest Private Law Enforcement Organization",
      "text": "From the 1870s to the 1890s, the Pinkerton National Detective Agency became the largest private law enforcement organization in the world, known for its involvement in labor disputes and strikebreaking.",
      "date": "1870"
    },
    {
      "headline": "Homestead Strike Involvement",
      "text": "In July 1892, Pinkerton agents were involved in the Homestead Strike, a major labor dispute at the Carnegie Steel Company in Homestead, Pennsylvania, which resulted in a violent confrontation.",
      "date": "1892-07"
    },
    {
      "headline": "Subsidiary of Securitas AB",
      "text": "In the 20th century, the Pinkerton National Detective Agency became a subsidiary of the Swedish-based security company Securitas AB, continuing its operations in private security and investigations.",
      "date": "2000"
    }
  ]
}

