      "headline": "Establishment of the Delhi Sultanate",
      "text": "The Delhi Sultanate was established around 1206–1211 in the former Ghurid territories in India.",
      "date": "1206"
    },
    {
      "headline": "Mamluk Dynasty Begins",
      "text": "The Mamluk dynasty, also known as the Slave dynasty, was the first of the five dynasties of the Delhi Sultanate, ruling from 1206 to 1290.",
      "date": "1206"
    },
    {
      "headline": "Reign of Iltutmish",
      "text": "Iltutmish, one of the most prominent rulers of the Mamluk dynasty, reigned from 1211 to 1236 and consolidated the Sultanate's power.",
      "date": "1211"
    },
    {
      "headline": "Khalji Dynasty Begins",
      "text": "The Khalji dynasty, the second dynasty of the Delhi Sultanate, began its rule in 1290 and lasted until 1320.",
      "date": "1290"
    },
    {
      "headline": "Reign of Alauddin Khalji",
      "text": "Alauddin Khalji, one of the most powerful rulers of the Khalji dynasty, reigned from 1296 to 1316 and expanded the Sultanate's territory significantly.",
      "date": "1296"
    },
    {
      "headline": "Tughlaq Dynasty Begins",
      "text": "The Tughlaq dynasty, the third dynasty of the Delhi Sultanate, began its rule in 1320 and lasted until 1414.",
      "date": "1320"
    },
    {
      "headline": "Reign of Muhammad bin Tughlaq",
      "text": "Muhammad bin Tughlaq, known for his ambitious projects and administrative reforms, reigned from 1325 to 1351.",
      "date": "1325"
    },
    {
      "headline": "Sayyid Dynasty Begins",
      "text": "The Sayyid dynasty, the fourth dynasty of the Delhi Sultanate, began its rule in 1414 and lasted until 1451.",
      "date": "1414"
    },
    {
      "headline": "Lodi Dynasty Begins",
      "text": "The Lodi dynasty, the fifth and final dynasty of the Delhi Sultanate, began its rule in 1451 and lasted until 1526.",
      "date": "1451"
    },
    {
      "headline": "End of the Delhi Sultanate",
      "text": "The Delhi Sultanate came to an end in 1526 when the last Lodi ruler, Ibrahim Lodi, was defeated by Babur at the First Battle of Panipat, leading to the establishment of the Mughal Empire.",
      "date": "1526"
    }
  ]
}

