    {
      "headline": "RICO Act Enacted",
      "text": "The Racketeer Influenced and Corrupt Organizations (RICO) Act was enacted on October 15, 1970, as part of the Organized Crime Control Act of 1970. It was designed to combat organized crime in the United States by allowing prosecution and civil penalties for racketeering activity performed as part of an ongoing criminal enterprise.",
      "date": "1970-10-15"
    },
    {
      "headline": "First Major RICO Case",
      "text": "The first major RICO case was against the Hells Angels Motorcycle Club in 1979. Although the case did not result in a conviction, it set a precedent for the use of the RICO Act against organized crime groups.",
      "date": "1979"
    },
    {
      "headline": "RICO Act Used Against Mafia",
      "text": "In the 1980s, the RICO Act was successfully used to prosecute members of the Mafia, significantly impacting organized crime in the United States. Notable cases include the Mafia Commission Trial of 1985-1986, which resulted in the conviction of several top Mafia leaders.",
      "date": "1985"
    },
    {
      "headline": "RICO Act Applied to White Collar Crime",
      "text": "The RICO Act began to be applied to white-collar crime in the 1980s and 1990s, expanding its use beyond traditional organized crime. This included cases involving securities fraud, insider trading, and other forms of corporate misconduct.",
      "date": "1980"
    },
    {
      "headline": "RICO Act in Civil Litigation",
      "text": "The RICO Act has been used in civil litigation to allow private individuals and organizations to sue for damages caused by racketeering activities. This has led to numerous high-profile civil cases, including those against major corporations.",
      "date": "1990"
    }
  ]
}

