      "headline": "Establishment of the Yuan Dynasty",
      "text": "In 1271, Kublai Khan officially proclaimed the establishment of the Yuan dynasty, marking the beginning of Mongol rule over China.",
      "date": "1271"
    },
    {
      "headline": "Conquest of the Southern Song Dynasty",
      "text": "In 1279, the Yuan dynasty completed its conquest of the Southern Song dynasty, unifying China under Mongol rule.",
      "date": "1279"
    },
    {
      "headline": "Kublai Khan's Death",
      "text": "Kublai Khan, the founder of the Yuan dynasty, died in 1294, leading to a succession of less effective rulers.",
      "date": "1294"
    },
    {
      "headline": "Reign of Temür Khan",
      "text": "Temür Khan, Kublai Khan's grandson, ruled from 1294 to 1307, maintaining the stability of the Yuan dynasty.",
      "date": "1294"
    },
    {
      "headline": "Reign of Ayurbarwada Buyantu Khan",
      "text": "Ayurbarwada Buyantu Khan ruled from 1311 to 1320 and is known for his efforts to sinicize the Yuan administration.",
      "date": "1311"
    },
    {
      "headline": "Reign of Gegeen Khan",
      "text": "Gegeen Khan ruled from 1321 to 1323, continuing the policies of his predecessor.",
      "date": "1321"
    },
    {
      "headline": "Reign of Yesün Temür",
      "text": "Yesün Temür ruled from 1323 to 1328, during which internal strife and corruption began to weaken the dynasty.",
      "date": "1323"
    },
    {
      "headline": "Reign of Jayaatu Khan Tugh Temür",
      "text": "Jayaatu Khan Tugh Temür ruled from 1328 to 1329 and again from 1329 to 1332, known for his cultural patronage.",
      "date": "1328"
    },
    {
      "headline": "Reign of Toghon Temür",
      "text": "Toghon Temür, the last Yuan emperor, ruled from 1333 to 1368, during which the dynasty faced significant internal and external challenges.",
      "date": "1333"
    },
    {
      "headline": "Red Turban Rebellion",
      "text": "The Red Turban Rebellion began in 1351, severely weakening the Yuan dynasty and leading to its eventual downfall.",
      "date": "1351"
    },
    {
      "headline": "Fall of the Yuan Dynasty",
      "text": "In 1368, the Yuan dynasty fell to the Ming dynasty, marking the end of Mongol rule in China.",
      "date": "1368"
    }
  ]
}

