{
  "timeline": [
    {
      "headline": "Foundation of the Parthian Empire",
      "text": "In 247 BC, Arsaces I, leader of the Parni tribe, conquered the region of Parthia, establishing the Parthian Empire. This region was previously a satrapy under the control of Andragoras, who was rebelling against the Seleucid Empire.",
      "date": "-0247"
    },
    {
      "headline": "Reign of Arsaces I",
      "text": "Arsaces I ruled from 247 BC until his death in 217 BC, establishing the Arsacid dynasty and laying the foundations for the Parthian Empire.",
      "date": "-0247"
    },
    {
      "headline": "Reign of Mithridates I",
      "text": "Mithridates I expanded the Parthian Empire significantly during his reign from 171 BC to 132 BC, capturing Media and Babylonia from the Seleucids.",
      "date": "-0171"
    },
    {
      "headline": "Parthian Conquest of Seleucia",
      "text": "In 141 BC, Mithridates I captured the city of Seleucia on the Tigris, a major city of the Seleucid Empire, marking a significant expansion of Parthian control.",
      "date": "-0141"
    },
    {
      "headline": "Reign of Mithridates II",
      "text": "Mithridates II, known as 'the Great', ruled from 124 BC to 91 BC, and is credited with establishing diplomatic relations with Rome and China.",
      "date": "-0124"
    },
    {
      "headline": "Battle of Carrhae",
      "text": "In 53 BC, the Parthians, under General Surena, defeated the Roman forces led by Crassus at the Battle of Carrhae, one of the most significant defeats of Rome by the Parthian Empire.",
      "date": "-0053"
    },
    {
      "headline": "Reign of Orodes II",
      "text": "Orodes II ruled from 57 BC to 37 BC and was the Parthian king during the Battle of Carrhae.",
      "date": "-0057"
    },
    {
      "headline": "Reign of Phraates IV",
      "text": "Phraates IV ruled from 37 BC to 2 BC, and during his reign, he faced multiple Roman invasions but managed to maintain Parthian independence.",
      "date": "-0037"
    },
    {
      "headline": "Reign of Artabanus II",
      "text": "Artabanus II ruled from 10 AD to 38 AD, and his reign was marked by internal strife and conflict with Rome.",
      "date": "0010"
    },
    {
      "headline": "Reign of Vologases I",
      "text": "Vologases I ruled from 51 AD to 78 AD, known for his efforts to restore Zoroastrianism and for founding the city of Vologasia.",
      "date": "0051"
    },
    {
      "headline": "End of the Parthian Empire",
      "text": "In 224 AD, the Parthian Empire came to an end when Ardashir I, the founder of the Sassanian Empire, defeated the last Parthian king, Artabanus IV, at the Battle of Hormozdgan.",
      "date": "0224"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Srebrenica Declared a Safe Area",
      "text": "In April 1993, the United Nations declared Srebrenica a 'safe area' under UN protection, intended to be free from any armed attack or any other hostile act.",
      "date": "1993-04"
    },
    {
      "headline": "Bosnian Serb Forces Begin Siege",
      "text": "In early July 1995, Bosnian Serb forces, led by General Ratko Mladić, began an offensive to capture the town of Srebrenica, which was under the protection of a small contingent of Dutch UN peacekeepers.",
      "date": "1995-07"
    },
    {
      "headline": "Srebrenica Falls to Bosnian Serb Forces",
      "text": "On July 11, 1995, the town of Srebrenica fell to Bosnian Serb forces. Thousands of Bosniak refugees fled to the UN base at Potočari seeking protection.",
      "date": "1995-07-11"
    },
    {
      "headline": "Mass Killings Begin",
      "text": "From July 12 to July 22, 1995, more than 8,000 Bosniak Muslim men and boys were systematically executed by Bosnian Serb forces in and around Srebrenica.",
      "date": "1995-07-12"
    },
    {
      "headline": "Discovery of Mass Graves",
      "text": "In the months following the massacre, mass graves were discovered in the Srebrenica area, confirming the scale of the genocide.",
      "date": "1995-08"
    },
    {
      "headline": "International Criminal Tribunal for the Former Yugoslavia (ICTY) Established",
      "text": "The ICTY was established to prosecute serious crimes committed during the Yugoslav Wars, including the Srebrenica massacre.",
      "date": "1993"
    },
    {
      "headline": "Ratko Mladić Indicted",
      "text": "In November 1995, Ratko Mladić was indicted by the ICTY for genocide and other crimes related to the Srebrenica massacre.",
      "date": "1995-11"
    },
    {
      "headline": "Srebrenica Genocide Recognized",
      "text": "In 2004, the ICTY ruled that the massacre of Srebrenica constituted genocide, marking it as the first legally recognized genocide in Europe since World War II.",
      "date": "2004"
    },
    {
      "headline": "Ratko Mladić Arrested",
      "text": "On May 26, 2011, Ratko Mladić was arrested in Serbia after years of evading capture. He was extradited to The Hague to stand trial at the ICTY.",
      "date": "2011-05-26"
    },
    {
      "headline": "Ratko Mladić Convicted",
      "text": "On November 22, 2017, Ratko Mladić was convicted by the ICTY of genocide, war crimes, and crimes against humanity, and was sentenced to life imprisonment.",
      "date": "2017-11-22"
    }
  ]
}

