{
  "timeline": [
    {
      "headline": "Henry VIII Breaks from the Catholic Church",
      "text": "In 1534, King Henry VIII broke away from the Roman Catholic Church and established the Church of England, appointing himself as its Supreme Head. This was primarily due to the Pope's refusal to annul his marriage to Catherine of Aragon.",
      "date": "1534"
    },
    {
      "headline": "Act of Supremacy",
      "text": "The Act of Supremacy was passed in 1534, declaring Henry VIII as the Supreme Head of the Church of England, marking the official start of the English Reformation.",
      "date": "1534"
    },
    {
      "headline": "Publication of the Book of Common Prayer",
      "text": "In 1549, the first Book of Common Prayer was published, standardizing the liturgy of the Church of England and marking a significant step in the English Reformation.",
      "date": "1549"
    },
    {
      "headline": "Elizabethan Religious Settlement",
      "text": "In 1559, the Elizabethan Religious Settlement was established, which sought to unite the country under a moderate form of Protestantism and established the Church of England's doctrines and practices.",
      "date": "1559"
    },
    {
      "headline": "Thirty-Nine Articles",
      "text": "In 1571, the Thirty-Nine Articles were established as the defining statements of doctrines and practices of the Church of England, forming a foundation for Anglican theology.",
      "date": "1571"
    },
    {
      "headline": "English Civil War and the Church",
      "text": "During the English Civil War (1642-1651), the Church of England faced significant challenges, including the abolition of the episcopacy and the rise of Puritan influence.",
      "date": "1642"
    },
    {
      "headline": "Restoration of the Monarchy and the Church",
      "text": "In 1660, the monarchy was restored in England, and with it, the Church of England was re-established as the state church, reaffirming its structure and practices.",
      "date": "1660"
    },
    {
      "headline": "Act of Uniformity",
      "text": "The Act of Uniformity was passed in 1662, requiring the use of the Book of Common Prayer in all church services and reinforcing the Church of England's liturgical practices.",
      "date": "1662"
    },
    {
      "headline": "Oxford Movement",
      "text": "In the 1830s, the Oxford Movement began, aiming to revive the Catholic heritage and practices within the Church of England, leading to significant theological and liturgical changes.",
      "date": "1830"
    },
    {
      "headline": "Ordination of Women",
      "text": "In 1994, the Church of England ordained its first female priests, marking a significant milestone in its history and opening the way for greater gender equality within the church.",
      "date": "1994"
    },
    {
      "headline": "Consecration of First Female Bishop",
      "text": "In 2015, the Church of England consecrated its first female bishop, Libby Lane, further advancing the role of women in church leadership.",
      "date": "2015"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of the Kingdom of Macedon",
      "text": "The Kingdom of Macedon was founded in the mid-7th century BCE by Caranus, according to ancient sources.",
      "date": "-0650"
    },
    {
      "headline": "Reign of King Philip II",
      "text": "Philip II became king of Macedon in 359 BCE and transformed it into a powerful military state.",
      "date": "-0359"
    },
    {
      "headline": "Battle of Chaeronea",
      "text": "In 338 BCE, Philip II of Macedon defeated the Greek city-states at the Battle of Chaeronea, establishing Macedonian hegemony over Greece.",
      "date": "-0338"
    },
    {
      "headline": "Assassination of Philip II",
      "text": "Philip II was assassinated in 336 BCE, leading to the ascension of his son, Alexander the Great.",
      "date": "-0336"
    },
    {
      "headline": "Reign of Alexander the Great",
      "text": "Alexander the Great ruled from 336 BCE until his death in 323 BCE, creating one of the largest empires in history.",
      "date": "-0336"
    },
    {
      "headline": "Battle of Gaugamela",
      "text": "In 331 BCE, Alexander the Great defeated Darius III of Persia at the Battle of Gaugamela, leading to the fall of the Persian Empire.",
      "date": "-0331"
    },
    {
      "headline": "Death of Alexander the Great",
      "text": "Alexander the Great died in 323 BCE in Babylon, leading to the division of his empire among his generals.",
      "date": "-0323"
    },
    {
      "headline": "Division of the Macedonian Empire",
      "text": "Following Alexander's death, his empire was divided among his generals, known as the Diadochi, in 321 BCE.",
      "date": "-0321"
    },
    {
      "headline": "Roman Conquest of Macedon",
      "text": "In 168 BCE, the Romans defeated the Macedonian king Perseus at the Battle of Pydna, leading to the annexation of Macedon as a Roman province.",
      "date": "-0168"
    },
    {
      "headline": "Establishment of the Republic of Macedonia",
      "text": "The Republic of Macedonia declared independence from Yugoslavia on September 8, 1991.",
      "date": "1991-09-08"
    },
    {
      "headline": "Name Change to North Macedonia",
      "text": "On February 12, 2019, the country officially changed its name to North Macedonia following the Prespa Agreement with Greece.",
      "date": "2019-02-12"
    }
  ]
}

