    {
      "headline": "RMS Titanic Sinks",
      "text": "On April 15, 1912, the British ocean liner RMS Titanic sank in the North Atlantic Ocean after hitting an iceberg during her maiden voyage from Southampton to New York City.",
      "date": "1912-04-15"
    },
    {
      "headline": "Discovery of the Wreck",
      "text": "The wreck of the RMS Titanic was discovered on September 1, 1985, by a Franco-American expedition led by oceanographer Robert Ballard.",
      "date": "1985-09-01"
    },
    {
      "headline": "First Manned Dive to the Wreck",
      "text": "In July 1986, the first manned dive to the wreck of the Titanic was conducted by Robert Ballard and his team, using the submersible Alvin.",
      "date": "1986-07"
    },
    {
      "headline": "Titanic Artifacts Recovered",
      "text": "Since the discovery of the wreck, numerous expeditions have been conducted to recover artifacts from the Titanic, with the first major recovery operation taking place in 1987.",
      "date": "1987"
    },
    {
      "headline": "Titanic Wreck Deterioration",
      "text": "Over the years, the wreck of the Titanic has been deteriorating due to metal-eating bacteria and deep-sea currents, with significant deterioration observed in the 1990s and 2000s.",
      "date": "1990"
    },
    {
      "headline": "Titanic Wreck Protection Efforts",
      "text": "In 2001, UNESCO adopted a convention to protect underwater cultural heritage, including the wreck of the Titanic, to prevent further deterioration and unauthorized salvage operations.",
      "date": "2001"
    }
  ]
}

