{
  "timeline": [
    {
      "headline": "Formation of ISRO",
      "text": "The Indian Space Research Organisation (ISRO) was founded on August 15, 1969, to harness space technology for national development.",
      "date": "1969-08-15"
    },
    {
      "headline": "First Satellite Launch",
      "text": "ISRO launched its first satellite, Aryabhata, on April 19, 1975, using a Soviet launch vehicle.",
      "date": "1975-04-19"
    },
    {
      "headline": "First Indigenous Satellite Launch Vehicle",
      "text": "On July 18, 1980, ISRO successfully launched Rohini-1 using its own Satellite Launch Vehicle (SLV-3), marking India's entry into the exclusive club of countries with indigenous satellite launch capability.",
      "date": "1980-07-18"
    },
    {
      "headline": "Establishment of Antrix Corporation",
      "text": "In 1992, ISRO established Antrix Corporation, its commercial arm, to promote products, services, and technologies developed by ISRO.",
      "date": "1992"
    },
    {
      "headline": "Launch of Chandrayaan-1",
      "text": "ISRO launched its first lunar probe, Chandrayaan-1, on October 22, 2008, which discovered water molecules on the Moon.",
      "date": "2008-10-22"
    },
    {
      "headline": "Mars Orbiter Mission (Mangalyaan)",
      "text": "On November 5, 2013, ISRO launched the Mars Orbiter Mission, also known as Mangalyaan, which successfully entered Mars' orbit on September 24, 2014, making India the first Asian nation to reach Mars orbit and the first nation in the world to do so on its first attempt.",
      "date": "2013-11-05"
    },
    {
      "headline": "Launch of Chandrayaan-2",
      "text": "ISRO launched Chandrayaan-2 on July 22, 2019, aiming to explore the south pole of the Moon. The orbiter successfully entered lunar orbit, although the lander, Vikram, crash-landed.",
      "date": "2019-07-22"
    },
    {
      "headline": "Launch of Chandrayaan-3",
      "text": "ISRO launched Chandrayaan-3 on July 14, 2023, with the objective of achieving a successful soft landing on the Moon. The mission was successful, making India the fourth country to achieve a soft landing on the lunar surface.",
      "date": "2023-07-14"
    }
  ]
}

