    {
      "headline": "Earliest Evidence of Welsh Language",
      "text": "The earliest evidence of the Welsh language is found in inscriptions dating from the 6th century. These inscriptions are written in the Latin alphabet and are found on stones in Wales.",
      "date": "0500"
    },
    {
      "headline": "Old Welsh Period",
      "text": "The Old Welsh period is generally considered to have lasted from the 9th to the 11th century. During this time, Welsh began to diverge more significantly from the other Brittonic languages.",
      "date": "0800"
    },
    {
      "headline": "Middle Welsh Period",
      "text": "Middle Welsh was the language used in much of the literature of Wales during the 12th to 14th centuries. This period saw the production of important works such as the Mabinogion.",
      "date": "1100"
    },
    {
      "headline": "Statute of Rhuddlan",
      "text": "In 1284, the Statute of Rhuddlan was enacted, which annexed Wales to the Kingdom of England. This marked the beginning of English influence over Welsh governance and language.",
      "date": "1284"
    },
    {
      "headline": "Publication of the Welsh Bible",
      "text": "In 1588, the complete Bible was translated into Welsh by William Morgan. This was a significant event in the history of the Welsh language, as it helped standardize the language and increase literacy.",
      "date": "1588"
    },
    {
      "headline": "Welsh Language Act 1967",
      "text": "The Welsh Language Act of 1967 was a significant legislative step that gave the Welsh language equal validity with English in Wales in certain legal contexts.",
      "date": "1967"
    },
    {
      "headline": "Welsh Language Act 1993",
      "text": "The Welsh Language Act of 1993 established the principle that the Welsh and English languages should be treated equally in the public sector in Wales.",
      "date": "1993"
    },
    {
      "headline": "Welsh Language (Wales) Measure 2011",
      "text": "In 2011, the Welsh Language (Wales) Measure was passed, giving the Welsh language official status in Wales and establishing the role of the Welsh Language Commissioner.",
      "date": "2011"
    }
  ]
}

