{
  "timeline": [
    {
      "headline": "Launch of TheFacebook",
      "text": "On February 4, 2004, Mark Zuckerberg, along with his college roommates Eduardo Saverin, Andrew McCollum, Dustin Moskovitz, and Chris Hughes, launched TheFacebook, a social networking website initially limited to Harvard University students.",
      "date": "2004-02-04"
    },
    {
      "headline": "Expansion to Other Universities",
      "text": "In March 2004, TheFacebook expanded to include students from Stanford, Columbia, and Yale. This expansion continued to other Ivy League universities and eventually most universities in the United States and Canada.",
      "date": "2004-03"
    },
    {
      "headline": "Renaming to Facebook",
      "text": "In August 2005, TheFacebook dropped 'The' from its name and became Facebook after purchasing the domain name facebook.com for $200,000.",
      "date": "2005-08"
    },
    {
      "headline": "Introduction of News Feed",
      "text": "On September 6, 2006, Facebook introduced the News Feed, a feature that aggregates users' friends' activities on the platform.",
      "date": "2006-09-06"
    },
    {
      "headline": "Opening to the General Public",
      "text": "On September 26, 2006, Facebook opened its registration to anyone aged 13 and older with a valid email address, expanding beyond its initial college student base.",
      "date": "2006-09-26"
    },
    {
      "headline": "Introduction of Facebook Platform",
      "text": "On May 24, 2007, Facebook launched the Facebook Platform, allowing third-party developers to create applications that interact with core Facebook features.",
      "date": "2007-05-24"
    },
    {
      "headline": "Introduction of Facebook Connect",
      "text": "In December 2008, Facebook introduced Facebook Connect, a single sign-on application that allows users to interact on other websites through their Facebook account.",
      "date": "2008-12"
    },
    {
      "headline": "Facebook's IPO",
      "text": "On May 18, 2012, Facebook held its initial public offering (IPO), raising $16 billion, making it one of the largest IPOs in U.S. history.",
      "date": "2012-05-18"
    },
    {
      "headline": "Acquisition of Instagram",
      "text": "On April 9, 2012, Facebook announced it would acquire Instagram, a photo-sharing app, for approximately $1 billion in cash and stock.",
      "date": "2012-04-09"
    },
    {
      "headline": "Acquisition of WhatsApp",
      "text": "On February 19, 2014, Facebook announced it would acquire WhatsApp, a messaging service, for $19 billion in cash and stock.",
      "date": "2014-02-19"
    },
    {
      "headline": "Introduction of Facebook Reactions",
      "text": "On February 24, 2016, Facebook expanded the Like button to include 'Reactions,' allowing users to express a range of emotions including Love, Haha, Wow, Sad, and Angry.",
      "date": "2016-02-24"
    },
    {
      "headline": "Rebranding to Meta",
      "text": "On October 28, 2021, Facebook announced it would rebrand its parent company to Meta Platforms, Inc., reflecting its focus on building the metaverse.",
      "date": "2021-10-28"
    }
  ]
}

