{
  "timeline": [
    {
      "headline": "Synthesis of Thalidomide",
      "text": "Thalidomide was first synthesized by the Swiss pharmaceutical company Ciba in 1953.",
      "date": "1953"
    },
    {
      "headline": "Introduction to Market",
      "text": "Thalidomide was introduced to the market by the German pharmaceutical company Chemie Grünenthal in 1957, initially marketed as a sedative.",
      "date": "1957"
    },
    {
      "headline": "Approval for Use in West Germany",
      "text": "In 1957, Thalidomide was approved for over-the-counter sale in West Germany under the brand name Contergan.",
      "date": "1957"
    },
    {
      "headline": "Discovery of Teratogenic Effects",
      "text": "In 1961, Australian obstetrician William McBride and German pediatrician Widukind Lenz independently discovered that Thalidomide was causing severe birth defects, including phocomelia.",
      "date": "1961"
    },
    {
      "headline": "Withdrawal from the Market",
      "text": "Thalidomide was withdrawn from the market in 1961 after its teratogenic effects were discovered.",
      "date": "1961"
    },
    {
      "headline": "FDA Refusal to Approve Thalidomide",
      "text": "In 1962, the U.S. Food and Drug Administration (FDA) refused to approve Thalidomide for use in the United States, largely due to the efforts of pharmacologist Frances Kelsey.",
      "date": "1962"
    },
    {
      "headline": "Reintroduction for Leprosy Treatment",
      "text": "In the late 1960s, Thalidomide was found to be effective in treating erythema nodosum leprosum, a complication of leprosy, leading to its reintroduction for this purpose.",
      "date": "1960s"
    },
    {
      "headline": "Approval for Multiple Myeloma",
      "text": "In 1998, the FDA approved Thalidomide for the treatment of erythema nodosum leprosum, and in 2006, it was approved for use in combination with dexamethasone to treat multiple myeloma.",
      "date": "2006"
    }
  ]
}

