    {
      "headline": "Origins of Thor",
      "text": "Thor is a prominent god in Germanic paganism, with his name stemming from the Proto-Germanic theonym *Þun(a)raz, meaning 'Thunder'. He is associated with lightning, thunder, storms, sacred groves and trees, strength, the protection of humankind, hallowing, and fertility.",
      "date": "-0001"
    },
    {
      "headline": "Thor in Norse Mythology",
      "text": "In Norse mythology, Thor is depicted as a hammer-wielding god. He is one of the most important gods in the Norse pantheon and is often portrayed as a protector of mankind.",
      "date": "-0001"
    },
    {
      "headline": "Thor in Old English",
      "text": "In Old English, Thor is known as Thunor. He was worshipped by the Anglo-Saxons and is associated with thunder and lightning.",
      "date": "-0001"
    },
    {
      "headline": "Thor in Old High German",
      "text": "In Old High German, Thor is referred to as Donar. He was a significant deity among the Germanic tribes, embodying the power of thunder.",
      "date": "-0001"
    },
    {
      "headline": "Thor's Cultural Impact",
      "text": "Thor has had a lasting cultural impact, influencing various aspects of modern culture, including literature, art, and popular media. His legacy continues to be celebrated in various forms around the world.",
      "date": "0000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of Anfa",
      "text": "The area now known as Casablanca was originally settled by the Berbers in the 7th century BC and was known as Anfa.",
      "date": "-0700"
    },
    {
      "headline": "Portuguese Conquest",
      "text": "In 1468, the Portuguese conquered Anfa and destroyed it due to its use as a base by pirates.",
      "date": "1468"
    },
    {
      "headline": "Rebuilding as Casa Branca",
      "text": "In 1515, the Portuguese rebuilt the city and named it Casa Branca, meaning 'White House'.",
      "date": "1515"
    },
    {
      "headline": "Abandonment by the Portuguese",
      "text": "In 1755, an earthquake destroyed much of the city, leading the Portuguese to abandon it.",
      "date": "1755"
    },
    {
      "headline": "Reconstruction by Sultan Mohammed ben Abdallah",
      "text": "In the late 18th century, Sultan Mohammed ben Abdallah rebuilt the city and renamed it Dar el Beida, which translates to 'White House'.",
      "date": "1770"
    },
    {
      "headline": "French Protectorate Established",
      "text": "In 1912, Casablanca became part of the French Protectorate in Morocco, leading to significant urban development.",
      "date": "1912"
    },
    {
      "headline": "Casablanca Conference",
      "text": "In January 1943, the Casablanca Conference was held during World War II, attended by Winston Churchill and Franklin D. Roosevelt.",
      "date": "1943-01"
    },
    {
      "headline": "Independence of Morocco",
      "text": "In 1956, Morocco gained independence from France, and Casablanca became a major economic center in the newly independent country.",
      "date": "1956"
    },
    {
      "headline": "Development of Hassan II Mosque",
      "text": "The Hassan II Mosque, one of the largest mosques in the world, was completed in 1993, becoming a landmark of Casablanca.",
      "date": "1993"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "National Historic Preservation Act Enacted",
      "text": "The National Historic Preservation Act (NHPA) was enacted on October 15, 1966, establishing the National Register of Historic Places as part of a national program to coordinate and support public and private efforts to identify, evaluate, and protect America's historic and archeological resources.",
      "date": "1966-10-15"
    },
    {
      "headline": "First Listings on the National Register",
      "text": "The first properties were listed on the National Register of Historic Places in 1966, shortly after the enactment of the National Historic Preservation Act.",
      "date": "1966"
    },
    {
      "headline": "Introduction of the National Register Criteria",
      "text": "The National Register Criteria for Evaluation were introduced to guide the assessment of properties for inclusion in the National Register. These criteria focus on the significance of properties in American history, architecture, archeology, engineering, and culture.",
      "date": "1966"
    },
    {
      "headline": "First National Register Nomination Forms",
      "text": "The first National Register nomination forms were developed to standardize the process of documenting and evaluating properties for inclusion in the National Register.",
      "date": "1968"
    },
    {
      "headline": "Amendments to the National Historic Preservation Act",
      "text": "In 1980, amendments to the National Historic Preservation Act were enacted, which included provisions to improve the administration of the National Register and expand the role of state and local governments in the preservation process.",
      "date": "1980"
    },
    {
      "headline": "50,000th Listing on the National Register",
      "text": "The National Register of Historic Places reached a milestone with its 50,000th listing, highlighting the extensive efforts to preserve and recognize America's historic places.",
      "date": "1990"
    },
    {
      "headline": "50th Anniversary of the National Register",
      "text": "The National Register of Historic Places celebrated its 50th anniversary in 2016, marking five decades of efforts to preserve and protect the nation's historic and cultural heritage.",
      "date": "2016"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Zoroaster",
      "text": "Zoroaster, also known as Zarathushtra Spitama, was born in the eastern part of the Iranian Plateau. The exact date of his birth is uncertain, but it is traditionally placed around 1500 BCE.",
      "date": "-1500"
    },
    {
      "headline": "Zoroaster's Early Life",
      "text": "Zoroaster spent his early years in a pastoral community, where he was educated in the traditional religious practices of the time.",
      "date": "-1480"
    },
    {
      "headline": "Zoroaster's First Revelation",
      "text": "At the age of 30, Zoroaster received his first revelation from Ahura Mazda, the supreme god, which marked the beginning of his mission to reform the ancient Iranian religion.",
      "date": "-1470"
    },
    {
      "headline": "Zoroaster's Preaching",
      "text": "Zoroaster began preaching his new religious ideas, emphasizing the worship of Ahura Mazda and the importance of truth and righteousness.",
      "date": "-1465"
    },
    {
      "headline": "Composition of the Gathas",
      "text": "Zoroaster composed the Gathas, a collection of hymns and religious texts that form the core of the Zoroastrian scripture, the Avesta.",
      "date": "-1460"
    },
    {
      "headline": "Conversion of King Vishtaspa",
      "text": "Zoroaster gained the support of King Vishtaspa, who converted to Zoroastrianism and helped spread the religion throughout his kingdom.",
      "date": "-1450"
    },
    {
      "headline": "Death of Zoroaster",
      "text": "Zoroaster died at the age of 77. The exact date and circumstances of his death are uncertain, but it is traditionally placed around 1423 BCE.",
      "date": "-1423"
    }
  ]
}

