{
  "timeline": [
    {
      "headline": "First Mention of Tatars",
      "text": "The Tatars were first mentioned in the 5th century by Chinese chroniclers as a nomadic people living in the northeastern part of Mongolia.",
      "date": "0400"
    },
    {
      "headline": "Tatars in the Mongol Empire",
      "text": "In the 13th century, the Tatars became part of the Mongol Empire under Genghis Khan. They were incorporated into the Mongol army and played a significant role in the Mongol conquests.",
      "date": "1200"
    },
    {
      "headline": "Golden Horde Establishment",
      "text": "In the mid-13th century, the Tatars became a dominant group within the Golden Horde, a Mongol khanate established by Batu Khan, a grandson of Genghis Khan.",
      "date": "1250"
    },
    {
      "headline": "Decline of the Golden Horde",
      "text": "By the late 14th century, the Golden Horde began to decline due to internal strife and external pressures, leading to the fragmentation of Tatar groups.",
      "date": "1390"
    },
    {
      "headline": "Kazan Khanate Formation",
      "text": "In 1438, the Kazan Khanate was established as one of the successor states of the Golden Horde, becoming a major Tatar state in the Volga region.",
      "date": "1438"
    },
    {
      "headline": "Russian Conquest of Kazan",
      "text": "In 1552, the Kazan Khanate was conquered by Ivan the Terrible, marking the beginning of Russian expansion into Tatar territories.",
      "date": "1552"
    },
    {
      "headline": "Annexation of Crimean Khanate",
      "text": "In 1783, the Crimean Khanate, another Tatar state, was annexed by the Russian Empire under Catherine the Great.",
      "date": "1783"
    },
    {
      "headline": "Soviet Era and Tatar ASSR",
      "text": "In 1920, the Tatar Autonomous Soviet Socialist Republic (Tatar ASSR) was established within the Russian Soviet Federative Socialist Republic.",
      "date": "1920"
    },
    {
      "headline": "Tatarstan Declaration of Sovereignty",
      "text": "On August 30, 1990, the Tatarstan Autonomous Soviet Socialist Republic declared its sovereignty, leading to increased autonomy within the Russian Federation.",
      "date": "1990-08-30"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Classification and Naming",
      "text": "The snow leopard (Panthera uncia) is a species of large cat in the genus Panthera of the family Felidae. It was first described in 1775 by German naturalist Johann Christian Daniel von Schreber.",
      "date": "1775"
    },
    {
      "headline": "Habitat and Range",
      "text": "The snow leopard is native to the mountain ranges of Central and South Asia. It inhabits alpine and subalpine zones at elevations of 3,000–4,500 m, ranging from eastern Afghanistan, the Himalayas, and the Tibetan Plateau to southern Siberia, Mongolia, and western China.",
      "date": "0000"
    },
    {
      "headline": "Conservation Status",
      "text": "The snow leopard is listed as Vulnerable on the IUCN Red List because the global population is estimated to number fewer than 10,000 mature individuals and is expected to decline about 10% by 2040.",
      "date": "2023"
    },
    {
      "headline": "Threats to Survival",
      "text": "The species is mainly threatened by poaching and habitat destruction following infrastructural developments.",
      "date": "2023"
    }
  ]
}

