    {
      "headline": "PCI Express 1.0 Released",
      "text": "In 2003, PCI Express 1.0 was released, marking the introduction of a high-speed serial computer expansion bus standard designed to replace older standards such as PCI, PCI-X, and AGP.",
      "date": "2003"
    },
    {
      "headline": "PCI Express 2.0 Released",
      "text": "In January 2007, PCI Express 2.0 was released, doubling the data rate of PCIe 1.0 from 2.5 GT/s to 5 GT/s, effectively increasing the bandwidth available for devices.",
      "date": "2007-01"
    },
    {
      "headline": "PCI Express 3.0 Released",
      "text": "In November 2010, PCI Express 3.0 was released, further increasing the data rate to 8 GT/s and introducing improvements in encoding efficiency, which allowed for higher data throughput.",
      "date": "2010-11"
    },
    {
      "headline": "PCI Express 4.0 Released",
      "text": "In October 2017, PCI Express 4.0 was released, doubling the data rate again to 16 GT/s, providing even greater bandwidth for high-performance computing applications.",
      "date": "2017-10"
    },
    {
      "headline": "PCI Express 5.0 Released",
      "text": "In May 2019, PCI Express 5.0 was released, doubling the data rate to 32 GT/s, which significantly increased the bandwidth for data-intensive applications and devices.",
      "date": "2019-05"
    },
    {
      "headline": "PCI Express 6.0 Specification Published",
      "text": "In January 2022, the PCI Express 6.0 specification was published, introducing a data rate of 64 GT/s and utilizing PAM-4 (Pulse Amplitude Modulation with 4 levels) to achieve higher data throughput.",
      "date": "2022-01"
    }
  ]
}

