{
  "timeline": [
    {
      "headline": "Foundation of the Kingdom of Macedon",
      "text": "The Kingdom of Macedon was founded in the early 7th century BCE by the royal Argead dynasty. It was initially a small kingdom centered on the northeastern part of the Greek peninsula.",
      "date": "-0700"
    },
    {
      "headline": "Reign of King Amyntas I",
      "text": "Amyntas I ruled Macedon from approximately 547 BCE to 498 BCE. He was the first Macedonian king to have diplomatic relations with other Greek states.",
      "date": "-0547"
    },
    {
      "headline": "Reign of King Alexander I",
      "text": "Alexander I, known as 'the Philhellene', ruled from 498 BCE to 454 BCE. He expanded the kingdom and established Macedonian presence in the Olympic Games.",
      "date": "-0498"
    },
    {
      "headline": "Reign of King Archelaus I",
      "text": "Archelaus I ruled from 413 BCE to 399 BCE. He is credited with strengthening the kingdom's infrastructure and military.",
      "date": "-0413"
    },
    {
      "headline": "Reign of King Philip II",
      "text": "Philip II ruled from 359 BCE to 336 BCE. He reformed the Macedonian army and established Macedon as a dominant power in Greece.",
      "date": "-0359"
    },
    {
      "headline": "Battle of Chaeronea",
      "text": "In 338 BCE, Philip II defeated the combined forces of Athens and Thebes at the Battle of Chaeronea, securing Macedonian hegemony over Greece.",
      "date": "-0338"
    },
    {
      "headline": "Assassination of Philip II",
      "text": "Philip II was assassinated in 336 BCE, leading to the ascension of his son, Alexander the Great.",
      "date": "-0336"
    },
    {
      "headline": "Reign of Alexander the Great",
      "text": "Alexander the Great ruled from 336 BCE to 323 BCE. He created one of the largest empires in history, stretching from Greece to Egypt and into northwest India.",
      "date": "-0336"
    },
    {
      "headline": "Death of Alexander the Great",
      "text": "Alexander the Great died in 323 BCE in Babylon, leading to the division of his empire among his generals, known as the Diadochi.",
      "date": "-0323"
    },
    {
      "headline": "Reign of the Antipatrid Dynasty",
      "text": "Following the death of Alexander, the Antipatrid dynasty ruled Macedon from 321 BCE to 294 BCE.",
      "date": "-0321"
    },
    {
      "headline": "Reign of the Antigonid Dynasty",
      "text": "The Antigonid dynasty began its rule in 294 BCE and continued until the Roman conquest in 168 BCE.",
      "date": "-0294"
    },
    {
      "headline": "Battle of Pydna",
      "text": "In 168 BCE, the Romans defeated the Macedonian forces at the Battle of Pydna, leading to the end of the Antigonid dynasty and the annexation of Macedon by Rome.",
      "date": "-0168"
    }
  ]
}

