      "headline": "ARM7TDMI Core Release",
      "text": "In 1994, the ARM7TDMI core was released. It became one of the most successful ARM cores, widely used in embedded systems.",
      "date": "1994"
    },
    {
      "headline": "ARM Holdings IPO",
      "text": "ARM Holdings went public in 1998, listing on the London Stock Exchange and NASDAQ.",
      "date": "1998"
    },
