    {
      "headline": "Founding of Omaha",
      "text": "Omaha was founded on July 4, 1854, by speculators from the Council Bluffs, Iowa, area. The city was established on the west bank of the Missouri River.",
      "date": "1854-07-04"
    },
    {
      "headline": "Omaha Becomes County Seat",
      "text": "In 1855, Omaha was chosen as the county seat of Douglas County, Nebraska.",
      "date": "1855"
    },
    {
      "headline": "Territorial Capital",
      "text": "Omaha served as the territorial capital of Nebraska from 1854 until 1867 when Nebraska became a state and the capital was moved to Lincoln.",
      "date": "1854"
    },
    {
      "headline": "Transcontinental Railroad",
      "text": "On May 10, 1869, the First Transcontinental Railroad was completed, with Omaha serving as a key point in the Union Pacific Railroad's construction.",
      "date": "1869-05-10"
    },
    {
      "headline": "Omaha Race Riot",
      "text": "In 1919, the Omaha Race Riot occurred, resulting in the lynching of Will Brown, a black worker, and significant destruction in the city.",
      "date": "1919"
    },
    {
      "headline": "Omaha Stockyards Peak",
      "text": "In 1955, the Omaha Stockyards became the largest livestock market in the world, a title it held until the 1970s.",
      "date": "1955"
    },
    {
      "headline": "Civil Rights Movement",
      "text": "During the 1960s, Omaha was a center for civil rights activism, with significant events and protests occurring throughout the decade.",
      "date": "1960"
    },
    {
      "headline": "Omaha Tornado",
      "text": "On May 6, 1975, a devastating tornado struck Omaha, causing widespread damage and resulting in three deaths.",
      "date": "1975-05-06"
    },
    {
      "headline": "Omaha's Economic Growth",
      "text": "In the late 20th and early 21st centuries, Omaha experienced significant economic growth, becoming a hub for finance, insurance, and telecommunications.",
      "date": "2000"
    },
    {
      "headline": "Population Milestone",
      "text": "As of the 2020 census, Omaha had a population of 486,051, making it the 40th-most populous city in the United States.",
      "date": "2020"
    }
  ]
}

