{
  "timeline": [
    {
      "headline": "Birth of Pancho Villa",
      "text": "Francisco 'Pancho' Villa was born on June 5, 1878, in La Coyotada, San Juan del Río, Durango, Mexico.",
      "date": "1878-06-05"
    },
    {
      "headline": "Joins the Mexican Revolution",
      "text": "In 1910, Pancho Villa joined the Mexican Revolution, initially supporting Francisco I. Madero's uprising against the long-standing dictator Porfirio Díaz.",
      "date": "1910"
    },
    {
      "headline": "Battle of Ciudad Juárez",
      "text": "In May 1911, Villa played a significant role in the Battle of Ciudad Juárez, which was a decisive victory for the revolutionary forces and led to the resignation of Porfirio Díaz.",
      "date": "1911-05"
    },
    {
      "headline": "Break with Madero",
      "text": "After Madero became president, Villa had a falling out with him and was imprisoned in 1912. He escaped and fled to the United States.",
      "date": "1912"
    },
    {
      "headline": "Joins Anti-Huerta Forces",
      "text": "In 1913, following the coup by Victoriano Huerta, Villa joined the Constitutionalist Army led by Venustiano Carranza to fight against Huerta's regime.",
      "date": "1913"
    },
    {
      "headline": "Defeat of Huerta",
      "text": "In July 1914, Huerta was defeated and went into exile. Villa's forces played a crucial role in this victory.",
      "date": "1914-07"
    },
    {
      "headline": "Break with Carranza",
      "text": "After Huerta's defeat, Villa broke with Carranza due to political differences and formed an alliance with Emiliano Zapata.",
      "date": "1914"
    },
    {
      "headline": "Battle of Celaya",
      "text": "In April 1915, Villa suffered a significant defeat at the Battle of Celaya against Carranza's forces led by Álvaro Obregón.",
      "date": "1915-04"
    },
    {
      "headline": "Raid on Columbus, New Mexico",
      "text": "On March 9, 1916, Villa led a raid on the town of Columbus, New Mexico, which prompted the U.S. to launch the Punitive Expedition to capture him.",
      "date": "1916-03-09"
    },
    {
      "headline": "Retirement from Revolutionary Activities",
      "text": "In 1920, Villa retired from revolutionary activities after negotiating a peace agreement with the Mexican government.",
      "date": "1920"
    },
    {
      "headline": "Assassination",
      "text": "Pancho Villa was assassinated on July 20, 1923, in Parral, Chihuahua, Mexico.",
      "date": "1923-07-20"
    }
  ]
}

{
  "timeline": [
