{
  "timeline": [
    {
      "headline": "Establishment of the British Indian Ocean Territory",
      "text": "The British Indian Ocean Territory (BIOT) was established on November 8, 1965, when the United Kingdom separated the Chagos Archipelago from Mauritius and the islands of Aldabra, Farquhar, and Desroches from the Seychelles to form a new territory.",
      "date": "1965-11-08"
    },
    {
      "headline": "Transfer of Islands to Seychelles",
      "text": "In 1976, the islands of Aldabra, Farquhar, and Desroches were returned to Seychelles when it gained independence.",
      "date": "1976"
    },
    {
      "headline": "Establishment of Military Facility on Diego Garcia",
      "text": "In 1971, the United Kingdom and the United States established a joint military facility on Diego Garcia, the largest island in the British Indian Ocean Territory.",
      "date": "1971"
    },
    {
      "headline": "Eviction of Chagossians",
      "text": "Between 1968 and 1973, the native Chagossians were forcibly removed from the islands to make way for the military base on Diego Garcia.",
      "date": "1968-1973"
    },
    {
      "headline": "Legal Battles Over Chagossian Resettlement",
      "text": "Since the 2000s, there have been ongoing legal battles and campaigns by Chagossians seeking the right to return to the islands.",
      "date": "2000"
    },
    {
      "headline": "Marine Protected Area Declared",
      "text": "On April 1, 2010, the British government declared the British Indian Ocean Territory a Marine Protected Area, which was later challenged by Mauritius.",
      "date": "2010-04-01"
    },
    {
      "headline": "International Court of Justice Advisory Opinion",
      "text": "On February 25, 2019, the International Court of Justice issued an advisory opinion stating that the United Kingdom should end its administration of the Chagos Archipelago and return it to Mauritius.",
      "date": "2019-02-25"
    }
  ]
}

