{
  "timeline": [
    {
      "headline": "Union of Lublin",
      "text": "The Union of Lublin was signed on July 1, 1569, creating the Polish–Lithuanian Commonwealth. This act united the Kingdom of Poland and the Grand Duchy of Lithuania into a single state with a common monarch and parliament.",
      "date": "1569-07-01"
    },
    {
      "headline": "Warsaw Confederation",
      "text": "In 1573, the Warsaw Confederation was signed, granting religious freedom to the nobility and free persons within the Commonwealth. This was a significant step towards religious tolerance in Europe.",
      "date": "1573"
    },
    {
      "headline": "Battle of Khotyn",
      "text": "The Battle of Khotyn took place in 1621, where the Commonwealth forces successfully defended against the Ottoman Empire, marking a significant military achievement.",
      "date": "1621"
    },
    {
      "headline": "Deluge",
      "text": "The Deluge refers to a series of mid-17th-century invasions and wars, primarily the Swedish invasion of the Polish–Lithuanian Commonwealth, which began in 1655 and caused significant devastation.",
      "date": "1655"
    },
    {
      "headline": "Treaty of Andrusovo",
      "text": "The Treaty of Andrusovo was signed in 1667, ending the Thirteen Years' War between the Commonwealth and Tsardom of Russia, resulting in territorial losses for the Commonwealth.",
      "date": "1667"
    },
    {
      "headline": "Great Northern War",
      "text": "The Great Northern War (1700-1721) involved the Commonwealth as a battleground between Sweden and Russia, leading to further weakening of the Commonwealth's political structure.",
      "date": "1700"
    },
    {
      "headline": "First Partition of Poland",
      "text": "In 1772, the First Partition of Poland took place, where the Commonwealth's territory was divided among Prussia, Russia, and Austria, significantly reducing its size.",
      "date": "1772"
    },
    {
      "headline": "Constitution of May 3, 1791",
      "text": "The Constitution of May 3, 1791, was adopted, becoming the first modern constitution in Europe and the second in the world. It aimed to strengthen the Commonwealth politically and socially.",
      "date": "1791-05-03"
    },
    {
      "headline": "Second Partition of Poland",
      "text": "The Second Partition of Poland occurred in 1793, further reducing the Commonwealth's territory as Prussia and Russia annexed more land.",
      "date": "1793"
    },
    {
      "headline": "Third Partition of Poland",
      "text": "In 1795, the Third Partition of Poland was executed, leading to the complete dissolution of the Polish–Lithuanian Commonwealth as its remaining territories were divided among Prussia, Russia, and Austria.",
      "date": "1795"
    }
  ]
}

