{
  "timeline": [
    {
      "headline": "Birth of Jacob",
      "text": "Jacob, the patriarch of the Twelve Tribes of Israel, was born to Isaac and Rebekah. His birth is traditionally dated to around 2000 BCE.",
      "date": "-2000"
    },
    {
      "headline": "Jacob's Name Changed to Israel",
      "text": "According to the Hebrew Bible, Jacob's name was changed to Israel after he wrestled with an angel. This event is considered significant as it marks the beginning of the Israelite nation.",
      "date": "-1900"
    },
    {
      "headline": "Birth of the Twelve Sons",
      "text": "Jacob had twelve sons who became the progenitors of the Twelve Tribes of Israel. These sons were Reuben, Simeon, Levi, Judah, Dan, Naphtali, Gad, Asher, Issachar, Zebulun, Joseph, and Benjamin.",
      "date": "-1900"
    },
    {
      "headline": "Settlement in Egypt",
      "text": "The descendants of Jacob, including the Twelve Tribes, settled in Egypt during a famine. This event is traditionally dated to the time of Joseph, one of Jacob's sons, who had risen to power in Egypt.",
      "date": "-1700"
    },
    {
      "headline": "Exodus from Egypt",
      "text": "The Twelve Tribes of Israel, led by Moses, left Egypt in an event known as the Exodus. This is traditionally dated to around 1446 BCE.",
      "date": "-1446"
    },
    {
      "headline": "Conquest of Canaan",
      "text": "Under the leadership of Joshua, the Twelve Tribes of Israel entered and began the conquest of Canaan, the land promised to them according to the Hebrew Bible.",
      "date": "-1400"
    },
    {
      "headline": "Division of the Land",
      "text": "After the conquest of Canaan, the land was divided among the Twelve Tribes of Israel. Each tribe received a portion of land, except for the tribe of Levi, which was given cities and the responsibility of religious duties.",
      "date": "-1400"
    },
    {
      "headline": "Establishment of the United Monarchy",
      "text": "The Twelve Tribes were united under a single monarchy during the reigns of Saul, David, and Solomon. This period is traditionally dated to around 1050-930 BCE.",
      "date": "-1050"
    },
    {
      "headline": "Division of the Kingdom",
      "text": "After the death of Solomon, the united monarchy split into the northern kingdom of Israel and the southern kingdom of Judah. The northern kingdom consisted of ten tribes, while Judah and Benjamin formed the southern kingdom.",
      "date": "-930"
    },
    {
      "headline": "Assyrian Conquest of Israel",
      "text": "The northern kingdom of Israel, consisting of ten tribes, was conquered by the Assyrian Empire in 722 BCE, leading to the dispersion of these tribes.",
      "date": "-722"
    }
  ]
}

