{
  "timeline": [
    {
      "headline": "Founding of the Muslim Brotherhood",
      "text": "The Muslim Brotherhood was founded in 1928 by Hassan al-Banna in Ismailia, Egypt. It began as a religious and social organization advocating for the implementation of Islamic principles in personal and public life.",
      "date": "1928"
    },
    {
      "headline": "Expansion and Growth",
      "text": "During the 1930s, the Muslim Brotherhood expanded rapidly, establishing branches throughout Egypt and gaining a significant following. It focused on social services, education, and charitable activities.",
      "date": "1930"
    },
    {
      "headline": "Political Involvement",
      "text": "In the 1940s, the Muslim Brotherhood became increasingly involved in politics, opposing British colonial rule and advocating for the establishment of an Islamic state.",
      "date": "1940"
    },
    {
      "headline": "Assassination of Hassan al-Banna",
      "text": "On February 12, 1949, Hassan al-Banna, the founder of the Muslim Brotherhood, was assassinated in Cairo. His death marked a significant turning point for the organization.",
      "date": "1949-02-12"
    },
    {
      "headline": "Crackdown and Banning",
      "text": "In 1954, the Egyptian government banned the Muslim Brotherhood following an alleged assassination attempt on President Gamal Abdel Nasser. Many members were arrested, and the organization was forced underground.",
      "date": "1954"
    },
    {
      "headline": "Revival and Political Participation",
      "text": "In the 1970s, the Muslim Brotherhood began to re-emerge as a political force in Egypt, participating in elections and gaining influence in professional associations and student unions.",
      "date": "1970"
    },
    {
      "headline": "Arab Spring and Political Success",
      "text": "During the Arab Spring in 2011, the Muslim Brotherhood played a key role in the protests that led to the ousting of President Hosni Mubarak. In 2012, their political party, the Freedom and Justice Party, won the parliamentary elections, and Mohamed Morsi, a member of the Brotherhood, was elected President of Egypt.",
      "date": "2011"
    },
    {
      "headline": "Military Coup and Crackdown",
      "text": "In 2013, Mohamed Morsi was ousted by a military coup led by General Abdel Fattah el-Sisi. The Muslim Brotherhood was subsequently declared a terrorist organization by the Egyptian government, and many of its members were arrested or went into exile.",
      "date": "2013"
    }
  ]
}

