  "timeline": [
    {
      "headline": "First Clinical Description of Polio",
      "text": "The first clinical description of polio was provided by the English physician Michael Underwood in 1789, who referred to it as 'debility of the lower extremities'.",
      "date": "1789"
    },
    {
      "headline": "First Recognized Polio Epidemic",
      "text": "The first recognized polio epidemic occurred in the United States in 1894, in Vermont, with 132 cases.",
      "date": "1894"
    },
    {
      "headline": "Identification of Poliovirus",
      "text": "In 1908, Austrian physicians Karl Landsteiner and Erwin Popper identified the poliovirus as the cause of poliomyelitis.",
      "date": "1908"
    },
    {
      "headline": "Development of the Iron Lung",
      "text": "The iron lung, a type of negative pressure ventilator, was developed in 1928 by Philip Drinker and Louis Agassiz Shaw, and it became a critical tool for treating polio patients with respiratory paralysis.",
      "date": "1928"
    },
    {
      "headline": "Salk Polio Vaccine Trials",
      "text": "In 1954, large-scale trials of the inactivated polio vaccine developed by Jonas Salk were conducted, involving 1.8 million children in the United States.",
      "date": "1954"
    },
    {
      "headline": "Licensing of Salk Vaccine",
      "text": "On April 12, 1955, the Salk polio vaccine was declared safe and effective and was licensed for use in the United States.",
      "date": "1955-04-12"
    },
    {
      "headline": "Sabin Oral Polio Vaccine",
      "text": "Albert Sabin developed an oral polio vaccine using attenuated poliovirus strains, which was first tested in 1957 and became widely used in the 1960s.",
      "date": "1957"
    },
    {
      "headline": "Global Polio Eradication Initiative",
      "text": "The Global Polio Eradication Initiative was launched in 1988, led by the World Health Organization, Rotary International, the CDC, and UNICEF, aiming to eradicate polio worldwide.",
      "date": "1988"
    },
    {
      "headline": "Polio Eradicated in the Americas",
      "text": "In 1994, the Americas were declared polio-free by the World Health Organization.",
      "date": "1994"
    },
    {
      "headline": "Polio Eradicated in the Western Pacific",
      "text": "The Western Pacific region, including China and Australia, was declared polio-free in 2000.",
      "date": "2000"
    },
    {
      "headline": "Polio Eradicated in Europe",
      "text": "In 2002, Europe was certified polio-free by the World Health Organization.",
      "date": "2002"
    },
    {
      "headline": "Africa Declared Polio-Free",
      "text": "On August 25, 2020, the World Health Organization declared the African continent free of wild poliovirus.",
      "date": "2020-08-25"
    }
  ]
}

