    },
    {
      "headline": "Death of Gamal Abdel Nasser",
      "text": "Egyptian President Gamal Abdel Nasser, who played a key role in negotiating the ceasefire, died on 28 September 1970.",
      "date": "1970-09-28"
    },
    {
      "headline": "Renewed Fighting",
      "text": "Despite the ceasefire, sporadic fighting continued in Jordan between the Jordanian army and PLO forces into 1971.",
      "date": "1971"
    },
    {
      "headline": "End of Black September",
      "text": "The conflict officially ended on 17 July 1971, when the Jordanian army successfully expelled the remaining PLO forces from Jordan.",
      "date": "1971-07-17"
    }
  ]
}

