{
  "timeline": [
    {
      "headline": "Creation of the NSA",
      "text": "The National Security Agency (NSA) was officially established on November 4, 1952, by President Harry S. Truman. It was created to coordinate and consolidate the United States' cryptologic and signals intelligence activities.",
      "date": "1952-11-04"
    },
    {
      "headline": "NSA's Role in the Cold War",
      "text": "During the Cold War, the NSA played a crucial role in gathering intelligence on the Soviet Union and its allies. The agency's efforts focused on intercepting and deciphering communications to gain strategic advantages.",
      "date": "1950s-1991"
    },
    {
      "headline": "ECHELON Network",
      "text": "In the late 1960s, the NSA began developing the ECHELON network, a global system for intercepting communications. It became fully operational in the 1970s and was used to monitor communications worldwide.",
      "date": "1970s"
    },
    {
      "headline": "Church Committee Investigation",
      "text": "In 1975, the Church Committee investigated the NSA's domestic surveillance activities, leading to increased oversight and the establishment of the Foreign Intelligence Surveillance Act (FISA) in 1978.",
      "date": "1975"
    },
    {
      "headline": "Introduction of the Foreign Intelligence Surveillance Act (FISA)",
      "text": "The Foreign Intelligence Surveillance Act (FISA) was enacted in 1978, establishing procedures for the physical and electronic surveillance and collection of foreign intelligence information between foreign powers and agents of foreign powers.",
      "date": "1978"
    },
    {
      "headline": "9/11 and the NSA's Expanded Role",
      "text": "Following the September 11, 2001 terrorist attacks, the NSA's role expanded significantly under the USA PATRIOT Act, allowing for increased surveillance and intelligence-gathering capabilities.",
      "date": "2001-09-11"
    },
    {
      "headline": "Edward Snowden Revelations",
      "text": "In 2013, former NSA contractor Edward Snowden leaked classified information revealing the extent of the NSA's global surveillance programs, sparking widespread debate over privacy and government surveillance.",
      "date": "2013"
    },
    {
      "headline": "USA Freedom Act",
      "text": "In response to the Snowden revelations, the USA Freedom Act was passed in 2015, reforming some aspects of the NSA's surveillance practices, including ending the bulk collection of phone metadata.",
      "date": "2015"
    }
  ]
}

