{
  "timeline": [
    {
      "headline": "Disappearance of Malaysia Airlines Flight 370",
      "text": "On March 8, 2014, Malaysia Airlines Flight 370, a Boeing 777-200ER, disappeared while flying from Kuala Lumpur International Airport, Malaysia, to Beijing Capital International Airport, China.",
      "date": "2014-03-08"
    },
    {
      "headline": "Initial Search Efforts",
      "text": "Immediately after the disappearance on March 8, 2014, search efforts began in the Gulf of Thailand and the South China Sea, where the aircraft was last in contact with air traffic control.",
      "date": "2014-03-08"
    },
    {
      "headline": "Search Area Shifted to Southern Indian Ocean",
      "text": "On March 15, 2014, analysis of satellite communications led to the conclusion that the aircraft had likely flown south into the Indian Ocean, shifting the search area.",
      "date": "2014-03-15"
    },
    {
      "headline": "Australia Leads Search Efforts",
      "text": "On March 17, 2014, Australia took the lead in the search efforts in the southern Indian Ocean, coordinating with several other countries.",
      "date": "2014-03-17"
    },
    {
      "headline": "Debris Found on Reunion Island",
      "text": "On July 29, 2015, a flaperon from the aircraft was found on the shore of Réunion Island, confirming that the aircraft had crashed in the Indian Ocean.",
      "date": "2015-07-29"
    },
    {
      "headline": "Official Search Suspended",
      "text": "On January 17, 2017, the official search for Flight 370 was suspended after covering 120,000 square kilometers of the southern Indian Ocean without finding the main wreckage.",
      "date": "2017-01-17"
    },
    {
      "headline": "Private Search by Ocean Infinity",
      "text": "In January 2018, a private company, Ocean Infinity, began a new search for the aircraft on a 'no find, no fee' basis, but it was concluded in May 2018 without success.",
      "date": "2018-01"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Recognition of Kuru",
      "text": "Kuru was first recognized in the 1950s among the Fore people of Papua New Guinea. The disease was noted for its symptoms of tremors and pathological bursts of laughter.",
      "date": "1950"
    },
    {
      "headline": "Identification as a Prion Disease",
      "text": "In the 1960s, researchers identified kuru as a prion disease, a type of neurodegenerative disorder caused by infectious proteins.",
      "date": "1960"
    },
    {
      "headline": "Research by Carleton Gajdusek",
      "text": "In the 1960s, Carleton Gajdusek conducted extensive research on kuru, leading to the understanding of its transmission through cannibalistic funeral practices.",
      "date": "1960"
    },
    {
      "headline": "Nobel Prize in Physiology or Medicine",
      "text": "In 1976, Carleton Gajdusek was awarded the Nobel Prize in Physiology or Medicine for his work on kuru and other prion diseases.",
      "date": "1976"
    },
    {
      "headline": "Decline of Kuru Cases",
      "text": "By the late 20th century, the incidence of kuru had significantly declined due to the cessation of cannibalistic practices among the Fore people.",
      "date": "1980"
    }
  ]
}

