      "headline": "Birth of Aldous Huxley",
      "text": "Aldous Leonard Huxley was born on July 26, 1894, in Godalming, Surrey, England.",
      "date": "1894-07-26"
    },
    {
      "headline": "Education at Eton College",
      "text": "Huxley attended Eton College, where he initially planned to pursue a career in medicine.",
      "date": "1908"
    },
    {
      "headline": "Illness and Vision Impairment",
      "text": "In 1911, Huxley contracted an illness that left him nearly blind for two to three years, which ended his plans for a medical career.",
      "date": "1911"
    },
    {
      "headline": "Studied at Balliol College, Oxford",
      "text": "Huxley studied English literature at Balliol College, Oxford, and graduated with first-class honors in 1916.",
      "date": "1916"
    },
    {
      "headline": "Publication of First Book",
      "text": "In 1916, Huxley published his first book, a collection of poems titled 'The Burning Wheel'.",
      "date": "1916"
    },
    {
      "headline": "Marriage to Maria Nys",
      "text": "Huxley married Maria Nys, a Belgian refugee, on July 10, 1919.",
      "date": "1919-07-10"
    },
    {
      "headline": "Publication of 'Crome Yellow'",
      "text": "Huxley's first novel, 'Crome Yellow', was published in 1921, establishing him as a writer.",
      "date": "1921"
    },
    {
      "headline": "Publication of 'Brave New World'",
      "text": "In 1932, Huxley published 'Brave New World', one of his most famous works, depicting a dystopian future.",
      "date": "1932"
    },
    {
      "headline": "Move to the United States",
      "text": "Huxley moved to the United States in 1937, settling in Hollywood, California.",
      "date": "1937"
    },
    {
      "headline": "Publication of 'The Doors of Perception'",
      "text": "In 1954, Huxley published 'The Doors of Perception', detailing his experiences with psychedelic drugs.",
      "date": "1954"
    },
    {
      "headline": "Death of Maria Nys",
      "text": "Maria Nys, Huxley's first wife, passed away in 1955.",
      "date": "1955"
    },
    {
      "headline": "Marriage to Laura Archera",
      "text": "Huxley married Laura Archera, an Italian violinist and psychotherapist, in 1956.",
      "date": "1956"
    },
    {
      "headline": "Death of Aldous Huxley",
      "text": "Aldous Huxley died on November 22, 1963, in Los Angeles, California, from laryngeal cancer.",
      "date": "1963-11-22"
    }
  ]
}

