{
  "timeline": [
    {
      "headline": "First Burning Man Event",
      "text": "The first Burning Man event took place on Baker Beach in San Francisco, California, in 1986. Larry Harvey and Jerry James built an 8-foot wooden effigy and burned it in celebration of the summer solstice.",
      "date": "1986"
    },
    {
      "headline": "Move to Black Rock Desert",
      "text": "In 1990, the event moved from San Francisco's Baker Beach to the Black Rock Desert in Nevada. This move marked the beginning of Burning Man as a desert event.",
      "date": "1990"
    },
    {
      "headline": "Establishment of Black Rock City",
      "text": "Burning Man evolved into a temporary city known as Black Rock City, which is constructed each year in the Black Rock Desert. The city is designed to accommodate the growing number of participants.",
      "date": "1991"
    },
    {
      "headline": "Formation of the Burning Man Organization",
      "text": "In 1997, the Burning Man organization was formed to manage the event and its growing complexities. This organization oversees the logistics, safety, and principles of the event.",
      "date": "1997"
    },
    {
      "headline": "Introduction of the Ten Principles",
      "text": "In 2004, Larry Harvey articulated the Ten Principles of Burning Man, which include radical inclusion, gifting, decommodification, radical self-reliance, radical self-expression, communal effort, civic responsibility, leaving no trace, participation, and immediacy.",
      "date": "2004"
    },
    {
      "headline": "Record Attendance",
      "text": "In 2019, Burning Man reached a record attendance of approximately 78,850 participants, reflecting its growth and popularity as a cultural phenomenon.",
      "date": "2019"
    },
    {
      "headline": "Cancellation Due to COVID-19",
      "text": "In 2020, Burning Man was canceled for the first time in its history due to the COVID-19 pandemic. The event was held virtually instead.",
      "date": "2020"
    }
  ]
}

