      "headline": "Birth of Maria Theresa",
      "text": "Maria Theresa was born on May 13, 1717, in Vienna, Austria, as the eldest daughter of Emperor Charles VI and Elisabeth Christine of Brunswick-Wolfenbüttel.",
      "date": "1717-05-13"
    },
    {
      "headline": "Marriage to Francis Stephen of Lorraine",
      "text": "On February 12, 1736, Maria Theresa married Francis Stephen of Lorraine, who later became Holy Roman Emperor Francis I.",
      "date": "1736-02-12"
    },
    {
      "headline": "Accession to the Throne",
      "text": "Maria Theresa became the ruler of the Habsburg dominions on October 20, 1740, following the death of her father, Emperor Charles VI.",
      "date": "1740-10-20"
    },
    {
      "headline": "War of the Austrian Succession",
      "text": "The War of the Austrian Succession began in 1740 and lasted until 1748, as various European powers contested Maria Theresa's right to inherit the Habsburg territories.",
      "date": "1740"
    },
    {
      "headline": "Treaty of Aix-la-Chapelle",
      "text": "The Treaty of Aix-la-Chapelle was signed in 1748, ending the War of the Austrian Succession and recognizing Maria Theresa's rule over the Habsburg territories.",
      "date": "1748"
    },
    {
      "headline": "Reforms in the Habsburg Monarchy",
      "text": "Throughout the 1750s and 1760s, Maria Theresa implemented a series of administrative, financial, and educational reforms to strengthen the Habsburg Monarchy.",
      "date": "1750"
    },
    {
      "headline": "Seven Years' War",
      "text": "From 1756 to 1763, Maria Theresa was involved in the Seven Years' War, allying with France and Russia against Prussia and Great Britain.",
      "date": "1756"
    },
    {
      "headline": "Partition of Poland",
      "text": "In 1772, Maria Theresa participated in the first partition of Poland, acquiring the region of Galicia and Lodomeria for the Habsburg Monarchy.",
      "date": "1772"
    },
    {
      "headline": "Death of Maria Theresa",
      "text": "Maria Theresa died on November 29, 1780, in Vienna, Austria, after a 40-year reign over the Habsburg dominions.",
      "date": "1780-11-29"
    }
  ]
}

