{
  "timeline": [
    {
      "headline": "Establishment of R&AW",
      "text": "The Research and Analysis Wing (R&AW) was established on September 21, 1968, as India's foreign intelligence agency. It was created to handle the country's foreign intelligence needs, separate from the Intelligence Bureau.",
      "date": "1968-09-21"
    },
    {
      "headline": "First Chief of R&AW",
      "text": "R. N. Kao was appointed as the first chief of R&AW in 1968. He played a crucial role in setting up the agency and shaping its early operations.",
      "date": "1968"
    },
    {
      "headline": "Role in the Bangladesh Liberation War",
      "text": "R&AW played a significant role in the Bangladesh Liberation War of 1971 by providing intelligence support to the Indian Armed Forces and the Mukti Bahini, contributing to the creation of Bangladesh.",
      "date": "1971"
    },
    {
      "headline": "Operation Smiling Buddha",
      "text": "R&AW was involved in the security and secrecy of India's first nuclear test, Operation Smiling Buddha, conducted on May 18, 1974, at Pokhran.",
      "date": "1974-05-18"
    },
    {
      "headline": "Kao's Retirement",
      "text": "R. N. Kao retired from R&AW in 1977, after serving as its chief for nearly a decade and establishing its foundation.",
      "date": "1977"
    },
    {
      "headline": "Operation Meghdoot",
      "text": "R&AW provided intelligence for Operation Meghdoot in 1984, which led to India gaining control over the Siachen Glacier.",
      "date": "1984"
    },
    {
      "headline": "Kargil Conflict",
      "text": "During the Kargil Conflict in 1999, R&AW provided crucial intelligence that helped the Indian military in planning and executing operations to reclaim territory.",
      "date": "1999"
    },
    {
      "headline": "Role in Counter-Terrorism",
      "text": "R&AW has been actively involved in counter-terrorism efforts, particularly after the 2001 Indian Parliament attack and the 2008 Mumbai attacks, by gathering intelligence and supporting operations to prevent further attacks.",
      "date": "2001"
    },
    {
      "headline": "Expansion of R&AW's Role",
      "text": "Over the years, R&AW has expanded its role to include counter-proliferation and advising Indian policymakers, in addition to its traditional intelligence-gathering functions.",
      "date": "2000s"
    }
  ]
}

