      "headline": "First Dáil convenes",
      "text": "On January 21, 1919, the First Dáil convened in Dublin and issued a declaration of independence from Britain.",
      "date": "1919-01-21"
    },
    {
      "headline": "Soloheadbeg Ambush",
      "text": "On January 21, 1919, the Soloheadbeg Ambush took place in County Tipperary, marking the beginning of the Irish War of Independence.",
      "date": "1919-01-21"
    },
    {
      "headline": "Formation of the Irish Republican Army (IRA)",
      "text": "In 1919, the Irish Volunteers were reconstituted as the Irish Republican Army (IRA), which became the military force fighting for Irish independence.",
      "date": "1919"
    },
    {
      "headline": "Government of Ireland Act 1920",
      "text": "In December 1920, the British Parliament passed the Government of Ireland Act, which sought to establish two separate Home Rule parliaments in Ireland.",
      "date": "1920-12"
    },
    {
      "headline": "Bloody Sunday",
      "text": "On November 21, 1920, a day known as Bloody Sunday, the IRA assassinated 14 British intelligence agents in Dublin, and British forces retaliated by firing into the crowd at a Gaelic football match, killing 14 civilians.",
      "date": "1920-11-21"
    },
    {
      "headline": "Burning of Cork",
      "text": "On December 11, 1920, British forces set fire to the center of Cork city, causing extensive damage and destruction.",
      "date": "1920-12-11"
    },
    {
      "headline": "Truce declared",
      "text": "On July 11, 1921, a truce was declared between the IRA and British forces, effectively ending the hostilities of the Irish War of Independence.",
      "date": "1921-07-11"
    },
    {
      "headline": "Anglo-Irish Treaty signed",
      "text": "On December 6, 1921, the Anglo-Irish Treaty was signed, leading to the establishment of the Irish Free State and ending the war.",
      "date": "1921-12-06"
    },
    {
      "headline": "Ratification of the Anglo-Irish Treaty",
      "text": "In January 1922, the Anglo-Irish Treaty was ratified by the Dáil, leading to the creation of the Irish Free State.",
      "date": "1922-01"
    }
  ]
}

