{
  "timeline": [
    {
      "headline": "Foundation of the Knights Hospitaller",
      "text": "The Knights Hospitaller were founded in the 12th century in the crusader Kingdom of Jerusalem. The order was established to provide care for sick, poor, or injured pilgrims to the Holy Land.",
      "date": "1100"
    },
    {
      "headline": "Headquarters in Jerusalem",
      "text": "The Knights Hospitaller established their headquarters in Jerusalem, where they operated a hospital for pilgrims and participated in military activities during the Crusades.",
      "date": "1100"
    },
    {
      "headline": "Relocation to Cyprus",
      "text": "After the fall of Acre in 1291, the Knights Hospitaller moved their headquarters to Kolossi Castle in Cyprus, where they remained until 1310.",
      "date": "1302"
    },
    {
      "headline": "Establishment in Rhodes",
      "text": "In 1310, the Knights Hospitaller established their headquarters on the island of Rhodes. They fortified the island and became a significant naval power in the eastern Mediterranean.",
      "date": "1310"
    },
    {
      "headline": "Siege of Rhodes",
      "text": "The Knights Hospitaller successfully defended Rhodes against a siege by the Sultan of Egypt in 1444 and again against the Ottoman Empire in 1480.",
      "date": "1444"
    },
    {
      "headline": "Fall of Rhodes",
      "text": "In 1522, the Knights Hospitaller were forced to surrender Rhodes to the Ottoman Empire after a six-month siege.",
      "date": "1522"
    },
    {
      "headline": "Settlement in Malta",
      "text": "In 1530, the Knights Hospitaller were granted the islands of Malta and Gozo by Charles V, Holy Roman Emperor, establishing a new base of operations.",
      "date": "1530"
    },
    {
      "headline": "The Great Siege of Malta",
      "text": "In 1565, the Knights Hospitaller successfully defended Malta against a massive siege by the Ottoman Empire, solidifying their control over the island.",
      "date": "1565"
    },
    {
      "headline": "Loss of Malta",
      "text": "In 1798, Napoleon Bonaparte captured Malta during his campaign in the Mediterranean, forcing the Knights Hospitaller to leave the island.",
