{
  "timeline": [
    {
      "headline": "Beer Hall Putsch Begins",
      "text": "On November 8, 1923, Adolf Hitler and his followers attempted to overthrow the Weimar Republic by initiating the Beer Hall Putsch in Munich, Bavaria.",
      "date": "1923-11-08"
    },
    {
      "headline": "March on the Feldherrnhalle",
      "text": "On November 9, 1923, approximately two thousand Nazis marched on the Feldherrnhalle in Munich's city center, aiming to seize power.",
      "date": "1923-11-09"
    },
    {
      "headline": "Confrontation with Police",
      "text": "During the march on November 9, 1923, the Nazis were confronted by a police cordon, resulting in a violent clash.",
      "date": "1923-11-09"
    },
    {
      "headline": "Casualties of the Putsch",
      "text": "The confrontation on November 9, 1923, led to the deaths of 15 Nazis, four police officers, and one bystander.",
      "date": "1923-11-09"
    },
    {
      "headline": "Hitler's Arrest",
      "text": "Following the failed coup, Adolf Hitler was arrested on November 11, 1923, and subsequently charged with treason.",
      "date": "1923-11-11"
    },
    {
      "headline": "Trial and Imprisonment",
      "text": "In 1924, Adolf Hitler was tried for treason, found guilty, and sentenced to five years in Landsberg Prison, although he served only nine months.",
      "date": "1924"
    },
    {
      "headline": "Publication of Mein Kampf",
      "text": "While imprisoned, Hitler wrote 'Mein Kampf,' which was published in two volumes in 1925 and 1926, outlining his ideology and future plans for Germany.",
      "date": "1925"
    }
  ]
}

