{
  "timeline": [
    {
      "headline": "Black Thursday",
      "text": "On October 24, 1929, known as 'Black Thursday', a record 12.9 million shares were traded on the New York Stock Exchange (NYSE) in a single day, marking the beginning of the Wall Street Crash of 1929.",
      "date": "1929-10-24"
    },
    {
      "headline": "Black Monday",
      "text": "On October 28, 1929, known as 'Black Monday', the stock market continued to decline sharply, with the Dow Jones Industrial Average dropping 12.8%.",
      "date": "1929-10-28"
    },
    {
      "headline": "Black Tuesday",
      "text": "On October 29, 1929, known as 'Black Tuesday', about 16.4 million shares were traded on the NYSE, and the market suffered a significant loss, marking one of the most devastating days in stock market history.",
      "date": "1929-10-29"
    },
    {
      "headline": "Market Stabilization Efforts",
      "text": "In early November 1929, efforts were made to stabilize the market, but confidence continued to erode, and the market continued to decline.",
      "date": "1929-11"
    },
    {
      "headline": "End of the Crash",
      "text": "By mid-November 1929, the stock market had lost approximately half of its value compared to its peak in September 1929, marking the end of the initial crash phase.",
      "date": "1929-11-15"
    },
    {
      "headline": "Beginning of the Great Depression",
      "text": "The Wall Street Crash of 1929 marked the beginning of the worldwide Great Depression, which lasted until 1939, profoundly affecting economies and societies around the globe.",
      "date": "1929"
    }
  ]
}

