{
  "timeline": [
    {
      "headline": "Founding of OPEC",
      "text": "OPEC was founded on 14 September 1960 in Baghdad by the first five members: Iran, Iraq, Kuwait, Saudi Arabia, and Venezuela.",
      "date": "1960-09-14"
    },
    {
      "headline": "First OPEC Conference",
      "text": "The first OPEC conference was held in Baghdad from 10 to 14 September 1960, where the organization was officially established.",
      "date": "1960-09-10"
    },
    {
      "headline": "First OPEC Headquarters",
      "text": "OPEC established its first headquarters in Geneva, Switzerland, in 1961.",
      "date": "1961"
    },
    {
      "headline": "Relocation of Headquarters to Vienna",
      "text": "In 1965, OPEC moved its headquarters from Geneva to Vienna, Austria, where it remains to this day.",
      "date": "1965"
    },
    {
      "headline": "Oil Embargo of 1973",
      "text": "In October 1973, OPEC imposed an oil embargo against countries perceived as supporting Israel during the Yom Kippur War, leading to a global oil crisis.",
      "date": "1973-10"
    },
    {
      "headline": "OPEC's Expansion",
      "text": "Throughout the 1970s and 1980s, OPEC expanded its membership to include countries such as Algeria, Nigeria, Ecuador, and Gabon.",
      "date": "1970"
    },
    {
      "headline": "OPEC's Influence in the 1980s",
      "text": "During the 1980s, OPEC's influence fluctuated due to internal disagreements and external pressures, including the rise of non-OPEC oil producers.",
      "date": "1980"
    },
    {
      "headline": "Oil Price Collapse of 1986",
      "text": "In 1986, oil prices collapsed due to a combination of increased production by non-OPEC countries and internal disagreements within OPEC.",
      "date": "1986"
    },
    {
      "headline": "OPEC's Role in the 1990s",
      "text": "In the 1990s, OPEC continued to play a significant role in the global oil market, adjusting production levels to stabilize prices.",
      "date": "1990"
    },
    {
      "headline": "OPEC's Response to 2008 Financial Crisis",
      "text": "In response to the 2008 global financial crisis, OPEC cut oil production to stabilize falling prices.",
      "date": "2008"
    },
    {
      "headline": "OPEC and Non-OPEC Cooperation",
      "text": "In 2016, OPEC and non-OPEC countries, including Russia, agreed to cooperate in cutting oil production to address oversupply and low prices.",
      "date": "2016"
    },
    {
      "headline": "OPEC's Current Membership",
      "text": "As of 2022, OPEC comprises 12 member countries and accounts for 38 percent of global oil production.",
      "date": "2022"
    }
  ]
}

