      "headline": "Circumnavigation of the Globe",
      "text": "On December 13, 1577, Drake set sail from Plymouth on an expedition that would become the first English circumnavigation of the globe, completed in 1580.",
      "date": "1577-12-13"
    },
    {
      "headline": "Return to England",
      "text": "Drake returned to England on September 26, 1580, after successfully circumnavigating the globe.",
      "date": "1580-09-26"
    },
    {
      "headline": "Knighted by Queen Elizabeth I",
      "text": "On April 4, 1581, Queen Elizabeth I knighted Francis Drake aboard his ship, the Golden Hind, in Deptford.",
      "date": "1581-04-04"
    },
    {
      "headline": "Mayor of Plymouth",
      "text": "In 1581, Drake was elected Mayor of Plymouth, serving in this role for a year.",
      "date": "1581"
    },
    {
      "headline": "Role in the Spanish Armada",
      "text": "In 1588, Drake served as vice-admiral in the English fleet that defeated the Spanish Armada.",
      "date": "1588"
    },
    {
      "headline": "Final Expedition",
      "text": "In 1595, Drake embarked on his final expedition to the West Indies, which ended in failure.",
      "date": "1595"
    },
    {
      "headline": "Death of Francis Drake",
      "text": "Francis Drake died of dysentery on January 28, 1596, off the coast of Portobelo, Panama.",
      "date": "1596-01-28"
    }
  ]
