  "timeline": [
    {
      "headline": "Discovery of Stainless Steel",
      "text": "In 1913, Harry Brearley, a metallurgist from Sheffield, England, discovered stainless steel while seeking a corrosion-resistant alloy for gun barrels. He found that adding chromium to low carbon steel gave it stain resistance.",
      "date": "1913"
    },
    {
      "headline": "First Patent for Stainless Steel",
      "text": "In 1915, the first patent for stainless steel was granted to Harry Brearley in the United States, marking the beginning of its commercial production and use.",
      "date": "1915"
    },
    {
      "headline": "Introduction of Austenitic Stainless Steel",
      "text": "In 1924, W. H. Hatfield developed austenitic stainless steel, which contains 18% chromium and 8% nickel, known as 18/8 stainless steel. This became one of the most common types of stainless steel.",
      "date": "1924"
    },
    {
      "headline": "Development of Ferritic Stainless Steel",
      "text": "In the 1930s, ferritic stainless steels were developed, which are chromium-based and contain little to no nickel, offering good corrosion resistance and formability.",
      "date": "1930"
    },
    {
      "headline": "Introduction of Martensitic Stainless Steel",
      "text": "Martensitic stainless steels were developed in the 1930s, characterized by their high strength and hardness, making them suitable for cutlery and surgical instruments.",
      "date": "1930"
    },
    {
      "headline": "Invention of Duplex Stainless Steel",
      "text": "In the 1930s, duplex stainless steels were invented, combining the properties of austenitic and ferritic stainless steels, offering higher strength and resistance to stress corrosion cracking.",
      "date": "1930"
    },
    {
      "headline": "Commercial Production of Stainless Steel",
      "text": "By the 1950s, stainless steel was being produced commercially on a large scale, with various grades developed for different industrial applications.",
      "date": "1950"
    },
    {
      "headline": "Advancements in Stainless Steel Technology",
      "text": "In the late 20th century, advancements in stainless steel technology led to the development of super austenitic and super duplex stainless steels, offering enhanced corrosion resistance and strength.",
      "date": "1980"
    }
  ]
}

