      "headline": "Qing Dynasty Establishment",
      "text": "In 1644, the Manchu people from Manchuria established the Qing Dynasty, which ruled China until 1912.",
      "date": "1644"
    },
    {
      "headline": "Treaty of Nerchinsk",
      "text": "In 1689, the Treaty of Nerchinsk was signed between the Qing Dynasty and the Russian Empire, establishing borders between the two empires in the region of Manchuria.",
      "date": "1689"
    },
    {
      "headline": "Amur Annexation",
      "text": "Between 1858 and 1860, the Qing Dynasty ceded territories in Outer Manchuria to the Russian Empire through the Treaty of Aigun and the Treaty of Peking.",
      "date": "1858"
    },
    {
      "headline": "Mukden Incident",
      "text": "On September 18, 1931, the Mukden Incident occurred, leading to the Japanese invasion of Manchuria and the establishment of the puppet state of Manchukuo.",
      "date": "1931-09-18"
    },
    {
      "headline": "Establishment of Manchukuo",
      "text": "In 1932, Japan established the puppet state of Manchukuo in Manchuria, with the last Qing emperor, Puyi, as its nominal ruler.",
      "date": "1932"
    },
    {
      "headline": "Soviet Invasion of Manchuria",
      "text": "In August 1945, the Soviet Union invaded Manchuria, defeating Japanese forces and contributing to the end of World War II.",
      "date": "1945-08"
    },
    {
      "headline": "Return to Chinese Control",
      "text": "After World War II, Manchuria was returned to Chinese control, and the region became a significant industrial base for the People's Republic of China.",
      "date": "1945"
    }
  ]
}

