{
  "timeline": [
    {
      "headline": "First Recorded Submarine Concept",
      "text": "In 1578, Englishman William Bourne designed one of the first recorded concepts of a submarine, a completely enclosed boat that could be submerged and rowed beneath the surface.",
      "date": "1578"
    },
    {
      "headline": "First Working Submarine",
      "text": "In 1620, Cornelis Drebbel, a Dutch engineer working for the English Royal Navy, built the first working submarine. It was propelled by oars and could remain submerged for several hours.",
      "date": "1620"
    },
    {
      "headline": "Turtle Submarine",
      "text": "In 1775, American inventor David Bushnell built the Turtle, the first submarine used in combat. It was used during the American Revolutionary War to attempt to attach explosives to British ships.",
      "date": "1775"
    },
    {
      "headline": "Nautilus Submarine",
      "text": "In 1800, American inventor Robert Fulton built the Nautilus, one of the first practical submarines. It was tested in France and featured a collapsible mast and sail for surface propulsion.",
      "date": "1800"
    },
    {
      "headline": "CSS Hunley",
      "text": "In 1864, the Confederate submarine CSS Hunley became the first submarine to sink an enemy warship, the USS Housatonic, during the American Civil War.",
      "date": "1864"
    },
    {
      "headline": "Holland VI",
      "text": "In 1897, John Philip Holland designed and built the Holland VI, which became the first modern submarine commissioned by the U.S. Navy as USS Holland (SS-1) in 1900.",
      "date": "1897"
    },
    {
      "headline": "World War I Submarine Warfare",
      "text": "During World War I (1914-1918), submarines were used extensively by Germany, particularly the U-boats, which targeted Allied shipping in the Atlantic Ocean.",
      "date": "1914"
    },
    {
      "headline": "Nuclear Submarine",
      "text": "In 1954, the USS Nautilus was launched as the world's first operational nuclear-powered submarine, marking a significant advancement in submarine technology.",
      "date": "1954"
    },
    {
      "headline": "Deep-Sea Exploration",
      "text": "In 1960, the bathyscaphe Trieste, a deep-diving research submarine, reached the Challenger Deep in the Mariana Trench, the deepest known point in the Earth's oceans.",
      "date": "1960"
    }
  ]
}

