{
  "timeline": [
    {
      "headline": "Conditional Women's Suffrage in Sweden",
      "text": "During the Age of Liberty from 1718 to 1772, women in Sweden were allowed to vote under certain conditions. This period marked one of the earliest instances of women's suffrage in Europe.",
      "date": "1718"
    },
    {
      "headline": "Women's Suffrage in New Jersey",
      "text": "In 1776, New Jersey's state constitution granted voting rights to all inhabitants who met certain property requirements, which included some women. However, this right was rescinded in 1807.",
      "date": "1776"
    },
    {
      "headline": "Seneca Falls Convention",
      "text": "The first women's rights convention was held in Seneca Falls, New York, in July 1848. It marked the beginning of the organized women's suffrage movement in the United States.",
      "date": "1848-07"
    },
    {
      "headline": "Wyoming Grants Women's Suffrage",
      "text": "In 1869, the Wyoming Territory granted women the right to vote, becoming the first U.S. territory or state to do so.",
      "date": "1869"
    },
    {
      "headline": "New Zealand Grants Women's Suffrage",
      "text": "On September 19, 1893, New Zealand became the first self-governing country to grant all women the right to vote in parliamentary elections.",
      "date": "1893-09-19"
    },
    {
      "headline": "Australian Women Gain the Right to Vote",
      "text": "In 1902, the Commonwealth Franchise Act granted most women in Australia the right to vote and stand for election at the federal level.",
      "date": "1902"
    },
    {
      "headline": "Finnish Women Gain Full Political Rights",
      "text": "In 1906, Finland became the first European country to grant women both the right to vote and to stand for election.",
      "date": "1906"
    },
    {
      "headline": "British Women Over 30 Gain the Vote",
      "text": "The Representation of the People Act 1918 granted voting rights to women over the age of 30 in the United Kingdom.",
      "date": "1918"
    },
    {
      "headline": "19th Amendment to the U.S. Constitution",
      "text": "On August 18, 1920, the 19th Amendment was ratified, granting American women the right to vote.",
      "date": "1920-08-18"
    },
    {
      "headline": "French Women Gain the Right to Vote",
      "text": "In 1944, French women were granted the right to vote, and they participated in their first election in 1945.",
      "date": "1944"
    },
    {
      "headline": "Swiss Women Gain the Right to Vote",
      "text": "In 1971, Swiss women were granted the right to vote in federal elections.",
      "date": "1971"
    },
    {
      "headline": "Saudi Arabian Women Gain the Right to Vote",
      "text": "In 2015, women in Saudi Arabia were allowed to vote and run for office in municipal elections for the first time.",
      "date": "2015"
    }
  ]
}

