    {
      "headline": "Emergence of Emo",
      "text": "Emo emerged as a style of hardcore punk and post-hardcore from the mid-1980s Washington, D.C. hardcore scene, where it was known as emotional hardcore or emocore. Bands like Rites of Spring and Embrace pioneered the genre.",
      "date": "1980"
    },
    {
      "headline": "Rites of Spring Formation",
      "text": "Rites of Spring, one of the pioneering bands of the emo genre, formed in 1984 in Washington, D.C.",
      "date": "1984"
    },
    {
      "headline": "Embrace Formation",
      "text": "Embrace, another key band in the development of emo, formed in 1985 in Washington, D.C.",
      "date": "1985"
    },
    {
      "headline": "Emo's Evolution in the 1990s",
      "text": "In the early-to-mid 1990s, emo was adopted and reinvented by alternative rock, indie rock, punk rock, and pop-punk bands, including Sunny Day Real Estate, Jawbreaker, Cap'n Jazz, and Jimmy Eat World.",
      "date": "1990"
    },
    {
      "headline": "Midwest Emo Emergence",
      "text": "By the mid-1990s, bands like Braid, the Promise Ring, and the Get Up Kids emerged from the Midwest emo scene, and several independent record labels began to specialize in the genre.",
      "date": "1995"
    },
    {
      "headline": "Screamo Emergence",
      "text": "Screamo, a more aggressive style of emo using screamed vocals, emerged in the mid-1990s, pioneered by San Diego bands Heroin and Antioch Arrow.",
      "date": "1995"
    },
    {
      "headline": "Mainstream Success of Screamo",
      "text": "Screamo achieved mainstream success in the 2000s with bands like Hawthorne Heights, Silverstein, Story of the Year, Thursday, the Used, and Underoath.",
      "date": "2000"
    }
  ]
}

