{
  "timeline": [
    {
      "headline": "Introduction of Kanji to Japan",
      "text": "Kanji were introduced to Japan from China around the 5th century CE. These logographic characters became a major part of the Japanese writing system.",
      "date": "0500"
    },
    {
      "headline": "Development of Hiragana and Katakana",
      "text": "During the Heian period (794-1185), the Japanese developed the syllabic scripts of hiragana and katakana, derived from kanji, to complement the use of kanji in writing.",
      "date": "0800"
    },
    {
      "headline": "Creation of Kokuji",
      "text": "Some kanji characters were invented in Japan, known as kokuji, by constructing character components derived from other Chinese characters.",
      "date": "1000"
    },
    {
      "headline": "Meiji Restoration and Kanji Simplification",
      "text": "After the Meiji Restoration in 1868, Japan began efforts to simplify kanji, similar to China's simplification efforts, to increase literacy among the general public.",
      "date": "1868"
    },
    {
      "headline": "Publication of Character Lists",
      "text": "Since the 1920s, the Japanese government has published character lists periodically to help direct the education of its citizenry through the myriad Chinese characters that exist.",
      "date": "1920"
    },
    {
      "headline": "Establishment of Jōyō Kanji",
      "text": "In 1981, the Japanese government established the Jōyō Kanji list, which includes 2,136 characters for use in daily life.",
      "date": "1981"
    },
    {
      "headline": "Revision of Jōyō Kanji",
      "text": "The Jōyō Kanji list was revised in 2010, adding 196 characters and removing 5, bringing the total to 2,136 characters.",
      "date": "2010"
    }
  ]
}

