{
  "timeline": [
    {
      "headline": "Birth of John Wesley",
      "text": "John Wesley, a key figure in the founding of Methodism, was born on June 28, 1703, in Epworth, England.",
      "date": "1703-06-28"
    },
    {
      "headline": "Birth of Charles Wesley",
      "text": "Charles Wesley, brother of John Wesley and co-founder of Methodism, was born on December 18, 1707, in Epworth, England.",
      "date": "1707-12-18"
    },
    {
      "headline": "Holy Club Formation",
      "text": "In 1729, John Wesley, Charles Wesley, and George Whitefield formed the 'Holy Club' at Oxford University, which was the precursor to the Methodist movement.",
      "date": "1729"
    },
    {
      "headline": "John Wesley's Aldersgate Experience",
      "text": "On May 24, 1738, John Wesley experienced a profound spiritual awakening at a meeting on Aldersgate Street in London, which became a pivotal moment in the Methodist movement.",
      "date": "1738-05-24"
    },
    {
      "headline": "First Methodist Society",
      "text": "In 1739, John Wesley founded the first Methodist society in London, marking the beginning of organized Methodism.",
      "date": "1739"
    },
    {
      "headline": "George Whitefield's Preaching Tours",
      "text": "George Whitefield began his preaching tours in the American colonies in 1739, significantly contributing to the spread of Methodism.",
      "date": "1739"
    },
    {
      "headline": "Methodist Conference",
      "text": "The first Methodist Conference was held in 1744, establishing a formal structure for the movement.",
      "date": "1744"
    },
    {
      "headline": "Death of George Whitefield",
      "text": "George Whitefield, a prominent early leader in the Methodist movement, died on September 30, 1770.",
      "date": "1770-09-30"
    },
    {
      "headline": "Death of Charles Wesley",
      "text": "Charles Wesley, co-founder of Methodism and prolific hymn writer, died on March 29, 1788.",
      "date": "1788-03-29"
    },
    {
      "headline": "Death of John Wesley",
      "text": "John Wesley, the principal founder of Methodism, died on March 2, 1791, in London, England.",
      "date": "1791-03-02"
    },
    {
      "headline": "Methodist Episcopal Church Formation",
      "text": "In 1784, the Methodist Episcopal Church was formed in the United States, marking the formal separation of Methodism from the Church of England.",
      "date": "1784"
    },
    {
      "headline": "Methodism's Global Expansion",
      "text": "Throughout the 19th century, Methodism expanded globally through vigorous missionary work, establishing a significant presence in the British Empire, the United States, and beyond.",
      "date": "1800"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Origins of Swahili Language",
      "text": "The Swahili language originated as a Bantu language spoken by the Swahili people along the East African coast. It developed through interactions with Arabic-speaking traders, incorporating many Arabic loanwords.",
      "date": "-1000"
    },
    {
      "headline": "Swahili as a Trade Language",
      "text": "By the 10th century, Swahili had become a lingua franca along the East African coast, facilitating trade between African, Arab, Persian, and Indian merchants.",
      "date": "0900"
    },
    {
      "headline": "Swahili Script Development",
      "text": "In the 18th century, Swahili began to be written in the Arabic script, known as Ajami, due to the influence of Arab traders and Islamic scholars.",
      "date": "1700"
    },
    {
      "headline": "German Colonization and Swahili",
      "text": "During the late 19th century, German colonizers in East Africa adopted Swahili as the administrative language in their colonies, promoting its use in education and governance.",
      "date": "1885"
    },
    {
      "headline": "British Influence on Swahili",
      "text": "In the early 20th century, the British continued to use Swahili as an administrative language in their East African colonies, further standardizing it and promoting its use in schools.",
      "date": "1920"
    },
    {
      "headline": "Swahili as a National Language",
      "text": "After gaining independence in the 1960s, Tanzania and Kenya adopted Swahili as a national language, promoting its use in government, education, and media.",
      "date": "1960"
    },
    {
      "headline": "Swahili in the African Union",
      "text": "In 2004, Swahili was adopted as one of the official languages of the African Union, recognizing its importance as a widely spoken language across the continent.",
      "date": "2004"
    }
  ]
}

