    },
    {
      "headline": "Establishment of the University of Adelaide",
      "text": "The University of Adelaide was established in 1874, making it the third oldest university in Australia.",
      "date": "1874"
    },
    {
      "headline": "Federation of Australia",
      "text": "In 1901, Adelaide became part of the Commonwealth of Australia when the six colonies federated to form the nation.",
      "date": "1901"
