    },
    {
      "headline": "Development of Modern Martial Arts",
      "text": "A subset of techniques from certain styles of jujutsu were used to develop many modern martial arts and combat sports, such as judo, aikido, sambo, Brazilian jiu-jitsu, ARB, and mixed martial arts.",
      "date": "1882"
    },
    {
      "headline": "Foundation of Judo",
      "text": "Jigoro Kano founded judo in 1882, which was derived from jujutsu. Judo emphasized throwing techniques and was developed as a safer and more sportive form of jujutsu.",
      "date": "1882"
    },
    {
      "headline": "Creation of Aikido",
      "text": "Aikido was created by Morihei Ueshiba in the early 20th century. It was influenced by jujutsu and focused on harmony and blending with the opponent's movements.",
      "date": "1920"
    },
    {
      "headline": "Emergence of Brazilian Jiu-Jitsu",
      "text": "Brazilian jiu-jitsu emerged in the early 20th century, developed by the Gracie family in Brazil. It was based on Kodokan judo ground fighting (newaza) fundamentals that were taught to Carlos Gracie by Mitsuyo Maeda.",
      "date": "1925"
    },
    {
      "headline": "Introduction of Jujutsu in Mixed Martial Arts",
      "text": "Jujutsu techniques became a fundamental part of mixed martial arts (MMA), particularly through the influence of Brazilian jiu-jitsu, which gained prominence in the 1990s.",
      "date": "1993"
    }
  ]
}

