{
  "timeline": [
    {
      "headline": "Battle of Covadonga",
      "text": "The Battle of Covadonga, traditionally dated to 722, marked the first significant Christian victory over the Muslim forces in the Iberian Peninsula. This battle is considered the beginning of the Reconquista.",
      "date": "0722"
    },
    {
      "headline": "Establishment of the Kingdom of Asturias",
      "text": "In the early 8th century, following the Battle of Covadonga, the Kingdom of Asturias was established as a Christian stronghold in the north of the Iberian Peninsula.",
      "date": "0718"
    },
    {
      "headline": "Battle of Tours",
      "text": "In 732, Charles Martel defeated an invading Muslim army at the Battle of Tours in France, halting the northward expansion of Islam in Western Europe.",
      "date": "0732"
    },
    {
      "headline": "Battle of Roncevaux Pass",
      "text": "In 778, the Battle of Roncevaux Pass occurred, where Basque forces ambushed Charlemagne's army, marking a significant event in the context of Christian-Muslim conflicts in the region.",
      "date": "0778"
    },
    {
      "headline": "Battle of Clavijo",
      "text": "The legendary Battle of Clavijo, dated to 844, is said to have been a significant Christian victory against Muslim forces, although its historicity is debated.",
      "date": "0844"
    },
    {
      "headline": "Battle of Simancas",
      "text": "In 939, the Battle of Simancas took place, where the Christian forces of King Ramiro II of León defeated the Muslim army of Abd al-Rahman III.",
      "date": "0939"
    },
    {
      "headline": "Fall of Toledo",
      "text": "In 1085, Alfonso VI of León and Castile captured Toledo, a major Muslim city, marking a significant turning point in the Reconquista.",
      "date": "1085"
    },
    {
      "headline": "Battle of Sagrajas",
      "text": "In 1086, the Battle of Sagrajas occurred, where the Almoravid army defeated the forces of Alfonso VI, temporarily halting the Christian advance.",
      "date": "1086"
    },
    {
      "headline": "Battle of Las Navas de Tolosa",
      "text": "In 1212, the Battle of Las Navas de Tolosa was a decisive Christian victory over the Almohad Caliphate, significantly weakening Muslim power in the Iberian Peninsula.",
      "date": "1212"
    },
    {
      "headline": "Conquest of Córdoba",
      "text": "In 1236, Ferdinand III of Castile captured Córdoba, an important cultural and political center of Muslim Spain.",
      "date": "1236"
    },
    {
      "headline": "Conquest of Seville",
      "text": "In 1248, Ferdinand III of Castile captured Seville, further consolidating Christian control over the southern part of the Iberian Peninsula.",
      "date": "1248"
    },
    {
      "headline": "Treaty of Granada",
      "text": "In 1491, the Treaty of Granada was signed, setting the terms for the surrender of the Nasrid Kingdom of Granada to the Catholic Monarchs.",
      "date": "1491"
    },
    {
      "headline": "Fall of Granada",
      "text": "On January 2, 1492, the city of Granada surrendered to the Catholic Monarchs, Ferdinand II of Aragon and Isabella I of Castile, marking the end of the Reconquista.",
      "date": "1492-01-02"
    }
  ]
}

