{
  "timeline": [
    {
      "headline": "First Recorded Execution in the American Colonies",
      "text": "In 1608, Captain George Kendall was executed in the Jamestown colony of Virginia, marking the first recorded execution in the American colonies.",
      "date": "1608"
    },
    {
      "headline": "First Legal Execution in the United States",
      "text": "On June 25, 1630, John Billington was executed in Plymouth Colony for murder, marking the first legal execution in what would become the United States.",
      "date": "1630-06-25"
    },
    {
      "headline": "Pennsylvania Abolishes Public Executions",
      "text": "In 1834, Pennsylvania became the first state to move executions away from the public eye and conduct them within correctional facilities.",
      "date": "1834"
    },
    {
      "headline": "Michigan Abolishes Capital Punishment",
      "text": "In 1846, Michigan became the first English-speaking government in the world to abolish the death penalty for all crimes except treason.",
      "date": "1846"
    },
    {
      "headline": "First Use of the Electric Chair",
      "text": "On August 6, 1890, William Kemmler was executed in New York, marking the first use of the electric chair as a method of execution.",
      "date": "1890-08-06"
    },
    {
      "headline": "Furman v. Georgia",
      "text": "On June 29, 1972, the U.S. Supreme Court ruled in Furman v. Georgia that the death penalty, as administered, constituted cruel and unusual punishment, effectively halting executions nationwide.",
      "date": "1972-06-29"
    },
    {
      "headline": "Gregg v. Georgia",
      "text": "On July 2, 1976, the U.S. Supreme Court decision in Gregg v. Georgia reinstated the death penalty under a revised sentencing procedure.",
      "date": "1976-07-02"
    },
    {
      "headline": "First Execution After Reinstatement",
      "text": "On January 17, 1977, Gary Gilmore was executed by firing squad in Utah, marking the first execution in the United States after the reinstatement of the death penalty.",
      "date": "1977-01-17"
    },
    {
      "headline": "Introduction of Lethal Injection",
      "text": "On December 7, 1982, Charles Brooks Jr. was executed in Texas, becoming the first person to be executed by lethal injection.",
      "date": "1982-12-07"
    },
    {
      "headline": "Roper v. Simmons",
      "text": "On March 1, 2005, the U.S. Supreme Court ruled in Roper v. Simmons that it is unconstitutional to impose capital punishment for crimes committed while under the age of 18.",
      "date": "2005-03-01"
    },
    {
      "headline": "Baze v. Rees",
      "text": "On April 16, 2008, the U.S. Supreme Court upheld the constitutionality of a particular method of lethal injection in Baze v. Rees.",
      "date": "2008-04-16"
    },
    {
      "headline": "Federal Executions Resume",
      "text": "In July 2020, the federal government resumed executions after a 17-year hiatus, with the execution of Daniel Lewis Lee.",
      "date": "2020-07"
    }
  ]
}

