{
  "timeline": [
    {
      "headline": "Birth of Saint Patrick",
      "text": "Saint Patrick was born in Roman Britain. The exact date of his birth is not known, but it is believed to be around the late 4th century, circa 385.",
      "date": "0385"
    },
    {
      "headline": "Captured by Irish Raiders",
      "text": "At the age of 16, around 401, Patrick was captured by Irish raiders and taken as a slave to Ireland.",
      "date": "0401"
    },
    {
      "headline": "Escape from Slavery",
      "text": "After six years of captivity, Patrick escaped from slavery in Ireland and returned to his family in Britain, around 407.",
      "date": "0407"
    },
    {
      "headline": "Return to Ireland as a Missionary",
      "text": "Patrick returned to Ireland as a Christian missionary around 432, after having a vision that called him to convert the Irish to Christianity.",
      "date": "0432"
    },
    {
      "headline": "Consecration as Bishop",
      "text": "Patrick was consecrated as a bishop in Ireland, although the exact date is uncertain, it is believed to have been shortly after his return as a missionary.",
      "date": "0432"
    },
    {
      "headline": "Establishment of Churches and Monasteries",
      "text": "Throughout his mission, Patrick established many churches and monasteries across Ireland, significantly contributing to the spread of Christianity in the region.",
      "date": "0432-0461"
    },
    {
      "headline": "Death of Saint Patrick",
      "text": "Saint Patrick died on March 17, 461. This date is now celebrated as Saint Patrick's Day.",
      "date": "0461-03-17"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Construction Begins",
      "text": "Construction of the Large Hadron Collider (LHC) began in 1998. It was built by the European Organization for Nuclear Research (CERN) with collaboration from over 10,000 scientists and hundreds of universities and laboratories across more than 100 countries.",
      "date": "1998"
    },
    {
      "headline": "LHC Construction Completed",
      "text": "The construction of the LHC was completed in 2008. The collider is located in a tunnel 27 kilometres in circumference and as deep as 175 metres beneath the France–Switzerland border near Geneva.",
      "date": "2008"
    },
    {
      "headline": "First Beam Circulation",
      "text": "On September 10, 2008, the first beam was successfully circulated through the LHC.",
      "date": "2008-09-10"
    },
    {
      "headline": "First High-Energy Collisions",
      "text": "The LHC achieved its first high-energy collisions on March 30, 2010, marking the beginning of its physics research program.",
      "date": "2010-03-30"
    },
    {
      "headline": "Discovery of Higgs Boson",
      "text": "On July 4, 2012, CERN announced the discovery of a new particle consistent with the Higgs boson, a fundamental particle predicted by the Standard Model of particle physics.",
      "date": "2012-07-04"
    },
    {
      "headline": "First Long Shutdown",
      "text": "The LHC underwent its first long shutdown from February 2013 to April 2015 for maintenance and upgrades.",
      "date": "2013-02"
    },
    {
      "headline": "Restart and Run 2",
      "text": "The LHC restarted in April 2015 after its first long shutdown, beginning its second run with increased collision energy.",
      "date": "2015-04"
    },
    {
      "headline": "Second Long Shutdown",
      "text": "The LHC entered its second long shutdown in December 2018 for further upgrades and maintenance.",
      "date": "2018-12"
    },
    {
      "headline": "Restart and Run 3",
      "text": "The LHC was scheduled to restart in 2022 for its third run, following the completion of the second long shutdown.",
      "date": "2022"
    }
  ]
}

{
