      "date": "1700"
    },
    {
      "headline": "Bourbons in Naples, Sicily, and Parma",
      "text": "Further branches of the House of Bourbon, descended from the Spanish Bourbons, held thrones in Naples, Sicily, and Parma during the 18th and 19th centuries.",
      "date": "1734"
