{
  "timeline": [
    {
      "headline": "Henry VIII's Act of Supremacy",
      "text": "In 1534, King Henry VIII of England passed the Act of Supremacy, declaring himself the Supreme Head of the Church of England, marking the beginning of Anglicanism as a distinct tradition separate from the Roman Catholic Church.",
      "date": "1534"
    },
    {
      "headline": "Publication of the Book of Common Prayer",
      "text": "In 1549, the first Book of Common Prayer was published under the direction of Thomas Cranmer. It was the first prayer book to include the complete forms of service for daily and Sunday worship in English.",
      "date": "1549"
    },
    {
      "headline": "Elizabethan Religious Settlement",
      "text": "In 1559, the Elizabethan Religious Settlement was established under Queen Elizabeth I, which defined the Church of England's doctrine and practices, balancing between Roman Catholicism and Protestant Reformation ideals.",
      "date": "1559"
    },
    {
      "headline": "The Thirty-Nine Articles",
      "text": "In 1571, the Thirty-Nine Articles were established, outlining the doctrinal foundation of the Church of England and serving as a defining statement of Anglican beliefs.",
      "date": "1571"
    },
    {
      "headline": "The Lambeth Conference",
      "text": "In 1867, the first Lambeth Conference was held, bringing together bishops from across the Anglican Communion to discuss issues of mutual concern, marking a significant step in the development of Anglican unity.",
      "date": "1867"
    },
    {
      "headline": "Establishment of the Anglican Consultative Council",
      "text": "In 1968, the Anglican Consultative Council was established to facilitate cooperation and dialogue among the provinces of the Anglican Communion.",
      "date": "1968"
    },
    {
      "headline": "Ordination of Women",
      "text": "In 1992, the Church of England voted to allow the ordination of women as priests, a significant change in Anglican practice.",
      "date": "1992"
    },
    {
      "headline": "Consecration of the First Female Bishop",
      "text": "In 2015, the Church of England consecrated its first female bishop, Libby Lane, marking a historic moment in the Anglican tradition.",
      "date": "2015"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of the Seljuk Empire",
      "text": "The Seljuk Empire was founded in 1037 by Tughril Beg, who established control over Khorasan, marking the beginning of the Seljuk rule.",
      "date": "1037"
    },
    {
      "headline": "Battle of Dandanaqan",
      "text": "In 1040, the Seljuks defeated the Ghaznavid Empire at the Battle of Dandanaqan, which solidified their control over Khorasan.",
      "date": "1040"
    },
    {
      "headline": "Capture of Baghdad",
      "text": "In 1055, Tughril Beg captured Baghdad, marking the Seljuk Empire's dominance over the Abbasid Caliphate and establishing the Seljuks as the protectors of the Caliphate.",
      "date": "1055"
    },
    {
      "headline": "Battle of Manzikert",
      "text": "The Seljuk Empire, under Alp Arslan, defeated the Byzantine Empire at the Battle of Manzikert in 1071, leading to the Seljuk conquest of much of Anatolia.",
      "date": "1071"
    },
    {
      "headline": "Death of Alp Arslan",
      "text": "Alp Arslan, the second sultan of the Seljuk Empire, died in 1072, succeeded by his son Malik Shah I.",
      "date": "1072"
    },
    {
      "headline": "Reign of Malik Shah I",
      "text": "Malik Shah I ruled from 1072 to 1092, during which the Seljuk Empire reached its greatest territorial extent and cultural achievements.",
      "date": "1072"
    },
    {
      "headline": "Death of Malik Shah I",
      "text": "Malik Shah I died in 1092, leading to a period of fragmentation and internal strife within the Seljuk Empire.",
      "date": "1092"
    },
    {
      "headline": "First Crusade",
      "text": "The First Crusade began in 1096, posing a significant challenge to Seljuk control in the Levant.",
      "date": "1096"
    },
    {
      "headline": "Battle of Didgori",
      "text": "In 1121, the Seljuk forces were defeated by the Kingdom of Georgia at the Battle of Didgori, marking a significant setback for the Seljuks in the Caucasus region.",
      "date": "1121"
    },
    {
      "headline": "End of Seljuk Rule in Persia",
      "text": "The Seljuk rule in Persia effectively ended in 1194 after the defeat by the Khwarezmian Empire.",
      "date": "1194"
    },
    {
      "headline": "End of the Seljuk Empire",
      "text": "The Seljuk Empire officially ended in 1308 with the fall of the Sultanate of Rum, the last remaining Seljuk state in Anatolia.",
      "date": "1308"
    }
  ]
}

