{
  "timeline": [
    {
      "headline": "Discovery of Malaria Parasite",
      "text": "In 1880, Charles Louis Alphonse Laveran, a French army surgeon working in Algeria, discovered the malaria parasite in the blood of a patient. This was the first time a protozoan was identified as causing disease in humans.",
      "date": "1880"
    },
    {
      "headline": "Identification of Mosquito Vector",
      "text": "In 1897, British doctor Ronald Ross discovered that malaria is transmitted by mosquitoes. He identified the Anopheles mosquito as the vector responsible for spreading the disease.",
      "date": "1897"
    },
    {
      "headline": "Development of Quinine",
      "text": "Quinine, derived from the bark of the cinchona tree, was used as a treatment for malaria as early as the 17th century. It became the standard treatment for malaria until the development of synthetic drugs.",
      "date": "1600"
    },
    {
      "headline": "Synthesis of Chloroquine",
      "text": "Chloroquine, a synthetic drug, was developed in the 1930s and became widely used as an antimalarial treatment during World War II.",
      "date": "1930"
    },
    {
      "headline": "Launch of Global Malaria Eradication Program",
      "text": "In 1955, the World Health Organization launched the Global Malaria Eradication Program, aiming to eliminate malaria worldwide through widespread use of DDT and antimalarial drugs.",
      "date": "1955"
    },
    {
      "headline": "Emergence of Drug Resistance",
      "text": "By the late 1960s, resistance to chloroquine and other antimalarial drugs began to emerge, complicating efforts to control the disease.",
      "date": "1960"
    },
    {
      "headline": "Introduction of Artemisinin-based Combination Therapies",
      "text": "In the 2000s, artemisinin-based combination therapies (ACTs) were introduced as the standard treatment for malaria, due to their effectiveness against drug-resistant strains.",
      "date": "2000"
    },
    {
      "headline": "Approval of First Malaria Vaccine",
      "text": "In 2021, the World Health Organization approved the first malaria vaccine, RTS,S/AS01 (Mosquirix), for use in children in areas with moderate to high transmission of Plasmodium falciparum malaria.",
      "date": "2021"
    }
  ]
}

