    {
      "headline": "End of World War II",
      "text": "World War II ended on September 2, 1945, but Onoda continued to fight, unaware of the war's conclusion.",
      "date": "1945-09-02"
    },
    {
      "headline": "Discovery by Norio Suzuki",
      "text": "In 1974, Norio Suzuki, a Japanese explorer, found Onoda on Lubang Island and informed him that the war had ended.",
      "date": "1974"
    },
    {
      "headline": "Formal Surrender",
      "text": "On March 9, 1974, Onoda formally surrendered to the Philippine authorities after receiving orders from his former commanding officer.",
      "date": "1974-03-09"
    },
    {
      "headline": "Return to Japan",
      "text": "Onoda returned to Japan on March 12, 1974, after nearly 30 years of holding out.",
      "date": "1974-03-12"
    },
    {
      "headline": "Publication of Memoir",
      "text": "In 1974, Onoda published his memoir, 'No Surrender: My Thirty-Year War,' detailing his experiences.",
      "date": "1974"
    },
    {
      "headline": "Move to Brazil",
      "text": "In 1975, Onoda moved to Brazil, where he became a cattle farmer.",
      "date": "1975"
    },
    {
      "headline": "Return to Japan and Establishment of Nature School",
      "text": "Onoda returned to Japan in 1984 and established a nature school for young people.",
      "date": "1984"
    },
    {
      "headline": "Death of Hiroo Onoda",
      "text": "Hiroo Onoda passed away on January 16, 2014, in Tokyo, Japan, at the age of 91.",
