      "headline": "Nobel Memorial Prize in Economic Sciences Established",
      "text": "The Nobel Memorial Prize in Economic Sciences was established in 1968 by the Sveriges Riksbank in memory of Alfred Nobel.",
      "date": "1968"
    },
    {
      "headline": "Publication of 'A Theory of Justice'",
      "text": "John Rawls published 'A Theory of Justice' in 1971, influencing economic thought on justice and fairness.",
      "date": "1971"
    },
    {
      "headline": "Publication of 'An Evolutionary Theory of Economic Change'",
      "text": "Richard Nelson and Sidney Winter published 'An Evolutionary Theory of Economic Change' in 1982, contributing to evolutionary economics.",
      "date": "1982"
    },
    {
      "headline": "Publication of 'Capital in the Twenty-First Century'",
      "text": "Thomas Piketty published 'Capital in the Twenty-First Century' in 2013, analyzing wealth and income inequality.",
      "date": "2013"
    }
  ]
}

