{
  "timeline": [
    {
      "headline": "Formation of Indian Armed Forces",
      "text": "The Indian Armed Forces were officially formed after India gained independence from British rule on August 15, 1947. This marked the beginning of the modern Indian military structure.",
      "date": "1947-08-15"
    },
    {
      "headline": "First Indo-Pakistani War",
      "text": "The first Indo-Pakistani War, also known as the First Kashmir War, took place between October 1947 and December 1948. It was fought between India and Pakistan over the princely state of Jammu and Kashmir.",
      "date": "1947-10"
    },
    {
      "headline": "Integration of Indian Armed Forces",
      "text": "In 1950, the Indian Armed Forces were integrated under the Ministry of Defence, Government of India, following the adoption of the Constitution of India on January 26, 1950.",
      "date": "1950-01-26"
    },
    {
      "headline": "Indo-China War",
      "text": "The Sino-Indian War, also known as the Indo-China War, occurred in 1962. It was a border conflict between China and India that resulted in a Chinese victory.",
      "date": "1962"
    },
    {
      "headline": "Second Indo-Pakistani War",
      "text": "The second Indo-Pakistani War, also known as the Second Kashmir War, took place in 1965. It was fought between India and Pakistan over the Kashmir region.",
      "date": "1965"
    },
    {
      "headline": "Indo-Pakistani War of 1971",
      "text": "The Indo-Pakistani War of 1971 was a military confrontation between India and Pakistan that occurred during the Bangladesh Liberation War. It resulted in the creation of Bangladesh.",
      "date": "1971"
    },
    {
      "headline": "Nuclear Tests at Pokhran",
      "text": "India conducted a series of nuclear tests at the Pokhran Test Range in May 1974, known as Operation Smiling Buddha, marking India's entry into the group of nuclear-armed nations.",
      "date": "1974-05"
    },
    {
      "headline": "Operation Blue Star",
      "text": "Operation Blue Star was a military operation carried out by the Indian Armed Forces in June 1984 to remove Sikh militants from the Golden Temple in Amritsar, Punjab.",
      "date": "1984-06"
    },
    {
      "headline": "Kargil War",
      "text": "The Kargil War was fought between India and Pakistan from May to July 1999 in the Kargil district of Jammu and Kashmir and elsewhere along the Line of Control (LoC).",
      "date": "1999-05"
    },
    {
      "headline": "Formation of Strategic Forces Command",
      "text": "The Strategic Forces Command was established in 2003 as part of India's Nuclear Command Authority to manage and administer the country's nuclear arsenal.",
      "date": "2003"
    },
    {
      "headline": "Establishment of Andaman and Nicobar Command",
      "text": "The Andaman and Nicobar Command, the first and only tri-service theater command of the Indian Armed Forces, was established in 2001 to safeguard India's strategic interests in the region.",
      "date": "2001"
    },
    {
      "headline": "Largest Volunteer Army",
      "text": "As of 2023, the Indian Armed Forces are recognized as having the world's largest volunteer army, with over 1.4 million active personnel.",
      "date": "2023"
    }
  ]
}

