{
  "timeline": [
    {
      "headline": "Origins of Ceviche",
      "text": "Ceviche is believed to have originated in the coastal regions of present-day Peru. The dish has ancient roots, with evidence suggesting that a form of ceviche was consumed by the Moche culture, which thrived along the northern coast of Peru around 2000 years ago.",
      "date": "-0001"
    },
    {
      "headline": "Spanish Influence",
      "text": "With the arrival of the Spanish in the 16th century, new ingredients such as citrus fruits were introduced to the Americas. These ingredients were incorporated into the traditional preparation of ceviche, evolving the dish into its modern form.",
      "date": "1500"
    },
    {
      "headline": "Ceviche in Peruvian Culture",
      "text": "Ceviche became a staple of Peruvian cuisine, with its preparation and consumption deeply embedded in the country's cultural identity. It is often served with side dishes such as sweet potato, corn, or avocado.",
      "date": "1900"
    },
    {
      "headline": "Recognition by UNESCO",
      "text": "In 2004, ceviche was recognized by UNESCO as an expression of Peruvian traditional cuisine and Intangible Cultural Heritage of Humanity, highlighting its cultural significance and historical roots.",
      "date": "2004"
    },
    {
      "headline": "Ceviche as a Flagship Dish",
      "text": "In Peru, ceviche is considered a flagship dish and cultural heritage, celebrated for its unique flavors and historical importance. It is a symbol of national pride and culinary tradition.",
      "date": "2000"
