    {
      "headline": "Publication of All Quiet on the Western Front",
      "text": "All Quiet on the Western Front was first published in German as 'Im Westen nichts Neues' on January 29, 1929. The novel was written by Erich Maria Remarque, a German veteran of World War I, and it describes the extreme physical and mental trauma experienced by German soldiers during the war.",
      "date": "1929-01-29"
    },
    {
      "headline": "English Translation Released",
      "text": "The English translation of All Quiet on the Western Front was released in the same year as the original German publication, 1929. The translation helped the novel reach a wider audience and contributed to its international acclaim.",
      "date": "1929"
    },
    {
      "headline": "Film Adaptation Released",
      "text": "The first film adaptation of All Quiet on the Western Front was released in 1930. Directed by Lewis Milestone, the film won the Academy Award for Best Picture and is considered one of the greatest anti-war films ever made.",
      "date": "1930"
    },
    {
      "headline": "Nazi Ban on the Novel",
      "text": "In 1933, the novel was banned in Nazi Germany. The regime viewed it as unpatriotic and subversive, and copies of the book were among those burned in the infamous book burnings of that year.",
      "date": "1933"
    },
    {
      "headline": "Television Adaptation",
      "text": "A television adaptation of All Quiet on the Western Front was released in 1979. This adaptation was directed by Delbert Mann and starred Richard Thomas and Ernest Borgnine.",
      "date": "1979"
    },
    {
      "headline": "Modern Film Adaptation",
      "text": "A modern film adaptation of All Quiet on the Western Front was released in 2022. This adaptation was directed by Edward Berger and brought the story to a new generation of viewers.",
      "date": "2022"
    }
  ]
}

{
  "timeline": [
