      "headline": "Expo 88",
      "text": "In 1988, Brisbane hosted World Expo 88, a World's Fair that celebrated the bicentenary of European settlement in Australia.",
      "date": "1988"
    },
    {
      "headline": "Queensland's First Female Premier",
      "text": "In 2007, Anna Bligh became Queensland's first female Premier.",
      "date": "2007"
