    {
      "headline": "Commissioning of the Georgia Guidestones",
      "text": "In June 1979, a man using the pseudonym R.C. Christian approached the Elberton Granite Finishing Company to commission the Georgia Guidestones. He claimed to represent a group of loyal Americans who wanted to offer guidance to humanity.",
      "date": "1979-06"
    },
    {
      "headline": "Construction of the Georgia Guidestones",
      "text": "The Georgia Guidestones were constructed and erected in Elbert County, Georgia. The monument was completed and unveiled on March 22, 1980.",
      "date": "1980-03-22"
    },
    {
      "headline": "Unveiling of the Georgia Guidestones",
      "text": "On March 22, 1980, the Georgia Guidestones were officially unveiled to the public. The monument featured inscriptions in eight modern languages and a shorter message in four ancient language scripts.",
      "date": "1980-03-22"
    },
    {
      "headline": "Vandalism and Controversy",
      "text": "Over the years, the Georgia Guidestones became the subject of controversy and conspiracy theories, leading to several acts of vandalism. The inscriptions were often interpreted as promoting controversial ideas.",
      "date": "Various dates"
    },
    {
      "headline": "Destruction of the Georgia Guidestones",
      "text": "On July 6, 2022, an explosive device was detonated at the site, causing significant damage to the Georgia Guidestones. The remaining structure was subsequently demolished for safety reasons.",
      "date": "2022-07-06"
    }
  ]
}

