{
  "timeline": [
    {
      "headline": "Formation of Earth",
      "text": "The Earth formed approximately 4.54 billion years ago, marking the beginning of the geologic time scale.",
      "date": "-4540000000"
    },
    {
      "headline": "Hadean Eon",
      "text": "The Hadean Eon spans from the formation of the Earth about 4.54 billion years ago to about 4 billion years ago. It is characterized by the formation of the Earth's initial crust and the appearance of the first oceans.",
      "date": "-4540000000"
    },
    {
      "headline": "Archean Eon",
      "text": "The Archean Eon extends from about 4 billion to 2.5 billion years ago. During this time, the Earth's crust stabilized, and the first known life forms, simple single-celled organisms, appeared.",
      "date": "-4000000000"
    },
    {
      "headline": "Proterozoic Eon",
      "text": "The Proterozoic Eon lasted from 2.5 billion to 541 million years ago. It saw the buildup of atmospheric oxygen and the emergence of more complex life forms, including the first multicellular organisms.",
      "date": "-2500000000"
    },
    {
      "headline": "Cambrian Period",
      "text": "The Cambrian Period, beginning around 541 million years ago, marks the start of the Paleozoic Era. It is known for the 'Cambrian Explosion,' a rapid diversification of life forms.",
      "date": "-541000000"
    },
    {
      "headline": "Ordovician Period",
      "text": "The Ordovician Period, from about 485 to 444 million years ago, saw the diversification of marine life and the first appearance of land plants.",
      "date": "-485000000"
    },
    {
      "headline": "Silurian Period",
      "text": "The Silurian Period, from about 444 to 419 million years ago, is noted for the stabilization of Earth's climate and the spread of jawed fish and terrestrial plants.",
      "date": "-444000000"
    },
    {
      "headline": "Devonian Period",
      "text": "The Devonian Period, from about 419 to 359 million years ago, is often called the 'Age of Fishes' due to the diversity of fish species. It also saw the first forests and terrestrial vertebrates.",
      "date": "-419000000"
    },
    {
      "headline": "Carboniferous Period",
      "text": "The Carboniferous Period, from about 359 to 299 million years ago, is known for extensive forests of vascular plants and the formation of vast coal deposits.",
      "date": "-359000000"
    },
    {
      "headline": "Permian Period",
      "text": "The Permian Period, from about 299 to 252 million years ago, ended with the largest mass extinction in Earth's history, wiping out approximately 90% of marine species.",
      "date": "-299000000"
    },
    {
      "headline": "Triassic Period",
      "text": "The Triassic Period, from about 252 to 201 million years ago, marks the beginning of the Mesozoic Era. It saw the rise of dinosaurs and the first mammals.",
      "date": "-252000000"
    },
    {
      "headline": "Jurassic Period",
      "text": "The Jurassic Period, from about 201 to 145 million years ago, is known for the dominance of dinosaurs and the appearance of the first birds.",
      "date": "-201000000"
    },
    {
      "headline": "Cretaceous Period",
      "text": "The Cretaceous Period, from about 145 to 66 million years ago, ended with a mass extinction event that led to the demise of the dinosaurs.",
      "date": "-145000000"
    },
    {
      "headline": "Paleogene Period",
      "text": "The Paleogene Period, from about 66 to 23 million years ago, marks the beginning of the Cenozoic Era and saw the rise of mammals and birds.",
      "date": "-66000000"
    },
    {
      "headline": "Neogene Period",
      "text": "The Neogene Period, from about 23 to 2.6 million years ago, is characterized by further mammalian evolution and the formation of modern ecosystems.",
      "date": "-23000000"
    },
    {
      "headline": "Quaternary Period",
      "text": "The Quaternary Period, from about 2.6 million years ago to the present, includes the development of humans and the current Ice Age cycles.",
      "date": "-2600000"
    }
  ]
}

