{
  "timeline": [
    {
      "headline": "Development of MP3 Begins",
      "text": "The development of MP3 began in the late 1980s at the Fraunhofer Society in Germany, under the lead of Karlheinz Brandenburg. The goal was to create a digital audio format that could significantly reduce file size while maintaining sound quality.",
      "date": "1987"
    },
    {
      "headline": "First MP3 Codec Released",
      "text": "In 1991, the first MP3 codec was released. This marked the beginning of MP3 as a format for digital audio compression.",
      "date": "1991"
    },
    {
      "headline": "ISO Standardization",
      "text": "In 1993, the MP3 format was standardized as part of the MPEG-1 standard by the International Organization for Standardization (ISO).",
      "date": "1993"
    },
    {
      "headline": "Fraunhofer Releases First MP3 Encoder",
      "text": "In 1994, Fraunhofer released the first software MP3 encoder, which allowed users to convert audio files into the MP3 format.",
      "date": "1994"
    },
    {
      "headline": "MP3 Becomes Popular",
      "text": "By the late 1990s, MP3 had become a popular format for music distribution on the internet, largely due to its ability to compress audio files to a manageable size while retaining quality.",
      "date": "1998"
    },
    {
      "headline": "Napster Launches",
      "text": "In 1999, Napster, a peer-to-peer file sharing service, launched and popularized the sharing of MP3 files, leading to widespread use and controversy over music piracy.",
      "date": "1999"
    },
    {
      "headline": "MP3 Players Enter the Market",
      "text": "In the late 1990s and early 2000s, portable MP3 players began to enter the market, allowing users to carry large libraries of music in a compact device.",
      "date": "1998-2000"
    },
    {
      "headline": "iPod Release",
      "text": "In 2001, Apple released the iPod, a portable media player that significantly boosted the popularity of MP3 files by allowing users to easily store and play thousands of songs.",
      "date": "2001"
    },
    {
      "headline": "End of MP3 Licensing Program",
      "text": "In 2017, the Fraunhofer Society terminated its licensing program for certain MP3-related patents, signaling the end of the format's dominance as newer audio formats emerged.",
      "date": "2017"
    }
  ]
}

