    {
      "headline": "SALT I Treaty",
      "text": "On May 26, 1972, the United States and the Soviet Union signed the Strategic Arms Limitation Talks (SALT I) treaty, which limited the number of ICBMs and other strategic arms.",
      "date": "1972-05-26"
    },
    {
      "headline": "SALT II Treaty",
      "text": "On June 18, 1979, the SALT II treaty was signed by the United States and the Soviet Union, further limiting the number of strategic nuclear weapons, including ICBMs.",
      "date": "1979-06-18"
    },
    {
      "headline": "START I Treaty",
      "text": "On July 31, 1991, the United States and the Soviet Union signed the Strategic Arms Reduction Treaty (START I), which aimed to reduce and limit strategic offensive arms, including ICBMs.",
      "date": "1991-07-31"
    },
    {
      "headline": "New START Treaty",
      "text": "On April 8, 2010, the United States and Russia signed the New START treaty, which further reduced the number of deployed strategic nuclear warheads and delivery systems, including ICBMs.",
      "date": "2010-04-08"
    }
  ]
}

