{
  "timeline": [
    {
      "headline": "Birth of Chandragupta Maurya",
      "text": "Chandragupta Maurya was born around 340 BCE. The exact date and location of his birth are not precisely known, but it is believed to be in the Magadha region.",
      "date": "-0340"
    },
    {
      "headline": "Rise to Power",
      "text": "Following the death of Alexander the Great in 323 BCE, Chandragupta Maurya began his rise to power. Around 317 BCE, he raised an army to resist the Greeks and annexed Greek territories in the eastern Indus Valley.",
      "date": "-0317"
    },
    {
      "headline": "Defeat of the Nanda Dynasty",
      "text": "Chandragupta Maurya started a war against the unpopular Nanda dynasty after being insulted and ordered to be executed by the Nanda king. He defeated them and established the Maurya Empire around 322-319 BCE.",
      "date": "-0322"
    },
    {
      "headline": "Alliance with Seleucus I Nicator",
      "text": "Around 305-303 BCE, Chandragupta Maurya expanded his empire through a dynastic marriage alliance with Seleucus I Nicator, gaining control over parts of the western Indus Valley and possibly eastern Afghanistan.",
      "date": "-0305"
    },
    {
      "headline": "Expansion of the Maurya Empire",
      "text": "Under Chandragupta's rule, the Maurya Empire expanded to include Gujarat, controlling a geographically extensive network of cities and trade routes.",
      "date": "-0300"
    },
    {
      "headline": "Abdication and Conversion to Jainism",
      "text": "Chandragupta Maurya abdicated the throne in favor of his son, Bindusara, and converted to Jainism. He is said to have migrated south to Shravanabelagola in present-day Karnataka.",
      "date": "-0297"
    },
    {
      "headline": "Death of Chandragupta Maurya",
      "text": "Chandragupta Maurya died around 297 BCE in Shravanabelagola, Karnataka, after having fasted to death in the Jain tradition of Sallekhana.",
      "date": "-0297"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Assassination of John F. Kennedy",
      "text": "On November 22, 1963, President John F. Kennedy was assassinated in Dallas, Texas, while riding in a presidential motorcade.",
      "date": "1963-11-22"
    },
    {
      "headline": "Warren Commission Report",
      "text": "The Warren Commission, established by President Lyndon B. Johnson, released its report on September 24, 1964, concluding that Lee Harvey Oswald acted alone in the assassination of President Kennedy.",
      "date": "1964-09-24"
    },
    {
      "headline": "Emergence of Conspiracy Theories",
      "text": "Following the release of the Warren Commission Report, various conspiracy theories began to emerge, suggesting that entities such as the CIA, the Mafia, and others were involved in the assassination.",
      "date": "1964"
    },
    {
      "headline": "Jim Garrison Investigation",
      "text": "In 1966, New Orleans District Attorney Jim Garrison began an investigation into the assassination, which led to the trial of Clay Shaw in 1969. Shaw was acquitted, but the trial fueled further conspiracy theories.",
      "date": "1966"
    },
    {
      "headline": "House Select Committee on Assassinations",
      "text": "In 1976, the United States House of Representatives established the House Select Committee on Assassinations to investigate the deaths of John F. Kennedy and Martin Luther King Jr. The committee concluded in 1979 that Kennedy was probably assassinated as a result of a conspiracy.",
      "date": "1976"
    },
    {
      "headline": "HSCA Report",
      "text": "The House Select Committee on Assassinations released its final report on March 29, 1979, suggesting that there was a high probability that two gunmen fired at President Kennedy.",
      "date": "1979-03-29"
    },
    {
      "headline": "Vincent Bugliosi's Estimate",
      "text": "In 2007, lawyer and author Vincent Bugliosi estimated that a total of 42 groups, 82 assassins, and 214 people had been accused at one time or another in various conspiracy scenarios related to the assassination.",
      "date": "2007"
    }
  ]
}

