{
  "timeline": [
    {
      "headline": "Brown v. Board of Education Decision",
      "text": "On May 17, 1954, the U.S. Supreme Court delivered its decision in Brown v. Board of Education, declaring state laws establishing separate public schools for black and white students to be unconstitutional.",
      "date": "1954-05-17"
    },
    {
      "headline": "Montgomery Bus Boycott",
      "text": "The Montgomery Bus Boycott began on December 5, 1955, after Rosa Parks was arrested for refusing to give up her seat to a white person. This boycott lasted until December 20, 1956, and led to a Supreme Court ruling that segregation on public buses was unconstitutional.",
      "date": "1955-12-05"
    },
    {
      "headline": "Southern Christian Leadership Conference (SCLC) Founded",
      "text": "In January 1957, Martin Luther King Jr. and other civil rights leaders founded the Southern Christian Leadership Conference (SCLC) to harness the moral authority and organizing power of black churches to conduct nonviolent protests in the service of civil rights reform.",
      "date": "1957-01"
    },
    {
      "headline": "Little Rock Nine",
      "text": "On September 4, 1957, nine African American students, known as the Little Rock Nine, were initially prevented from entering the racially segregated Little Rock Central High School by the Governor of Arkansas. President Eisenhower intervened, sending federal troops to escort the students.",
      "date": "1957-09-04"
    },
    {
      "headline": "Greensboro Sit-ins",
      "text": "On February 1, 1960, four African American college students began a sit-in at a segregated Woolworth's lunch counter in Greensboro, North Carolina, sparking a wave of similar protests across the South.",
      "date": "1960-02-01"
    },
    {
      "headline": "Freedom Rides",
      "text": "Starting on May 4, 1961, the Freedom Rides were organized by CORE and SNCC to challenge segregation in interstate bus terminals across the South. The rides faced violent opposition but led to federal enforcement of desegregation laws.",
      "date": "1961-05-04"
    },
    {
      "headline": "Albany Movement",
      "text": "The Albany Movement was a desegregation campaign formed on November 17, 1961, in Albany, Georgia. It was the first mass movement in the modern civil rights era to have as its goal the desegregation of an entire community.",
      "date": "1961-11-17"
    },
    {
      "headline": "Birmingham Campaign",
      "text": "In April 1963, the Birmingham Campaign was launched by the SCLC to bring attention to the integration efforts of African Americans in Birmingham, Alabama. The campaign featured nonviolent protests and was met with violent responses from authorities.",
      "date": "1963-04"
    },
    {
      "headline": "March on Washington",
      "text": "On August 28, 1963, the March on Washington for Jobs and Freedom took place, where Martin Luther King Jr. delivered his famous 'I Have a Dream' speech. The march was a pivotal event in the civil rights movement.",
      "date": "1963-08-28"
    },
    {
      "headline": "Civil Rights Act of 1964",
      "text": "On July 2, 1964, President Lyndon B. Johnson signed the Civil Rights Act of 1964 into law, prohibiting discrimination based on race, color, religion, sex, or national origin and ending segregation in public places.",
      "date": "1964-07-02"
    },
    {
      "headline": "Selma to Montgomery Marches",
      "text": "The Selma to Montgomery marches were three protest marches held in 1965, from March 7 to March 21, along the 54-mile highway from Selma, Alabama, to the state capital of Montgomery. These marches were pivotal in leading to the Voting Rights Act.",
      "date": "1965-03-07"
    },
    {
      "headline": "Voting Rights Act of 1965",
      "text": "On August 6, 1965, President Lyndon B. Johnson signed the Voting Rights Act into law, prohibiting racial discrimination in voting, a landmark achievement of the civil rights movement.",
      "date": "1965-08-06"
    },
    {
      "headline": "Fair Housing Act",
      "text": "On April 11, 1968, the Fair Housing Act was signed into law, prohibiting discrimination concerning the sale, rental, and financing of housing based on race, religion, national origin, and sex.",
      "date": "1968-04-11"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Creation of The Art of War",
      "text": "The Art of War is an ancient Chinese military treatise attributed to Sun Tzu, a military strategist. It was created during the late Spring and Autumn period, which lasted from approximately 771 to 476 BCE.",
      "date": "-0476"
    },
    {
      "headline": "Inclusion in the Seven Military Classics",
      "text": "In 1080, The Art of War was included as the lead text in an anthology known as the Seven Military Classics by Emperor Shenzong of Song. This formalized its status as a critical text in military strategy.",
      "date": "1080"
    },
    {
      "headline": "Influence on East Asian Warfare",
      "text": "For almost 1,500 years, The Art of War remained the most influential strategy text in East Asian warfare, shaping military theory and thinking across the region.",
      "date": "1500"
    },
    {
      "headline": "Influence on Western Military Theory",
      "text": "The Art of War has also influenced Western military theory and thinking, becoming a key text in understanding military strategy and tactics.",
      "date": "1500"
    },
    {
      "headline": "Applications in Modern Competitive Endeavors",
      "text": "In modern times, The Art of War has found applications in various competitive non-military endeavors, including espionage, culture, politics, business, and sports.",
      "date": "2000"
    }
  ]
}

