{
  "timeline": [
    {
      "headline": "Origins of the Samaritans",
      "text": "The Samaritans originate from the Hebrews and Israelites of the ancient Near East. They are indigenous to Samaria, a historical region of ancient Israel and Judah.",
      "date": "-0722"
    },
    {
      "headline": "Assyrian Conquest of Israel",
      "text": "In 722 BCE, the Assyrian Empire conquered the northern Kingdom of Israel, leading to significant demographic and cultural changes in the region of Samaria.",
      "date": "-0722"
    },
    {
      "headline": "Construction of Mount Gerizim Temple",
      "text": "The Samaritans built their temple on Mount Gerizim, which became the center of their religious life. The exact date is uncertain, but it was likely constructed during the Persian period (539–332 BCE).",
      "date": "-0500"
    },
    {
      "headline": "Destruction of the Samaritan Temple",
      "text": "In 128 BCE, the Jewish Hasmonean king John Hyrcanus destroyed the Samaritan temple on Mount Gerizim.",
      "date": "-0128"
    },
    {
      "headline": "Samaritan Revolts",
      "text": "Throughout the Roman period, the Samaritans engaged in several revolts against Roman rule, notably during the 5th and 6th centuries CE.",
      "date": "0500"
    },
    {
      "headline": "Byzantine Persecution",
      "text": "During the Byzantine Empire, the Samaritans faced persecution, leading to a significant decline in their population and influence.",
      "date": "0600"
    },
    {
      "headline": "Islamic Conquest",
      "text": "The Islamic conquest of the Levant in the 7th century CE brought changes to the region, with the Samaritans living under Muslim rule.",
      "date": "0637"
    },
    {
      "headline": "Modern Era",
      "text": "In the modern era, the Samaritans have maintained their distinct religious and cultural identity, primarily residing in the West Bank and Israel.",
      "date": "1900"
    }
  ]
}

