{
  "timeline": [
    {
      "headline": "Discovery of Europa",
      "text": "Europa was discovered on January 8, 1610, by Galileo Galilei, along with the other Galilean moons: Io, Ganymede, and Callisto. Simon Marius also independently discovered Europa around the same time.",
      "date": "1610-01-08"
    },
    {
      "headline": "Naming of Europa",
      "text": "The moon was named Europa after the Phoenician mother of King Minos of Crete and lover of Zeus (the Greek equivalent of the Roman god Jupiter). The name was suggested by Simon Marius, who published it in his work Mundus Jovialis in 1614.",
      "date": "1614"
    },
    {
      "headline": "Voyager 1 and 2 Flybys",
      "text": "In 1979, the Voyager 1 and Voyager 2 spacecraft conducted flybys of Europa, providing the first close-up images of the moon's surface, revealing a smooth, icy crust with few craters.",
      "date": "1979"
    },
    {
      "headline": "Galileo Mission",
      "text": "The Galileo spacecraft, launched by NASA, arrived at Jupiter in 1995 and conducted detailed observations of Europa, suggesting the presence of a subsurface ocean beneath its icy crust.",
      "date": "1995"
    },
    {
      "headline": "Hubble Space Telescope Observations",
      "text": "In 2012, the Hubble Space Telescope detected water vapor plumes erupting from Europa's surface, supporting the theory of a subsurface ocean.",
      "date": "2012"
    },
    {
      "headline": "Europa Clipper Mission Announcement",
      "text": "In 2015, NASA announced the Europa Clipper mission, aimed at conducting detailed reconnaissance of Europa's ice shell and subsurface ocean.",
      "date": "2015"
    }
  ]
}

