{
  "timeline": [
    {
      "headline": "Introduction of Slavery in the Americas",
      "text": "Slavery was introduced to the Americas during European colonization. The first known instance of African slaves in what would become the United States occurred in 1526.",
      "date": "1526"
    },
    {
      "headline": "Slavery in the Thirteen Colonies",
      "text": "Slavery was practiced in all of Britain's colonies, including the Thirteen Colonies that later formed the United States.",
      "date": "1600"
    },
    {
      "headline": "Founding of the United States",
      "text": "The United States was founded in 1776, and slavery was prevalent in the country from its founding.",
      "date": "1776"
    },
    {
      "headline": "Constitutional Convention and the Three-Fifths Compromise",
      "text": "In 1787, the Constitutional Convention resulted in the Three-Fifths Compromise, which counted three out of every five slaves for the purpose of representation and taxation.",
      "date": "1787"
    },
    {
      "headline": "Abolition of the Transatlantic Slave Trade",
      "text": "The United States abolished the transatlantic slave trade in 1808, although slavery itself continued.",
      "date": "1808"
    },
    {
      "headline": "Missouri Compromise",
      "text": "The Missouri Compromise was enacted in 1820 to maintain the balance of power between slave and free states.",
      "date": "1820"
    },
    {
      "headline": "Nat Turner's Rebellion",
      "text": "In 1831, Nat Turner led a slave rebellion in Virginia, which heightened tensions over the issue of slavery.",
      "date": "1831"
    },
    {
      "headline": "Compromise of 1850",
      "text": "The Compromise of 1850 included measures to appease both slave and free states, including the Fugitive Slave Act.",
      "date": "1850"
    },
    {
      "headline": "Dred Scott Decision",
      "text": "In 1857, the Supreme Court ruled in Dred Scott v. Sandford that African Americans could not be American citizens and that Congress could not prohibit slavery in the territories.",
      "date": "1857"
    },
    {
      "headline": "American Civil War",
      "text": "The American Civil War was fought from 1861 to 1865, largely over the issue of slavery.",
      "date": "1861"
    },
    {
      "headline": "Emancipation Proclamation",
      "text": "President Abraham Lincoln issued the Emancipation Proclamation on January 1, 1863, declaring all slaves in Confederate-held territory to be free.",
      "date": "1863-01-01"
    },
    {
      "headline": "Abolition of Slavery",
      "text": "Slavery was abolished in the United States with the ratification of the 13th Amendment on December 6, 1865.",
      "date": "1865-12-06"
    },
    {
      "headline": "End of Reconstruction",
      "text": "Reconstruction ended in 1877, leading to the continuation of many of slavery's economic and social functions through segregation, sharecropping, and convict leasing.",
      "date": "1877"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Ancient Origins",
      "text": "The Basques are believed to be descended from the ancient Vascones and Aquitanians, indigenous peoples who inhabited the western Pyrenees and the Bay of Biscay region. Their presence in this area dates back to prehistoric times.",
      "date": "-05000"
    },
    {
      "headline": "Roman Era",
      "text": "During the Roman Empire, the Basque region was known as Vasconia. The Basques maintained a degree of autonomy and were not fully Romanized, preserving their language and culture.",
      "date": "-00200"
    },
    {
      "headline": "Middle Ages",
      "text": "In the early Middle Ages, the Basques were involved in the formation of the Kingdom of Navarre, which became a significant political entity in the region.",
      "date": "0824"
    },
    {
      "headline": "Battle of Roncevaux Pass",
      "text": "The Basques famously defeated Charlemagne's rearguard in the Battle of Roncevaux Pass, which took place on August 15, 778. This battle is celebrated in the Basque cultural memory.",
      "date": "0778-08-15"
    },
    {
      "headline": "Navarrese Expansion",
      "text": "Under Sancho III of Navarre, the Kingdom of Navarre expanded significantly, reaching its zenith in the early 11th century.",
      "date": "1004"
    },
    {
      "headline": "Spanish Conquest of Navarre",
      "text": "In 1512, the southern part of the Kingdom of Navarre was conquered by Ferdinand II of Aragon, leading to its incorporation into the Kingdom of Spain.",
      "date": "1512"
    },
    {
      "headline": "Basque Statutes",
      "text": "The Basque provinces enjoyed a degree of autonomy under the Spanish crown, governed by their own local laws known as fueros, until the 19th century.",
      "date": "1800"
    },
    {
      "headline": "Carlist Wars",
      "text": "During the 19th century, the Basque Country was a stronghold for the Carlist movement, which sought to preserve traditional regional rights and the monarchy.",
      "date": "1833"
    },
    {
      "headline": "Spanish Civil War",
      "text": "The Basque Country was a significant battleground during the Spanish Civil War (1936-1939), with the bombing of Guernica in 1937 becoming a symbol of the conflict.",
      "date": "1937-04-26"
    },
    {
      "headline": "Basque Autonomy",
      "text": "Following the end of Franco's dictatorship, the Basque Country was granted autonomy within Spain in 1979, allowing for self-governance in many areas.",
      "date": "1979"
    },
    {
      "headline": "End of ETA",
      "text": "The Basque separatist group ETA declared a permanent ceasefire in 2011, ending decades of violence in pursuit of Basque independence.",
      "date": "2011"
    }
  ]
}

