    {
      "headline": "Liberation of Kraków",
      "text": "In 1945, Soviet forces liberated Kraków from Nazi occupation.",
      "date": "1945"
    },
    {
      "headline": "Kraków's Old Town Declared UNESCO World Heritage Site",
