  "timeline": [
    {
      "headline": "Origins of Scots Language",
      "text": "Scots language originated from the Northumbrian dialect of Old English, which was spoken in the Kingdom of Northumbria. This dialect evolved into Early Scots during the Middle English period.",
      "date": "-1100"
    },
    {
      "headline": "Scots Language in the Middle Ages",
      "text": "By the 14th century, Scots had become the dominant language in the Scottish Lowlands, replacing Gaelic in many areas.",
      "date": "1300"
    },
    {
      "headline": "Scots in Literature",
      "text": "The 15th century saw the flourishing of Scots literature, with poets like Robert Henryson and William Dunbar contributing to its development.",
      "date": "1400"
    },
    {
      "headline": "The Reformation and Scots",
      "text": "During the 16th century, the Protestant Reformation influenced the Scots language, as religious texts were translated into Scots.",
      "date": "1500"
    },
    {
      "headline": "Union of the Crowns",
      "text": "In 1603, the Union of the Crowns under James VI of Scotland and I of England led to increased influence of English on Scots.",
      "date": "1603"
    },
    {
      "headline": "Decline of Scots",
      "text": "The 18th century saw a decline in the use of Scots, as English became the language of education and government following the Acts of Union in 1707.",
      "date": "1707"
    },
    {
      "headline": "Revival of Scots",
      "text": "The late 20th and early 21st centuries have seen a revival of interest in the Scots language, with efforts to promote its use in education and media.",
      "date": "1980"
    }
  ]
}

