  "timeline": [
    {
      "headline": "First Temple Constructed",
      "text": "According to the Hebrew Bible, the First Temple was constructed by King Solomon in the 10th century BCE as a permanent resting place for the Ark of the Covenant.",
      "date": "-0970"
    },
    {
      "headline": "Destruction of the First Temple",
      "text": "The First Temple was destroyed by the Babylonians under King Nebuchadnezzar II in 586 BCE during the siege of Jerusalem.",
      "date": "-0586"
    },
    {
      "headline": "Second Temple Constructed",
      "text": "The Second Temple was completed in 516 BCE after the return of the Jewish exiles from Babylon.",
      "date": "-0516"
    },
    {
      "headline": "Herod's Expansion of the Second Temple",
      "text": "King Herod the Great began a massive expansion and renovation of the Second Temple around 20 BCE, which greatly enhanced its grandeur.",
      "date": "-0020"
    },
    {
      "headline": "Destruction of the Second Temple",
      "text": "The Second Temple was destroyed by the Romans in 70 CE during the Siege of Jerusalem, a pivotal event in Jewish history.",
      "date": "0070"
    },
    {
      "headline": "Construction of the Dome of the Rock",
      "text": "The Dome of the Rock was completed in 691 CE by the Umayyad Caliph Abd al-Malik, marking an important Islamic architectural achievement.",
      "date": "0691"
    },
    {
      "headline": "Construction of Al-Aqsa Mosque",
      "text": "The Al-Aqsa Mosque was completed in 705 CE, further establishing the Temple Mount as a significant Islamic site.",
      "date": "0705"
    },
    {
      "headline": "Crusader Control and Transformation",
      "text": "During the Crusades, the Temple Mount was captured by the Crusaders in 1099 and transformed into a Christian site, with the Dome of the Rock becoming a church.",
      "date": "1099"
    },
    {
      "headline": "Ayyubid Restoration",
      "text": "Saladin recaptured Jerusalem in 1187, restoring the Islamic sanctity of the Temple Mount and converting the Dome of the Rock and Al-Aqsa Mosque back to Muslim worship.",
      "date": "1187"
    },
    {
      "headline": "Ottoman Renovations",
      "text": "The Ottoman Empire, which controlled Jerusalem from 1517, undertook significant renovations of the Temple Mount, including the Dome of the Rock and Al-Aqsa Mosque.",
      "date": "1517"
    },
    {
      "headline": "Israeli Control",
      "text": "Following the Six-Day War in 1967, Israel captured East Jerusalem, including the Temple Mount, but allowed the Islamic Waqf to continue administering the site.",
      "date": "1967"
    }
  ]
}

