{
  "timeline": [
    {
      "headline": "Foundation of the Seleucid Empire",
      "text": "The Seleucid Empire was founded in 312 BC by Seleucus I Nicator, a Macedonian general, following the division of the Macedonian Empire after the death of Alexander the Great.",
      "date": "-0312"
    },
    {
      "headline": "Battle of Ipsus",
      "text": "In 301 BC, Seleucus I Nicator, along with his allies, defeated Antigonus I Monophthalmus at the Battle of Ipsus, which led to the expansion of the Seleucid Empire.",
      "date": "-0301"
    },
    {
      "headline": "Seleucus I Nicator's Assassination",
      "text": "Seleucus I Nicator was assassinated in 281 BC by Ptolemy Keraunos, marking the end of his reign.",
      "date": "-0281"
    },
    {
      "headline": "Reign of Antiochus I Soter",
      "text": "Antiochus I Soter, son of Seleucus I, ruled the Seleucid Empire from 281 BC to 261 BC.",
      "date": "-0281"
    },
    {
      "headline": "Reign of Antiochus II Theos",
      "text": "Antiochus II Theos ruled the Seleucid Empire from 261 BC to 246 BC, during which he fought the Second Syrian War against Ptolemaic Egypt.",
      "date": "-0261"
    },
    {
      "headline": "Third Syrian War",
      "text": "The Third Syrian War, also known as the Laodicean War, took place from 246 BC to 241 BC, involving the Seleucid Empire and Ptolemaic Egypt.",
      "date": "-0246"
    },
    {
      "headline": "Reign of Antiochus III the Great",
      "text": "Antiochus III the Great ruled from 222 BC to 187 BC, during which he expanded the empire to its greatest extent.",
      "date": "-0222"
    },
    {
      "headline": "Battle of Raphia",
      "text": "In 217 BC, Antiochus III the Great was defeated by Ptolemy IV Philopator at the Battle of Raphia, leading to the loss of Coele-Syria.",
      "date": "-0217"
    },
    {
      "headline": "Peace of Apamea",
      "text": "In 188 BC, the Peace of Apamea was signed, ending the Roman-Seleucid War and forcing Antiochus III to cede territory to Rome.",
      "date": "-0188"
    },
    {
      "headline": "Reign of Antiochus IV Epiphanes",
      "text": "Antiochus IV Epiphanes ruled from 175 BC to 164 BC, known for his attempts to Hellenize the Jewish population, leading to the Maccabean Revolt.",
      "date": "-0175"
    },
    {
      "headline": "Maccabean Revolt",
      "text": "The Maccabean Revolt against Seleucid rule began in 167 BC, led by the Jewish priest Mattathias and his sons.",
      "date": "-0167"
    },
    {
      "headline": "Reign of Demetrius I Soter",
      "text": "Demetrius I Soter ruled from 161 BC to 150 BC, during which he faced internal revolts and external threats.",
      "date": "-0161"
    },
    {
      "headline": "Annexation by the Roman Republic",
      "text": "In 63 BC, the Seleucid Empire was annexed by the Roman Republic under Pompey, marking the end of the empire.",
      "date": "-0063"
    }
  ]
}

