{
  "timeline": [
    {
      "headline": "Establishment of the First Nazi Concentration Camp",
      "text": "The first Nazi concentration camp, Dachau, was established on March 22, 1933. It was located near Munich and initially intended to hold political prisoners.",
      "date": "1933-03-22"
    },
    {
      "headline": "Opening of Sachsenhausen Concentration Camp",
      "text": "Sachsenhausen concentration camp was opened in July 1936. It was located near Berlin and served as a model for other concentration camps.",
      "date": "1936-07"
    },
    {
      "headline": "Kristallnacht and Increased Arrests",
      "text": "During Kristallnacht on November 9-10, 1938, thousands of Jews were arrested and sent to concentration camps, marking a significant escalation in Nazi persecution.",
      "date": "1938-11-09"
    },
    {
      "headline": "Opening of Auschwitz Concentration Camp",
      "text": "Auschwitz concentration camp was established on May 20, 1940. It became the largest of the Nazi concentration and extermination camps.",
      "date": "1940-05-20"
    },
    {
      "headline": "Wannsee Conference and the Final Solution",
      "text": "On January 20, 1942, the Wannsee Conference was held, where Nazi officials formalized plans for the 'Final Solution,' leading to the mass deportation of Jews to extermination camps.",
      "date": "1942-01-20"
    },
    {
      "headline": "Liberation of Majdanek Concentration Camp",
      "text": "Majdanek concentration camp was liberated by Soviet forces on July 23, 1944, making it the first major concentration camp to be liberated.",
      "date": "1944-07-23"
    },
    {
      "headline": "Liberation of Auschwitz Concentration Camp",
      "text": "Auschwitz concentration camp was liberated by Soviet troops on January 27, 1945. The liberation revealed the extent of the atrocities committed there.",
      "date": "1945-01-27"
    },
    {
      "headline": "Liberation of Dachau Concentration Camp",
      "text": "Dachau concentration camp was liberated by American forces on April 29, 1945, marking one of the final liberations of Nazi concentration camps.",
      "date": "1945-04-29"
    },
    {
      "headline": "End of World War II and Closure of Camps",
      "text": "With the end of World War II in Europe on May 8, 1945, the remaining Nazi concentration camps were liberated and closed.",
      "date": "1945-05-08"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Alfred Dreyfus Convicted of Treason",
      "text": "In December 1894, Captain Alfred Dreyfus, a French artillery officer of Jewish descent, was wrongfully convicted of treason for allegedly communicating French military secrets to the German Embassy in Paris.",
      "date": "1894-12"
    },
    {
      "headline": "Dreyfus Sent to Devil's Island",
      "text": "In 1895, following his conviction, Alfred Dreyfus was sentenced to life imprisonment and sent to the penal colony on Devil's Island in French Guiana, where he endured harsh conditions.",
      "date": "1895"
    },
    {
      "headline": "Émile Zola Publishes 'J'Accuse…!'",
      "text": "On January 13, 1898, the famous French writer Émile Zola published an open letter titled 'J'Accuse…!' in the newspaper L'Aurore, accusing the French government of anti-Semitism and wrongful imprisonment of Alfred Dreyfus.",
      "date": "1898-01-13"
    },
    {
      "headline": "Dreyfus Pardoned",
      "text": "On September 19, 1899, Alfred Dreyfus was pardoned by the French President, although he was not yet exonerated.",
      "date": "1899-09-19"
    },
    {
