{
  "timeline": [
    {
      "headline": "Formation of Jethro Tull",
      "text": "Jethro Tull was formed in Blackpool, Lancashire in 1967. The band was initially known for playing blues rock and jazz fusion.",
      "date": "1967"
    },
    {
      "headline": "Release of Debut Album 'This Was'",
      "text": "Jethro Tull released their debut album 'This Was' in October 1968, which showcased their blues rock style.",
      "date": "1968-10"
    },
    {
      "headline": "Release of 'Stand Up'",
      "text": "In August 1969, Jethro Tull released their second album 'Stand Up', which marked a shift towards a more progressive rock sound.",
