{
  "timeline": [
    {
      "headline": "Establishment of the Order of Canada",
      "text": "The Order of Canada was established on July 1, 1967, as part of Canada's centennial celebrations. It was created to recognize outstanding achievement, dedication to the community, and service to the nation.",
      "date": "1967-07-01"
    },
    {
      "headline": "First Appointments to the Order of Canada",
      "text": "The first appointments to the Order of Canada were made on July 1, 1967. The initial list included 90 members, with Governor General Roland Michener as the first Chancellor of the Order.",
      "date": "1967-07-01"
    },
    {
      "headline": "Introduction of Companions, Officers, and Members",
      "text": "In 1972, the Order of Canada was expanded to include three levels: Companions, Officers, and Members, to better recognize varying degrees of achievement and service.",
      "date": "1972"
    },
    {
      "headline": "First Indigenous Appointee",
      "text": "In 1973, Chief Dan George became the first Indigenous person to be appointed to the Order of Canada, highlighting the Order's commitment to recognizing contributions from all Canadians.",
      "date": "1973"
    },
    {
      "headline": "First Female Companion",
      "text": "In 1974, Pauline Vanier became the first woman to be appointed as a Companion of the Order of Canada, the highest level of the Order.",
      "date": "1974"
    },
    {
      "headline": "Introduction of the Sovereign's Medal for Volunteers",
      "text": "In 1995, the Sovereign's Medal for Volunteers was introduced as part of the Canadian Honours System, complementing the Order of Canada by recognizing volunteerism.",
      "date": "1995"
    },
    {
      "headline": "50th Anniversary of the Order of Canada",
      "text": "In 2017, the Order of Canada celebrated its 50th anniversary, marking half a century of recognizing Canadians who have made significant contributions to the nation.",
      "date": "2017"
    }
  ]
}

