{
  "timeline": [
    {
      "headline": "Roman Conquest of Armorica",
      "text": "The region known as Armorica, which includes modern-day Brittany, was conquered by the Romans. This occurred during the Gallic Wars led by Julius Caesar.",
      "date": "-0056"
    },
    {
      "headline": "Migration of Britons to Armorica",
      "text": "Following the collapse of Roman authority in Britain, Britons migrated to Armorica, which later became known as Brittany. This migration began around the 5th century.",
      "date": "0400"
    },
    {
      "headline": "Establishment of the Kingdom of Brittany",
      "text": "The Kingdom of Brittany was established by Nominoe, who became the first Duke of Brittany after defeating the Franks at the Battle of Ballon in 845.",
      "date": "0845"
    },
    {
      "headline": "Treaty of Compiègne",
      "text": "The Treaty of Compiègne was signed, recognizing Brittany's independence from the Frankish Empire.",
      "date": "0866"
    },
    {
      "headline": "Duchy of Brittany",
      "text": "Brittany became a duchy in the 10th century, maintaining its independence while being influenced by both the French and English crowns.",
      "date": "0900"
    },
    {
      "headline": "War of the Breton Succession",
      "text": "The War of the Breton Succession took place from 1341 to 1364, a conflict between the House of Blois and the House of Montfort over the control of the Duchy of Brittany.",
      "date": "1341"
    },
    {
      "headline": "Treaty of Guérande",
      "text": "The Treaty of Guérande was signed in 1365, ending the War of the Breton Succession and confirming John IV of Montfort as Duke of Brittany.",
      "date": "1365"
    },
    {
      "headline": "Union of Brittany and France",
      "text": "The Duchy of Brittany was united with the Kingdom of France through the Treaty of Union in 1532, although it retained a degree of autonomy.",
      "date": "1532"
    },
    {
      "headline": "French Revolution and Integration",
      "text": "During the French Revolution, Brittany was fully integrated into France, losing its autonomous status as a province.",
      "date": "1790"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Establishment of CERN",
      "text": "CERN was established in 1954 as an intergovernmental organization to operate the largest particle physics laboratory in the world. It is based in Meyrin, a western suburb of Geneva, on the France–Switzerland border.",
      "date": "1954"
    },
    {
      "headline": "First Particle Accelerator",
      "text": "In 1957, CERN's first particle accelerator, the Synchrocyclotron, began operation. It was used for experiments in particle physics until 1990.",
      "date": "1957"
    },
    {
      "headline": "Proton Synchrotron Begins Operation",
      "text": "The Proton Synchrotron, a 28 GeV accelerator, started operation in 1959, marking a significant advancement in CERN's capabilities.",
      "date": "1959"
    },
    {
      "headline": "Discovery of Neutral Currents",
      "text": "In 1973, CERN scientists discovered neutral currents in the Gargamelle bubble chamber, providing crucial evidence for the electroweak theory.",
      "date": "1973"
    },
    {
      "headline": "Invention of the World Wide Web",
      "text": "In 1989, Tim Berners-Lee, a scientist at CERN, invented the World Wide Web, revolutionizing information sharing and communication.",
      "date": "1989"
    },
    {
      "headline": "Large Electron-Positron Collider (LEP) Begins Operation",
      "text": "The Large Electron-Positron Collider (LEP), one of the largest particle accelerators ever built, began operation in 1989.",
      "date": "1989"
    },
    {
      "headline": "Large Hadron Collider (LHC) Construction Begins",
      "text": "Construction of the Large Hadron Collider (LHC), the world's largest and most powerful particle collider, began in 1998.",
      "date": "1998"
    },
    {
      "headline": "Large Hadron Collider (LHC) Becomes Operational",
      "text": "The Large Hadron Collider (LHC) became operational in 2008, allowing scientists to conduct groundbreaking experiments in particle physics.",
      "date": "2008"
    },
    {
      "headline": "Discovery of the Higgs Boson",
      "text": "On July 4, 2012, CERN announced the discovery of a new particle consistent with the Higgs boson, a fundamental particle in the Standard Model of particle physics.",
      "date": "2012-07-04"
    },
    {
      "headline": "Israel Becomes a Full Member",
      "text": "In 2013, Israel was admitted as a full member of CERN, becoming the first non-European country to achieve this status.",
      "date": "2013"
    }
  ]
}

