      "headline": "Composition of 'La Marseillaise'",
      "text": "Claude Joseph Rouget de Lisle composed 'La Marseillaise' on April 25, 1792, in Strasbourg. It was originally titled 'Chant de guerre pour l'Armée du Rhin' (War Song for the Army of the Rhine).",
      "date": "1792-04-25"
    },
    {
      "headline": "Adoption as National Anthem",
      "text": "'La Marseillaise' was adopted as the national anthem of France by the French National Convention on July 14, 1795.",
      "date": "1795-07-14"
    },
    {
      "headline": "Ban and Reinstatement",
      "text": "The anthem was banned by Napoleon during his reign and later reinstated as the national anthem in 1879 during the Third Republic.",
      "date": "1879"
    },
    {
      "headline": "Official Recognition",
      "text": "The French government officially recognized 'La Marseillaise' as the national anthem in 1887, standardizing its lyrics and music.",
      "date": "1887"
    }
  ]
}

