{
  "timeline": [
    {
      "headline": "Minoxidil Development",
      "text": "Minoxidil was initially developed in the late 1950s by the Upjohn Company as a treatment for ulcers. However, during clinical trials, it was found to be ineffective for ulcers but showed promise as a vasodilator.",
      "date": "1950"
    },
    {
      "headline": "FDA Approval for Hypertension",
      "text": "In 1979, Minoxidil was approved by the U.S. Food and Drug Administration (FDA) for the treatment of high blood pressure. It was marketed under the brand name Loniten.",
      "date": "1979"
    },
    {
      "headline": "Discovery of Hair Growth Side Effect",
      "text": "During the use of Minoxidil for hypertension, patients and doctors noticed an interesting side effect: increased hair growth. This led to further research into its potential use for treating hair loss.",
      "date": "1980s"
    },
    {
      "headline": "FDA Approval for Hair Loss",
      "text": "In 1988, the FDA approved Minoxidil for the treatment of androgenetic alopecia (pattern hair loss) in men. It was marketed under the brand name Rogaine.",
      "date": "1988"
    },
    {
      "headline": "Approval for Women's Use",
      "text": "In 1991, Minoxidil was approved by the FDA for use by women experiencing hair loss.",
      "date": "1991"
    },
    {
      "headline": "Introduction of Foam Formulation",
      "text": "In 2006, a foam formulation of Minoxidil was introduced, providing an alternative to the liquid form and offering easier application for users.",
      "date": "2006"
    }
  ]
}

