    {
      "headline": "Founding of the Bauhaus",
      "text": "The Staatliches Bauhaus was founded by Walter Gropius in Weimar, Germany, on April 1, 1919. It was established as a new kind of art school that combined crafts and fine arts.",
      "date": "1919-04-01"
    },
    {
      "headline": "Move to Dessau",
      "text": "In 1925, due to political pressure and funding cuts in Weimar, the Bauhaus moved to Dessau, Germany. This move marked a new phase in the school's development, with a focus on architecture and industrial design.",
      "date": "1925"
    },
    {
      "headline": "Hannes Meyer becomes director",
      "text": "In 1928, Hannes Meyer succeeded Walter Gropius as the director of the Bauhaus. Under his leadership, the school emphasized social responsibility and functional design.",
      "date": "1928"
    },
    {
      "headline": "Ludwig Mies van der Rohe becomes director",
      "text": "In 1930, Ludwig Mies van der Rohe took over as the director of the Bauhaus. He focused on architecture and sought to maintain the school's independence amidst increasing political pressure.",
      "date": "1930"
    },
    {
      "headline": "Closure of the Bauhaus in Dessau",
      "text": "In 1932, the Bauhaus was forced to close in Dessau due to pressure from the Nazi regime, which viewed the school's modernist ideas as degenerate.",
      "date": "1932"
    },
    {
      "headline": "Final closure in Berlin",
      "text": "The Bauhaus briefly relocated to Berlin in 1932, but was ultimately closed by the Nazi regime in 1933, marking the end of its operation in Germany.",
      "date": "1933"
    }
  ]
}

