{
  "timeline": [
    {
      "headline": "Introduction of CUDA",
      "text": "CUDA was introduced by Nvidia in 2006 as a parallel computing platform and application programming interface (API) that allows software to use certain types of graphics processing units (GPUs) for accelerated general-purpose processing.",
      "date": "2006"
    },
    {
      "headline": "CUDA 1.0 Release",
      "text": "Nvidia released CUDA 1.0 in 2007, marking the first official release of the platform, enabling developers to harness the power of Nvidia GPUs for general-purpose computing.",
      "date": "2007"
    },
    {
      "headline": "CUDA 2.0 Release",
      "text": "In 2008, Nvidia released CUDA 2.0, which introduced new features such as double precision floating point support, making it more suitable for scientific computing.",
      "date": "2008"
    },
    {
      "headline": "CUDA 3.0 Release",
      "text": "CUDA 3.0 was released in 2010, adding support for the Fermi architecture, which included features like unified memory and improved performance.",
      "date": "2010"
    },
    {
      "headline": "CUDA 4.0 Release",
      "text": "In 2011, CUDA 4.0 was released, introducing features such as Unified Virtual Addressing and GPUDirect, which improved data transfer speeds between GPUs and other devices.",
      "date": "2011"
    },
    {
      "headline": "CUDA 5.0 Release",
      "text": "CUDA 5.0 was released in 2012, offering new features like Dynamic Parallelism and GPU-accelerated libraries, further enhancing the capabilities of CUDA for developers.",
      "date": "2012"
    },
    {
      "headline": "CUDA 6.0 Release",
      "text": "Released in 2014, CUDA 6.0 introduced Unified Memory, allowing easier memory management across CPU and GPU, and improved performance for developers.",
      "date": "2014"
    },
    {
      "headline": "CUDA 7.0 Release",
      "text": "CUDA 7.0 was released in 2015, adding support for C++11, new performance tools, and improved support for the latest Nvidia GPU architectures.",
      "date": "2015"
    },
    {
      "headline": "CUDA 8.0 Release",
      "text": "In 2016, CUDA 8.0 was released, featuring support for the Pascal GPU architecture, improved performance, and new developer tools.",
      "date": "2016"
    },
    {
      "headline": "CUDA 9.0 Release",
      "text": "CUDA 9.0 was released in 2017, introducing support for the Volta GPU architecture, new libraries, and enhanced performance for deep learning applications.",
      "date": "2017"
    },
    {
      "headline": "CUDA 10.0 Release",
      "text": "Released in 2018, CUDA 10.0 added support for the Turing GPU architecture and new features for AI and machine learning applications.",
      "date": "2018"
    },
    {
      "headline": "CUDA 11.0 Release",
      "text": "CUDA 11.0 was released in 2020, providing support for the Ampere GPU architecture and new tools for developers working on AI and high-performance computing.",
