    {
      "headline": "Creation of the First Nuclear Reactor",
      "text": "On December 2, 1942, Fermi led the team that achieved the first controlled nuclear chain reaction with the Chicago Pile-1 at the University of Chicago.",
      "date": "1942-12-02"
    },
    {
      "headline": "Involvement in the Manhattan Project",
      "text": "During World War II, Fermi was a key member of the Manhattan Project, which developed the first nuclear weapons.",
      "date": "1942"
    },
    {
      "headline": "Naturalization as a U.S. Citizen",
      "text": "In 1944, Enrico Fermi became a naturalized citizen of the United States.",
      "date": "1944"
    },
    {
      "headline": "Professor at the University of Chicago",
      "text": "After World War II, Fermi became a professor at the University of Chicago, where he continued his research in nuclear physics.",
      "date": "1945"
    },
    {
      "headline": "Death of Enrico Fermi",
      "text": "Enrico Fermi passed away on November 28, 1954, in Chicago, Illinois, USA.",
      "date": "1954-11-28"
    }
  ]
}

