    },
    {
      "headline": "Founding of Santo Domingo",
      "text": "Santo Domingo, the oldest continuously inhabited European settlement in the Americas, was founded by Bartholomew Columbus in 1496.",
      "date": "1496"
    },
    {
      "headline": "Treaty of Ryswick",
      "text": "The Treaty of Ryswick in 1697 formally ceded the western third of Hispaniola from Spain to France, which became known as Saint-Domingue.",
      "date": "1697"
    },
    {
      "headline": "Haitian Revolution Begins",
      "text": "The Haitian Revolution, a successful anti-slavery and anti-colonial insurrection by self-liberated slaves against French colonial rule, began in 1791.",
      "date": "1791"
    },
    {
      "headline": "Haitian Independence",
      "text": "Haiti declared its independence from France on January 1, 1804, becoming the first independent nation in Latin America and the Caribbean, and the first post-colonial independent black-led nation in the world.",
      "date": "1804-01-01"
    },
    {
      "headline": "Dominican War of Independence",
      "text": "The Dominican War of Independence began in 1844, leading to the establishment of the Dominican Republic as a sovereign state.",
      "date": "1844"
    },
    {
      "headline": "Dominican Republic Independence",
      "text": "The Dominican Republic declared its independence from Haiti on February 27, 1844.",
      "date": "1844-02-27"
    },
    {
      "headline": "US Occupation of Haiti",
      "text": "The United States occupied Haiti from 1915 to 1934, following political instability and financial difficulties in the country.",
      "date": "1915"
    },
    {
      "headline": "US Occupation of the Dominican Republic",
      "text": "The United States occupied the Dominican Republic from 1916 to 1924, due to concerns over political instability and foreign debt.",
      "date": "1916"
    },
    {
      "headline": "Trujillo Era Begins",
      "text": "Rafael Trujillo began his dictatorship in the Dominican Republic in 1930, which lasted until his assassination in 1961.",
      "date": "1930"
    },
    {
      "headline": "Duvalier Dynasty Begins",
      "text": "François 'Papa Doc' Duvalier became President of Haiti in 1957, establishing a repressive regime that lasted until 1986 under his son, Jean-Claude 'Baby Doc' Duvalier.",
      "date": "1957"
    },
    {
      "headline": "End of Trujillo Era",
      "text": "Rafael Trujillo was assassinated on May 30, 1961, ending his 31-year dictatorship in the Dominican Republic.",
      "date": "1961-05-30"
    },
